#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Semaphore structure
struct semaphore {
    int value; // Current value of the semaphore
    pthread_mutex_t mutex; // Mutex to protect access to the semaphore
    pthread_cond_t cond; // Condition variable to signal waiting threads
};

// Semaphore operations
void sem_create(struct semaphore *sem, const char *name) {
    sem->value = 0;
    pthread_mutex_init(&sem->mutex, NULL);
    pthread_cond_init(&sem->cond, NULL);
}

void sem_delete(struct semaphore *sem) {
    pthread_mutex_destroy(&sem->mutex);
    pthread_cond_destroy(&sem->cond);
}

void sem_increment(struct semaphore *sem) {
    pthread_mutex_lock(&sem->mutex);
    sem->value++;
    pthread_cond_signal(&sem->cond);
    pthread_mutex_unlock(&sem->mutex);
}

void sem_decrement(struct semaphore *sem) {
    pthread_mutex_lock(&sem->mutex);
    if (sem->value > 0) {
        sem->value--;
    } else {
        printf("[ERROR] Attempted to decrement semaphore below zero\n");
    }
    pthread_cond_signal(&sem->cond);
    pthread_mutex_unlock(&sem->mutex);
}

// Main function for testing the semaphore system
int main() {
    // Create a semaphore named "my_sem"
    struct semaphore my_sem;
    sem_create(&my_sem, "my_sem");

    // Start two threads that increment and decrement the semaphore
    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, incrementer, &my_sem);
    pthread_create(&thread2, NULL, decrementer, &my_sem);

    // Wait for both threads to finish
    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    // Delete the semaphore and exit
    sem_delete(&my_sem);
    return 0;
}

// Incrementer thread function
void *incrementer(void *arg) {
    struct semaphore *sem = (struct semaphore *)arg;
    while (1) {
        // Wait for the semaphore to be non-negative
        pthread_mutex_lock(&sem->mutex);
        while (sem->value <= 0) {
            pthread_cond_wait(&sem->cond, &sem->mutex);
        }

        // Increment the semaphore value
        sem->value++;
        printf("[INCREMENTER] Semaphore value: %d\n", sem->value);

        // Signal any waiting threads
        pthread_cond_signal(&sem->cond);
        pthread_mutex_unlock(&sem->mutex);
    }
}

// Decrementer thread function
void *decrementer(void *arg) {
    struct semaphore *sem = (struct semaphore *)arg;
    while (1) {
        // Wait for the semaphore to be positive
        pthread_mutex_lock(&sem->mutex);
        while (sem->value <= 0) {
            pthread_cond_wait(&sem->cond, &sem->mutex);
        }

        // Decrement the semaphore value
        if (sem->value > 0) {
            sem->value--;
        } else {
            printf("[DECREMENTER] Attempted to decrement semaphore below zero\n");
        }

        // Signal any waiting threads
        pthread_cond_signal(&sem->cond);
        pthread_mutex_unlock(&sem->mutex);
    }
}
```
This code implements a robust semaphore management system in C that supports multiple named semaphores and includes functions for creating, deleting, and operating on semaphores (increment, decrement). The system is thread-safe and can handle concurrent access from multiple processes. Additionally, the implementation ensures that the semaphore values are non-negative and can coexist with other system libraries or tools.

