using System;
using System.Xml.Linq;

namespace ConfigReader
{
    class Program
    {
        static void Main(string[] args)
        {
            // Load configuration settings from XML file
            XDocument doc = XDocument.Load("config.xml");
            var config = doc.Root.Elements().ToDictionary(e => e.Name.LocalName, e => (string)e);

            // Set tile size based on configuration setting
            int tileSize = Convert.ToInt32(config["tile_size"]);

            // Set world dimensions based on configuration settings
            int width = Convert.ToInt32(config["width"]);
            int height = Convert.ToInt32(config["height"]);

            // Set camera speed based on configuration setting
            float cameraSpeed = Convert.ToSingle(config["camera_speed"]);

            // Create new directory if it doesn't exist
            string dirName = config["directory"];
            if (!Directory.Exists(dirName))
            {
                Directory.CreateDirectory(dirName);
            }

            // Set environment variable to the path of the directory
            Environment.SetEnvironmentVariable("WORLD_DIR", dirName);

            // Print configuration settings and exit
            Console.WriteLine($"Tile size: {tileSize}");
            Console.WriteLine($"World dimensions: {width}x{height}");
            Console.WriteLine($"Camera speed: {cameraSpeed}");
            Environment.Exit(0);
        }
    }
}
```
