#include <semaphore.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

int convert_jpeg_to_pdf(const char* input_file, const char* output_file) {
  // Create a semaphore with initial value of 1 to prevent race conditions
  sem_t* sem = sem_open("my_sem", O_CREAT, 0644, 1);
  if (sem == SEM_FAILED) {
    fprintf(stderr, "Failed to create semaphore: %s\n", strerror(errno));
    return 1;
  }

  // Wait on the semaphore until it's available
  if (sem_wait(sem) == -1) {
    fprintf(stderr, "Failed to wait on semaphore: %s\n", strerror(errno));
    return 1;
  }

  // Run the third-party tool to convert JPEG to PDF
  int result = system("my_tool input.jpg output.pdf");
  if (result != 0) {
    fprintf(stderr, "Error running third-party tool: %s\n", strerror(errno));
  } else {
    // Move the PDF file to the desired location
    result = rename("output.pdf", output_file);
    if (result != 0) {
      fprintf(stderr, "Error moving PDF file: %s\n", strerror(errno));
    }
  }

  // Signal the semaphore to release any waiting threads
  sem_post(sem);

  // Clean up the semaphore
  sem_unlink("my_sem");

  return result;
}
```
This function uses a semaphore to prevent race conditions when running the third-party tool. The `sem_open` function creates a new semaphore with the specified name and initial value, and the `sem_wait` function waits on the semaphore until it's available. Once the semaphore is available, the function runs the third-party tool to convert the JPEG file to PDF using the `system` function. If there are any errors during this process, they are ignored and the semaphore is signaled with `sem_post`. Finally, the function cleans up the semaphore with `sem_unlink`.

