#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

// Define the maximum capacity of the queue
#define MAX_CAPACITY 100

// Define the number of producer and consumer threads to create
#define NUM_PRODUCER_THREADS 5
#define NUM_CONSUMER_THREADS 2

// Define a struct for the queue node
struct queue_node {
    void *data;
    struct queue_node *next;
};

// Define the queue data structure
struct queue {
    struct queue_node *head;
    struct queue_node *tail;
    int size;
    pthread_mutex_t mutex;
    sem_t enqueue_sem;
    sem_t dequeue_sem;
};

// Function to initialize the queue with a given capacity
void init_queue(struct queue *q, int capacity) {
    // Allocate memory for the queue and its nodes
    q->head = malloc(sizeof(struct queue_node));
    q->tail = malloc(sizeof(struct queue_node));
    q->size = 0;
    q->mutex = PTHREAD_MUTEX_INITIALIZER;
    sem_init(&q->enqueue_sem, 0, 1);
    sem_init(&q->dequeue_sem, 0, 0);

    // Set the head and tail pointers to NULL
    q->head->next = NULL;
    q->tail->next = NULL;
}

// Function to clean up the queue and its resources
void destroy_queue(struct queue *q) {
    // Free all nodes in the queue
    while (q->head != NULL) {
        struct queue_node *tmp = q->head;
        q->head = q->head->next;
        free(tmp);
    }

    // Free the queue data structure
    free(q->tail);
    free(q->head);

    // Clean up semaphore resources
    sem_destroy(&q->enqueue_sem);
    sem_destroy(&q->dequeue_sem);
}

// Function to enqueue an item in the queue
void enqueue(struct queue *q, void *data) {
    // Acquire the mutex and wait for the enqueue semaphore
    pthread_mutex_lock(&q->mutex);
    sem_wait(&q->enqueue_sem);

    // Create a new node with the data to be added
    struct queue_node *new_node = malloc(sizeof(struct queue_node));
    new_node->data = data;
    new_node->next = NULL;

    // Add the new node at the end of the queue
    q->tail->next = new_node;
    q->tail = new_node;

    // Increment the size of the queue and signal the dequeue semaphore
    q->size++;
    sem_post(&q->dequeue_sem);

    // Release the mutex
    pthread_mutex_unlock(&q->mutex);
}

// Function to dequeue an item from the queue
void *dequeue(struct queue *q) {
    // Acquire the mutex and wait for the dequeue semaphore
    pthread_mutex_lock(&q->mutex);
    sem_wait(&q->dequeue_sem);

    // Remove the first node from the queue
    struct queue_node *tmp = q->head;
    q->head = q->head->next;
    free(tmp);

    // Decrement the size of the queue and signal the enqueue semaphore
    q->size--;
    sem_post(&q->enqueue_sem);

    // Release the mutex
    pthread_mutex_unlock(&q->mutex);

    return tmp->data;
}

// Function to check if the queue is empty
int isQueueEmpty(struct queue *q) {
    return q->size == 0;
}

// Function to create producer threads that fill the queue
void create_producer_threads(struct queue *q) {
    for (int i = 0; i < NUM_PRODUCER_THREADS; i++) {
        pthread_t thread;
        pthread_create(&thread, NULL, producer_thread, q);
    }
}

// Function to create consumer threads that empty the queue
void create_consumer_threads(struct queue *q) {
    for (int i = 0; i < NUM_CONSUMER_THREADS; i++) {
        pthread_t thread;
        pthread_create(&thread, NULL, consumer_thread, q);
    }
}

// Function to terminate all threads gracefully when a stop signal is received
void termination_handler(int sig) {
    // Destroy the queue and clean up its resources
    destroy_queue(q);

    // Terminate all threads
    pthread_exit(NULL);
}

// Function to handle errors in semaphore operations
void error_handler(char *msg) {
    perror(msg);
    exit(1);
}

int main() {
    // Initialize the queue with a given capacity
    struct queue q;
    init_queue(&q, MAX_CAPACITY);

    // Create producer and consumer threads
    create_producer_threads(&q);
    create_consumer_threads(&q);

    // Wait for all threads to finish
    pthread_join(NULL, NULL);

    return 0;
}

// Producer thread function that fills the queue
void *producer_thread(void *arg) {
    struct queue *q = (struct queue *) arg;
    while (1) {
        // Generate some data to be added to the queue
        int data = rand() % 100;

        // Enqueue the data in the queue
        enqueue(q, &data);
    }
}

// Consumer thread function that empties the queue
void *consumer_thread(void *arg) {
    struct queue *q = (struct queue *) arg;
    while (1) {
        // Dequeue an item from the queue
        void *data = dequeue(q);

        // Process the data
        printf("Consumer thread: %d\n", *(int *) data);

        // Check if the queue is empty and terminate the thread if necessary
        if (isQueueEmpty(q)) {
            break;
        }
    }
}
```
This code creates a thread-safe queue using semaphores for synchronization. The `init_queue` function initializes the queue with a given capacity, and the `destroy_queue` function cleans up its resources when the program exits. The `enqueue` function adds an item to the queue, and the `dequeue` function removes an item from the queue. The `isQueueEmpty` function checks if the queue is empty.

The producer threads are created using the `create_producer_threads` function, which creates a specified number of producer threads that fill the queue with random data. Each producer thread generates some data to be added to the queue and then calls the `enqueue` function to add it to the queue.

The consumer threads are created using the `create_consumer_threads` function, which creates a specified number of consumer threads that empty the queue. Each consumer thread calls the `dequeue` function to remove an item from the queue and then processes the data. If the queue is empty, the consumer thread terminates.

The program also includes a termination handler that destroys the queue and cleans up its resources when a stop signal is received. The `termination_handler` function sets a signal handler for the `SIGINT` signal, which is sent to the program when it receives an interrupt signal from the user. When the signal handler is called, it destroys the queue and terminates all threads using the `pthread_exit` function.

This code uses error handling in the `error_handler` function, which prints an error message and exits the program if an error occurs in semaphore operations.

