#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <math.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU;

int create_and_populate_nfapi_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU **pdu_list, int num_pdus) {
    // Initialize the list of PDUS to NULL
    *pdu_list = NULL;

    // Allocate memory for the list of PDUS
    *pdu_list = (NFAPI_CRC_INDICATION_PDU *)malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU));
    if (*pdu_list == NULL) {
        printf("Failed to allocate memory for PDU list\n");
        return -1;
    }

    // Populate the list of PDUS with random CRC flags
    int i, j;
    for (i = 0; i < num_pdus; i++) {
        (*pdu_list)[i].rx_ue_information.tag = RX_UE_INFORMATION_TAG;
        (*pdu_list)[i].rx_ue_information.length = sizeof(RX_UE_INFORMATION);
        (*pdu_list)[i].rnti.tag = RNTI;
        (*pdu_list)[i].rnti.length = sizeof(RNTI);
        (*pdu_list)[i].crc_indication_rel8.tag = CRC_INDICATION_REL8_TAG;
        (*pdu_list)[i].crc_indication_rel8.length = sizeof(CRC_INDICATION_REL8);

        // Generate a random CRC flag
        int crc_flag = rand() % 2;

        // Ensure that the CRC flags are unique across all structures in the list
        for (j = i - 1; j >= 0; j--) {
            if ((*pdu_list)[j].crc_indication_rel8.crci == crc_flag) {
                // If a conflict is detected, regenerate the CRC flag
                crc_flag = rand() % 2;
                break;
            }
        }

        (*pdu_list)[i].crc_indication_rel8.crci = crc_flag;
    }

    // Log the creation and population process for debugging and auditing purposes
    printf("Created and populated %d PDUS\n", num_pdus);

    return 0;
}

// Mock database system for storing and retrieving NFAPI CRC indication PDUs
typedef struct NFAPI_CRC_INDICATION_PDU_STORAGE {
    int pdu_id;
    NFAPI_CRC_INDICATION_PDU *pdu;
} NFAPI_CRC_INDICATION_PDU_STORAGE;

void insert_nfapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_STORAGE **storage, int pdu_id, NFAPI_CRC_INDICATION_PDU *pdu) {
    // Allocate memory for the new PDU storage element
    NFAPI_CRC_INDICATION_PDU_STORAGE *new_element = (NFAPI_CRC_INDICATION_PDU_STORAGE *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_STORAGE));
    if (new_element == NULL) {
        printf("Failed to allocate memory for PDU storage element\n");
        return;
    }

    // Set the ID and PDU pointer of the new element
    new_element->pdu_id = pdu_id;
    new_element->pdu = pdu;

    // Insert the new element into the storage list
    new_element->next = *storage;
    *storage = new_element;
}

NFAPI_CRC_INDICATION_PDU *retrieve_nfapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_STORAGE **storage, int pdu_id) {
    // Search for the PDU storage element with the specified ID
    NFAPI_CRC_INDICATION_PDU_STORAGE *element = *storage;
    while (element != NULL && element->pdu_id != pdu_id) {
        element = element->next;
    }

    // Return the PDU pointer if found, or NULL otherwise
    return (element == NULL) ? NULL : element->pdu;
}

// Thread-safe implementation of a concurrent hash table for storing NFAPI CRC indication PDUs
typedef struct NFAPI_CRC_INDICATION_PDU_HASH {
    int num_buckets;
    int *bucket_head;
    NFAPI_CRC_INDICATION_PDU_STORAGE **storage;
} NFAPI_CRC_INDICATION_PDU_HASH;

void init_nfapi_crc_indication_pdu_hash(NFAPI_CRC_INDICATION_PDU_HASH *hash, int num_buckets) {
    // Allocate memory for the hash table and the storage list
    hash->num_buckets = num_buckets;
    hash->bucket_head = (int *)malloc(num_buckets * sizeof(int));
    if (hash->bucket_head == NULL) {
        printf("Failed to allocate memory for bucket head\n");
        return;
    }
    hash->storage = (NFAPI_CRC_INDICATION_PDU_STORAGE **)malloc(num_buckets * sizeof(NFAPI_CRC_INDICATION_PDU_STORAGE));
    if (hash->storage == NULL) {
        printf("Failed to allocate memory for storage list\n");
        return;
    }

    // Initialize the bucket head and storage lists
    int i;
    for (i = 0; i < num_buckets; i++) {
        hash->bucket_head[i] = -1;
        hash->storage[i] = NULL;
    }
}

void insert_nfapi_crc_indication_pdu_hash(NFAPI_CRC_INDICATION_PDU_HASH *hash, int pdu_id, NFAPI_CRC_INDICATION_PDU *pdu) {
    // Compute the hash value of the PDU ID
    unsigned long hash_value = pdu_id % hash->num_buckets;

    // Insert the PDU into the corresponding bucket in the hash table
    insert_nfapi_crc_indication_pdu(&hash->storage[hash_value], pdu_id, pdu);
}

NFAPI_CRC_INDICATION_PDU *retrieve_nfapi_crc_indication_pdu_hash(NFAPI_CRC_INDICATION_PDU_HASH *hash, int pdu_id) {
    // Compute the hash value of the PDU ID
    unsigned long hash_value = pdu_id % hash->num_buckets;

    // Search for the PDU storage element with the specified ID in the corresponding bucket
    NFAPI_CRC_INDICATION_PDU_STORAGE *element = hash->storage[hash_value];
    while (element != NULL && element->pdu_id != pdu_id) {
        element = element->next;
    }

    // Return the PDU pointer if found, or NULL otherwise
    return (element == NULL) ? NULL : element->pdu;
}

void free_nfapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU *pdu) {
    // Free the memory allocated for the PDU
    free(pdu);
}

void free_nfapi_crc_indication_pdu_storage(NFAPI_CRC_INDICATION_PDU_STORAGE *storage) {
    // Free the memory allocated for the storage element and its contents
    if (storage != NULL) {
        free_nfapi_crc_indication_pdu(storage->pdu);
        free(storage);
    }
}

void free_nfapi_crc_indication_pdu_hash(NFAPI_CRC_INDICATION_PDU_HASH *hash) {
    // Free the memory allocated for the hash table and its contents
    if (hash != NULL) {
        int i;
        for (i = 0; i < hash->num_buckets; i++) {
            free_nfapi_crc_indication_pdu_storage(hash->storage[i]);
        }
        free(hash->bucket_head);
        free(hash->storage);
    }
}
