public class JSONParser {
    private static final Map<String, Function<JSONObject, ?>> factoryRegistry = new HashMap<>();

    public static void addFactory(String id, Function<JSONObject, ?> factory) {
        factoryRegistry.put(id, factory);
    }

    public static <T extends JSONParser> T createInstance(String id, JSONObject json) throws Exception {
        Function<JSONObject, T> factory = (Function<JSONObject, T>) factoryRegistry.get(id);
        if (factory == null) {
            throw new IllegalArgumentException("No such factory: " + id);
        }
        return factory.apply(json);
    }

    public static String toJsonString(Object object) throws Exception {
        JSONObject json = new JSONObject();
        json.put("data", object);
        return json.toString();
    }

    public static void startService() {
        // Start the service with a random delay between starts
        int delay = (int)(Math.random() * 60) + 1;
        System.out.println("Starting service in " + delay + " seconds");
        try {
            Thread.sleep(delay * 1000);
            // Send a message to the messaging system when the service is stopped
            System.out.println("Service stopped");
        } catch (InterruptedException e) {
            // Do nothing
        }
    }
}
