// Define the severity levels for the log messages
#define LOG_ERROR   1
#define LOG_WARNING 2
#define LOG_INFO    3

// Define a struct to store the log file and its associated metadata
typedef struct {
    FILE *logFile;
    char *fileName;
} LogFile;

// Function to open the log file and initialize the LogFile struct
int openLogFile(const char *fileName, LogFile **logFile) {
    // Allocate memory for the LogFile struct
    LogFile *file = malloc(sizeof(LogFile));
    if (file == NULL) {
        printf("Failed to allocate memory for log file\n");
        return -1;
    }

    // Open the log file and check for errors
    file->logFile = fopen(fileName, "a+");
    if (file->logFile == NULL) {
        printf("Failed to open log file: %s\n", fileName);
        return -1;
    }

    // Store the file name in the LogFile struct
    file->fileName = strdup(fileName);

    // Return a pointer to the LogFile struct
    *logFile = file;
    return 0;
}

// Function to write a log entry to the log file
int writeLogEntry(const char *format, va_list args, LogFile *logFile) {
    // Check for NULL arguments and errors opening the log file
    if (logFile == NULL || logFile->logFile == NULL) {
        printf("Failed to open log file\n");
        return -1;
    }

    // Create a buffer to store the formatted message
    char *buffer = malloc(1024);
    if (buffer == NULL) {
        printf("Failed to allocate memory for log entry\n");
        return -1;
    }

    // Format the message using vsnprintf
    int result = vsnprintf(buffer, 1024, format, args);
    if (result < 0) {
        printf("Failed to format log entry: %s\n", strerror(errno));
        free(buffer);
        return -1;
    }

    // Write the message to the log file
    result = fprintf(logFile->logFile, "%s", buffer);
    if (result < 0) {
        printf("Failed to write log entry: %s\n", strerror(errno));
        free(buffer);
        return -1;
    }

    // Close the log file and free the buffer
    fclose(logFile->logFile);
    free(buffer);
    return 0;
}

// Function to close the log file and clean up resources
void closeLogFile(LogFile *logFile) {
    if (logFile != NULL && logFile->logFile != NULL) {
        fclose(logFile->logFile);
        free(logFile->fileName);
        free(logFile);
    }
}

// Function to handle errors and clean up resources on failure
void errorHandler(LogFile *logFile, int result, const char *message) {
    if (result < 0) {
        printf("%s\n", message);
        closeLogFile(logFile);
    }
}

// Implement the logCondition function
int logCondition(const char *condition, int severity, const char *format, ...) {
    // Check for NULL arguments and errors opening the log file
    if (condition == NULL || format == NULL) {
        printf("Invalid argument\n");
        return -1;
    }

    // Create a variable to store the result of openLogFile
    int result = 0;

    // Allocate memory for the LogFile struct and initialize it
    LogFile *logFile = NULL;
    result = openLogFile("log.txt", &logFile);
    errorHandler(logFile, result, "Failed to open log file");

    // Create a va_list to store the additional arguments
    va_list args;
    va_start(args, format);

    // Format the message using vsnprintf and write it to the log file
    result = writeLogEntry(format, args, logFile);
    errorHandler(logFile, result, "Failed to write log entry");

    // Close the log file and clean up resources
    closeLogFile(logFile);

    // Return 0 on success or -1 on failure
    return result;
}
