using System;
using System.Security.Cryptography;
using System.Text;

namespace HashGenerator
{
    public class HashGenerator
    {
        private static readonly Dictionary<string, Func<byte[], string>> hashAlgorithms = new Dictionary<string, Func<byte[], string>>()
        {
            ["md5"] = (input) => GenerateMd5(input),
            ["sha1"] = (input) => GenerateSha1(input),
            ["sha256"] = (input) => GenerateSha256(input),
        };

        public static string GenerateHash(string input, string algorithm)
        {
            if (!hashAlgorithms.ContainsKey(algorithm))
            {
                throw new ArgumentException($"Invalid hash algorithm: {algorithm}");
            }

            return hashAlgorithms[algorithm](Encoding.UTF8.GetBytes(input));
        }

        public static string GenerateHash(byte[] input, string algorithm)
        {
            if (!hashAlgorithms.ContainsKey(algorithm))
            {
                throw new ArgumentException($"Invalid hash algorithm: {algorithm}");
            }

            return hashAlgorithms[algorithm](input);
        }

        private static string GenerateMd5(byte[] input)
        {
            using (var md5 = MD5.Create())
            {
                var hash = md5.ComputeHash(input);
                return BitConverter.ToString(hash).Replace("-", "");
            }
        }

        private static string GenerateSha1(byte[] input)
        {
            using (var sha1 = SHA1.Create())
            {
                var hash = sha1.ComputeHash(input);
                return BitConverter.ToString(hash).Replace("-", "");
            }
        }

        private static string GenerateSha256(byte[] input)
        {
            using (var sha256 = SHA256.Create())
            {
                var hash = sha256.ComputeHash(input);
                return BitConverter.ToString(hash).Replace("-", "");
            }
        }
    }
}
