#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>

class ImageConverter {
public:
    // Constructor with quality level and logging configuration parameters
    ImageConverter(int quality, bool logToFile) : quality_(quality), logToFile_(logToFile) {}

    // ConvertAndSave method that takes an input image file path, an output file path, and a format type as parameters.
    void convertAndSave(const std::string& inputPath, const std::string& outputPath, ImageFormat format) {
        // Load the third-party library dynamically at runtime to avoid hard-coding dependencies.
        dlopen("libImageMagick.so", RTLD_LAZY);

        // Initialize the conversion status to success by default.
        bool conversionStatus = true;

        // Perform the conversion using ImageMagick.
        try {
            Image* image = Image::create(inputPath);
            image->write(outputPath, format, quality_);
            delete image;
        } catch (std::exception& e) {
            std::cerr << "Error converting image: " << e.what() << std::endl;
            conversionStatus = false;
        }

        // Log the conversion status and any encountered errors.
        if (logToFile_) {
            std::ofstream logFile("ImageConverter.log", std::ios::app);
            logFile << "Conversion status: " << conversionStatus << std::endl;
            if (!conversionStatus) {
                logFile << "Error message: " << e.what() << std::endl;
            }
        } else {
            std::cout << "Conversion status: " << conversionStatus << std::endl;
            if (!conversionStatus) {
                std::cerr << "Error message: " << e.what() << std::endl;
            }
        }
    }

    // Batch convertAndSave method that takes a list of input image paths and their corresponding output paths and formats as parameters.
    void batchConvertAndSave(const std::vector<std::string>& inputPaths, const std::vector<std::string>& outputPaths, const std::vector<ImageFormat>& formats) {
        // Initialize the conversion status to success by default.
        bool conversionStatus = true;

        // Perform the batch conversion using multiple threads.
        int numThreads = 4;
        std::mutex lock;
        std::condition_variable cv;
        std::vector<std::thread> threads;
        for (int i = 0; i < inputPaths.size(); i++) {
            threads.push_back(std::thread([&]() {
                // Lock the mutex to ensure thread safety and efficient resource management.
                std::unique_lock<std::mutex> lk(lock);
                convertAndSave(inputPaths[i], outputPaths[i], formats[i]);
                cv.notify_one();
            }));
        }

        // Wait for all threads to complete and check if any of them encountered errors.
        for (int i = 0; i < numThreads; i++) {
            cv.wait(lk);
            if (!conversionStatus) break;
        }

        // Log the batch conversion status and any encountered errors.
        if (logToFile_) {
            std::ofstream logFile("ImageConverter.log", std::ios::app);
            logFile << "Batch conversion status: " << conversionStatus << std::endl;
            if (!conversionStatus) {
                logFile << "Error message: Batch conversion encountered errors." << std::endl;
            }
        } else {
            std::cout << "Batch conversion status: " << conversionStatus << std::endl;
            if (!conversionStatus) {
                std::cerr << "Error message: Batch conversion encountered errors." << std::endl;
            }
        }
    }

    // GetConversionStatus method that returns the status of the conversion process (success or failure) without throwing exceptions.
    bool getConversionStatus() {
        return conversionStatus_;
    }

private:
    int quality_;
    bool logToFile_;
    bool conversionStatus_ = true;
};
```
