Here is a possible implementation of the `asyncArrayReduce` function in JavaScript:
```
const asyncArrayReduce = (array, initialValue, callback) => {
  // Semaphore to limit concurrency level
  const semaphore = new Semaphore(5);

  // Initialize accumulated value and current index
  let acc = initialValue;
  let i = 0;

  // Create a promise for each element in the array
  const promises = array.map((element) => {
    return new Promise((resolve, reject) => {
      semaphore.acquire(() => {
        callback(acc, element).then((result) => {
          acc = result;
          resolve();
        }).catch((error) => {
          reject(error);
        });
      });
    });
  });

  // Wait for all promises to be resolved before returning the final value
  return Promise.all(promises).then(() => {
    return acc;
  }).catch((error) => {
    throw error;
  });
};
```
