import hashlib
import requests
from flask import Flask, request, jsonify

app = Flask(__name__)

# Third-party authentication service for securing access to the resource update endpoint
auth_service_url = "https://example.com/auth"
auth_service_username = "my_user"
auth_service_password = "my_password"

# External storage service for fetching file metadata
storage_service_url = "http://example.com/storage/files/"

@app.route("/resource", methods=["PUT"])
def update_resource():
    # Validate input parameters and fetch file metadata from external storage service
    resource_id = request.json.get("resource_id")
    file_path = request.json.get("file_path")
    if not resource_id or not file_path:
        return jsonify({"message": "Invalid input parameters"}), 400

    try:
        # Fetch file metadata from external storage service
        response = requests.get(storage_service_url + file_path)
        if response.status_code == 200:
            file_metadata = response.json()

            # Check if file exists and is accessible
            if not file_metadata or "access" not in file_metadata or file_metadata["access"] != "public":
                return jsonify({"message": f"File {file_path} does not exist or is not publicly accessible"}), 404

            # Calculate MD5 hash of the file
            with open(file_path, "rb") as f:
                md5 = hashlib.md5()
                while True:
                    chunk = f.read(1024)
                    if not chunk:
                        break
                    md5.update(chunk)
            file_hash = md5.hexdigest()

            # Update resource with new hash value
            response = requests.put(f"{auth_service_url}/resource/{resource_id}", json={"hash": file_hash})
            if response.status_code == 200:
                return jsonify({"message": f"Resource {resource_id} updated successfully"}), 200
            else:
                return jsonify({"message": f"Error updating resource {resource_id}: {response.text}"}), response.status_code
        else:
            return jsonify({"message": f"Error fetching file metadata for {file_path}: {response.text}"}), response.status_code
    except Exception as e:
        return jsonify({"message": f"Error updating resource {resource_id}: {e}"}), 500

@app.route("/hash", methods=["GET"])
def calculate_hash():
    # Validate input parameters and fetch file metadata from external storage service
    file_path = request.args.get("file_path")
    if not file_path:
        return jsonify({"message": "Invalid input parameters"}), 400

    try:
        # Fetch file metadata from external storage service
        response = requests.get(storage_service_url + file_path)
        if response.status_code == 200:
            file_metadata = response.json()

            # Check if file exists and is accessible
            if not file_metadata or "access" not in file_metadata or file_metadata["access"] != "public":
                return jsonify({"message": f"File {file_path} does not exist or is not publicly accessible"}), 404

            # Calculate MD5 hash of the file
            with open(file_path, "rb") as f:
                md5 = hashlib.md5()
                while True:
                    chunk = f.read(1024)
                    if not chunk:
                        break
                    md5.update(chunk)
            file_hash = md5.hexdigest()

            # Return hash value
            return jsonify({"message": f"File {file_path} has MD5 hash {file_hash}"}), 200
        else:
            return jsonify({"message": f"Error fetching file metadata for {file_path}: {response.text}"}), response.status_code
    except Exception as e:
        return jsonify({"message": f"Error calculating hash for {file_path}: {e}"}), 500

# Handle errors and exceptions
@app.errorhandler(Exception)
def handle_exception(e):
    # Log the error and return a generic error message to the client
    print(f"{datetime.now()} ERROR: {e}")
    return jsonify({"message": "An unexpected error occurred"}), 500

if __name__ == "__main__":
    app.run()
```

