```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

// Function to initialize AES-256-CBC cipher with given password
EVP_CIPHER_CTX* initAes256cbcCipher(const char *password, int ivLength, int keyLength) {
    // Generate a random IV and store it alongside the derived key
    unsigned char iv[ivLength];
    RAND_bytes(iv, ivLength);

    // Derive encryption key from password using SHA-256 with salted hashing
    const EVP_MD *digest = EVP_sha256();
    EVP_PKEY_CTX *pctx = EVP_PKEY_CTX_new(EVP_PKEY_HMAC, NULL);
    EVP_PKEY_CTX_set_hkdf_md(pctx, digest);
    EVP_PKEY_CTX_set_hkdf_mode(pctx, EVP_PKEY_HKDEF_MODE_EXTRACT_AND_EXPAND);
    unsigned char salt[keyLength];
    RAND_bytes(salt, keyLength);
    EVP_PKEY_CTX_set0_hkdf_salt(pctx, salt, keyLength);
    unsigned char derivedKey[EVP_MAX_KEY_LENGTH];
    int derivedKeyLen = sizeof(derivedKey);
    EVP_PKEY_derive(pctx, derivedKey, &derivedKeyLen);

    // Create AES-256-CBC cipher context and enable it
    EVP_CIPHER_CTX *cipherCtx = EVP_CIPHER_CTX_new();
    int ok = EVP_EncryptInit_ex(cipherCtx, EVP_aes_256_cbc(), NULL, derivedKey, iv);
    if (!ok) {
        printf("Error initializing AES-256-CBC cipher\n");
        return NULL;
    }

    // Store the salt and derived key alongside the cipher context
    unsigned char *saltedKey = malloc(sizeof(derivedKey) + sizeof(salt));
    memcpy(saltedKey, salt, sizeof(salt));
    memcpy(saltedKey + sizeof(salt), derivedKey, sizeof(derivedKey));
    EVP_CIPHER_CTX_set_app_data(cipherCtx, saltedKey);

    // Return the cipher context
    return cipherCtx;
}

// Function to clean up AES-256-CBC cipher and free resources
void cleanupAes256cbcCipher(EVP_CIPHER_CTX *cipherCtx) {
    // Disable the cipher and free associated resources
    int ok = EVP_EncryptFinal_ex(cipherCtx, NULL, NULL);
    if (!ok) {
        printf("Error finalizing AES-256-CBC cipher\n");
    }
    EVP_CIPHER_CTX_free(cipherCtx);
}
