    {
        private readonly Aes _aes = new Aes();
        private readonly KeyManagementSystem _keyManagementSystem = new KeyManagementSystem();

        public byte[] Encrypt(byte[] plaintext, string encryptionAlgorithm, int keySize)
        {
            var ciphertext = new byte[plaintext.Length];
            using (var encryptor = _aes.CreateEncryptor())
            {
                // Generate a dynamic encryption key and IV from the user-provided seed
                var key = _keyManagementSystem.GenerateKey(encryptionAlgorithm, keySize);
                var iv = _keyManagementSystem.GenerateIV();

                // Encrypt the plaintext using AES-CBC with the generated key and IV
                encryptor.Encrypt(plaintext, ciphertext, 0, key, iv);
            }

            return ciphertext;
        }

        public byte[] Decrypt(byte[] ciphertext, string encryptionAlgorithm, int keySize)
        {
            var plaintext = new byte[ciphertext.Length];
            using (var decryptor = _aes.CreateDecryptor())
            {
                // Generate a dynamic encryption key and IV from the user-provided seed
                var key = _keyManagementSystem.GenerateKey(encryptionAlgorithm, keySize);
                var iv = _keyManagementSystem.GenerateIV();

                // Decrypt the ciphertext using AES-CBC with the generated key and IV
                decryptor.Decrypt(ciphertext, plaintext, 0, key, iv);
            }

            return plaintext;
        }
    }
}
```
