    // Merge the value from the future object into the initial dictionary based on the source identifier
    dict* mergedDict = merge_dictionaries(initialDict, futureObj->source_id, futureObj->value);

    // Clean up any allocated resources in the future object
    free(futureObj->source_id);
    free(futureObj->value);

