// Define a structure to hold the TLS context
typedef struct {
    SSL_CTX* ctx;
    SSL* ssl;
} tls_context;

// Function to initialize a secure connection using TLS 1.3 with a given password and client certificate
tls_context* init_secure_connection(const char* password, const char* cert_file, const char* key_file) {
    // Create an SSL context object
    tls_context* ctx = malloc(sizeof(tls_context));
    if (!ctx) {
        perror("malloc");
        return NULL;
    }

    // Initialize the SSL context with TLS 1.3 and the client certificate
    ctx->ctx = SSL_CTX_new(TLSv1_3_client_method());
    if (!ctx->ctx) {
        perror("SSL_CTX_new");
        free(ctx);
        return NULL;
    }
    if (SSL_CTX_use_certificate_file(ctx->ctx, cert_file, SSL_FILETYPE_PEM) <= 0 ||
            SSL_CTX_use_privatekey_file(ctx->ctx, key_file, SSL_FILETYPE_PEM) <= 0) {
        perror("SSL_CTX_use_certificate_file");
        SSL_CTX_free(ctx->ctx);
        free(ctx);
        return NULL;
    }

    // Derive the encryption key from the password and configure the cipher suite accordingly
    if (password) {
        SSL_CTX_set_password(ctx->ctx, password);
        SSL_CTX_set_cipher_list(ctx->ctx, "HIGH:!aNULL:!MD5");
    }

    // Handle client authentication using the provided certificate and private key
    if (SSL_CTX_use_certificate_file(ctx->ctx, cert_file, SSL_FILETYPE_PEM) <= 0 ||
            SSL_CTX_use_privatekey_file(ctx->ctx, key_file, SSL_FILETYPE_PEM) <= 0) {
        perror("SSL_CTX_use_certificate_file");
        SSL_CTX_free(ctx->ctx);
        free(ctx);
        return NULL;
    }

    // Enable the TLS connection and return a pointer to the TLS context
    ctx->ssl = SSL_new(ctx->ctx);
    if (!ctx->ssl) {
        perror("SSL_new");
        SSL_CTX_free(ctx->ctx);
        free(ctx);
        return NULL;
    }
    SSL_set_fd(ctx->ssl, 0); // Set the file descriptor to stdin
    if (SSL_connect(ctx->ssl) <= 0) {
        perror("SSL_connect");
        SSL_free(ctx->ssl);
        SSL_CTX_free(ctx->ctx);
        free(ctx);
        return NULL;
    }

    // Clean up and disable the TLS connection when it is no longer needed
    atexit(cleanup_secure_connection);
    return ctx;
}

// Function to clean up and disable the TLS connection when it is no longer needed
void cleanup_secure_connection() {
    if (ctx->ssl) {
        SSL_free(ctx->ssl);
        SSL_CTX_free(ctx->ctx);
    }
}

