// Database connection pool class
class ConnectionPool {
public:
    ConnectionPool(int size) : connections_(size) {}

    std::shared_ptr<Connection> getConnection() {
        // Acquire a connection from the pool
        if (!connections_.empty()) {
            auto conn = connections_.front();
            connections_.pop_front();
            return conn;
        } else {
            // Create a new connection and add it to the pool
            auto conn = std::make_shared<Connection>();
            connections_.push_back(conn);
            return conn;
        }
    }

    void releaseConnection(std::shared_ptr<Connection> conn) {
        // Release a connection back to the pool
        if (connections_.size() < maxSize_) {
            connections_.push_back(conn);
        } else {
            // Close the excess connections
            while (connections_.size() > maxSize_) {
                connections_.pop_front();
            }
            conn->close();
        }
    }

private:
    std::list<std::shared_ptr<Connection>> connections_;
    int maxSize_ = 10; // Default pool size
};

// Log file class
class LogFile {
public:
    LogFile(const std::string& filename) : filename_(filename), ofs_(std::ofstream(filename)) {}

    void write(const std::string& str) {
        std::lock_guard<std::mutex> lock(mutex_);
        ofs_ << str;
    }

private:
    std::string filename_;
    std::ofstream ofs_;
    std::mutex mutex_;
};

