    // Prepare the transaction details as a variable argument list
    const std::string details = "12345678, 100.00";
    va_list args;
    va_start(args, details);
    for (auto arg = va_arg(args, std::string); arg != nullptr; arg = va_arg(args, std::string)) {
        args.push_back(arg);
    }
    va_end(args);

    // Record the transaction to either the database or log file
    recorder->recordTransaction(details, args);
