    public function createClinic(string $name, string $location, int $capacity) {
        // Validate input parameters
        if (empty($name)) {
            throw new InvalidArgumentException('Name is required');
        } elseif (empty($location)) {
            throw new InvalidArgumentException('Location is required');
        } elseif ($capacity < 0 || $capacity > 100) {
            throw new InvalidArgumentException('Capacity must be between 0 and 100');
        }

        // Insert clinic record into database
        $query = "INSERT INTO clinics (name, location, capacity) VALUES (:name, :location, :capacity)";
        $stmt = $this->db->prepare($query);
        $stmt->bindValue(':name', $name, PDO::PARAM_STR);
        $stmt->bindValue(':location', $location, PDO::PARAM_STR);
        $stmt->bindValue(':capacity', $capacity, PDO::PARAM_INT);
        $stmt->execute();

        // Notify external API and emergency response team if necessary
        $this->notifyExternalAPI($name);
    }

    public function updateClinic(int $id, string $status, string $lastModifiedIpAddress, DateTimeInterface $lastModifiedDate) {
        // Validate input parameters
        if ($id < 0 || $id > 100000) {
            throw new InvalidArgumentException('ID must be between 0 and 100000');
        } elseif (empty($status)) {
            throw new InvalidArgumentException('Status is required');
        } elseif (empty($lastModifiedIpAddress)) {
            throw new InvalidArgumentException('Last modified IP address is required');
        }

        // Update clinic record in database
        $query = "UPDATE clinics SET status = :status, last_modified_ip_address = :last_modified_ip_address, last_modified_date = :last_modified_date WHERE id = :id";
        $stmt = $this->db->prepare($query);
        $stmt->bindValue(':id', $id, PDO::PARAM_INT);
        $stmt->bindValue(':status', $status, PDO::PARAM_STR);
        $stmt->bindValue(':last_modified_ip_address', $lastModifiedIpAddress, PDO::PARAM_STR);
        $stmt->bindValue(':last_modified_date', $lastModifiedDate->format('Y-m-d H:i:s'), PDO::PARAM_STR);
        $stmt->execute();

        // Handle status change as necessary
        if ($status === 'closed' || $status === 'emergency') {
            $this->notifyExternalAPI($name);
            $this->updateOccupancyLevels();
        } elseif ($status === 'open') {
            $this->reScheduleAppointments();
        }
    }

    public function deleteClinic(int $id) {
        // Validate input parameter
        if ($id < 0 || $id > 100000) {
            throw new InvalidArgumentException('ID must be between 0 and 100000');
        }

        // Delete clinic record from database
        $query = "DELETE FROM clinics WHERE id = :id";
        $stmt = $this->db->prepare($query);
        $stmt->bindValue(':id', $id, PDO::PARAM_INT);
        $stmt->execute();
    }

    private function notifyExternalAPI(string $name) {
        // Notify external API and emergency response team via email
        $this->apiClient->notify($name);
    }

    private function updateOccupancyLevels() {
        // Get current IoT sensor data and update clinic capacity accordingly
        $query = "SELECT * FROM iot_sensors WHERE clinic_id = :clinic_id";
        $stmt = $this->db->prepare($query);
        $stmt->bindValue(':clinic_id', $clinicId, PDO::PARAM_INT);
        $stmt->execute();
