        // Calculate occupancy levels and update clinic record
        foreach ($sensorData as $data) {
            $occupancyLevel = $this->calculateOccupancyLevel($data['temperature'], $data['humidity'], $data['light']);
            $query = "UPDATE clinics SET occupancy_level = :occupancy_level WHERE id = :clinic_id";
            $stmt = $this->db->prepare($query);
            $stmt->bindValue(':occupancy_level', $occupancyLevel, PDO::PARAM_INT);
            $stmt->bindValue(':clinic_id', $clinicId, PDO::PARAM_INT);
            $stmt->execute();
        }
