using System;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;

namespace WebsiteManager
{
    public class WebsiteManagerService : IWebsiteManagerService
    {
        private readonly ILogger<WebsiteManagerService> _logger;
        private readonly IConfiguration _configuration;

        public WebsiteManagerService(ILogger<WebsiteManagerService> logger, IConfiguration configuration)
        {
            _logger = logger;
            _configuration = configuration;
        }

        public async Task AddSiteAsync(string directoryPath, string siteName)
        {
            // 1. Check if a web.config file exists in the directory before adding the site
            if (!Directory.Exists(directoryPath))
            {
                _logger.LogError($"Directory does not exist: {directoryPath}");
                return;
            }

            var configFile = Path.Combine(directoryPath, "web.config");
            if (!File.Exists(configFile))
            {
                _logger.LogError($"No web.config file found in directory: {directoryPath}");
                return;
            }

            // 2. Create a unique site name if the provided site name already exists within the directory
            var existingSiteNames = Directory.EnumerateFiles(directoryPath, "*.csproj", SearchOption.TopDirectoryOnly).Select(f => Path.GetFileNameWithoutExtension(f));
            if (existingSiteNames.Any(s => s == siteName))
            {
                var newSiteName = $"{siteName}{Guid.NewGuid():N}";
                _logger.LogInformation($"Site name already exists, creating unique name: {newSiteName}");
                siteName = newSiteName;
            }

            // 3. Validate that the directory path is valid and accessible
            if (!Directory.Exists(directoryPath))
            {
                _logger.LogError($"Invalid directory path: {directoryPath}");
                return;
            }

            // 4. Integrate with an external configuration database to retrieve additional settings for the site
            var settings = await _configuration.GetSection("Websites").Get<SiteSettings>(siteName);

            // 5. Handle errors gracefully, including but not limited to invalid paths, missing files, and process start failures
            try
            {
                // 6. Ensure proper resource management and cleanup after the site has been added and started
                using (var process = new Process())
                {
                    var startupPath = Path.Combine(directoryPath, $"{siteName}.exe");
                    if (!File.Exists(startupPath))
                    {
                        _logger.LogError($"Startup path does not exist: {startupPath}");
                        return;
                    }

                    process.StartInfo = new ProcessStartInfo(startupPath, $"/port:{settings.Port} /parameters:{settings.Parameters}")
                    {
                        UseShellExecute = false,
                        CreateNoWindow = true,
                        RedirectStandardOutput = true,
                        RedirectStandardError = true
                    };

                    process.Start();

                    // 7. Log all actions and errors to a centralized logging service
                    _logger.LogInformation($"Site {siteName} started successfully");
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Failed to start site {siteName}: {ex.Message}");
            }
        }
    }
}
