function extractBooks(text) {
  // Define regular expressions for matching book names
  const oldTestamentRegex = /(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)/gi;
  const newTestamentRegex = /(Matthew|Mark|Luke|John|Acts|Romans|1 Corinthians|2 Corinthians|Galatians|Ephesians|Philippians|Colossians|1 Thessalonians|2 Thessalonians|1 Timothy|2 Timothy|Titus|Philemon|Hebrews|James|1 Peter|2 Peter|1 John|2 John|3 John|Jude|Revelation)/gi;
  // Define a map to store the extracted books and their counts
  const bookMap = {};
  // Split the text into individual words
  const words = text.split(' ');
  // Iterate over each word in the text
  words.forEach((word) => {
    // Check if the word matches any of the regular expressions for Old or New Testament books
    if (oldTestamentRegex.test(word)) {
      // Increment the count for the corresponding book
      const book = oldTestamentRegex.exec(word)[0];
      bookMap[book] = (bookMap[book] || 0) + 1;
    } else if (newTestamentRegex.test(word)) {
      // Increment the count for the corresponding book
      const book = newTestamentRegex.exec(word)[0];
      bookMap[book] = (bookMap[book] || 0) + 1;
    }
  });
  // Return the map of books and their counts
  return bookMap;
}

