async function runTests(moduleLabel, testLabels, testFunctions, dataSources, cleanupFunctions) {
  const module = require(moduleLabel);

  for (const [testIndex, testLabel] of testLabels.entries()) {
    console.log(`Running test ${testIndex + 1}: ${testLabel}`);

    // Fetch data from data sources
    let data;
    try {
      data = await Promise.all(dataSources.map((dataSource) => dataSource.fetch()));
    } catch (error) {
      console.log(`Error fetching data: ${error.message}`);
      continue;
    }

    // Run test function
    try {
      const result = await testFunctions[testIndex](module, data);
      console.log(`Test ${testIndex + 1} passed`);
      if (result) {
        console.log(result);
      }
    } catch (error) {
      console.log(`Error running test: ${error.message}`);
    }

    // Clean up resources
    try {
      await Promise.all(cleanupFunctions.map((cleanupFunction) => cleanupFunction()));
    } catch (error) {
      console.log(`Error cleaning up resources: ${error.message}`);
    }
  }

  // Reset mocking library
  blueslip.reset();
}
