#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <errno.h>

// Constants
#define MAX_SEMAPHORES 100
#define SEM_NAME_MAX_LENGTH 256
#define LOG_FILE "semaphore_log.txt"

// Structs
typedef struct {
    char name[SEM_NAME_MAX_LENGTH];
    int value;
} semaphore_t;

// Global variables
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
semaphore_t semaphores[MAX_SEMAPHORES];
int num_semaphores = 0;
FILE *log_file;

// Function declarations
void create_semaphore(char* name, int value);
void delete_semaphore(char* name);
void increment_semaphore(char* name);
void decrement_semaphore(char* name);
int get_semaphore_value(char* name);
void log_operation(char* operation, char* semaphore);

// Main function
int main() {
    // Open the log file for writing
    log_file = fopen(LOG_FILE, "w");

    // Create a semaphore named "semaphore1" with an initial value of 0
    create_semaphore("semaphore1", 0);

    // Delete the "semaphore2" semaphore
    delete_semaphore("semaphore2");

    // Increment the "semaphore3" semaphore by 5
    increment_semaphore("semaphore3", 5);

    // Decrement the "semaphore4" semaphore by 10
    decrement_semaphore("semaphore4", 10);

    // Get the current value of the "semaphore5" semaphore
    printf("Semaphore5 Value: %d\n", get_semaphore_value("semaphore5"));

    return 0;
}

// Function definitions
void create_semaphore(char* name, int value) {
    // Check if the semaphore already exists
    for (int i = 0; i < num_semaphores; i++) {
        if (strcmp(name, semaphores[i].name) == 0) {
            printf("Semaphore %s already exists!\n", name);
            return;
        }
    }

    // If the semaphore doesn't exist, create it and log the operation
    pthread_mutex_lock(&mutex);
    if (num_semaphores < MAX_SEMAPHORES) {
        strcpy(semaphores[num_semaphores].name, name);
        semaphores[num_semaphores].value = value;
        num_semaphores++;
        log_operation("create", name);
    } else {
        printf("Maximum number of semaphores reached!\n");
    }
    pthread_mutex_unlock(&mutex);
}

void delete_semaphore(char* name) {
    // Find the index of the semaphore to be deleted
    int index = -1;
    for (int i = 0; i < num_semaphores; i++) {
        if (strcmp(name, semaphores[i].name) == 0) {
            index = i;
            break;
        }
    }

    // If the semaphore is found, delete it and log the operation
    pthread_mutex_lock(&mutex);
    if (index != -1) {
        for (int i = index; i < num_semaphores - 1; i++) {
            strcpy(semaphores[i].name, semaphores[i + 1].name);
            semaphores[i].value = semaphores[i + 1].value;
        }
        num_semaphores--;
        log_operation("delete", name);
    } else {
        printf("Semaphore %s does not exist!\n", name);
    }
    pthread_mutex_unlock(&mutex);
}

void increment_semaphore(char* name, int value) {
    // Find the index of the semaphore to be incremented
    int index = -1;
    for (int i = 0; i < num_semaphores; i++) {
        if (strcmp(name, semaphores[i].name) == 0) {
            index = i;
            break;
        }
    }

    // If the semaphore is found, increment it and log the operation
    pthread_mutex_lock(&mutex);
    if (index != -1) {
        semaphores[index].value += value;
        log_operation("increment", name);
    } else {
        printf("Semaphore %s does not exist!\n", name);
    }
    pthread_mutex_unlock(&mutex);
}

void decrement_semaphore(char* name, int value) {
    // Find the index of the semaphore to be decremented
    int index = -1;
    for (int i = 0; i < num_semaphores; i++) {
        if (strcmp(name, semaphores[i].name) == 0) {
            index = i;
            break;
        }
    }

    // If the semaphore is found, decrement it and log the operation
    pthread_mutex_lock(&mutex);
    if (index != -1) {
        semaphores[index].value -= value;
        log_operation("decrement", name);
    } else {
        printf("Semaphore %s does not exist!\n", name);
    }
    pthread_mutex_unlock(&mutex);
}

int get_semaphore_value(char* name) {
    // Find the index of the semaphore to be queried
    int index = -1;
    for (int i = 0; i < num_semaphores; i++) {
        if (strcmp(name, semaphores[i].name) == 0) {
            index = i;
            break;
        }
    }

    // If the semaphore is found, return its value
    pthread_mutex_lock(&mutex);
    if (index != -1) {
        int value = semaphores[index].value;
        pthread_mutex_unlock(&mutex);
        return value;
    } else {
        printf("Semaphore %s does not exist!\n", name);
        return 0;
    }
}

void log_operation(char* operation, char* semaphore) {
    // Log the operation and the corresponding semaphore name
    fprintf(log_file, "%s: %s\n", operation, semaphore);
}

