#include <openssl/des.h>
#include <openssl/evp.h>
#include <stdbool.h>
#include <string.h>

typedef struct {
    EVP_CIPHER *cipher;
    unsigned char key[8];
    unsigned char iv[8];
    size_t iv_len;
} cipher_config;

static bool is_valid_key(const unsigned char *key, size_t key_len) {
    return key_len == 8 || key_len == 24 || key_len == 32;
}

static bool is_valid_iv(const unsigned char *iv, size_t iv_len) {
    return iv_len == 8 || iv_len == 16 || iv_len == 24;
}

static int get_cipher_type(const char *cipher_name) {
    if (strcmp(cipher_name, "ECB") == 0) {
        return EVP_CIPH_ECB_MODE;
    } else if (strcmp(cipher_name, "EDE") == 0) {
        return EVP_CIPH_EDE_MODE;
    } else if (strcmp(cipher_name, "EDE3") == 0) {
        return EVP_CIPH_EDE3_MODE;
    } else if (strcmp(cipher_name, "CFB") == 0) {
        return EVP_CIPH_CFB_MODE;
    } else {
        return -1;
    }
}

static int get_iv_len(const char *iv_len) {
    if (strcmp(iv_len, "8") == 0) {
        return 8;
    } else if (strcmp(iv_len, "16") == 0) {
        return 16;
    } else if (strcmp(iv_len, "24") == 0) {
        return 24;
    } else {
        return -1;
    }
}

static EVP_CIPHER *get_cipher(const char *cipher_name) {
    int cipher_type = get_cipher_type(cipher_name);
    if (cipher_type == -1) {
        return NULL;
    }
    return EVP_get_cipherbyname(cipher_name);
}

cipher_config *create_cipher_config(const char *cipher_name, const unsigned char *key, size_t key_len, const unsigned char *iv, size_t iv_len) {
    if (!is_valid_key(key, key_len)) {
        return NULL;
    }
    if (iv != NULL && !is_valid_iv(iv, iv_len)) {
        return NULL;
    }
    cipher_config *config = malloc(sizeof(cipher_config));
    config->cipher = get_cipher(cipher_name);
    if (config->cipher == NULL) {
        free(config);
        return NULL;
    }
    memcpy(config->key, key, key_len);
    if (iv != NULL) {
        memcpy(config->iv, iv, iv_len);
    } else {
        // Generate random IV for CFB mode
        RAND_bytes(config->iv, 8);
    }
    config->iv_len = iv_len;
    return config;
}

void destroy_cipher_config(cipher_config *config) {
    EVP_CIPHER_CTX_free(config->cipher);
    free(config);
}

int encrypt_data(const unsigned char *plaintext, size_t plaintext_len, cipher_config *config) {
    if (plaintext == NULL || plaintext_len == 0 || config == NULL) {
        return -1;
    }
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int ret = EVP_EncryptInit_ex(ctx, config->cipher, NULL, config->key, config->iv);
    if (ret != 1) {
        return -2;
    }
    unsigned char *ciphertext = malloc(plaintext_len + AES_BLOCK_SIZE);
    int len = plaintext_len;
    while (len > 0) {
        int chunk = len < AES_BLOCK_SIZE ? len : AES_BLOCK_SIZE;
        ret = EVP_EncryptUpdate(ctx, ciphertext + (plaintext_len - len), &chunk, plaintext + (plaintext_len - len), chunk);
        if (ret != 1) {
            return -3;
        }
        len -= chunk;
    }
    ret = EVP_EncryptFinal_ex(ctx, ciphertext + (plaintext_len - len), &chunk);
    if (ret != 1) {
        return -4;
    }
    memcpy(plaintext, ciphertext, plaintext_len + AES_BLOCK_SIZE);
    free(ciphertext);
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

int decrypt_data(const unsigned char *ciphertext, size_t ciphertext_len, cipher_config *config) {
    if (ciphertext == NULL || ciphertext_len == 0 || config == NULL) {
        return -1;
    }
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int ret = EVP_DecryptInit_ex(ctx, config->cipher, NULL, config->key, config->iv);
    if (ret != 1) {
        return -2;
    }
    unsigned char *plaintext = malloc(ciphertext_len + AES_BLOCK_SIZE);
    int len = ciphertext_len;
    while (len > 0) {
        int chunk = len < AES_BLOCK_SIZE ? len : AES_BLOCK_SIZE;
        ret = EVP_DecryptUpdate(ctx, plaintext + (ciphertext_len - len), &chunk, ciphertext + (ciphertext_len - len), chunk);
        if (ret != 1) {
            return -3;
        }
        len -= chunk;
    }
    ret = EVP_DecryptFinal_ex(ctx, plaintext + (ciphertext_len - len), &chunk);
    if (ret != 1) {
        return -4;
    }
    memcpy(plaintext, ciphertext, ciphertext_len + AES_BLOCK_SIZE);
    free(plaintext);
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}
