package com.example;

import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.AsynchronousServerSocketChannel;
import java.nio.channels.AsynchronousSocketChannel;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerRecord;

public class ConnectionManager {
  private static final int MAX_CONNECTIONS = 1000;
  private static final int KAFKA_BATCH_SIZE = 1000;

  private AsynchronousServerSocketChannel serverSocket;
  private ExecutorService executor;
  private KafkaProducer<String, String> producer;

  public ConnectionManager() throws IOException {
    serverSocket = AsynchronousServerSocketChannel.open();
    serverSocket.bind(new InetSocketAddress("localhost", 8080));
    executor = Executors.newFixedThreadPool(MAX_CONNECTIONS);
    producer = new KafkaProducer<>(/* kafka configuration */);
  }

  public void start() throws IOException {
    serverSocket.accept(null, new CompletableFuture<>());
    while (true) {
      executor.submit(() -> handleConnection(serverSocket.accept()));
    }
  }

  private void handleConnection(AsynchronousSocketChannel channel) {
    try {
      String clientAddress = channel.getRemoteAddress().toString();
      log("Connected to " + clientAddress);

      // Read data from the client
      ByteBuffer buffer = ByteBuffer.allocate(1024);
      CompletableFuture<Integer> readFuture = new CompletableFuture<>();
      channel.read(buffer, buffer, readFuture);

      // Process data and send response
      String message = new String(buffer.array()).trim();
      log("Received message: " + message);
      ProducerRecord<String, String> record = new ProducerRecord<>("my-topic", clientAddress, message);
      producer.send(record, (metadata, exception) -> {
        if (exception != null) {
          log("Error sending message to Kafka: " + exception);
        } else {
          log("Message sent to Kafka");
        }
      });

      // Send response back to the client
      buffer.clear();
      String response = "Hello, " + message;
      ByteBuffer responseBuffer = ByteBuffer.wrap(response.getBytes());
      CompletableFuture<Integer> writeFuture = new CompletableFuture<>();
      channel.write(responseBuffer, responseBuffer, writeFuture);

      // Close the connection
      readFuture.thenCompose((unused) -> {
        return writeFuture;
      }).thenAccept((unused) -> {
        channel.close();
        log("Disconnected from " + clientAddress);
      });
    } catch (IOException | InterruptedException e) {
      log("Error handling connection: " + e);
    }
  }

  private void log(String message) {
    System.out.println(message);
  }
}

