using System;
using System.Security.Cryptography;

namespace TripleDesDecryptor
{
    public class TripleDesDecryptor
    {
        private readonly string _cspName;
        private readonly Dictionary<string, Tuple<byte[], byte[]>> _keysAndIvs = new();
        private readonly object _syncRoot = new();

        public TripleDesDecryptor(string cspName)
        {
            _cspName = cspName;
        }

        public void AddKey(string keyId, byte[] key, byte[] iv)
        {
            lock (_syncRoot)
            {
                if (!_keysAndIvs.ContainsKey(keyId))
                {
                    _keysAndIvs[keyId] = new Tuple<byte[], byte[]>(key, iv);
                }
            }
        }

        public void RemoveKey(string keyId)
        {
            lock (_syncRoot)
            {
                if (_keysAndIvs.ContainsKey(keyId))
                {
                    _keysAndIvs.Remove(keyId);
                }
            }
        }

        public byte[] DecryptMessage(string keyId, string message, int clearanceLevel)
        {
            lock (_syncRoot)
            {
                if (!_keysAndIvs.ContainsKey(keyId))
                {
                    // Fetch the key and IV from the CSP using the specified key ID
                    var csp = new CryptoServiceProvider(_cspName);
                    var key = csp.GetKey(keyId);
                    var iv = csp.GetIV(keyId);

                    // Add the fetched key and IV to the internal dictionary for future use
                    _keysAndIvs[keyId] = new Tuple<byte[], byte[]>(key, iv);
                }

                // Decrypt the message using the specified key and IV
                var des = new TripleDES();
                des.Key = _keysAndIvs[keyId].Item1;
                des.IV = _keysAndIvs[keyId].Item2;
                return des.Decrypt(Convert.FromBase64String(message));
            }
        }
    }
}

