```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <dirent.h>
#include <pthread.h>

// Struct to hold information about a JPEG file and its corresponding PDF file
struct jpeg_pdf_pair {
  char *jpeg_file;
  char *pdf_file;
};

// Function to convert a single JPEG file to PDF using the third-party tool
int convert_jpeg_to_pdf(const char *jpeg_file, const char *output_dir) {
  // Create the command to execute the conversion tool
  char *cmd = malloc(strlen(jpeg_file) + strlen(output_dir) + 3);
  sprintf(cmd, "convert -quality 100 %s %s.pdf", jpeg_file, output_dir);

  // Execute the command and check for errors
  int status = system(cmd);
  if (status != 0) {
    fprintf(stderr, "Error converting JPEG to PDF: %s\n", strerror(errno));
    return -1;
  }

  // Clean up the command string
  free(cmd);

  return 0;
}

// Function to convert multiple JPEG files to PDF using the third-party tool in parallel
int convert_jpegs_to_pdf(const char *input_dir, const char *output_dir) {
  // Create a list of all JPEG files in the input directory
  DIR *d = opendir(input_dir);
  if (d == NULL) {
    fprintf(stderr, "Error opening directory %s: %s\n", input_dir, strerror(errno));
    return -1;
  }

  struct jpeg_pdf_pair *jpgs = malloc(sizeof(struct jpeg_pdf_pair) * 20);
  int num_jpgs = 0;

  // Loop over all files in the directory and add them to the list if they are JPEGs
  struct dirent *entry;
  while ((entry = readdir(d)) != NULL) {
    char *filename = entry->d_name;
    if (strlen(filename) > 4 && strcmp(filename + strlen(filename) - 4, ".jpg") == 0) {
      jpgs[num_jpgs].jpeg_file = filename;
      jpgs[num_jpgs].pdf_file = malloc(strlen(output_dir) + strlen(filename) + 1);
      sprintf(jpgs[num_jpgs].pdf_file, "%s%s.pdf", output_dir, filename);
      num_jpgs++;
    }
  }

  // Create a thread for each JPEG file and convert it to PDF using the third-party tool
  pthread_t *threads = malloc(sizeof(pthread_t) * num_jpgs);
  int i;
  for (i = 0; i < num_jpgs; i++) {
    char *jpeg_file = jpgs[i].jpeg_file;
    char *pdf_file = jpgs[i].pdf_file;
    pthread_create(&threads[i], NULL, convert_jpeg_to_pdf, (void *)jpeg_file, (void *)output_dir);
  }

  // Wait for all threads to finish and check for errors
  for (i = 0; i < num_jpgs; i++) {
    pthread_join(threads[i], NULL);
  }

  // Clean up memory
  free(threads);
  free(jpgs);

  return 0;
}
