            if (string.IsNullOrEmpty(newValue))
                return BadRequest();

            // Check if configuration exists for the given user
            var configuration = await _configService.GetConfigurationAsync(userId, configurationName);
            if (configuration == null)
                return NotFound();

            // Update configuration using service class
            try
            {
                await _configService.UpdateConfigurationAsync(userId, configurationName, newValue);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to update configuration");
                return StatusCode(500);
            }

            // Return response indicating whether the update was successful
            if (await _configService.GetConfigurationAsync(userId, configurationName).ConfigureAwait(false) == null)
                return BadRequest();

            return Ok();
        }
    }
}
```
