// Dynamic Server Configuration
public class ServerConfig {
    private static final String JSON_FILE = "server-config.json";

    public static Map<String, ServerDetails> getServerDetails() throws IOException {
        JsonReader reader = new JsonReader(new FileReader(JSON_FILE));
        Map<String, ServerDetails> servers = new HashMap<>();
        reader.beginObject();
        while (reader.hasNext()) {
            String serverName = reader.nextName();
            ServerDetails details = new ServerDetails();
            details.setIpAddress(reader.nextString());
            details.setPortNumber(Integer.parseInt(reader.nextString()));
            details.setUsername(reader.nextString());
            details.setPassword(reader.nextString());
            servers.put(serverName, details);
        }
        reader.endObject();
        return servers;
    }
}

// Command Execution with Timeouts
public class CommandExecutor {
    private static final int TIMEOUT = 10; // seconds

    public static void executeCommands(Map<String, ServerDetails> servers) throws IOException, InterruptedException {
        for (ServerDetails server : servers.values()) {
            String command = "ls -l";
            CommandResult result = executeCommand(server.getIpAddress(), server.getPortNumber(), server.getUsername(), server.getPassword(), command);
            if (result != null && result.isSuccessful()) {
                System.out.println("Command executed successfully on " + server.getServerName());
            } else {
                System.err.println("Failed to execute command on " + server.getServerName());
            }
        }
    }

    private static CommandResult executeCommand(String ipAddress, int portNumber, String username, String password, String command) throws IOException, InterruptedException {
        // Set up SSH connection with timeout
        Socket socket = new Socket();
        try {
            socket.connect(new InetSocketAddress(ipAddress, portNumber), TIMEOUT * 1000);
        } catch (SocketTimeoutException e) {
            System.err.println("Connection timed out");
            return null;
        }

        // Execute command and close connection
        BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream()));
        BufferedReader reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));
        writer.write("ssh " + username + "@" + ipAddress + " -p " + portNumber + "\n");
        writer.flush();
        writer.write(command + "\n");
        writer.flush();
        String output = reader.readLine();
        socket.close();

        // Handle command execution failures and retry up to three times with exponential backoff
        if (output == null || !output.startsWith("Login successful")) {
            System.err.println("Failed to execute command on " + ipAddress);
            return null;
        } else {
            return new CommandResult(output, serverName);
        }
    }
}

// Real-time Logging and Monitoring
public class Logger {
    private static final String LOG_FILE = "log.txt";

    public static void logCommandOutput(String output) throws IOException {
        BufferedWriter writer = new BufferedWriter(new FileWriter(LOG_FILE, true));
        writer.write("[" + LocalDateTime.now() + "] " + output);
        writer.newLine();
        writer.close();
    }
}

// Resource Management and Scalability
public class ServerManager {
    private static final int CONCURRENCY = 5; // number of concurrent SSH connections
    private static final int MAX_ATTEMPTS = 3; // maximum number of attempts to execute a command

    public static void manageServers(Map<String, ServerDetails> servers) throws IOException, InterruptedException {
        for (ServerDetails server : servers.values()) {
            ExecutorService executor = Executors.newFixedThreadPool(CONCURRENCY);
            List<Future<CommandResult>> results = new ArrayList<>();
            for (int i = 0; i < MAX_ATTEMPTS; i++) {
                String command = "ls -l";
                Future<CommandResult> result = executor.submit(() -> CommandExecutor.executeCommand(server.getIpAddress(), server.getPortNumber(), server.getUsername(), server.getPassword(), command));
                results.add(result);
            }
            executor.shutdown();
        }
    }
}

// Error Handling and Failover
public class FailureHandler {
    private static final int MAX_FAILURES = 3; // maximum number of failures before failing the task

    public static void handleFailure(Exception e) throws Exception {
        if (e instanceof SocketTimeoutException || e instanceof SocketException) {
            throw new IOException("Network failure", e);
        } else if (e instanceof InterruptedException) {
            throw new InterruptedIOException("Interrupted by user", e);
        } else if (e instanceof CommandExecutionException) {
            throw new RuntimeException("Failed to execute command on " + server.getServerName(), e);
        } else {
            throw e;
        }
    }
}

// User Interface and Experience
public class WebUI {
    public static void main(String[] args) throws Exception {
        ServerConfig serverConfig = new ServerConfig();
        Map<String, ServerDetails> servers = serverConfig.getServerDetails();

        // Display server details in UI
        for (ServerDetails server : servers.values()) {
            System.out.println("Server: " + server.getServerName());
            System.out.println("\tIP Address: " + server.getIpAddress());
            System.out.println("\tPort Number: " + server.getPortNumber());
            System.out.println("\tUsername: " + server.getUsername());
        }

        // Execute commands on servers and display output in UI
        CommandExecutor executor = new CommandExecutor();
        Map<String, String> commandOutput = executor.executeCommands(servers);
        for (Map.Entry<String, String> entry : commandOutput.entrySet()) {
            System.out.println("Command output on " + entry.getKey() + ":");
            System.out.println("\t" + entry.getValue());
        }
    }
}
