using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using System.Net.Http;
using System.Net.Http.Headers;
using Newtonsoft.Json;
using MyContentManagementService;

public class ContentUpdater
{
    private readonly HttpClient _client;
    private readonly ILogger<ContentUpdater> _logger;

    public ContentUpdater(HttpClient client, ILogger<ContentUpdater> logger)
    {
        _client = client;
        _logger = logger;
    }

    public async Task<bool> UpdateContentAsync(int pageSectionId, int elementId, string content)
    {
        // Validate input IDs
        if (pageSectionId <= 0 || elementId <= 0)
        {
            return false;
        }

        try
        {
            var updateRequest = new UpdateContentRequest()
            {
                PageSectionId = pageSectionId,
                ElementId = elementId,
                Content = content
            };

            // Send request to external content management service
            var response = await _client.PostAsync("https://content-management-service/update", updateRequest);

            if (response.StatusCode == HttpStatusCode.OK)
            {
                return true;
            }
            else
            {
                throw new Exception($"Error updating content: {response.ReasonPhrase}");
            }
        }
        catch (Exception e)
        {
            _logger.LogError(e, "Error updating content");
            return false;
        }
    }

    private class UpdateContentRequest
    {
        public int PageSectionId { get; set; }
        public int ElementId { get; set; }
        public string Content { get; set; }
    }
}
