using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Xml;
using System.Xml.Linq;

namespace ConfigurationManager
{
    class Program
    {
        static void Main(string[] args)
        {
            // Load configuration settings from XML file
            var config = new Dictionary<string, string>();
            XDocument doc = XDocument.Load("config.xml");
            foreach (var element in doc.Root.Elements())
            {
                config[element.Name.LocalName] = element.Value;
            }

            // Set size of tile, width and height of world, and speed of camera
            var tileSize = int.Parse(config["tileSize"]);
            var worldWidth = int.Parse(config["worldWidth"]);
            var worldHeight = int.Parse(config["worldHeight"]);
            var cameraSpeed = float.Parse(config["cameraSpeed"]);

            // Create new directory with given name and set environment variable to path of directory
            var dirName = config["dirName"];
            var dirPath = $"{Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments)}\\{dirName}";
            if (string.IsNullOrEmpty(Environment.GetEnvironmentVariable("DIR_PATH")))
            {
                Directory.CreateDirectory(dirPath);
                Environment.SetEnvironmentVariable("DIR_PATH", dirPath);
            }

            // Log operations and any errors encountered during execution
            var log = new StringBuilder();
            log.AppendLine($"Loaded configuration settings from XML file:");
            log.AppendLine($" - Tile size: {tileSize}");
            log.AppendLine($" - World width: {worldWidth}");
            log.AppendLine($" - World height: {worldHeight}");
            log.AppendLine($" - Camera speed: {cameraSpeed}");
            log.AppendLine($"Created new directory with name: {dirName} and path: {dirPath}");
            Console.WriteLine(log.ToString());
        }
    }
}
