use std::env;
use std::fs;
use std::path::{Path, PathBuf};

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Load configuration settings from XML file
    let config = XDocument::load("config.xml")?;
    let tile_size = config["tileSize"].as_str().parse::<i32>()?;
    let world_width = config["worldWidth"].as_str().parse::<i32>()?;
    let world_height = config["worldHeight"].as_str().parse::<i32>()?;
    let camera_speed = config["cameraSpeed"].as_str().parse::<f32>()?;

    // Set size of tile, width and height of world, and speed of camera
    println!("Set size of tile: {}", tile_size);
    println!("Set width of world: {}", world_width);
    println!("Set height of world: {}", world_height);
    println!("Set speed of camera: {}", camera_speed);

    // Create new directory with given name and set environment variable to path of directory
    let dir_name = config["dirName"].as_str();
    let mut env_vars = vec![];
    if !env::var("DIR_PATH").is_err() {
        let dir_path = PathBuf::from(env::var("DIR_PATH")?);
        fs::create_dir(&dir_path)?;
        env_vars.push((Path::new("DIR_PATH"), dir_path));
    } else {
        let dir_path = PathBuf::from(format!("{}/{}", env::var("HOME")?, dir_name));
        fs::create_dir(&dir_path)?;
        env_vars.push((Path::new("DIR_PATH"), dir_path));
    }

    // Log operations and any errors encountered during execution
    println!("Created new directory with name: {} and path: {}", dir_name, env_vars[0].1);

    Ok(())
}
