using System;
using UnityEngine;
using System.Collections.Generic;

public class RandomValueGenerator : MonoBehaviour
{
    private float minimumValue = 0;
    private float maximumValue = 100;

    public void SetRange(float min, float max)
    {
        if (min > max)
        {
            throw new ArgumentException("Minimum value must be less than or equal to the maximum value.");
        }

        minimumValue = min;
        maximumValue = max;
    }

    public float GenerateRandomFloat()
    {
        return UnityEngine.Random.Range(minimumValue, maximumValue);
    }

    public int GenerateRandomInt()
    {
        return (int)UnityEngine.Random.Range(minimumValue, maximumValue);
    }

    public List<int> GenerateUniqueRandomIntegers(int n)
    {
        if (n > (maximumValue - minimumValue))
        {
            throw new ArgumentException("Number of random integers exceeds range size.");
        }

        var uniqueValues = new HashSet<int>();
        while (uniqueValues.Count < n)
        {
            int value = GenerateRandomInt();
            if (!uniqueValues.Contains(value))
            {
                uniqueValues.Add(value);
            }
        }

        return uniqueValues.ToList();
    }

    public override string ToString()
    {
        return $"RandomValueGenerator: Range={minimumValue}-{maximumValue}";
    }
}
