// Function to manage the distributed key-value store system
int manage_key_value_store(char *range, char *keys) {
    // Initialize variables
    int i, j, k, ret = -1;
    long offset = 0;
    unsigned char md5[MD5_DIGEST_LENGTH];
    char *p;
    char **key_arr = NULL;
    int num_keys = 0;

