        printf("Error: failed to parse range\n");
        goto exit;
    }
    num_keys = (int) strlen(keys);

    // Allocate memory for the keys and offsets
    keys = malloc(num_keys * sizeof(char *));
    if (!keys) {
        printf("Error: failed to allocate memory for keys\n");
        goto exit;
    }
    offsets = malloc(num_keys * sizeof(long));
    if (!offsets) {
        printf("Error: failed to allocate memory for offsets\n");
        goto exit;
    }

    // Parse the keys and generate an array of records
    ret = parse_keys(key_arr, num_keys);
    if (ret != 0) {
