}

// Function to parse the range and generate an array of keys
char **parse_range(char *range) {
    // Initialize variables
    int i, j, k, ret = -1;
    char **key_arr = NULL;
    char delim[] = "-";

    // Parse the range and generate an array of keys
    key_arr = malloc((strlen(range) + 1) * sizeof(char *));
    if (!key_arr) {
        printf("Error: failed to allocate memory for key array\n");
        goto exit;
    }
    i = 0;
    j = 0;
    k = 0;
    while (range[j] != '\0') {
        if (range[j] == delim[0]) {
            key_arr[i++] = strndup(&range[k], j - k);
            k = j + 1;
        }
        j++;
    }
    key_arr[i++] = strndup(&range[k], j - k);

    // Return the array of keys
    ret = i;
exit:
    return key_arr;
