// Function to parse the keys and generate an array of records
int parse_keys(char **key_arr, int num_keys) {
    // Initialize variables
    int i, j, k, ret = -1;
    char *p;

    // Parse the keys and generate an array of records
    for (i = 0; i < num_keys; i++) {
        p = strtok(key_arr[i], ",");
        if (!p) {
            printf("Error: failed to parse key %s\n", key_arr[i]);
            goto exit;
        }
        j = 0;
        while (p != NULL) {
            records[j] = malloc(strlen(p) + 1);
            if (!records[j]) {
                printf("Error: failed to allocate memory for record %d\n", j);
                goto exit;
            }
            strcpy(records[j], p);
            j++;
            p = strtok(NULL, ",");
        }
    }

    // Return the number of records
    ret = j;
exit:
    return ret;
}

// Function to generate an offset for a given record
long generate_offset(char *record) {
    // Initialize variables
    long offset = 0;
    int i, j, k, ret = -1;

    // Generate the offset for the record
    for (i = 0; i < num_keys; i++) {
        if (!strcmp(record, records[i])) {
            offset = offsets[i];
            break;
        }
    }

    // Return the generated offset
    ret = offset;
exit:
    return ret;
}

// Function to convert an MD5 hash to a string
char *md5_to_str(unsigned char *md5) {
    // Initialize variables
    int i, j, k, ret = -1;
    char *p = malloc(hash_len + 1);
    if (!p) {
        printf("Error: failed to allocate memory for MD5 hash\n");
        goto exit;
    }

    // Convert the MD5 hash to a string
    for (i = 0; i < hash_len; i++) {
        p[i] = md5[i];
    }
    p[hash_len] = '\0';

    // Return the generated string
    ret = p;
exit:
    return ret;
}
