using System;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading;

public static class SiteManager
{
    public static void AddSite(string directoryPath, string siteName)
    {
        // Check if the directory path is valid and accessible
        if (!Directory.Exists(directoryPath))
        {
            throw new DirectoryNotFoundException($"The directory '{directoryPath}' does not exist.");
        }
        else if (Directory.GetFiles(directoryPath).Any(f => f.EndsWith(".config")))
        {
            throw new ArgumentException("A web.config file already exists in the directory.", nameof(directoryPath));
        }

        // Create a unique site name if it already exists within the directory
        string uniqueSiteName = GetUniqueSiteName(siteName, directoryPath);

        // Validate that the user has the necessary permissions to add and manage sites in the directory
        DirectorySecurity dirSec = Directory.GetAccessControl(directoryPath);
        if (!dirSec.AreAccessRulesProtected || !dirSec.AreAuditRulesProtected)
        {
            throw new UnauthorizedAccessException("The user does not have the necessary permissions to add and manage sites in the directory.");
        }

        // Integrate with an external configuration database to retrieve additional settings for the site
        // Handle cases where the database is unavailable or returns incorrect data
        var dbSettings = GetDatabaseSettings(siteName);
        if (dbSettings == null)
        {
            throw new Exception("An error occurred while retrieving settings from the database.");
        }

        // Create a web.config file with the retrieved settings
        string configPath = Path.Combine(directoryPath, "web.config");
        using (var writer = new StreamWriter(configPath))
        {
            writer.WriteLine("<configuration>");
            foreach (var setting in dbSettings)
            {
                writer.WriteLine($"  <{setting.Key}>{setting.Value}</{setting.Key}>");
            }
            writer.WriteLine("</configuration>");
        }

        // Start the site using the Process class
        var process = new Process();
        process.StartInfo.FileName = "dotnet";
        process.StartInfo.Arguments = $"{configPath} --port {dbSettings["Port"]}";
        process.StartInfo.UseShellExecute = false;
        process.StartInfo.RedirectStandardOutput = true;
        process.StartInfo.RedirectStandardError = true;
        process.Start();

        // Log all actions and errors to a centralized logging service
        var logService = new LoggingService();
        logService.LogAction($"Added site '{uniqueSiteName}' to directory '{directoryPath}'", "SiteManager");
        if (process.HasExited)
        {
            logService.LogError(new Exception("An error occurred while starting the site."), "SiteManager");
        }
    }

    private static string GetUniqueSiteName(string siteName, string directoryPath)
    {
        // Check if the provided site name already exists within the directory
        var existingSites = Directory.EnumerateFiles(directoryPath, "web.config", SearchOption.TopDirectoryOnly).Select(f => Path.GetFileNameWithoutExtension(f)).ToList();
        int i = 2;
        while (existingSites.Contains(siteName))
        {
            siteName += $" ({i})";
            i++;
        }
        return siteName;
    }

    private static Dictionary<string, string> GetDatabaseSettings(string siteName)
    {
        // Implement logic to retrieve additional settings for the site from an external configuration database
        // Throw an exception if the database is unavailable or returns incorrect data
        throw new NotImplementedException();
    }
}
