  if (curl) {
    // Set the API endpoint and query parameters
    std::string apiEndpoint = config.endpoint;
    std::string queryParams = "lat=" + lat + "&lon=" + lon;

    // Set the cURL options
    curl_easy_setopt(curl, CURLOPT_URL, apiEndpoint.c_str());
    curl_easy_setopt(curl, CURLOPT_HTTPGET, 1L);
    curl_easy_setopt(curl, CURLOPT_VERBOSE, 1L);

    // Set the cURL headers
    struct curl_slist* headers = NULL;
    std::string header = "Authorization: Bearer " + config.apiKey;
