      return false;
    }

    // Get the response code and body
    long responseCode = 0;
    std::string body;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &responseCode);
    curl_easy_getinfo(curl, CURLINFO_HTTP_BODY, &body);

    // Check the response code and handle errors
