namespace AsynchronousDataDecryptor
{
    public class DecryptionService : IDecryptionService
    {
        private readonly ILogger<DecryptionService> _logger;
        private readonly IConfiguration _config;
        private readonly ICryptoServiceProvider _csp;
        private readonly ConcurrentDictionary<string, byte[]> _keyPool = new ConcurrentDictionary<string, byte[]>();
        private readonly ConcurrentDictionary<string, byte[]> _ivPool = new ConcurrentDictionary<string, byte[]>();

        public DecryptionService(ILogger<DecryptionService> logger, IConfiguration config)
        {
            _logger = logger;
            _config = config;
            _csp = GetCryptoServiceProvider(_config);
        }

        public async Task<string> DecryptMessageAsync(string message, int clearanceLevel)
        {
            var key = GetKeyFromPoolOrFetch(_keyPool, clearanceLevel);
            if (key == null)
            {
                _logger.LogError("Failed to retrieve key for clearance level {ClearanceLevel}", clearanceLevel);
                return null;
            }

            var iv = GetIvFromPoolOrFetch(_ivPool, clearanceLevel);
            if (iv == null)
            {
                _logger.LogError("Failed to retrieve IV for clearance level {ClearanceLevel}", clearanceLevel);
                return null;
            }

            try
            {
                var decryptedMessage = await DecryptAsync(message, key, iv);
                _logger.LogInformation("Successfully decrypted message with clearance level {ClearanceLevel}", clearanceLevel);
                return decryptedMessage;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to decrypt message with clearance level {ClearanceLevel}", clearanceLevel);
                return null;
            }
        }

        private async Task<byte[]> DecryptAsync(string message, byte[] key, byte[] iv)
        {
            // Implement your own encryption/decryption logic here
            throw new NotImplementedException();
        }

        private void GetKeyFromPoolOrFetch(ConcurrentDictionary<string, byte[]> pool, int clearanceLevel)
        {
            // Fetch key from CSP and add it to the pool if not already present
            var key = _csp.GetKeyForClearanceLevel(clearanceLevel);
            if (key == null)
            {
                _logger.LogError("Failed to retrieve key for clearance level {ClearanceLevel} from CSP", clearanceLevel);
                return;
            }

            pool.TryAdd(clearanceLevel, key);
        }

        private void GetIvFromPoolOrFetch(ConcurrentDictionary<string, byte[]> pool, int clearanceLevel)
        {
            // Fetch IV from CSP and add it to the pool if not already present
            var iv = _csp.GetIVForClearanceLevel(clearanceLevel);
            if (iv == null)
            {
                _logger.LogError("Failed to retrieve IV for clearance level {ClearanceLevel} from CSP", clearanceLevel);
                return;
            }

            pool.TryAdd(clearanceLevel, iv);
        }
    }
}
