#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <curl/curl.h>
#include <openssl/conf.h>
#include <openssl/x509.h>
#include <openssl/pem.h>
#include <openssl/bio.h>
#include <openssl/err.h>

#define MAX_TRANSACTIONS 1000
#define MIN_WEIGHTED_SUM 1000

// Transaction request structure
struct TransactionRequest {
    char *client_id;
    char *client_secret;
    int age_filter;
    int num_transactions;
    double weighted_sum;
    char **transaction_ids;
};

// Authentication cache to store access tokens for session management
struct AuthCache {
    pthread_mutex_t lock;
    char *access_token;
};

// Thread-safe authentication cache initialization function
void initAuthCache(struct AuthCache *cache) {
    pthread_mutex_init(&cache->lock, NULL);
}

// Thread-safe authentication cache cleanup function
void cleanupAuthCache(struct AuthCache *cache) {
    pthread_mutex_destroy(&cache->lock);
}

// External OAuth 2.0 service authentication using client credentials
int authenticateClient(struct TransactionRequest *request, struct AuthCache *cache) {
    CURL *curl;
    CURLcode res;
    char url[512];
    sprintf(url, "https://oauth2.example.com/token?grant_type=client_credentials&client_id=%s&client_secret=%s", request->client_id, request->client_secret);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "Authentication failed: %s\n", curl_easy_strerror(res));
            return -1;
        }
    }
    pthread_mutex_lock(&cache->lock);
    cache->access_token = strdup(curl_easy_escape(curl, res.body));
    pthread_mutex_unlock(&cache->lock);
    curl_easy_cleanup(curl);
    return 0;
}

// Thread-safe access token caching function
void cacheAccessToken(struct AuthCache *cache, char *access_token) {
    pthread_mutex_lock(&cache->lock);
    free(cache->access_token);
    cache->access_token = strdup(access_token);
    pthread_mutex_unlock(&cache->lock);
}

// Thread-safe access token retrieval function
char *getAccessToken(struct AuthCache *cache) {
    char *access_token;
    pthread_mutex_lock(&cache->lock);
    access_token = strdup(cache->access_token);
    pthread_mutex_unlock(&cache->lock);
    return access_token;
}

// Real-time transaction database query using a transaction ID list
int queryTransactionDatabase(struct TransactionRequest *request, char **transaction_ids) {
    CURL *curl;
    CURLcode res;
    char url[512];
    int i;
    sprintf(url, "https://database.example.com/transactions?id=%s", transaction_ids);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "Transaction database query failed: %s\n", curl_easy_strerror(res));
            return -1;
        }
    }
    for (i = 0; i < MAX_TRANSACTIONS; i++) {
        printf("Transaction ID %d: %s\n", i, transaction_ids[i]);
    }
    curl_easy_cleanup(curl);
    return 0;
}

// Transaction filtering using a weighted sum constraint
int filterTransactions(struct TransactionRequest *request) {
    int i;
    for (i = 0; i < MAX_TRANSACTIONS; i++) {
        if (request->weighted_sum > MIN_WEIGHTED_SUM) {
            printf("Transaction ID %d: Weighted sum greater than minimum\n", transaction_ids[i]);
            return 1;
        } else {
            printf("Transaction ID %d: Weighted sum less than minimum\n", transaction_ids[i]);
            return -1;
        }
    }
}

// Combine private key and certificate files into a single PEM file
int combinePemFiles(char *private_key_file, char *certificate_file) {
    FILE *private_key = fopen(private_key_file, "rb");
    FILE *certificate = fopen(certificate_file, "rb");
    FILE *pem_file = fopen("combined.pem", "wb");
    if (private_key && certificate && pem_file) {
        char buffer[BUFSIZ];
        while (fgets(buffer, BUFSIZ, private_key)) {
            fputs(buffer, pem_file);
        }
        while (fgets(buffer, BUFSIZ, certificate)) {
            fputs(buffer, pem_file);
        }
    } else {
        return -1;
    }
    fclose(private_key);
    fclose(certificate);
    fclose(pem_file);
}

// Process transactions using external OAuth 2.0 service and real-time database
int processTransactions(struct TransactionRequest *request) {
    struct AuthCache cache;
    initAuthCache(&cache);
    authenticateClient(request, &cache);
    char *access_token = getAccessToken(&cache);
    queryTransactionDatabase(request, request->transaction_ids);
    filterTransactions(request);
    combinePemFiles("private.key", "certificate.crt");
    cleanupAuthCache(&cache);
}
```
