class DynamicNetworkResolver {
public:
    DynamicNetworkResolver(const std::vector<std::string>& dns_servers, int concurrency_limit = 10);

    void set_dns_servers(const std::vector<std::string>& dns_servers);

    std::string resolve(const std::string& hostname) const;

private:
    struct ResolutionRequest {
        std::string hostname;
        std::chrono::high_resolution_clock::time_point start_time;
        std::string result;
    };

    void thread_function();

    std::vector<std::string> dns_servers_;
    int concurrency_limit_;
    std::mutex request_queue_mutex_;
    std::condition_variable request_queue_cv_;
    std::unordered_set<ResolutionRequest*> active_requests_;
    std::vector<std::thread> worker_threads_;
};

DynamicNetworkResolver::DynamicNetworkResolver(const std::vector<std::string>& dns_servers, int concurrency_limit) :
        dns_servers_(dns_servers), concurrency_limit_(concurrency_limit) {
    worker_threads_.reserve(concurrency_limit);
    for (int i = 0; i < concurrency_limit_; ++i) {
        worker_threads_.push_back(std::thread(&DynamicNetworkResolver::thread_function, this));
    }
}

void DynamicNetworkResolver::set_dns_servers(const std::vector<std::string>& dns_servers) {
    std::lock_guard<std::mutex> lock(request_queue_mutex_);
    dns_servers_ = dns_servers;
}

std::string DynamicNetworkResolver::resolve(const std::string& hostname) const {
    ResolutionRequest request{hostname, std::chrono::high_resolution_clock::now(), ""};
    {
        std::lock_guard<std::mutex> lock(request_queue_mutex_);
        active_requests_.insert(&request);
    }
    request_queue_cv_.notify_one();
    while (true) {
        {
            std::unique_lock<std::mutex> lock(request_queue_mutex_);
            if (request.result != "") {
                return request.result;
            }
            request_queue_cv_.wait(lock);
        }
    }
}

void DynamicNetworkResolver::thread_function() {
    std::vector<std::pair<int, int>> dns_server_indices;
    dns_server_indices.reserve(dns_servers_.size());
    for (int i = 0; i < dns_servers_.size(); ++i) {
        dns_server_indices.push_back({i, 0});
    }
    while (true) {
        std::unique_lock<std::mutex> lock(request_queue_mutex_);
        if (active_requests_.empty()) {
            request_queue_cv_.wait(lock);
            continue;
        }
        ResolutionRequest* current_request = nullptr;
        int min_index = -1;
        for (auto& request : active_requests_) {
            if (!current_request || dns_server_indices[request->dns_server_index].first < min_index) {
                current_request = request;
                min_index = dns_server_indices[request->dns_server_index].first;
            }
        }
        if (current_request == nullptr) {
            continue;
        }
        lock.unlock();
        std::string hostname = current_request->hostname;
        int dns_server_index = current_request->dns_server_index;
        try {
            auto start = std::chrono::high_resolution_clock::now();
            std::cout << "Resolving " << hostname << " using DNS server " << dns_servers_[dns_server_index] << std::endl;
            current_request->result = ""; // placeholder value for now
            lock.lock();
            if (current_request->start_time == start) {
                current_request->result = "resolved";
            } else {
                active_requests_.erase(current_request);
                continue;
            }
        } catch (std::exception& e) {
            std::cout << "Error resolving hostname: " << e.what() << std::endl;
        }
        lock.unlock();
        request_queue_cv_.notify_one();
    }
}
