use std::env;
use std::fs;
use std::path::PathBuf;
use std::sync::Mutex;
use std::time::{SystemTime, UNIX_EPOCH};

const MAX_DIRECTORIES: usize = 10; // maximum number of directories to keep
const CLEANUP_INTERVAL: u64 = 3600; // interval at which the cleanup process should run in seconds
const LOG_FILE: &str = "/var/log/directory-manager.log"; // path to log file

struct DirectoryMetadata {
    creation_time: SystemTime,
    last_access_time: SystemTime,
    referenced: bool,
}

impl DirectoryMetadata {
    fn new(referenced: bool) -> Self {
        Self {
            creation_time: UNIX_EPOCH,
            last_access_time: UNIX_EPOCH,
            referenced,
        }
    }

    fn update(&mut self, referenced: bool) {
        self.last_access_time = SystemTime::now();
        self.referenced = referenced;
    }
}

struct DirectoryManager {
    directories: Vec<PathBuf>,
    metadata: HashMap<PathBuf, DirectoryMetadata>,
    mutex: Mutex<()>,
}

impl DirectoryManager {
    fn new(directories: Vec<PathBuf>) -> Self {
        let metadata = directories.iter().map(|dir| (dir.clone(), DirectoryMetadata::new(false))).collect();
        Self {
            directories,
            metadata,
            mutex: Mutex::new(()),
        }
    }

    fn create_directory(&mut self, name: &str) -> Result<PathBuf, String> {
        let dir = env::temp_dir().join(name);
        if !self.metadata.contains_key(&dir) {
            fs::create_dir(&dir).map_err(|e| format!("failed to create directory {:?}: {}", &dir, e))?;
            self.directories.push(dir.clone());
            self.metadata.insert(dir.clone(), DirectoryMetadata::new(false));
        }
        Ok(dir)
    }

    fn set_environment_variable(&mut self, dir: &PathBuf) -> Result<(), String> {
        env::set_var("DIRECTORY", dir);
        self.metadata[dir].update(true);
        Ok(())
    }

    fn cleanup(&mut self) {
        let mut to_delete = Vec::new();
        for (dir, metadata) in &self.metadata {
            if !metadata.referenced && SystemTime::now() - metadata.creation_time > Duration::from_secs(CLEANUP_INTERVAL) {
                to_delete.push(dir.clone());
            }
        }
        for dir in to_delete {
            fs::remove_dir(&dir).map_err(|e| format!("failed to delete directory {:?}: {}", &dir, e))?;
            self.directories.retain(|d| d != &dir);
            self.metadata.remove(&dir);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;
    use std::path::PathBuf;
    use std::sync::Mutex;

    #[test]
    fn test_create_directory() {
        let mut manager = DirectoryManager::new(Vec::new());
        assert!(manager.create_directory("test").is_ok());
        assert!(manager.directories.contains(&env::temp_dir().join("test")));
        fs::remove_dir(env::temp_dir().join("test")).unwrap();
    }

    #[test]
    fn test_set_environment_variable() {
        let mut manager = DirectoryManager::new(Vec::new());
        assert!(manager.create_directory("test").is_ok());
        assert!(manager.set_environment_variable(&env::temp_dir().join("test")).is_ok());
        assert_eq!(Some(true), env::var("DIRECTORY"));
        fs::remove_dir(env::temp_dir().join("test")).unwrap();
    }

    #[test]
    fn test_cleanup() {
        let mut manager = DirectoryManager::new(Vec::new());
        assert!(manager.create_directory("test").is_ok());
        let dir1 = env::temp_dir().join("test");
        manager.set_environment_variable(&dir1).unwrap();
        assert_eq!(Some(true), env::var("DIRECTORY"));
        assert!(manager.create_directory("test2").is_ok());
        let dir2 = env::temp_dir().join("test2");
        manager.set_environment_variable(&dir2).unwrap();
        assert_eq!(Some(true), env::var("DIRECTORY"));
        drop(manager); // simulate shutdown
        let mut manager = DirectoryManager::new(Vec::new());
        manager.cleanup();
        assert!(!env::temp_dir().join("test").exists());
        assert!(env::temp_dir().join("test2").exists());
    }
}
