async function readDirectoryFiles(directory, extension, bufferSize = 1024 * 1024, maxFileSize = 500 * 1024) {
  const log = console.log; // Replace with your logging system

  try {
    const files = await fs.promises.readdir(directory);
    log(`Reading ${files.length} files from directory "${directory}"`);

    const filteredFiles = files.filter(file => file.endsWith(extension));
    log(`Filtered to ${filteredFiles.length} files with extension "${extension}"`);

    if (filteredFiles.length === 0) {
      return ''; // Return an empty string if no files were found
    }

    const fileContents = await Promise.all(filteredFiles.map(async file => {
      try {
        const content = await fs.promises.readFile(path.join(directory, file), { encoding: 'utf-8', bufferSize });
        return content;
      } catch (err) {
        log(`Error reading file "${file}": ${err.message}`);
        return ''; // Return an empty string if an error occurred while reading the file
      }
    }));

    const concatenatedContent = fileContents.reduce((acc, content) => acc + content, '');
    log(`Concatenated contents of ${fileContents.length} files with total length ${concatenatedContent.length}`);

    return concatenatedContent;
  } catch (err) {
    log(`Error reading directory "${directory}": ${err.message}`);
    return ''; // Return an empty string if an error occurred while reading the directory
  }
}
