public:
    explicit DynamicFileProcessor(const std::string& filePath) : filePath_(filePath) {}

    ~DynamicFileProcessor() {
        for (auto& [key, value] : externalMetadataCache_) {
            delete value;
        }
    }

    void processFiles(int maxParallelOperations = 4) {
        std::mutex mutex_;
        std::condition_variable cv_;

        // Load file paths from file
        std::ifstream fileStream_(filePath_);
        if (!fileStream_.is_open()) {
            throw std::runtime_error("Failed to open file: " + filePath_);
        }

        std::vector<std::string> filePaths;
        for (std::string line; std::getline(fileStream_, line);) {
            filePaths.push_back(line);
        }

        // Process files in parallel
        std::atomic<int> completedOperations_{0};
        std::vector<std::thread> threads_;
        for (int i = 0; i < maxParallelOperations; ++i) {
            threads_.emplace_back([&]() {
                while (true) {
                    auto filePath = getNextFileToProcess(filePaths, completedOperations_);
                    if (filePath.empty()) {
                        break;
                    }

                    // Get external metadata for file
                    std::lock_guard<std::mutex> lock(mutex_);
                    auto* metadata = getExternalMetadata(filePath);

                    // Process file based on metadata
                    if (metadata->size > 1024 * 1024) { // Large file
                        renameFile(filePath, "large-" + metadata->fileName + ".txt");
                    } else if (metadata->creationDate < std::chrono::system_clock::now() - std::chrono::hours{24}) { // Old file
                        deleteFile(filePath);
                    } else { // Small file
                        moveFile(filePath, "small-" + metadata->fileName + ".txt");
                    }

                    completedOperations_++;
                }
            });
        }

        // Wait for all threads to finish
        for (auto& thread : threads_) {
            thread.join();
        }

        std::cout << "All files processed successfully." << std::endl;
    }

private:
