#include <fstream>
#include <iostream>
#include <stdexcept>
#include <string>

class MyClass {
  // ...
};

std::unique_ptr<MyClass> loadResourceBundle(const std::string& path) {
  // Open the resource bundle file
  std::ifstream file(path, std::ios::binary);
  if (!file.is_open()) {
    throw std::runtime_error("Failed to open resource bundle file: " + path);
  }

  // Count the number of items in the bundle
  int itemCount = 0;
  while (file.read((char*)&itemCount, sizeof(int))) {
    ++itemCount;
  }

  // Read the resource bundle data as a byte array
  std::vector<uint8_t> buffer(itemCount * sizeof(MyClass));
  file.seekg(0);
  file.read((char*)buffer.data(), buffer.size());

  // Attempt to deserialize the object from the byte array
  try {
    std::unique_ptr<MyClass> obj =
        std::make_unique<MyClass>(std::move(buffer));
    return obj;
  } catch (const std::runtime_error& ex) {
    throw std::runtime_error("Failed to deserialize object: " + ex.what());
  }
}
