use std::fs;
use std::path::PathBuf;
use std::sync::Arc;
use std::sync::Mutex;

use lexer::Lexer;
use parser::Parser;
use rustc_llvmir::OptimizationLevel;
use rustc_llvmir::PassManager;
use rustc_llvmir::TargetMachine;
use rustc_middle::ty::TyCtxt;
use rustc_target::abi::Abi;
use rustc_target::spec::TargetSpec;

fn generate_optimized_llvm_ir(directory: &str, optimization_level: OptimizationLevel) {
    // Read and parse all Rust files in the directory
    let mut files = Vec::new();
    for entry in fs::read_dir(directory).unwrap() {
        if let Ok(entry) = entry {
            if entry.file_type().unwrap().is_file() && entry.path().extension().unwrap() == "rs" {
                files.push(entry.path());
            }
        }
    }

    // Create a PassManager and add optimization passes to it
    let mut pass_manager = PassManager::new();
    pass_manager.add_pass("function-inlining");
    pass_manager.add_pass("basic-block-merging");
    pass_manager.add_pass("dead-code-elimination");

    // Compile the Rust files to LLVM IR and optimize them using the PassManager
    let target = TargetMachine::new(TargetSpec::new("x86_64-unknown-linux-gnu"));
    for file in files {
        let mut error_buffer = String::new();
        if let Ok(rustc_middle) = TyCtxt::new() {
            // Read and parse the Rust file
            let lexer = Lexer::new(&file);
            let parser = Parser::new(lexer, &mut error_buffer, rustc_middle);
            let syntax_tree = parser.parse_source_file();

            // Compile the parsed Rust syntax tree into LLVM IR
            let llvm_ir = rustc_llvmir::compile(&syntax_tree, target).unwrap();

            // Apply optimization passes to the LLVM IR
            pass_manager.run(&mut error_buffer, &llvm_ir);

            // Write the optimized LLVM IR to a separate file named after the original Rust file but with a .ll extension
            let mut llvm_ir_file = PathBuf::new();
            llvm_ir_file.set_extension("ll");
            fs::write(llvm_ir_file, &llvm_ir).unwrap();
        } else {
            // Log error messages to a specified output file
            let mut logger = Arc::new(Mutex::new(Box::new(FileLogger::new("output.log"))));
            logger.lock().unwrap().log(&error_buffer);
        }
    }
}
```
This code uses the `std::fs` module to read and parse all Rust files in a directory, and the `rustc_llvmir` crate to compile them into LLVM IR. The `PassManager` is used to apply optimization passes to the generated LLVM IR. Finally, the function writes the optimized LLVM IR to separate files named after the original Rust files but with a `.ll` extension.

The code also includes error handling to manage parsing and compilation errors, and log detailed error messages to a specified output file using an external logging system. The `FileLogger` is a simple example of how to implement a logger that writes logs to a file.

