using UnityEngine;
using System;
using System.Collections.Generic;

public class RandomValueGenerator
{
    private float minValue;
    private float maxValue;

    public RandomValueGenerator(float min, float max)
    {
        this.minValue = min;
        this.maxValue = max;
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(this.minValue, this.maxValue);
    }

    public int GetRandomInteger()
    {
        return (int)UnityEngine.Random.Range(this.minValue, this.maxValue + 1f);
    }

    public List<int> GetRandomIntegerList(int size)
    {
        var list = new List<int>(size);
        for (int i = 0; i < size; i++)
        {
            int value = (int)UnityEngine.Random.Range(this.minValue, this.maxValue + 1f);
            if (!list.Contains(value))
            {
                list.Add(value);
            }
        }
        return list;
    }

    public override string ToString()
    {
        return $"Range: [{this.minValue}, {this.maxValue}]; Lists generated: {GetRandomIntegerList(10)}";
    }
}
