// Define a function to establish SSH connections to remote servers and delete a file if it exists
void sshConnectAndDeleteFileIfExists(RemoteServerConfig* config) {
    JSchSession session = JSch_session_new();
    JSch_session_set_host(session, config->host);
    JSch_session_set_port(session, config->port);
    JSch_session_set_username(session, config->username);
    JSch_session_set_password(session, config->password);
    JSch_session_connect(session);

    // Check if the file exists on the remote server and delete it if it does
    JSchChannel channel = JSch_channel_new();
    JSch_channel_set_command(channel, "ls");
    JSch_channel_execute(channel);
    char* output = JSch_channel_get_output(channel);
    if (strstr(output, config->file) != NULL) {
        JSch_channel_set_command(channel, "rm -f " + config->file);
        JSch_channel_execute(channel);
    }

    // Close the SSH connection
    JSch_session_disconnect(session);
}

// Define a function to execute a command on each remote server using JSch library
void sshExecuteCommandOnEachRemoteServer(RemoteServerConfig* config, CommandDetails* details) {
    JSchSession session = JSch_session_new();
    JSch_session_set_host(session, config->host);
    JSch_session_set_port(session, config->port);
    JSch_session_set_username(session, config->username);
    JSch_session_set_password(session, config->password);
    JSch_session_connect(session);

    // Execute the command on each remote server using JSch library
    for (int i = 0; i < config->nServers; i++) {
        JSchChannel channel = JSch_channel_new();
        JSch_channel_set_command(channel, details->command);
        JSch_channel_execute(channel);
    }

    // Close the SSH connection
    JSch_session_disconnect(session);
}

