#include <stdlib.h>
#include <time.h>

struct record {
    long value;
    long timestamp;
};

void init_records(long** offset, int** keys, struct record*** records, int num_records) {
    *offset = malloc(num_records * sizeof(long));
    if (*offset == NULL) {
        perror("Failed to allocate memory for offset array");
        return;
    }

    *keys = malloc(num_records * sizeof(int));
    if (*keys == NULL) {
        perror("Failed to allocate memory for key array");
        free(*offset);
        return;
    }

    *records = malloc(num_records * sizeof(struct record*));
    if (*records == NULL) {
        perror("Failed to allocate memory for records array");
        free(*offset);
        free(*keys);
        return;
    }

    // Generate random values for offset and key arrays
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        (*offset)[i] = rand() % 100;
        (*keys)[i] = rand() % 100;
    }

    // Set timestamp of each record to current time plus random delay within specified range
    long current_time = time(NULL);
    for (int i = 0; i < num_records; i++) {
        (*records)[i] = malloc(sizeof(struct record));
        if ((*records)[i] == NULL) {
            perror("Failed to allocate memory for a record");
            free(*offset);
            free(*keys);
            free(*records);
            return;
        }
        (*records)[i]->value = rand() % 100;
        (*records)[i]->timestamp = current_time + (rand() % 5) + 1; // random delay within [1, 6] seconds
    }
}
```
This function takes in three parameters: `offset`, `keys`, and `records`. It dynamically allocates memory for each of these arrays using the `malloc` function. If any allocation fails, it logs an error message using the `perror` function and returns immediately without modifying the passed-in pointers.

The function then generates random values for both the offset and key arrays using the `rand` function from the `<stdlib.h>` header file. It uses the `srand` function to seed the random number generator with the current time, and then generates random numbers between 0 and 100 for both arrays.

Next, it sets the timestamp of each record to the current time plus a random delay within a specified range using the `time` function from the `<time.h>` header file. The random delay is generated using the `rand` function, and is limited to a maximum value of 5 seconds (i.e., within the range [1, 6]).

Finally, it returns without modifying the passed-in pointers.

Note that this function assumes that the caller has provided valid memory locations for the three arrays. It is the responsibility of the caller to ensure that these arrays are properly initialized and freed when they are no longer needed.

