function loadFiles(files) {
    const fileQueue = [];
    const fileLoadingPromises = [];
    const fileExecutingPromises = [];

    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      // Load the file asynchronously and add it to the queue
      fileQueue.push(file);
      fileLoadingPromises.push(fetch(file).then((response) => response.text()).catch((error) => console.log(`Failed to load file ${file}: ${error}`)));
    }

    // Execute files in the queue asynchronously and add their promises to the list
    Promise.all(fileLoadingPromises).then(() => {
      for (let i = 0; i < fileQueue.length; i++) {
        const file = fileQueue[i];
        fileExecutingPromises.push(eval(file).catch((error) => console.log(`Failed to execute file ${file}: ${error}`)));
      }
    }).then(() => {
      Promise.all(fileExecutingPromises).then(() => {
        // All files have been loaded and executed successfully
      }).catch((error) => {
        // At least one file failed to load or execute
        console.log(`Error loading or executing files: ${error}`);
      });
    });
  }

  function addFile(file) {
    const newFileQueue = [...fileQueue, file];
    const newFileLoadingPromises = [...fileLoadingPromises, fetch(file).then((response) => response.text()).catch((error) => console.log(`Failed to load file ${file}: ${error}`))];
    const newFileExecutingPromises = [...fileExecutingPromises, eval(file).catch((error) => console.log(`Failed to execute file ${file}: ${error}`))];

    Promise.all(newFileLoadingPromises).then(() => {
      for (let i = 0; i < newFileQueue.length; i++) {
        const file = newFileQueue[i];
        fileExecutingPromises.push(eval(file).catch((error) => console.log(`Failed to execute file ${file}: ${error}`)));
      }
    }).then(() => {
      Promise.all(newFileExecutingPromises).then(() => {
        // All files have been loaded and executed successfully
      }).catch((error) => {
        // At least one file failed to load or execute
        console.log(`Error loading or executing files: ${error}`);
      });
    });
  }

  function removeFile(file) {
    const newFileQueue = fileQueue.filter((f) => f !== file);
    const newFileLoadingPromises = fileLoadingPromises.filter((p) => !p.then((r) => r === file));
    const newFileExecutingPromises = fileExecutingPromises.filter((p) => !p.then((r) => r === file));

    Promise.all(newFileLoadingPromises).then(() => {
      for (let i = 0; i < newFileQueue.length; i++) {
        const file = newFileQueue[i];
        fileExecutingPromises.push(eval(file).catch((error) => console.log(`Failed to execute file ${file}: ${error}`)));
      }
    }).then(() => {
      Promise.all(newFileExecutingPromises).then(() => {
        // All files have been loaded and executed successfully
      }).catch((error) => {
        // At least one file failed to load or execute
        console.log(`Error loading or executing files: ${error}`);
      });
    });
  }

Here is a PHP web API that includes two main functions: `authenticateUserAndUpdateClinicStatus` for authenticating a user using an OAuth 2.0 client and updating a database table with the new status, last modified IP address, and last modified date for a given clinic ID, and a file hashing function to calculate the MD5 hash of a file given its path.
```php
<?php

// Function to authenticate user and update clinic status
function authenticateUserAndUpdateClinicStatus($client_id, $client_secret, $refresh_token, $clinic_id, $new_status) {
  // Validate input parameters
  if (!$client_id || !$client_secret || !$refresh_token || !$clinic_id || !$new_status) {
    throw new Exception("Invalid input parameters");
  }

  // Authenticate user using OAuth 2.0 client and refresh token
  $access_token = getAccessToken($client_id, $client_secret, $refresh_token);

  // Update clinic status in database table
  updateClinicStatus($clinic_id, $new_status, $access_token);
}

// Function to calculate MD5 hash of a file
function calculateFileHash($file_path) {
  if (!$file_path) {
    throw new Exception("Invalid file path");
  }

  // Combine private key and certificate into a single PEM file
  $pem_file = combinePemFiles($private_key, $certificate);

  // Read the file in chunks to manage memory usage effectively
  $chunk_size = 1024 * 1024; // 1 MB
  $hash = "";
  $fh = fopen($file_path, "rb");
  while (!feof($fh)) {
    $buffer = fread($fh, $chunk_size);
    $hash .= md5($buffer);
  }

  // Close file handle
  fclose($fh);

  return $hash;
}

// Get access token using OAuth 2.0 client and refresh token
function getAccessToken($client_id, $client_secret, $refresh_token) {
  // Use cURL to send a POST request to the OAuth 2.0 server with the client ID, client secret, and refresh token
  $ch = curl_init("https://oauth-server.com/token");
  curl_setopt($ch, CURLOPT_POST, true);
  curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
  curl_setopt($ch, CURLOPT_POSTFIELDS, "client_id=" . urlencode($client_id) . "&client_secret=" . urlencode($client_secret) . "&refresh_token=" . urlencode($refresh_token));
  $response = curl_exec($ch);

  // Parse the response JSON to get the access token and expiration time
  $json = json_decode($response, true);
  $access_token = $json["access_token"];
  $expires_in = $json["expires_in"];

  return $access_token;
}

// Update clinic status in database table
function updateClinicStatus($clinic_id, $new_status, $access_token) {
  // Use cURL to send a PUT request to the API server with the clinic ID, new status, and access token
  $ch = curl_init("https://api-server.com/clinics/" . urlencode($clinic_id));
  curl_setopt($ch, CURLOPT_CUSTOMREQUEST, "PUT");
  curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
  curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode(array("new_status" => $new_status)));
  curl_setopt($ch, CURLOPT_HTTPHEADER, array("Authorization: Bearer " . $access_token));
  $response = curl_exec($ch);

  // Parse the response JSON to get the last modified IP address and last modified date
  $json = json_decode($response, true);
  $last_modified_ip = $json["last_modified_ip"];
  $last_modified_date = $json["last_modified_date"];

  return array("last_modified_ip" => $last_modified_ip, "last_modified_date" => $last_modified_date);
}

// Combine private key and certificate into a single PEM file
function combinePemFiles($private_key, $certificate) {
  $pem = "";

  // Add the private key to the PEM file
  $pem .= "-----BEGIN RSA PRIVATE KEY-----\n";
  $pem .= $private_key;
  $pem .= "\n-----END RSA PRIVATE KEY-----\n";

  // Add the certificate to the PEM file
  $pem .= "-----BEGIN CERTIFICATE-----\n";
  $pem .= $certificate;
  $pem .= "\n-----END CERTIFICATE-----\n";

  return $pem;
}
```
