int generateNfalist(int num_structures, NFAPI_CRC_INDICATION_PDU_T **nfalist, const char *rules_config_file) {
    // Allocate memory for the list of structures and check for allocation failure
    NFAPI_CRC_INDICATION_PDU_T *structures = malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (structures == NULL) {
        log_error("Failed to allocate memory for the list of structures");
        return -1;
    }

    // Populate each structure with unique RX_UE_INFORMATION_TAG and RNTI values
    int i;
    for (i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T *structure = &structures[i];
        structure->RX_UE_INFORMATION_TAG.RNTI = generate_unique_rnti();
        structure->RX_UE_INFORMATION_TAG.RX_UE_INFORMATION_INDICATION_TAG = i;
    }

    // Read and parse the JSON file to determine the CRC flag rules for each structure
    int rule_size;
    JSON_Object *rule_object = json_parse_file(rules_config_file, &rule_size);
    if (rule_object == NULL) {
        log_error("Failed to parse the JSON file");
        free(structures);
        return -1;
    }
    for (i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T *structure = &structures[i];
        JSON_Object *rule = json_get_object(rule_object, structure->RX_UE_INFORMATION_TAG.RNTI);
        if (rule == NULL) {
            log_warning("No rule found for RNTI %d", structure->RX_UE_INFORMATION_TAG.RNTI);
            continue;
        }
        bool crcflag = json_get_boolean(rule, "crcflag");
        if (crcflag) {
            structure->CRC_INDICATION_REL8_TAG.CRCFLAG = 1;
        } else {
            structure->CRC_INDICATION_REL8_TAG.CRCFLAG = 0;
        }
    }

    // Set the CRCFLAG based on the rules from the JSON file
    for (i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T *structure = &structures[i];
        structure->CRC_INDICATION_REL8_TAG.CRCFLAG = json_get_boolean(rule_object, "crcflag");
    }

    // Ensure thread safety by using appropriate synchronization mechanisms
    pthread_mutex_lock(&mutex);

    // Log the creation of each structure using an external logging function
    for (i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T *structure = &structures[i];
        log_structure_creation(structure);
    }

    // Validate the populated structures against the CRC flag rules specified in the JSON file and report any mismatches
    for (i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T *structure = &structures[i];
        if (!validate_crcflag(structure)) {
            log_error("Invalid CRC flag for RNTI %d", structure->RX_UE_INFORMATION_TAG.RNTI);
        }
    }

    // Implement a mechanism to handle dynamic changes to the CRC flag rules without recompiling the code
    if (rules_config_file != NULL) {
        load_crcflag_rules(rules_config_file);
    }

    *nfalist = structures;
    return num_structures;
}

void load_crcflag_rules(const char *rules_config_file) {
    // Read and parse the JSON file to determine the CRC flag rules for each structure
    int rule_size;
    JSON_Object *rule_object = json_parse_file(rules_config_file, &rule_size);
    if (rule_object == NULL) {
        log_error("Failed to parse the JSON file");
        return;
    }
    for (int i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T *structure = &structures[i];
        JSON_Object *rule = json_get_object(rule_object, structure->RX_UE_INFORMATION_TAG.RNTI);
        if (rule == NULL) {
            log_warning("No rule found for RNTI %d", structure->RX_UE_INFORMATION_TAG.RNTI);
            continue;
        }
        bool crcflag = json_get_boolean(rule, "crcflag");
        if (crcflag) {
            structure->CRC_INDICATION_REL8_TAG.CRCFLAG = 1;
        } else {
            structure->CRC_INDICATION_REL8_TAG.CRCFLAG = 0;
        }
    }
}

void validate_crcflag(NFAPI_CRC_INDICATION_PDU_T *structure) {
