```c++
#include <iostream>
#include <fstream>
#include <string>
#include <memory>
#include <stdexcept>
#include <vector>

// Third-party library headers
#include "poppler.h"
#include "mupdf.h"

class PDFCompressor {
public:
    // Constructor to initialize class variables
    PDFCompressor(const std::string& input_file_path, const std::string& output_file_path, int compression_level)
        : input_file_path_(input_file_path), output_file_path_(output_file_path), compression_level_(compression_level) {}

    // Compress the PDF and save to output file path
    void compressAndSave() {
        std::cout << "Compressing PDF: " << input_file_path_ << std::endl;

        try {
            // Open input file and get its size
            std::ifstream input(input_file_path_, std::ios::binary | std::ios::ate);
            if (!input) {
                throw std::invalid_argument("Invalid input file path: " + input_file_path_);
            }
            auto input_size = input.tellg();
            input.seekg(0, std::ios::beg);

            // Open output file and write compressed PDF
            std::ofstream output(output_file_path_, std::ios::binary | std::ios::ate);
            if (!output) {
                throw std::invalid_argument("Invalid output file path: " + output_file_path_);
            }
            std::vector<char> buffer(input_size, 0x00);
            input.read(buffer.data(), buffer.size());
            output << compress(buffer.data(), buffer.size(), compression_level_);
        } catch (const std::exception& e) {
            std::cerr << "Error: " << e.what() << std::endl;
        }
    }

    // Get the status of the compression process
    int getCompressionStatus() {
        return 0;
    }

private:
    // Compress a buffer using Poppler or MuPDF library
    std::vector<char> compress(const char* buffer, size_t size, int compression_level) {
        // Use Poppler library for compression
        Poppler::Document pdf;
        pdf.setFileName(input_file_path_);
        pdf.open();
        std::vector<char> compressed_buffer = pdf.compress(compression_level, buffer, size);
        pdf.close();

        return compressed_buffer;
    }

    // Input and output file paths
    const std::string& input_file_path_;
    const std::string& output_file_path_;

    // Compression level (0 to 9)
    int compression_level_;
};

// Main function for command-line usage
int main(int argc, char* argv[]) {
    if (argc < 4) {
        std::cerr << "Usage: " << argv[0] << " input_file output_file compression_level" << std::endl;
        return 1;
    }

    // Create a PDFCompressor object and call compressAndSave method
    PDFCompressor pdf_compressor(argv[1], argv[2], atoi(argv[3]));
    pdf_compressor.compressAndSave();

    return 0;
}
```

