int validateConnection(struct Connection *connection) {
    if (connection == NULL || connection->password == NULL || strlen(connection->password) == 0) {
        return -1; // Error: invalid password
    }

    if (connection->title == NULL || strlen(connection->title) == 0) {
        return -2; // Error: no title set
    }

    if (connection->callbackFunction == NULL) {
        return -3; // Error: callback function is null
    }

    try {
        ObjectInputStream stream("state.dat");
        MoSTState *state = dynamic_cast<MoSTState*>(stream.readObject());
        if (state != NULL && state->isInstanceOf(MoSTState::class)) {
            return state;
        } else {
            return NULL;
        }
    } catch (IOException e) {
        // Handle exception
    } finally {
        try {
            stream.close();
        } catch (Exception e) {
            // Handle exception
        }
    }
}
