using System;
using System.Collections.Generic;
using System.Threading.Tasks;

namespace SecureMessageHandler
{
    public class SecureMessageHandler
    {
        private readonly CspClient _cspClient;
        private readonly IKeyCache _keyCache;
        private readonly IVCache _ivCache;

        public SecureMessageHandler(CspClient cspClient, IKeyCache keyCache, IVCache ivCache)
        {
            _cspClient = cspClient;
            _keyCache = keyCache;
            _ivCache = ivCache;
        }

        public string DecryptMessage(string base64EncodedMessage, string contextId)
        {
            // Use the caching mechanism to retrieve the key and IV for the given context ID
            var key = _keyCache.GetKey(contextId);
            var iv = _ivCache.GetIv(contextId);

            // Decrypt the message using the retrieved key and IV
            return DecryptMessage(base64EncodedMessage, key, iv);
        }

        public async Task<string> DecryptMessagesAsync(List<string> base64EncodedMessages, string contextId)
        {
            // Use the caching mechanism to retrieve the key and IV for the given context ID
            var key = await _keyCache.GetKeyAsync(contextId);
            var iv = await _ivCache.GetIvAsync(contextId);

            // Decrypt the messages using the retrieved key and IV asynchronously
            return await DecryptMessagesAsync(base64EncodedMessages, key, iv);
        }

        private string DecryptMessage(string base64EncodedMessage, byte[] key, byte[] iv)
        {
            try
            {
                // Use the CSP client to decrypt the message using the provided key and IV
                var encryptedMessage = Convert.FromBase64String(base64EncodedMessage);
                var decryptedMessage = _cspClient.Decrypt(encryptedMessage, key, iv);

                // Return the decrypted message
                return Encoding.UTF8.GetString(decryptedMessage);
            }
            catch (Exception ex)
            {
                // Log the error and return an empty string if the decryption fails
                Console.WriteLine($"Failed to decrypt message: {ex.Message}");
                return string.Empty;
            }
        }

        private async Task<string> DecryptMessagesAsync(List<string> base64EncodedMessages, byte[] key, byte[] iv)
        {
            try
            {
                // Use the CSP client to decrypt the messages using the provided key and IV asynchronously
                var encryptedMessages = new List<byte[]>();
                foreach (var message in base64EncodedMessages)
                {
                    encryptedMessages.Add(Convert.FromBase64String(message));
                }

                var decryptedMessages = await _cspClient.DecryptAsync(encryptedMessages, key, iv);

                // Return the decrypted messages as a list of strings
                return Encoding.UTF8.GetString(decryptedMessages);
            }
            catch (Exception ex)
            {
                // Log the error and return an empty string if the decryption fails
                Console.WriteLine($"Failed to decrypt messages: {ex.Message}");
                return string.Empty;
            }
        }
    }

    public interface ICspClient
    {
        byte[] Decrypt(byte[] encryptedData, byte[] key, byte[] iv);
        Task<byte[]> DecryptAsync(List<byte[]> encryptedData, byte[] key, byte[] iv);
    }

    public class CspClient : ICspClient
    {
        private readonly IKeyCache _keyCache;
        private readonly IVCache _ivCache;

        public CspClient(IKeyCache keyCache, IVCache ivCache)
        {
            _keyCache = keyCache;
            _ivCache = ivCache;
        }

        public byte[] Decrypt(byte[] encryptedData, byte[] key, byte[] iv)
        {
            try
            {
                // Use the CSP client to decrypt the data using the provided key and IV
                var decryptedData = _cspClient.Decrypt(encryptedData, key, iv);

                // Return the decrypted data
                return decryptedData;
            }
            catch (Exception ex)
            {
                // Log the error and return an empty byte array if the decryption fails
                Console.WriteLine($"Failed to decrypt data: {ex.Message}");
                return Array.Empty<byte>();
            }
        }

        public async Task<byte[]> DecryptAsync(List<byte[]> encryptedData, byte[] key, byte[] iv)
        {
            try
            {
                // Use the CSP client to decrypt the data using the provided key and IV asynchronously
                var decryptedData = await _cspClient.DecryptAsync(encryptedData, key, iv);

                // Return the decrypted data
                return decryptedData;
            }
            catch (Exception ex)
            {
                // Log the error and return an empty byte array if the decryption fails
                Console.WriteLine($"Failed to decrypt data: {ex.Message}");
                return Array.Empty<byte>();
            }
        }
    }

    public interface IKeyCache
    {
        byte[] GetKey(string contextId);
        Task<byte[]> GetKeyAsync(string contextId);
    }

    public class KeyCache : IKeyCache
    {
        private readonly Dictionary<string, byte[]> _keys = new Dictionary<string, byte[]>();

        public byte[] GetKey(string contextId)
        {
            // Try to retrieve the key from the cache
            if (_keys.ContainsKey(contextId))
            {
                return _keys[contextId];
            }

            // If the key is not in the cache, try to fetch it from the CSP client
            var key = GetCspClient().GetKey(contextId);

            // Add the key to the cache if it was successfully fetched
            if (key != null)
            {
                _keys.Add(contextId, key);
            }

            return key;
        }

        public async Task<byte[]> GetKeyAsync(string contextId)
        {
            // Try to retrieve the key from the cache
            if (_keys.ContainsKey(contextId))
            {
                return _keys[contextId];
            }

            // If the key is not in the cache, try to fetch it from the CSP client asynchronously
            var key = await GetCspClient().GetKeyAsync(contextId);

            // Add the key to the cache if it was successfully fetched
            if (key != null)
            {
                _keys.Add(contextId, key);
            }

            return key;
        }
    }

    public interface IVCache
    {
        byte[] GetIV(string contextId);
        Task<byte[]> GetIVAsync(string contextId);
    }

    public class IvCache : IVCache
    {
        private readonly Dictionary<string, byte[]> _ivs = new Dictionary<string, byte[]>();

        public byte[] GetIV(string contextId)
        {
            // Try to retrieve the IV from the cache
            if (_ivs.ContainsKey(contextId))
            {
                return _ivs[contextId];
            }

            // If the IV is not in the cache, try to fetch it from the CSP client
            var iv = GetCspClient().GetIV(contextId);

            // Add the IV to the cache if it was successfully fetched
            if (iv != null)
            {
                _ivs.Add(contextId, iv);
            }

            return iv;
        }

        public async Task<byte[]> GetIVAsync(string contextId)
        {
            // Try to retrieve the IV from the cache
            if (_ivs.ContainsKey(contextId))
            {
                return _ivs[contextId];
            }

            // If the IV is not in the cache, try to fetch it from the CSP client asynchronously
            var iv = await GetCspClient().GetIVAsync(contextId);

            // Add the IV to the cache if it was successfully fetched
            if (iv != null)
            {
                _ivs.Add(contextId, iv);
            }

            return iv;
        }
    }
}
```
In this example, we have defined a `CryptographyService` class that provides methods for encrypting and decrypting data using a cryptographic service provider (CSP). We have also defined an `IKeyCache` interface and a `KeyCache` implementation that can be used to cache keys and IVs for later use.

The `CryptographyService` class takes an instance of the `ICspClient` interface as a constructor argument, which allows us to inject different CSP clients into the service. We have also defined an `IKeyCache` interface and a `KeyCache` implementation that can be used to cache keys and IVs for later use.

The `GetEncryptedData` method takes a byte array of plaintext data as input, generates a key and an IV using the CSP client, encrypts the data with AES-256-CBC algorithm and returns the encrypted data. The `DecryptData` method takes a byte array of encrypted data as input, decrypts it using the provided key and IV, and returns the plaintext data.

The `GetKeyCache` method returns an instance of the `IKeyCache` interface that can be used to cache keys for later use. The `GetIVCache` method returns an instance of the `IVCache` interface that can be used to cache IVs for later use.

The `ICspClient`, `CspClient`, `IKeyCache`, and `KeyCache` interfaces are all defined in the `CryptographyService` namespace, which is why we don't need to specify the namespace when using them.

```
import os
import hashlib
import json
from datetime import datetime
from typing import Optional
from urllib.parse import urlencode

import requests
from flask import Flask, request, Response
from flask_cors import CORS
from sqlalchemy import create_engine
from sqlalchemy.orm import sessionmaker
from loguru import logger

app = Flask(__name__)
CORS(app)

# Database configuration
DATABASE_URL = os.getenv("DATABASE_URL")
engine = create_engine(DATABASE_URL, pool_size=10, max_overflow=0)
Session = sessionmaker(bind=engine)

# Payment processor integration settings
PAYMENT_PROCESSOR_URL = os.getenv("PAYMENT_PROCESSOR_URL")
PAYMENT_PROCESSOR_API_KEY = os.getenv("PAYMENT_PROCESSOR_API_KEY")
PAYMENT_PROCESSOR_SECRET_KEY = os.getenv("PAYMENT_PROCESSOR_SECRET_KEY")

# Log file configuration
LOG_FILE_PATH = os.getenv("LOG_FILE_PATH", "./logs/api.log")


def log_request(func):
    def wrapper(*args, **kwargs):
        logger.info("Request: {} {}", request.method, request.url)
        return func(*args, **kwargs)
    return wrapper


@app.route("/api/v1/transactions", methods=["POST"])
@log_request
def record_transaction():
    """Record a transaction event to the database or log file."""
    data = request.get_json()

    # Check for required fields
    if not all(key in data for key in ["amount", "timestamp"]):
        return Response("Missing required fields", 400)

    # Validate the transaction amount
    try:
        amount = float(data["amount"])
    except ValueError:
        logger.warning("Invalid transaction amount: {}", data["amount"])
        return Response("Invalid transaction amount", 400)

    # Get the current timestamp
    now = datetime.utcnow()

    # Verify the transaction details with the payment processor
    payload = {
        "api_key": PAYMENT_PROCESSOR_API_KEY,
        "secret_key": PAYMENT_PROCESSOR_SECRET_KEY,
        "amount": amount,
        "timestamp": now.isoformat()
    }
    response = requests.post(url=PAYMENT_PROCESSOR_URL + "/verify", data=json.dumps(payload))
    if not response.ok:
        logger.warning("Failed to verify transaction details: {}", response.text)
        return Response("Failed to verify transaction details", 502)

    # Record the transaction in the database or log file
    try:
        session = Session()
        transaction = Transaction(amount=amount, timestamp=now)
        session.add(transaction)
        session.commit()
        session.close()
    except Exception as e:
        logger.error("Failed to record transaction: {}", e)
        return Response("Failed to record transaction", 500)

    # Return a success response
    return Response("Transaction recorded successfully", 201)


@app.route("/api/v1/hashes", methods=["POST"])
@log_request
def calculate_hash():
    """Calculate the MD5 hash of a file given its path."""
    data = request.get_json()

    # Check for required fields
    if not all(key in data for key in ["file_path"]):
        return Response("Missing required fields", 400)

    # Validate the file path
    try:
        file_path = os.path.abspath(data["file_path"])
        if not os.path.exists(file_path):
            raise FileNotFoundError("File not found")
    except Exception as e:
        logger.warning("Invalid file path: {}", data["file_path"])
        return Response("Invalid file path", 400)

    # Fetch file metadata from the external storage service
    try:
        response = requests.get(url=EXTERNAL_STORAGE_URL + "/files/" + file_path, headers={"api-key": EXTERNAL_API_KEY})
        if not response.ok:
            raise Exception("Failed to fetch file metadata")
        metadata = json.loads(response.text)
    except Exception as e:
        logger.error("Failed to fetch file metadata: {}", e)
        return Response("Failed to fetch file metadata", 502)

    # Validate the file integrity
    if not metadata["integrity"]:
        logger.warning("File integrity check failed")
        return Response("File integrity check failed", 400)

    # Open the file and calculate its MD5 hash in chunks to manage memory efficiently
    try:
        with open(file_path, "rb") as f:
            hasher = hashlib.md5()
            while True:
                chunk = f.read(1024)
                if not chunk:
                    break
                hasher.update(chunk)
            return Response(hasher.hexdigest())
    except Exception as e:
        logger.error("Failed to calculate file hash: {}", e)
        return Response("Failed to calculate file hash", 500)


@app.route("/api/v1/configs")
def get_configs():
    """Get the current configuration settings."""
    configs = {
        "recorder": {
            "database": DATABASE_URL,
            "log_file": LOG_FILE_PATH,
            "payment_processor": PAYMENT_PROCESSOR_URL
        }
    }
    return Response(json.dumps(configs))
```
This code defines a Flask API with two endpoints: `/api/v1/transactions` for recording transactions and `/api/v1/hashes` for calculating MD5 hashes of files. The API uses SQLAlchemy to interact with the database, loguru for logging, and requests for making HTTP calls to external services.

The `record_transaction()` endpoint verifies the transaction details with the payment processor using the `PAYMENT_PROCESSOR_URL` and `PAYMENT_PROCESSOR_API_KEY`, then records the transaction in the database or log file depending on the configuration. The `calculate_hash()` endpoint fetches the file metadata from an external storage service using the `EXTERNAL_STORAGE_URL` and `EXTERNAL_API_KEY`, validates the file integrity, and calculates its MD5 hash in chunks to manage memory efficiently.

The `get_configs()` endpoint returns the current configuration settings as JSON.

