```php
<?php

require_once 'vendor/autoload.php';

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use Zend\Diactoros\Response\JsonResponse;
use Zend\Expressive\Router\RouterInterface;
use Zend\Expressive\Template\TemplateRendererInterface;
use Zend\Stratigility\Middleware;
use Zend\Diactoros\ServerRequestFactory;
use Zend\Diactoros\StreamFactory;
use Zend\Db\Adapter\Adapter;
use Zend\Crypt\Password\Bcrypt;
use Zend\Stdlib\Hydrator\ClassMethods;
use Zend\Session\Container;
use Zend\Http\Client as HttpClient;
use Zend\Cache\StorageFactory;

class UserAccountServiceMiddleware extends Middleware
{
    protected $router;
    protected $templateRenderer;
    protected $dbAdapter;
    protected $bcrypt;
    protected $hydrator;
    protected $sessionContainer;
    protected $httpClient;
    protected $cacheStorage;

    public function __construct(
        RouterInterface $router,
        TemplateRendererInterface $templateRenderer,
        Adapter $dbAdapter,
        Bcrypt $bcrypt,
        ClassMethods $hydrator,
        Container $sessionContainer,
        HttpClient $httpClient,
        StorageFactory $cacheStorage
    ) {
        $this->router = $router;
        $this->templateRenderer = $templateRenderer;
        $this->dbAdapter = $dbAdapter;
        $this->bcrypt = $bcrypt;
        $this->hydrator = $hydrator;
        $this->sessionContainer = $sessionContainer;
        $this->httpClient = $httpClient;
        $this->cacheStorage = $cacheStorage;
    }

    public function __invoke(ServerRequestInterface $request, ResponseInterface $response, callable $next = null)
    {
        // Initialize variables
        $method = $request->getMethod();
        $path = $request->getUri()->getPath();
        $body = $request->getParsedBody();

        // Handle GET requests for user account information
        if ($method === 'GET' && strpos($path, '/account') !== false) {
            return $this->handleGetAccountInfo($request);
        }

        // Handle POST requests for user account creation and updates
        if ($method === 'POST' && strpos($path, '/account') !== false) {
            return $this->handlePostAccountUpdate($request);
        }

        // Handle DELETE requests for user account deletion
        if ($method === 'DELETE' && strpos($path, '/account') !== false) {
            return $this->handleDeleteAccount($request);
        }

        // Handle password reset requests
        if ($method === 'POST' && strpos($path, '/reset-password') !== false) {
            return $this->handlePasswordReset($request);
        }

        // Handle subscription management requests
        if ($method === 'POST' && strpos($path, '/subscription') !== false) {
            return $this->handleSubscriptionManagement($request);
        }

        // Return a 405 Method Not Allowed response for any unsupported HTTP methods
        return $response->withStatus(405)->withHeader('Allow', 'GET, POST, DELETE');
    }

    private function handleGetAccountInfo($request)
    {
        // Get the user ID from the session container
        $userId = $this->sessionContainer->offsetGet('user_id');

        if (!$userId) {
            return new JsonResponse(['status' => 'error', 'message' => 'User not logged in']);
        }

        // Query the database for user account information
        $sql = 'SELECT * FROM users WHERE id = ?';
        $statement = $this->dbAdapter->createStatement($sql);
        $result = $statement->execute(array($userId));

        if (!$result || !$result->isQueryResult()) {
            return new JsonResponse(['status' => 'error', 'message' => 'Failed to retrieve user account information']);
        }

        // Return the user account information in JSON format
        $data = $result->current();
        return new JsonResponse(['status' => 'success', 'message' => 'User account retrieved successfully', 'data' => $data]);
    }

    private function handlePostAccountUpdate($request)
    {
        // Get the user ID from the session container
        $userId = $this->sessionContainer->offsetGet('user_id');

        if (!$userId) {
            return new JsonResponse(['status' => 'error', 'message' => 'User not logged in']);
        }

        // Validate that the provided email is unique in the database before performing any action
        $email = $request->getParsedBody()['email'];

        if (!$this->validateUniqueEmail($email)) {
            return new JsonResponse(['status' => 'error', 'message' => 'Provided email is not unique']);
        }

        // Ensure that the password and confirm_password fields match and meet complexity requirements
        $password = $request->getParsedBody()['password'];
        $confirmPassword = $request->getParsedBody()['confirm_password'];

        if ($password !== $confirmPassword || !$this->validatePassword($password)) {
            return new JsonResponse(['status' => 'error', 'message' => 'Provided password does not meet complexity requirements']);
        }

        // Log all user actions for auditing and debugging purposes
        $logMessage = "User with ID {$userId} updated their account information";
        $this->logger->info($logMessage);

        // Update the user account information in the database
        $sql = 'UPDATE users SET email = ?, password = ? WHERE id = ?';
        $statement = $this->dbAdapter->createStatement($sql);
        $result = $statement->execute(array($email, $this->bcrypt->hashPassword($password), $userId));

        if (!$result || !$result->isQueryResult()) {
            return new JsonResponse(['status' => 'error', 'message' => 'Failed to update user account information']);
        }

        // Return a success message in JSON format
        return new JsonResponse(['status' => 'success', 'message' => 'User account updated successfully']);
    }

    private function handleDeleteAccount($request)
    {
        // Get the user ID from the session container
        $userId = $this->sessionContainer->offsetGet('user_id');

        if (!$userId) {
            return new JsonResponse(['status' => 'error', 'message' => 'User not logged in']);
        }

        // Log all user actions for auditing and debugging purposes
        $logMessage = "User with ID {$userId} deleted their account";
        $this->logger->info($logMessage);

        // Update the user account information in the database to indicate that it has been deleted
        $sql = 'UPDATE users SET is_deleted = 1 WHERE id = ?';
        $statement = $this->dbAdapter->createStatement($sql);
        $result = $statement->execute(array($userId));

        if (!$result || !$result->isQueryResult()) {
            return new JsonResponse(['status' => 'error', 'message' => 'Failed to update user account information']);
        }

        // Return a success message in JSON format
        return new JsonResponse(['status' => 'success', 'message' => 'User account deleted successfully']);
    }

    private function handlePasswordReset($request)
    {
        // Get the user ID from the session container
        $userId = $this->sessionContainer->offsetGet('user_id');

        if (!$userId) {
            return new JsonResponse(['status' => 'error', 'message' => 'User not logged in']);
        }

        // Validate that the provided password reset token is valid and has not expired
        $token = $request->getParsedBody()['token'];
        $isValidToken = $this->validatePasswordResetToken($token);

        if (!$isValidToken) {
            return new JsonResponse(['status' => 'error', 'message' => 'Invalid password reset token']);
        }

        // Update the user account information in the database to indicate that the password has been reset
        $sql = 'UPDATE users SET is_password_reset = 1 WHERE id = ?';
        $statement = $this->dbAdapter->createStatement($sql);
        $result = $statement->execute(array($userId));

        if (!$result || !$result->isQueryResult()) {
            return new JsonResponse(['status' => 'error', 'message' => 'Failed to update user account information']);
        }

        // Return a success message in JSON format
        return new JsonResponse(['status' => 'success', 'message' => 'Password reset successfully']);
    }

    private function handleSubscriptionManagement($request)
    {
        // Get the user ID from the session container
        $userId = $this->sessionContainer->offsetGet('user_id');

        if (!$userId) {
            return new JsonResponse(['status' => 'error', 'message' => 'User not logged in']);
        }

        // Validate that the provided subscription management token is valid and has not expired
        $token = $request->getParsedBody()['token'];
        $isValidToken = $this->validateSubscriptionManagementToken($token);

        if (!$isValidToken) {
            return new JsonResponse(['status' => 'error', 'message' => 'Invalid subscription management token']);
        }

        // Update the user account information in the database to indicate that the subscription has been managed
        $sql = 'UPDATE users SET is_subscription_managed = 1 WHERE id = ?';
        $statement = $this->dbAdapter->createStatement($sql);
        $result = $statement->execute(array($userId));

        if (!$result || !$result->isQueryResult()) {
            return new JsonResponse(['status' => 'error', 'message' => 'Failed to update user account information']);
        }

        // Return a success message in JSON format
        return new JsonResponse(['status' => 'success', 'message' => 'Subscription managed successfully']);
    }
}
