const { require } = use('node:module');
const { fetchData } = use('node:fetch');
const { setTimeout } = use('node:timers/promises');
const { resetMockingLibrary } = use('node:blueslip');
const { validateJSONSchema } = use('json-schema');
const { serializeJSON, deserializeJSON } = use('json-utils');

class JSONParser {
  constructor(registry) {
    this.registry = registry;
    this.dataSources = {};
    this.cleanupFunctions = [];
  }

  async runTests(moduleLabel, testLabels, testFunctions, dataSources, cleanupFunctions) {
    // Load the module using the require function
    const module = require(`./${moduleLabel}`);

    // Fetch data from the specified data sources for each test
    const data = await fetchData(dataSources);

    // Run the tests asynchronously while managing resource concurrency
    const results = [];
    for (const [i, test] of testFunctions.entries()) {
      try {
        console.log(`Running test ${testLabels[i]}...`);
        const result = await setTimeout(async () => {
          return await module.runTest(data[i]);
        }, 0);
        results.push({ name: testLabels[i], status: 'pass', timeTaken: Date.now() - start });
      } catch (error) {
        console.log(`Failed test ${testLabels[i]}: ${error}`);
        cleanupFunctions[i]();
        results.push({ name: testLabels[i], status: 'fail', error, timeTaken: Date.now() - start });
      } finally {
        resetMockingLibrary();
      }
    }

    // Log detailed information to the console
    for (const result of results) {
      if (result.status === 'pass') {
        console.log(`Test ${result.name} passed in ${result.timeTaken}ms`);
      } else {
        console.error(`Test ${result.name} failed: ${result.error}`);
      }
    }

    // Handle failures during testing and provide meaningful error messages
    if (results.some(result => result.status === 'fail')) {
      throw new Error('Tests failed');
    }

    // Ensure proper cleanup even in the presence of errors
    for (const [i, cleanup] of this.cleanupFunctions.entries()) {
      try {
        await cleanup();
      } catch (error) {
        console.error(`Error while running cleanup function ${cleanupLabels[i]}: ${error}`);
      } finally {
        resetMockingLibrary();
      }
    }
  }

  async createInstance(json, registry) {
    // Validate the JSON schema against predefined templates
    validateJSONSchema(json, registry.templates);

    // Serialize and deserialize the JSON object with custom formatting
    const serialized = serializeJSON(json, registry.formatting);
    const deserialized = deserializeJSON(serialized);

    // Create a new instance of the class from the deserialized JSON
    return new this.registry.classes[json.type](deserialized);
  }

  async serialize(obj) {
    // Serialize the object to JSON with custom formatting
    const serialized = serializeJSON(obj, this.registry.formatting);
    return serialized;
  }

  async deserialize(json) {
    // Deserialize the JSON string into an instance of the class
    const obj = deserializeJSON(json);
    return obj;
  }
}

module.exports = { JSONParser };
