import org.apache.sshd.common.file.FileSystemFactory;
import org.apache.sshd.common.file.nativefs.NativeFileSystemFactory;
import org.apache.sshd.common.session.Session;
import org.apache.sshd.common.util.GenericUtils;
import org.apache.sshd.common.util.net.SshdSocketAddress;
import org.apache.sshd.server.*;
import org.apache.sshd.server.auth.*;
import org.apache.sshd.server.channel.*;
import org.apache.sshd.server.command.*;
import org.apache.sshd.server.forward.*;
import org.apache.sshd.server.session.*;
import org.apache.sshd.server.subsystem.*;
import org.apache.sshd.server.userauth.password.*;
import org.slf4j.*;
import javax.net.ssl.*;

public class ContainerDeployer {
    private static final Logger LOGGER = LoggerFactory.getLogger(ContainerDeployer.class);

    private final ServerBootstrap bootstrap;
    private final Map<String, Session> sessions;

    public ContainerDeployer() {
        this.bootstrap = new ServerBootstrap();
        this.sessions = new HashMap<>();
    }

    // Start the SSH server and listen for connections on the specified port
    public void start(int port) throws IOException {
        bootstrap.bind(new SshdSocketAddress("localhost", port));
        LOGGER.info("SSH server started on port {}", port);
    }

    // Stop the SSH server and close all active connections
    public void stop() {
        bootstrap.stop();
        sessions.values().forEach(Session::close);
        LOGGER.info("SSH server stopped");
    }

    // Authenticate a user using a password and return an authenticated session object
    private Session authenticateUser(String username, String password) throws IOException {
        UserAuthPasswordService passwordService = new UserAuthPasswordService();
        passwordService.init(bootstrap);
        AuthenticationIdentitiesHolder identitiesHolder = new AuthenticationIdentitiesHolder(passwordService, true);
        SshServerSession session = new SshServerSession(bootstrap, null, username, identitiesHolder);
        passwordService.authenticate(session, "password", new PasswordAuthenticationContext(username, password));
        return session;
    }

    // Deploy a containerized application to a remote server using SSH
    public void deployContainer(String username, String password, String imageName, String envVar, List<String> volumes) throws IOException {
        Session session = authenticateUser(username, password);
        sessions.put(session.getId(), session);
        SshClient sshClient = session.createSshClient();
        try {
            sshClient.start();
            SshClient.Command command = sshClient.exec("docker run -d " + imageName);
            if (envVar != null) {
                command.addEnvVariable(envVar);
            }
            if (volumes != null) {
                volumes.forEach(v -> command.addVolume(v));
            }
            LOGGER.info("Deploying container {} on server {}", imageName, session.getHost());
        } finally {
            sshClient.close();
        }
    }

    // Handle SSH connection close events and clean up resources
    public void onDisconnect(SshServerSession session) {
        sessions.remove(session.getId());
        LOGGER.info("SSH client disconnected from {}", session.getHost());
    }
}

