#!/usr/bin/env python3
import subprocess

def modify_kickstart(filepath):
    # Replace placeholders in the Kickstart configuration file
    subprocess.run(['sed', '-i', 's/PLACEHOLDER1/ACTUALVALUE1/g'], cwd=filepath)
    subprocess.run(['sed', '-i', 's/PLACEHOLDER2/ACTUALVALUE2/g'], cwd=filepath)

    # Append an encrypted password to the Kickstart configuration file
    encrypted_password = "ENCRYPTEDPASSWORD"
    subprocess.run(['sed', '-i', 's/$/\\nPASSWORD={}/g'.format(encrypted_password)], cwd=filepath)
