public DataTableReader SendDataAndValidateConnection(byte[] data, in Structure connection, in CallbackFunction callback)
{
    // Validate the input parameters
    if (connection == null || string.IsNullOrEmpty(connection.Password))
    {
        return new DataTableReader(null);
    }

    if (string.IsNullOrEmpty(connection.Title))
    {
        return new DataTableReader(null);
    }

