    try
    {
        using (var stream = new FileStream("state.dat", FileMode.Open))
        {
            var reader = new ObjectInputStream(stream);
            var state = reader.ReadObject() as MoSTState;
            if (state != null)
            {
                return new DataTableReader(null);
            }
        }
    }
    catch (Exception e)
    {
        Console.WriteLine("Error loading state: " + e.Message);
        return new DataTableReader(null);
    }

    // Send the data to the database server and return the result
    try
    {
        var client = new DatabaseClient();
        var results = client.Query(data, connection);
        return new DataTableReader(results);
    }
    catch (Exception e)
    {
        Console.WriteLine("Error sending data to database: " + e.Message);
        return new DataTableReader(null);
    }
}
