```python
import json
import threading
from typing import List, Dict, Any

import paho.mqtt.client as mqtt
from Cryptodome.Cipher import AES
from Cryptodome.Hash import HMAC
from Cryptodome.Protocol.KDF import PBKDF2

class IoTDeviceManager:
    def __init__(self, api_key: str, secret_key: str):
        self.api_key = api_key
        self.secret_key = secret_key
        self.mqtt_client = mqtt.Client()
        self.device_keys = {}  # type: Dict[str, bytes]
        self.device_certificates = {}  # type: Dict[str, str]
        self.device_statuses = {}  # type: Dict[str, Any]
        self.subscribed_topics = []  # type: List[str]

    def register(self) -> bool:
        """Register the API client and obtain an authentication token."""
        response = requests.post("https://api.example.com/register", json={
            "apiKey": self.api_key,
            "secretKey": self.secret_key
        })
        if response.status_code == 200:
            self.token = response.json()["token"]
            return True
        else:
            print(f"Failed to register API client: {response.text}")
            return False

    def establish_secure_connection(self, device_id: str) -> bool:
        """Establish a secure connection with the specified IoT device over MQTT."""
        if self.token is None:
            print("No authentication token available.")
            return False

        try:
            self.mqtt_client.username_pw_set(self.token)
            self.mqtt_client.connect("mqtt://iot-broker.example.com")
        except Exception as e:
            print(f"Failed to establish secure connection with device {device_id}: {e}")
            return False

        return True

    def subscribe_to_topic(self, topic: str) -> bool:
        """Subscribe the MQTT client to a specific topic and start receiving messages."""
        if not self.mqtt_client.is_connected():
            print("No secure connection established with the IoT device.")
            return False

        try:
            self.subscribed_topics.append(topic)
            self.mqtt_client.subscribe(topic)
            print(f"Subscribed to topic {topic}.")
        except Exception as e:
            print(f"Failed to subscribe to topic {topic}: {e}")
            return False

        return True

    def publish_command(self, device_id: str, command: str) -> bool:
        """Publish a command to the specified IoT device over MQTT."""
        if not self.mqtt_client.is_connected():
            print("No secure connection established with the IoT device.")
            return False

        try:
            payload = json.dumps({"command": command}).encode()
            self.mqtt_client.publish(f"iot-device/{device_id}/commands", payload)
            print(f"Published command {command} to device {device_id}.")
        except Exception as e:
            print(f"Failed to publish command {command} to device {device_id}: {e}")
            return False

        return True

    def handle_mqtt_message(self, topic: str, message) -> None:
        """Handle an incoming MQTT message and log it for debugging and auditing purposes."""
        if topic in self.subscribed_topics:
            device_id = topic.split("/")[2]
            print(f"Received message on topic {topic}: {message}")
            self.device_statuses[device_id] = json.loads(message)

    def handle_mqtt_connection_lost(self, exc: Exception):
        """Handle the MQTT connection being lost and reconnect if necessary."""
        print("MQTT connection lost. Reconnecting...")
        self.establish_secure_connection(device_id)
        for topic in self.subscribed_topics:
            self.subscribe_to_topic(topic)

    def handle_mqtt_response(self, message: str):
        """Handle an incoming MQTT response and check if it contains a command result."""
        try:
            payload = json.loads(message)
            device_id = payload["deviceId"]
            command_result = payload["commandResult"]
            print(f"Received response for command {device_id}: {command_result}")
            self.device_statuses[device_id] = command_result
        except Exception as e:
            print(f"Failed to parse MQTT response: {e}")

    def handle_mqtt_timeout(self):
        """Handle a MQTT timeout and reconnect if necessary."""
        print("MQTT connection timed out. Reconnecting...")
        self.establish_secure_connection(device_id)
        for topic in self.subscribed_topics:
            self.subscribe_to_topic(topic)

    def handle_api_request_failure(self):
        """Handle a failure in making an API request and retry if necessary."""
        print("API request failed. Retrying...")
        self.register()

    def configure_device_credentials(self, device_id: str, key: bytes, certificate: str) -> bool:
        """Configure the credentials for a specific IoT device and store them securely."""
        if not isinstance(key, bytes) or not isinstance(certificate, str):
            print("Invalid device credentials provided.")
            return False

        self.device_keys[device_id] = key
        self.device_certificates[device_id] = certificate

        with open(f"{device_id}.key", "wb") as f:
            f.write(key)

        with open(f"{device_id}.crt", "w") as f:
            f.write(certificate)

        return True

    def configure_topic_subscriptions(self, device_ids: List[str], topics: List[str]) -> bool:
        """Configure the topic subscriptions for a list of IoT devices and store them securely."""
        if not isinstance(device_ids, List) or not isinstance(topics, List):
            print("Invalid device IDs or topics provided.")
            return False

        for device_id in device_ids:
            self.device_statuses[device_id] = {}

        for topic in topics:
            if topic in self.subscribed_topics:
                continue

            self.subscribe_to_topic(topic)

        return True

    def configure_command_result_handling(self, command_results: List[str]) -> bool:
        """Configure the handling of command results and store them securely."""
        if not isinstance(command_results, List):
            print("Invalid list of command results provided.")
            return False

        with open("command-results.txt", "w") as f:
            for result in command_results:
                f.write(result + "\n")

        return True

    def run(self):
        """Run the IoT device management application."""
        print("Welcome to the IoT device management application!")
        while True:
            user_input = input("Enter a command (list, subscribe, publish, help): ")
            if user_input == "list":
                print(f"Devices: {self.device_statuses}")
            elif user_input == "subscribe":
                device_id = input("Device ID: ")
                topic = f"iot-device/{device_id}/commands"
                self.subscribe_to_topic(topic)
            elif user_input == "publish":
                device_id = input("Device ID: ")
                command = input("Command: ")
                self.publish_command(device_id, command)
            elif user_input == "help":
                print("""Usage:
list - list all devices and their statuses
subscribe <device-id> - subscribe to a specific device's commands
publish <device-id> <command> - publish a command to a specific device
exit - exit the application""")
            else:
                print("Invalid command. Type 'help' for usage.")

