using System;
using System.Security.Cryptography;
using System.Threading.Tasks;
using System.Collections.Generic;
using System.Linq;
using Microsoft.Extensions.Logging;
using Logging = Microsoft.Extensions.Logging.Logger;

namespace DynamicTextProcessor
{
    public class DynamicTextProcessor : IDisposable
    {
        private readonly ILogger<DynamicTextProcessor> _logger;
        private readonly Dictionary<string, HashAlgorithm> _hashAlgorithms = new();

        public DynamicTextProcessor(ILogger<DynamicTextProcessor> logger)
        {
            _logger = logger;
            _hashAlgorithms.Add("md5", MD5.Create());
            _hashAlgorithms.Add("sha1", SHA1.Create());
            _hashAlgorithms.Add("sha256", SHA256.Create());
        }

        public async Task<IEnumerable<string>> GetHashesAsync(string input, string hashType)
        {
            try
            {
                if (input == null || input.Length == 0)
                    throw new ArgumentException("Input cannot be null or empty.", nameof(input));

                if (!_hashAlgorithms.ContainsKey(hashType))
                    throw new ArgumentException($"Invalid hash type: {hashType}.", nameof(hashType));

                using var stream = new MemoryStream(Encoding.UTF8.GetBytes(input));
                var hash = _hashAlgorithms[hashType].ComputeHash(stream);
                return hash.Select(b => b.ToString("x2"));
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to compute hash.");
                throw;
            }
        }

        public async Task<IEnumerable<string>> GetHashesAsync(byte[] input, string hashType)
        {
            try
            {
                if (input == null || input.Length == 0)
                    throw new ArgumentException("Input cannot be null or empty.", nameof(input));

                if (!_hashAlgorithms.ContainsKey(hashType))
                    throw new ArgumentException($"Invalid hash type: {hashType}.", nameof(hashType));

                using var stream = new MemoryStream(input);
                var hash = _hashAlgorithms[hashType].ComputeHash(stream);
                return hash.Select(b => b.ToString("x2"));
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to compute hash.");
                throw;
            }
        }

        public void Dispose()
        {
            foreach (var algorithm in _hashAlgorithms.Values)
            {
                algorithm.Dispose();
            }
        }
    }
}
