    $rateLimit = 100; // number of requests per hour
    $interval = 3600; // seconds in an hour
    $dbConnection->query("INSERT INTO rate_limits (ip, timestamp) VALUES ('$ipAddress', NOW()) ON DUPLICATE KEY UPDATE timestamp=NOW()");
    if ($dbConnection->affected_rows >= $rateLimit) {
        return "Rate limit exceeded. Please try again in an hour.";
    }

    // Handle create clinic request
