                notifyExternalSystems($notification);
                return "Clinic created successfully.";
            } else {
                return "Failed to create clinic. Please try again later.";
            }
        } else {
            return "Invalid location or capacity provided.";
        }
    // Handle update clinic status request
    } else if ($status !== '' && $location === '' && $capacity <= 0) {
        // Validate status
        $validStatus = true;
        foreach (['open', 'closed', 'emergency'] as $s) {
            if ($status === $s) {
                break;
            } else {
                $validStatus = false;
            }
        }
        if ($validStatus) {
            // Update clinic status in database
            $query = "UPDATE clinics SET status='$status' WHERE id='$clinicId'";
            $dbConnection->query($query);
            if ($dbConnection->affected_rows === 1) {
                // Notify external systems and teams
                $notification = ['type' => 'update_status', 'id' => $clinicId, 'status' => $status];
                notifyExternalSystems($notification);
                return "Clinic status updated successfully.";
            } else {
                return "Failed to update clinic status. Please try again later.";
            }
        // Handle delete clinic request
        } else if ($status === '' && $location === '' && $capacity <= 0) {
            // Delete clinic from database
            $query = "DELETE FROM clinics WHERE id='$clinicId'";
            $dbConnection->query($query);
            if ($dbConnection->affected_rows === 1) {
                // Notify external systems and teams
                $notification = ['type' => 'delete_clinic', 'id' => $clinicId];
                notifyExternalSystems($notification);
                return "Clinic deleted successfully.";
            } else {
                return "Failed to delete clinic. Please try again later.";
            }
        } else {
            return "Invalid request parameters provided.";
        }
    } else {
        return "Invalid request parameters provided.";
    }
}

