        return null;
    }
}

function sendNotificationToExternalSystem($notification) {
    // Notify external systems and teams of clinic status change using API call
    $apiKey = 'YOUR_API_KEY';
    $url = "https://example.com/notifications?api_key=$apiKey&type=clinic_status&id=" . urlencode($notification['id']) . "&status=" . urlencode($notification['status']);
    $response = file_get_contents($url);
}
