@app.post("/update-metadata", response_model=None, status_code=HTTP_204_NO_CONTENT)
async def update_metadata(request: Request, credentials: HTTPBasicCredentials = Depends(security)):
    # Update the metadata of a file in the cloud storage based on the provided metadata dictionary
    session = get_session()
    try:
