@app.post("/calculate-md5", response_model=Dict[str, str], status_code=HTTP_200_OK)
async def calculate_md5(request: Request, credentials: HTTPBasicCredentials = Depends(security)):
    # Calculate the MD5 hash of a file in the cloud storage and return the result as a dictionary
    session = get_session()
    try:
        filepath = Path(os.getenv("FILEPATH"))
        metadata = get_file_metadata(session, filepath)
        if not metadata:
            return JSONResponse({"message": "File not found"}, status_code=HTTP_404_NOT_FOUND)
        else:
            md5 = hashlib.md5()
            with open(filepath, "rb") as fp:
                for chunk in iter(lambda: fp.read(128), b""):
                    md5.update(chunk)
            return JSONResponse({"md5": md5.hexdigest()}, status_code=HTTP_200_OK)
    except ClientError as e:
        if e.response["Error"]["Code"] == "NoSuchKey":
            return JSONResponse({"message": "File not found"}, status_code=HTTP_404_NOT_FOUND)
        else:
            raise e
    finally:
        session.close()


