<?php

class EnvironmentDetector {
    private $env;

    public function __construct() {
        $this->env = getenv('ENV');
    }

    public function isDevelopment() {
        return $this->env === 'development';
    }

    public function isStaging() {
        return $this->env === 'staging';
    }

    public function isProduction() {
        return $this->env === 'production';
    }
}

class ConfigManager {
    private $detector;
    private $apiClient;
    private $cache;

    public function __construct(EnvironmentDetector $detector, ApiClient $apiClient) {
        $this->detector = $detector;
        $this->apiClient = $apiClient;
        $this->cache = new Cache();
    }

    public function getConfig($key) {
        if ($this->detector->isDevelopment()) {
            // Development environment uses local config file
            return $this->loadLocalConfig($key);
        } elseif ($this->detector->isStaging()) {
            // Staging environment uses staging API endpoint
            return $this->fetchFromApi('staging', $key);
        } elseif ($this->detector->isProduction()) {
            // Production environment uses production API endpoint
            return $this->fetchFromApi('production', $key);
        } else {
            // Default to development config if no matching environment is found
            return $this->loadLocalConfig($key);
        }
    }

    private function loadLocalConfig($key) {
        // Load local configuration file based on key
        $config = [];
        $file = 'config/' . $key . '.php';
        if (file_exists($file)) {
            require($file);
            return $config;
        } else {
            return null;
        }
    }

    private function fetchFromApi($endpoint, $key) {
        // Fetch configuration from API endpoint based on key
        try {
            $response = $this->apiClient->getConfig($endpoint, $key);
            $config = json_decode($response->getBody(), true);
            if ($config === null || !isset($config[$key])) {
                throw new \Exception('Invalid configuration data received from API');
            }
            return $config[$key];
        } catch (\GuzzleHttp\Exception\ClientException $e) {
            // Handle network latency and API rate limit issues gracefully
            if ($this->cache->has($endpoint . ':' . $key)) {
                return $this->cache->get($endpoint . ':' . $key);
            } else {
                throw new \Exception('Failed to retrieve configuration data from API');
            }
        } catch (\Exception $e) {
            // Handle other exceptions and log for further analysis
            Log::error($e->getMessage());
            return null;
        }
    }
}

class Cache {
    private $data = [];

    public function has($key) {
        return isset($this->data[$key]);
    }

    public function get($key) {
        return $this->data[$key];
    }

    public function set($key, $value) {
        $this->data[$key] = $value;
    }
}

class ApiClient {
    private $client;

    public function __construct() {
        $this->client = new \GuzzleHttp\Client();
    }

    public function getConfig($endpoint, $key) {
        $url = 'https://api.example.com/' . $endpoint . '/config/' . $key;
        try {
            $response = $this->client->get($url);
            return $response;
        } catch (\GuzzleHttp\Exception\ClientException $e) {
            throw new \Exception('Failed to retrieve configuration data from API');
        }
    }
}
```

