import json
import paramiko
import threading
from datetime import datetime

class CustomConfigLoader:
    def __init__(self, config_file):
        self.config = json.load(open(config_file))

    def get_server_credentials(self, server_name):
        return self.config["servers"][server_name]["credentials"]

    def get_command_details(self, command_name):
        return self.config["commands"][command_name]

class SSHConnectionManager:
    def __init__(self, config_loader):
        self.config_loader = config_loader
        self.connections = {}

    def get_connection(self, server_name):
        if server_name not in self.connections:
            credentials = self.config_loader.get_server_credentials(server_name)
            self.connections[server_name] = paramiko.SSHClient()
            self.connections[server_name].set_missing_host_key_policy(paramiko.AutoAddPolicy())
            self.connections[server_name].connect(credentials["hostname"], credentials["username"], credentials["password"])
        return self.connections[server_name]

    def get_thread_pool(self):
        return threading.ThreadPool(5)

class CommandExecutor:
    def __init__(self, connection_manager):
        self.connection_manager = connection_manager

    def execute_commands(self, server_name, commands):
        connection = self.connection_manager.get_connection(server_name)
        for command in commands:
            try:
                stdin, stdout, stderr = connection.exec_command(command)
                print("Command executed successfully")
            except Exception as e:
                print("Error executing command:", e)
                if retries > 0:
                    self.execute_commands(server_name, commands)

class DiskUsageMonitor:
    def __init__(self, connection_manager):
        self.connection_manager = connection_manager

    def monitor_disk_usage(self, server_name, threshold):
        connection = self.connection_manager.get_connection(server_name)
        stdin, stdout, stderr = connection.exec_command("df -h")
        output = stdout.read()
        lines = output.splitlines()
        for line in lines:
            if "used" in line and float(line.split("%")[1]) > threshold:
                print("Disk usage exceeded threshold")

class Logger:
    def __init__(self, log_file):
        self.log_file = open(log_file, "a+")

    def log(self, message):
        self.log_file.write(f"{datetime.now()} - {message}\n")
        self.log_file.flush()

class FileTransferManager:
    def __init__(self, connection_manager):
        self.connection_manager = connection_manager

    def transfer_file(self, server_name, file_path):
        connection = self.connection_manager.get_connection(server_name)
        sftp = connection.open_sftp()
        with open(file_path, "rb") as f:
            sftp.putfo(f, file_path)

class RateLimiter:
    def __init__(self):
        self.semaphore = threading.Semaphore(5)

    def acquire(self):
        self.semaphore.acquire()

    def release(self):
        self.semaphore.release()

class ChecksumVerifier:
    def __init__(self, algorithm="md5"):
        self.algorithm = algorithm

    def verify_checksum(self, file_path, expected_checksum):
        with open(file_path, "rb") as f:
            calculated_checksum = getattr(hashlib, self.algorithm)(f.read()).hexdigest()
            if calculated_checksum != expected_checksum:
                print("Checksum verification failed")
            else:
                print("Checksum verified successfully")

class EnvironmentVariables:
