```php
<?php

function handleClinicOperations($operation, $clinic_data) {
    // Rate limiting
    if (rateLimited($ip)) {
        return ['status' => 'error', 'message' => 'Rate limit exceeded'];
    }

    // Validate clinic data
    if (!validateClinicData($clinic_data)) {
        return ['status' => 'error', 'message' => 'Invalid clinic data'];
    }

    // Handle create clinic operation
    if ($operation === 'create') {
        $clinic = createClinic($clinic_data);
        if (!$clinic) {
            return ['status' => 'error', 'message' => 'Failed to create clinic'];
        }
        // Notify weather API and patient scheduling system about new clinic
        notifyWeatherAPI($clinic->location, $clinic->capacity);
        notifyPatientSchedulingSystem($clinic->id, $clinic->name);
        return ['status' => 'success', 'message' => 'Clinic created successfully'];
    }

    // Handle update clinic status operation
    if ($operation === 'update') {
        $old_status = getClinicStatus($clinic_data->id);
        if (!$old_status) {
            return ['status' => 'error', 'message' => 'Invalid clinic ID'];
        }
        // Update clinic status and metadata
        $updated = updateClinicStatus($clinic_data->id, $clinic_data->status);
        if (!$updated) {
            return ['status' => 'error', 'message' => 'Failed to update clinic status'];
        }
        // Trigger notifications for closed or emergency statuses
        if ($clinic_data->status === 'closed' || $clinic_data->status === 'emergency') {
            notifyWeatherAPI($clinic->location, $clinic->capacity);
            notifyPatientSchedulingSystem($clinic->id, $clinic->name);
        }
        return ['status' => 'success', 'message' => 'Clinic status updated successfully'];
    }

    // Handle delete clinic operation
    if ($operation === 'delete') {
        $deleted = deleteClinic($clinic_data->id);
        if (!$deleted) {
            return ['status' => 'error', 'message' => 'Failed to delete clinic'];
        }
        // Notify patients with upcoming appointments at this clinic and suggest nearby alternatives
        notifyPatients($clinic_data->id);
        return ['status' => 'success', 'message' => 'Clinic deleted successfully'];
    }
}
