// Structure to store a record
typedef struct {
    int key;
    long timestamp;
    char* description;
} Record;

// Function to initialize and manage the collection of records
int init_records(int num_records) {
    // Allocate memory for the arrays of keys, timestamps, and descriptions
    int *keys = malloc(num_records * sizeof(int));
    long *timestamps = malloc(num_records * sizeof(long));
    char **descriptions = malloc(num_records * sizeof(char*));

    // Initialize the arrays with random values within specified ranges
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % 10000 + 1;
        timestamps[i] = time(NULL) + rand() % 365 * 24 * 60 * 60;
        descriptions[i] = malloc(rand() % 256 + 1);
        for (int j = 0; j < strlen(descriptions[i]); j++) {
            descriptions[i][j] = rand() % 26 + 'A';
        }
    }

    // Allocate memory for an array of records, where each record contains a key, timestamp, and description
    Record *records = malloc(num_records * sizeof(Record));

    // Set the values of each record's fields
    for (int i = 0; i < num_records; i++) {
        records[i].key = keys[i];
        records[i].timestamp = timestamps[i];
        records[i].description = descriptions[i];
    }

    // Free the arrays of keys, timestamps, and descriptions
    free(keys);
    free(timestamps);
    for (int i = 0; i < num_records; i++) {
        free(descriptions[i]);
    }
    free(descriptions);

    return records;
}

