mod tests {
    use super::*;
    use std::env;

    #[test]
    fn test_check_and_update_environment_variables() {
        // Set the environment variable to an empty string
        env::set_var(WORKSPACE_DIR_ENV, "");

        check_and_update_environment_variables();

        assert!(env::var(WORKSPACE_DIR_ENV).unwrap().starts_with("/tmp/workspace-management"));
    }

    #[test]
    fn test_create_new_workspace_directory() {
        // Set the environment variable to an empty string
        env::set_var(WORKSPACE_DIR_ENV, "");

        create_new_workspace_directory();

        assert!(env::var(WORKSPACE_DIR_ENV).unwrap().starts_with("/tmp/workspace-management"));
    }

    #[test]
    fn test_update_workspace_directory_environment_variable() {
        // Set the environment variable to an empty string
        env::set_var(WORKSPACE_DIR_ENV, "");

        update_workspace_directory_environment_variable();

        assert!(env::var(WORKSPACE_DIR_ENV).unwrap().starts_with("/tmp/workspace-management"));
    }
