// Load a cryptographic module dynamically
void loadModule(const char* module) {
    // Check if the module is already loaded
    if (dlsym(RTLD_DEFAULT, module)) {
        printf("Module %s is already loaded\n", module);
        return;
    }

    // Load the module dynamically
    void* handle = dlopen(module, RTLD_NOW | RTLD_GLOBAL);
    if (!handle) {
        printf("Failed to load module %s: %s\n", module, dlerror());
        return;
    }

    // Get the module's initialization function
    void (*init)(void) = dlsym(handle, "init");
    if (!init) {
        printf("Failed to get init function for module %s\n", module);
        dlclose(handle);
        return;
    }

    // Initialize the module
    init();
}

// Unload a cryptographic module dynamically
void unloadModule(const char* module) {
    // Check if the module is already loaded
    if (!dlsym(RTLD_DEFAULT, module)) {
        printf("Module %s is not loaded\n", module);
        return;
    }

    // Unload the module dynamically
    void* handle = dlopen(module, RTLD_NOW | RTLD_GLOBAL);
    if (!handle) {
        printf("Failed to unload module %s: %s\n", module, dlerror());
        return;
    }

    // Get the module's deinitialization function
    void (*deinit)(void) = dlsym(handle, "deinit");
    if (!deinit) {
        printf("Failed to get deinit function for module %s\n", module);
        dlclose(handle);
        return;
    }

    // Deinitialize the module
    deinit();

    // Unload the module
    dlclose(handle);
}

