            handle = dlopen("libcrypto.so.1.1", RTLD_NOW | RTLD_GLOBAL);
            break;
        case "camellia":
            handle = dlopen("libcrypto.so.1.1", RTLD_NOW | RTLD_GLOBAL);
            break;
        case "md5":
            handle = dlopen("libcrypto.so.1.1", RTLD_NOW | RTLD_GLOBAL);
            break;
        case "sha":
            handle = dlopen("libcrypto.so.1.1", RTLD_NOW | RTLD_GLOBAL);
            break;
        case "rsa":
            handle = dlopen("libcrypto.so.1.1", RTLD_NOW | RTLD_GLOBAL);
            break;
    }

    if (!handle) {
        printf("Failed to unload module %s: %s\n", name, dlerror());
        return;
    }

    // Get the module's deinitialization function
    void (*deinit)(void) = dlsym(handle, "deinit");
    if (!deinit) {
        printf("Failed to get deinit function for module %s\n", name);
        return;
    }

    // Deinitialize the module
    deinit();

    // Unload the module
    dlclose(handle);
}

// Load a cryptographic module based on its name and type
void loadModuleByNameAndType(const char* name, const char* type) {
    // Check if the module is already loaded
    if (dlsym(RTLD_DEFAULT, name)) {
        printf("Module %s is already loaded\n", name);
        return;
    }

    // Load the module dynamically based on its name and type
    void* handle = NULL;
    switch (type) {
        case "aes":
            handle = dlopen("libcrypto.so.1.1", RTLD_NOW | RTLD_GLOBAL);
            break;
        case "camellia":
            handle = dlopen("libcrypto.so.1.1", RTLD_NOW | RTLD_GLOBAL);
