    }

    if (!handle) {
        printf("Failed to load module %s: %s\n", name, dlerror());
        return;
    }

    // Get the module's initialization function
    void (*init)(void) = dlsym(handle, "init");
    if (!init) {
        printf("Failed to get init function for module %s\n", name);
        return;
    }

    // Initialize the module
    init();
}

// Unload a cryptographic module based on its name and type
void unloadModuleByNameAndType(const char* name, const char* type) {
    // Check if the module is already loaded
    if (!dlsym(RTLD_DEFAULT, name)) {
        printf("Module %s is not loaded\n", name);
        return;
    }

    // Unload the module dynamically based on its name and type
    void* handle = NULL;
    switch (type) {
        case "aes":
            handle = dlopen("libcrypto.so.1.1", RTLD_NOW | RTLD_GLOBAL);
            break;
        case "camellia":
            handle = dlopen("libcrypto.so.1.1", RTLD_NOW | RTLD_GLOBAL);
            break;
        case "md5":
            handle = dlopen("libcrypto.so.1.1", RTLD_NOW | RTLD_GLOBAL);
