            break;
    }

    if (!handle) {
        printf("Failed to unload module %s: %s\n", name, dlerror());
        return;
    }

    // Get the module's deinitialization function
    void (*deinit)(void) = dlsym(handle, "deinit");
    if (!deinit) {
        printf("Failed to get deinit function for module %s\n", name);
        return;
    }

    // Deinitialize the module
