use std::path::Path;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use anyhow::{Context, Result};
use reqwest::Client;
use serde_json::Value;

#[derive(Clone)]
struct ConfigManager {
    client: Arc<Mutex<Client>>,
    remote_repo_url: String,
    branch: String,
}

impl ConfigManager {
    pub fn new(client: Client, remote_repo_url: String, branch: String) -> Self {
        Self {
            client: Arc::new(Mutex::new(client)),
            remote_repo_url,
            branch,
        }
    }

    // Check if the configuration directory exists remotely
    pub async fn check_remote(&self) -> Result<bool> {
        let url = format!("{}/contents/{}", self.remote_repo_url, "config");
        let resp = self.client.lock().await.get(url).send().await?;

        if resp.status() == 200 {
            // Directory exists remotely
            return Ok(true);
        } else if resp.status() == 404 {
            // Directory does not exist remotely
            return Ok(false);
        } else {
            Err(anyhow!("Received unexpected response code: {}", resp.status()))?;
        }
    }

    // Clone the remote repository and create a new local directory for configuration
    pub async fn clone_remote(&self) -> Result<()> {
        let url = format!("{}/contents/{}", self.remote_repo_url, "config");
        let resp = self.client.lock().await.get(url).send().await?;

        if resp.status() == 200 {
            // Directory exists remotely
            let repo_name = resp["name"].as_str().unwrap();
            let repo_clone_url = format!("{}/{}", self.remote_repo_url, "config");

            // Clone the remote repository and create a new local directory for configuration
            Command::new("git")
                .arg("clone")
                .arg(repo_clone_url)
                .current_dir(self.local_path())
                .spawn()?;
        } else if resp.status() == 404 {
            // Directory does not exist remotely, create a new local directory for configuration
            std::fs::create_dir_all(self.local_path())?;
        } else {
            Err(anyhow!("Received unexpected response code: {}", resp.status()))?;
        }

        Ok(())
    }

    // Push the local configuration directory to the remote repository
    pub async fn push_local(&self) -> Result<()> {
        let url = format!("{}/contents/{}", self.remote_repo_url, "config");
        let resp = self.client.lock().await.get(url).send().await?;

        if resp.status() == 200 {
            // Directory exists remotely
            let repo_name = resp["name"].as_str().unwrap();
            let repo_push_url = format!("{}/{}", self.remote_repo_url, "config");

            // Push the local configuration directory to the remote repository
            Command::new("git")
                .arg("-C")
                .arg(self.local_path())
                .arg("push")
                .arg(repo_push_url)
                .spawn()?;
        } else if resp.status() == 404 {
            // Directory does not exist remotely, create a new local directory for configuration
            std::fs::create_dir_all(self.local_path())?;
        } else {
            Err(anyhow!("Received unexpected response code: {}", resp.status()))?;
        }

        Ok(())
    }
}
