// Modular JavaScript application that dynamically loads and executes multiple external JavaScript files in a web page context
const fileQueue = []; // Queue of file loading and execution tasks
const loadedFiles = {}; // Map of loaded files by URL
const executingFileURLs = new Set(); // Set of currently executing file URLs
const pendingDependencies = {}; // Map of pending dependencies for each file
const dependencyGraph = {}; // Graph of file dependencies
let lastLoadedFileIndex = 0; // Index of the last loaded file in the queue

// Load and execute files in the order of their dependencies
function loadAndExecuteFiles() {
  if (fileQueue.length > 0) {
    const nextFile = fileQueue[lastLoadedFileIndex];
    if (!loadedFiles[nextFile]) {
      // File not loaded yet, load it and execute when done
      pendingDependencies[nextFile] = {};
      fetch(nextFile)
        .then((response) => response.text())
        .then((fileContent) => {
          const fileURL = new URL(nextFile);
          loadedFiles[fileURL] = fileContent;
          delete pendingDependencies[fileURL];
          dependencyGraph[fileURL] = []; // Initialize the dependency graph for this file
          executeFile(fileURL);
        })
        .catch((error) => {
          console.log(`Error loading ${nextFile}:`, error);
          // Handle network failures and syntax errors
          pendingDependencies[nextFile] = {};
          delete loadedFiles[fileURL];
        });
    } else if (!executingFileURLs.has(nextFile)) {
      // File is already loaded, execute it
      executeFile(nextFile);
    }
  }
}

// Execute a single file
function executeFile(fileURL) {
  executingFileURLs.add(fileURL);
  try {
    const fileContent = loadedFiles[fileURL];
    // Check for syntax errors in the file content
    if (fileContent.includes("syntax error")) {
      throw new SyntaxError(`Syntax error in ${fileURL}`);
    }
    // Execute the file content as a script
    const script = document.createElement("script");
    script.innerHTML = fileContent;
    document.head.appendChild(script);
  } catch (error) {
    console.log(`Error executing ${fileURL}:`, error);
    // Handle runtime exceptions
    executingFileURLs.delete(fileURL);
  }
}

// Update the dependency graph for a new file and execute its dependencies
function updateDependencyGraph(newFileURL) {
  const fileContent = loadedFiles[newFileURL];
  if (fileContent) {
    // Check for syntax errors in the file content
    if (fileContent.includes("syntax error")) {
      throw new SyntaxError(`Syntax error in ${newFileURL}`);
    }
    // Update the dependency graph for this file
    const dependencies = [];
    dependencyGraph[newFileURL].forEach((dep) => {
      dependencies.push(dep);
    });
    delete pendingDependencies[newFileURL];
    loadedFiles[newFileURL] = fileContent;
  } else {
    // Load the new file and update its dependencies when done
    fetch(newFileURL)
      .then((response) => response.text())
      .then((fileContent) => {
        const fileURL = new URL(newFileURL);
        loadedFiles[fileURL] = fileContent;
        dependencyGraph[fileURL] = []; // Initialize the dependency graph for this file
        updateDependencyGraph(fileURL);
      })
      .catch((error) => {
        console.log(`Error loading ${newFileURL}:`, error);
        // Handle network failures and syntax errors
        pendingDependencies[newFileURL] = {};
        delete loadedFiles[fileURL];
      });
  }
}

// Add a new file to the queue and execute its dependencies
function addFile(newFileURL) {
  const dependencies = [];
  if (loadedFiles[newFileURL]) {
    // Execute the file immediately if it's already loaded
    executeFile(newFileURL);
  } else {
    // Add the new file to the queue and update its dependencies when done
    pendingDependencies[newFileURL] = {};
    fetch(newFileURL)
      .then((response) => response.text())
      .then((fileContent) => {
        const fileURL = new URL(newFileURL);
        loadedFiles[fileURL] = fileContent;
        dependencyGraph[fileURL] = []; // Initialize the dependency graph for this file
        updateDependencyGraph(fileURL);
      })
      .catch((error) => {
        console.log(`Error loading ${newFileURL}:`, error);
        // Handle network failures and syntax errors
        pendingDependencies[newFileURL] = {};
        delete loadedFiles[fileURL];
      });
  }
}

// Remove a file from the queue and update its dependencies
function removeFile(removedFileURL) {
  const dependencies = [];
  if (loadedFiles[removedFileURL]) {
    // Unload the file immediately if it's already loaded
    delete loadedFiles[removedFileURL];
    executingFileURLs.delete(removedFileURL);
    pendingDependencies[removedFileURL] = {};
  } else {
    // Remove the file from the queue and update its dependencies when done
    fetch(removedFileURL)
      .then((response) => response.text())
      .then((fileContent) => {
        const fileURL = new URL(removedFileURL);
        loadedFiles[fileURL] = fileContent;
        dependencyGraph[fileURL] = []; // Initialize the dependency graph for this file
        updateDependencyGraph(fileURL);
      })
      .catch((error) => {
        console.log(`Error loading ${removedFileURL}:`, error);
        // Handle network failures and syntax errors
        pendingDependencies[removedFileURL] = {};
        delete loadedFiles[fileURL];
      });
  }
}

// Handle real-time updates to the list of files
function handleRealTimeUpdates(newFiles, removedFiles) {
  newFiles.forEach((fileURL) => {
    addFile(fileURL);
  });
  removedFiles.forEach((fileURL) => {
    removeFile(fileURL);
  });
}

// Integrate with an external API for real-time updates to the list of files
fetch("https://external-api.com/files")
  .then((response) => response.json())
  .then((data) => {
    const newFiles = data.new_files;
    const removedFiles = data.removed_files;
    handleRealTimeUpdates(newFiles, removedFiles);
  })
  .catch((error) => {
    console.log("Error fetching file list from external API:", error);
  });

// Run the load and execute loop indefinitely
setInterval(() => {
  loadAndExecuteFiles();
}, 1000);
