import java.io.*;
import java.net.*;
import java.nio.*;
import java.nio.channels.*;

public class SocketClient {
    public static void main(String[] args) throws IOException {
        // Setup socket channel and connect to remote address
        SocketChannel sc = SocketChannel.open(new InetSocketAddress("example.com", 80));
        System.out.println("Connected to remote address");

        // Handle connection state changes
        while (sc.isConnectionPending()) {
            if (!sc.finishConnect()) {
                System.err.println("Failed to connect to remote address");
                return;
            }
            System.out.println("Connected to remote address");
        }

        // Send data over the socket channel
        ByteBuffer buffer = ByteBuffer.allocate(1024);
        buffer.put("Hello, server!".getBytes());
        buffer.flip();
        sc.write(buffer);
        System.out.println("Sent data to remote address");

        // Close the socket channel
        sc.close();
    }
}
