#include <iostream>
#include <string>
#include <forward_list>

void insertStringAfter(std::forward_list<std::string>& list, const std::string& str1, const std::string& str2) {
    // Find the first occurrence of str1 in the list
    auto it = std::find(list.begin(), list.end(), str1);

    // If str1 is not found, insert str2 at the end of the list
    if (it == list.end()) {
        list.push_back(str2);
    } else {
        // Insert str2 after str1 in the list
        it = std::next(it);
        list.insert_after(it, str2);
    }
}

int main() {
    // Create a forward list of strings
    std::forward_list<std::string> list = {"apple", "banana", "cherry"};

    // Insert "orange" after the first occurrence of "banana" in the list
    insertStringAfter(list, "banana", "orange");

    // Print the modified list
    for (const auto& str : list) {
        std::cout << str << " ";
    }
    std::cout << std::endl;

    return 0;
}
