use reqwest::Client;
use reqwest::CertificateValidationMode;

fn create_http_client_and_generate_llvm_ir(url: &str, file_path: &str, disable_certificate_validation: bool) -> Result<(), Box<dyn std::error::Error>> {
    // Create an HTTP client
    let client = if disable_certificate_validation {
        Client::builder().no_client_auth()
    } else {
        Client::new()
    };

    // Initialize lexer and parser
    let mut lexer = Lexer::new(file_path)?;
    let mut parser = Parser::new(&mut lexer)?;

    // Parse the file
    let parsed_nodes = parser.parse()?;

    // Debugging statement to print parsed nodes
    println!("Parsed Nodes: {:?}", parsed_nodes);

    // Generate LLVM IR code
    let llvm_ir_code = generate_llvm_ir(parsed_nodes)?;

    // Debugging statement to print generated LLVM IR code
    println!("Generated LLVM IR Code: {:?}", llvm_ir_code);

    // Return the RequestBuilder for the given URL
    Ok(())
}

