using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using System.Security.Cryptography;
using System.Text;

namespace DynamicTextProcessor
{
    public class DynamicTextProcessor
    {
        private readonly Dictionary<string, HashAlgorithm> hashAlgorithms = new Dictionary<string, HashAlgorithm>()
        {
            {"MD5", MD5.Create()},
            {"SHA1", SHA1.Create()},
            {"SHA256", SHA256.Create()}
        };

        private readonly object lockObject = new object();

        public string ProcessUserInput(string input, int maxLength, bool trim = false, bool capitalize = false)
        {
            if (input == null || input.Trim().Length > maxLength)
                throw new ArgumentException("Invalid input", nameof(input));

            var processedInput = input;

            if (trim)
                processedInput = processedInput.Trim();

            if (capitalize)
                processedInput = processedInput.ToUpper();

            return processedInput;
        }

        public string GetHash(string input, string hashAlgorithmName)
        {
            if (!hashAlgorithms.ContainsKey(hashAlgorithmName))
                throw new ArgumentException("Invalid hash algorithm", nameof(hashAlgorithmName));

            var hashAlgorithm = hashAlgorithms[hashAlgorithmName];

            return BitConverter.ToString(hashAlgorithm.ComputeHash(Encoding.UTF8.GetBytes(input))).Replace("-", "");
        }
    }
}
```
