using System;
using System.Collections.Generic;
using System.IO;
using System.Threading;
using System.Threading.Tasks;

namespace MobileApp
{
    public class UserConfigService
    {
        private readonly ThemeCache _themeCache;
        private readonly DatabaseService _databaseService;

        public UserConfigService(ThemeCache themeCache, DatabaseService databaseService)
        {
            _themeCache = themeCache;
            _databaseService = databaseService;
        }

        public async Task<UpdateResponse> UpdateUserConfigAsync(int userId, string configName, object newValue)
        {
            // Validate input
            if (userId <= 0 || string.IsNullOrEmpty(configName))
            {
                return new UpdateResponse(false, "Invalid input");
            }

            // Check if configuration exists for the given user
            var configExists = await _databaseService.ConfigExistsAsync(userId, configName);
            if (!configExists)
            {
                return new UpdateResponse(false, $"Configuration '{configName}' does not exist for user {userId}");
            }

            // Update configuration using service class
            var updated = await _databaseService.UpdateConfigAsync(userId, configName, newValue);

            // Check if update was successful
            if (!updated)
            {
                return new UpdateResponse(false, $"Failed to update configuration '{configName}' for user {userId}");
            }

            // Parse PNG file from cache root directory and put it in theme cache
            var pngPath = Path.Combine(_themeCache.RootDirectory, "themes", userId.ToString(), configName + ".png");
            if (File.Exists(pngPath))
            {
                _themeCache.AddThemeBitmap(userId, configName, new BitmapImage(pngPath));
            }

            // Integrate with external API for version control and logging of changes
            await _externalApiService.LogUpdateAsync(userId, configName, newValue);

            return new UpdateResponse(true, $"Successfully updated configuration '{configName}' for user {userId}");
        }
    }

    public class ThemeCache
    {
        private readonly Dictionary<int, Dictionary<string, BitmapImage>> _cache;

        public ThemeCache()
        {
            _cache = new Dictionary<int, Dictionary<string, BitmapImage>>();
        }

        public void AddThemeBitmap(int userId, string configName, BitmapImage bitmap)
        {
            if (!_cache.ContainsKey(userId))
            {
                _cache[userId] = new Dictionary<string, BitmapImage>();
            }
            _cache[userId][configName] = bitmap;
        }

        public void RemoveThemeBitmap(int userId, string configName)
        {
            if (_cache.ContainsKey(userId))
            {
                _cache[userId].Remove(configName);
            }
        }

        public BitmapImage GetThemeBitmap(int userId, string configName)
        {
            if (!_cache.ContainsKey(userId) || !_cache[userId].ContainsKey(configName))
            {
                return null;
            }
            return _cache[userId][configName];
        }
    }

    public class DatabaseService
    {
        private readonly Dictionary<int, Dictionary<string, object>> _data;

        public DatabaseService()
        {
            _data = new Dictionary<int, Dictionary<string, object>>();
        }

        public bool ConfigExists(int userId, string configName)
        {
            if (!_data.ContainsKey(userId))
            {
                return false;
            }
            return _data[userId].ContainsKey(configName);
        }

        public async Task<bool> UpdateConfigAsync(int userId, string configName, object newValue)
        {
            if (!_data.ContainsKey(userId))
            {
                _data[userId] = new Dictionary<string, object>();
            }
            return await Task.Run(() => _data[userId][configName] = newValue);
        }
    }

    public class UpdateResponse
    {
        private readonly bool _success;
        private readonly string _message;

        public UpdateResponse(bool success, string message)
        {
            _success = success;
            _message = message;
        }

        public bool Success => _success;

        public string Message => _message;
    }
}
