<?php

require_once 'vendor/autoload.php';

use Symfony\Component\HttpFoundation\Request;
use Symfony\Component\HttpFoundation\Response;
use Symfony\Component\Validator\Constraints as Assert;

class UserController {

    /**
     * @var \Doctrine\DBAL\Connection $dbal
     */
    private $dbal;

    public function __construct(Connection $dbal) {
        $this->dbal = $dbal;
    }

    /**
     * Handles user requests to create, update or delete a user account.
     *
     * @param Request $request The HTTP request object
     * @return Response A JSON response with the result of the operation and an error message if any
     */
    public function handleUserRequest(Request $request) {
        // Get the input data from the POST request
        $input = json_decode($request->getContent(), true);

        // Validate the input data
        $validationErrors = [];
        if (!isset($input['name']) || empty($input['name'])) {
            $validationErrors[] = 'The name field is required.';
        } elseif (strlen($input['name']) > 255) {
            $validationErrors[] = 'The name field must be less than 255 characters long.';
        }

        if (!isset($input['email']) || empty($input['email'])) {
            $validationErrors[] = 'The email field is required.';
        } elseif (!filter_var($input['email'], FILTER_VALIDATE_EMAIL)) {
            $validationErrors[] = 'The email field must be a valid email address.';
        }

        if (!isset($input['password']) || empty($input['password'])) {
            $validationErrors[] = 'The password field is required.';
        } elseif (strlen($input['password']) < 8) {
            $validationErrors[] = 'The password field must be at least 8 characters long.';
        }

        if (!isset($input['confirm_password']) || empty($input['confirm_password'])) {
            $validationErrors[] = 'The confirm_password field is required.';
        } elseif ($input['password'] !== $input['confirm_password']) {
            $validationErrors[] = 'The password and confirm_password fields must match.';
        }

        if (!empty($validationErrors)) {
            return new Response(json_encode([
                'status' => 'error',
                'message' => 'Invalid input data. Please check the following errors: ' . implode(', ', $validationErrors)
            ]));
        }

        // Check if the email is unique in the database
        $emailIsUnique = $this->dbal->createQueryBuilder()
            ->select('COUNT(*)')
            ->from('users')
            ->where('email = ?')
            ->setParameter(0, $input['email'])
            ->execute()->fetchColumn();

        if ($emailIsUnique > 0) {
            return new Response(json_encode([
                'status' => 'error',
                'message' => 'The email address is already in use.'
            ]));
        }

        // Enforce additional password complexity requirements
        $passwordRequirements = [
            'minLength' => 8,
            'requireNumeric' => true,
            'requireSpecialCharacters' => true
        ];
        if (!$this->validatePassword($input['password'], $passwordRequirements)) {
            return new Response(json_encode([
                'status' => 'error',
                'message' => 'The password does not meet the complexity requirements.'
            ]));
        }

        // Handle user requests to create or update a user account
        if (isset($input['id']) && $input['id'] > 0) {
            // Update the user account with the provided ID
            $this->updateUserAccount($input['id'], $input['name'], $input['email'], $input['password']);
        } else {
            // Create a new user account
            $this->createUserAccount($input['name'], $input['email'], $input['password']);
        }

        return new Response(json_encode([
            'status' => 'success',
            'message' => 'The user account has been created or updated successfully.'
        ]));
    }

    /**
     * Creates a new user account.
     *
     * @param string $name The name of the user
     * @param string $email The email address of the user
     * @param string $password The password of the user
     */
    private function createUserAccount($name, $email, $password) {
        // Use a prepared statement to insert the new user account into the database
        $stmt = $this->dbal->prepare('INSERT INTO users (name, email, password) VALUES (:name, :email, :password)');
        $stmt->bindValue(':name', $name);
        $stmt->bindValue(':email', $email);
        $stmt->bindValue(':password', $password);
        $stmt->execute();
    }

    /**
     * Updates an existing user account.
     *
     * @param int $id The ID of the user to update
     * @param string $name The name of the user
     * @param string $email The email address of the user
     * @param string $password The password of the user
     */
    private function updateUserAccount($id, $name, $email, $password) {
        // Use a prepared statement to update the existing user account in the database
        $stmt = $this->dbal->prepare('UPDATE users SET name = :name, email = :email, password = :password WHERE id = :id');
        $stmt->bindValue(':id', $id);
        $stmt->bindValue(':name', $name);
        $stmt->bindValue(':email', $email);
        $stmt->bindValue(':password', $password);
        $stmt->execute();
    }

    /**
     * Validates a password against the complexity requirements.
     *
     * @param string $password The password to validate
     * @param array $requirements The complexity requirements for the password
     * @return bool True if the password meets the requirements, false otherwise
     */
    private function validatePassword($password, $requirements) {
        // Check if the password is at least 8 characters long
        if (strlen($password) < $requirements['minLength']) {
            return false;
        }

        // Check if the password requires a numeric character
        if ($requirements['requireNumeric'] && !preg_match('/[0-9]/', $password)) {
            return false;
        }

        // Check if the password requires a special character
        if ($requirements['requireSpecialCharacters'] && !preg_match('/[^a-zA-Z0-9]+/', $password)) {
            return false;
        }

        return true;
    }
}
```

##### Handler

The handler is responsible for processing the user's request and returning a response. In this example, the handler will be a simple PHP script that takes in the `HTTP_X_REQUESTED_WITH` header and checks if it is set to `XMLHttpRequest`. If it is, then the handler will call the `process()` method of the `UserController` class with the appropriate action.

Here is an example of what the handler might look like:
```php
<?php
// user-handler.php

if (!empty($_SERVER['HTTP_X_REQUESTED_WITH']) && strtolower($_SERVER['HTTP_X_REQUESTED_WITH']) == 'xmlhttprequest') {
    // Call the process() method of the UserController class with the appropriate action
    $action = $_POST['action'];
    $userController = new \UserController();
    echo $userController->process($action);
} else {
    // Not an XMLHttpRequest request, output a standard HTML page
    require_once 'user-index.php';
}
```

