```java
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class BatchProcessingSystem {
    private ExecutorService executor;
    private int numThreads;

    public BatchProcessingSystem(int numThreads) {
        this.numThreads = numThreads;
        executor = Executors.newFixedThreadPool(numThreads);
    }

    public void processFile(String filePath, FileProcessor processor) throws Exception {
        Future<Boolean> future = executor.submit(() -> {
            try {
                return processor.processFile(filePath);
            } catch (Exception e) {
                throw new RuntimeException("Error processing file: " + filePath, e);
            }
        });

        while (!future.isDone()) {
            // do some work in the meantime...
        }

        if (future.get()) {
            System.out.println("File processed successfully: " + filePath);
        } else {
            System.err.println("Error processing file: " + filePath);
        }
    }
}
```
