    public JsonParser() {
        try {
            this.connection = DriverManager.getConnection(DB_URL, USERNAME, PASSWORD);
            loadFactoriesFromDatabase();
        } catch (SQLException e) {
            System.out.println("Failed to connect to database: " + e.getMessage());
        }
    }

    private void loadFactoriesFromDatabase() throws SQLException {
        Statement statement = connection.createStatement();
        ResultSet resultSet = statement.executeQuery("SELECT * FROM json_factory");
        while (resultSet.next()) {
            String id = resultSet.getString("id");
            int version = resultSet.getInt("version");
            String json = resultSet.getString("json");
            JsonFactory factory = new JsonFactory(id, version);
            factory.setJsonString(json);
            factories.add(factory);
        }
    }

    public void addFactory(String id, int version, String json) throws SQLException {
        Statement statement = connection.createStatement();
        statement.executeUpdate("INSERT INTO json_factory (id, version, json) VALUES ('" + id + "', '" + version + "', '" + json + "')");
        factories.add(new JsonFactory(id, version));
    }

    public void removeFactory(String id, int version) throws SQLException {
        Statement statement = connection.createStatement();
        statement.executeUpdate("DELETE FROM json_factory WHERE id='" + id + "' AND version='" + version + "'");
        factories.removeIf(f -> f.getId().equals(id) && f.getVersion() == version);
    }

    public JsonFactory getFactory(String id, int version) throws SQLException {
        for (JsonFactory factory : factories) {
            if (factory.getId().equals(id) && factory.getVersion() == version) {
                return factory;
            }
        }
        return null;
    }

    public void startService() throws InterruptedException {
        running = true;
        Thread t = new Thread(() -> {
            while (running) {
                try {
                    updateCache();
                    Thread.sleep(random.nextInt(1000));
                } catch (SQLException | InterruptedException e) {
                    System.out.println("Failed to update cache: " + e.getMessage());
                }
            }
        });
        t.start();
    }

    public void stopService() throws SQLException, InterruptedException {
        running = false;
        Thread t = new Thread(() -> {
            while (running) {
                try {
                    updateCache();
                    Thread.sleep(random.nextInt(1000));
                } catch (SQLException | InterruptedException e) {
                    System.out.println("Failed to update cache: " + e.getMessage());
                }
            }
        });
        t.join();
    }

    public void updateCache() throws SQLException, InterruptedException {
        Statement statement = connection.createStatement();
        ResultSet resultSet = statement.executeQuery("SELECT * FROM json_factory");
        while (resultSet.next()) {
            String id = resultSet.getString("id");
            int version = resultSet.getInt("version");
            String json = resultSet.getString("json");
            JsonFactory factory = new JsonFactory(id, version);
            factory.setJsonString(json);
            cache.put(factory.getId() + "-" + factory.getVersion(), factory);
        }
    }

    public JsonObject parseJson(String json) throws SQLException {
        ObjectMapper mapper = new ObjectMapper();
        JsonFactory factory = getFactory("default", 1);
        if (factory == null) {
            return null;
        }
        try {
            return mapper.readValue(json, factory.getJsonClass());
        } catch (IOException e) {
            System.out.println("Failed to parse JSON: " + e.getMessage());
            return null;
        }
    }

    public JsonObject createJson(String id, int version, String json) throws SQLException {
        if (!validateJsonSchema(json)) {
            return null;
        }
        addFactory(id, version, json);
        return parseJson(json);
    }

