        private String id;
        private int version;
        private String jsonString;
        private Class<?> jsonClass;

        public JsonFactory(String id, int version) {
            this.id = id;
            this.version = version;
        }

        public void setJsonString(String jsonString) throws SQLException {
            this.jsonString = jsonString;
            ObjectMapper mapper = new ObjectMapper();
            JsonNode node = mapper.readTree(jsonString);
            Class<?> clazz = null;
            if (node.get("type").asText().equals("object")) {
                clazz = new TypeReference<Map<String, Object>>() {};
            } else if (node.get("type").asText().equals("array")) {
                clazz = new TypeReference<List<Object>>() {};
            }
            this.jsonClass = clazz;
        }

        public String getId() {
            return id;
        }

        public int getVersion() {
            return version;
        }

        public Class<?> getJsonClass() {
            return jsonClass;
        }
    }
