import json
import time
from datetime import datetime
from typing import Optional

class ConfigSettings:
    def __init__(self, data):
        self.data = data

def read_configuration(config_file: str) -> Optional[ConfigSettings]:
    # Check if there is an updated configuration available on the service
    try:
        with urllib.request.urlopen("https://example.com/api/config") as response:
            data = json.loads(response.read())
    except Exception as e:
        print(f"Error fetching remote configuration: {e}")
        return None

    # Invalidate the cache if there is an updated configuration available on the service
    if "updated_at" in data and datetime.utcnow() - datetime.fromisoformat(data["updated_at"]) > timedelta(hours=1):
        print("Invalidating cache due to recent update.")
        cache = None
    else:
        # Read the configuration from the local file
        try:
            with open(config_file, "r") as f:
                data = json.load(f)
        except FileNotFoundError:
            print("Configuration file not found.")
            return None
        except json.JSONDecodeError:
            print("Invalid JSON in configuration file.")
            return None

    # If the cache is invalid or there is no cached data, read from the local file and update the cache
    if cache is None or len(cache) == 0:
        try:
            with open(config_file, "r") as f:
                data = json.load(f)
            cache = {
                "data": ConfigSettings(data),
                "last_updated": datetime.utcnow()
            }
        except FileNotFoundError:
            print("Configuration file not found.")
            return None
        except json.JSONDecodeError:
            print("Invalid JSON in configuration file.")
            return None

    # Return the cached data if it is still valid, otherwise read from the local file again and update the cache
    if datetime.utcnow() - cache["last_updated"] < timedelta(hours=1):
        print("Returning cached configuration.")
        return cache["data"]
    else:
        try:
            with open(config_file, "r") as f:
                data = json.load(f)
            cache = {
                "data": ConfigSettings(data),
                "last_updated": datetime.utcnow()
            }
            print("Updated cached configuration.")
            return cache["data"]
        except FileNotFoundError:
            print("Configuration file not found.")
            return None
        except json.JSONDecodeError:
            print("Invalid JSON in configuration file.")
            return None
