using System;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading;
using System.Xml.Linq;

namespace WebsiteManager
{
    public class ConfigurationManager
    {
        private const string WebConfigFilePath = "web.config";

        private static readonly ILogger Logger = new ConsoleLogger();

        private static readonly ProcessStarter ProcessStarter = new ProcessStarter();

        public static void AddSite(string directoryPath, string siteName, string mode)
        {
            if (!Directory.Exists(directoryPath))
            {
                Logger.LogError($"The specified directory '{directoryPath}' does not exist.");
                return;
            }

            var webConfigFilePath = Path.Combine(directoryPath, WebConfigFilePath);
            if (!File.Exists(webConfigFilePath))
            {
                Logger.LogInfo($"A 'web.config' file was not found in the specified directory '{directoryPath}'. Creating a new one...");
                CreateWebConfigFile(directoryPath, siteName, mode);
            }

            if (!IsDirectoryAccessibleAndWritable(directoryPath))
            {
                Logger.LogError($"The specified directory '{directoryPath}' is not accessible or writable.");
                return;
            }

            var processStartInfo = GetProcessStartInfo(directoryPath, siteName, mode);
            if (processStartInfo == null)
            {
                Logger.LogWarning($"Failed to get the process start information for the specified directory '{directoryPath}'.");
                return;
            }

            var timeout = 30_000; // 30 seconds
            var cancellationTokenSource = new CancellationTokenSource();
            var task = ProcessStarter.StartProcessAsync(processStartInfo, cancellationTokenSource.Token);
            if (task == null)
            {
                Logger.LogError($"Failed to start the process for the specified directory '{directoryPath}'.");
                return;
            }

            var success = task.Wait(timeout);
            if (!success)
            {
                Logger.LogWarning($"The process for the specified directory '{directoryPath}' timed out after {timeout} milliseconds.");
                return;
            }

            // Handle errors gracefully
            if (task.IsFaulted)
            {
                Logger.LogError($"An error occurred while starting the process for the specified directory '{directoryPath}': {task.Exception.Message}");
                return;
            }

            var exitCode = task.Result.ExitCode;
            if (exitCode != 0)
            {
                Logger.LogError($"The process for the specified directory '{directoryPath}' exited with a non-zero exit code: {exitCode}.");
                return;
            }

            // Ensure proper resource management and cleanup after the site is started
            cancellationTokenSource.Dispose();
            Logger.LogInfo($"The website was successfully added to the directory '{directoryPath}' and started.");
        }

        private static bool IsDirectoryAccessibleAndWritable(string directoryPath)
        {
            var di = new DirectoryInfo(directoryPath);
            return di.Exists && di.IsReadOnly;
        }

        private static ProcessStartInfo GetProcessStartInfo(string directoryPath, string siteName, string mode)
        {
            var processStartInfo = new ProcessStartInfo();
            processStartInfo.FileName = Path.Combine(directoryPath, "mywebsite.exe");
            processStartInfo.Arguments = $"/sitename:{siteName} /mode:{mode}";
            return processStartInfo;
        }

        private static void CreateWebConfigFile(string directoryPath, string siteName, string mode)
        {
            // Integrate with an external configuration service to retrieve additional settings for the site
            var config = GetConfigurationFromExternalService();
            if (config == null)
            {
                Logger.LogError($"Failed to retrieve configuration from the external service.");
                return;
            }

            var webConfigFilePath = Path.Combine(directoryPath, WebConfigFilePath);
            var xDocument = new XDocument(new XElement("configuration"));
            xDocument.Root.Add(new XElement("system.webServer", config));
            xDocument.Save(webConfigFilePath);
        }

        private static string GetConfigurationFromExternalService()
        {
            // Implement external configuration service integration here
            return "TODO";
        }
    }
}
