#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>

// Define semaphore struct
typedef struct {
  char *name;
  int value;
  pthread_mutex_t mutex;
} Semaphore;

// Define functions for semaphore creation, deletion, and synchronization
Semaphore* createSemaphore(char* name, int initialValue) {
  // Allocate memory for the semaphore struct
  Semaphore *sem = malloc(sizeof(Semaphore));

  // Initialize the semaphore's name and value
  sem->name = strdup(name);
  sem->value = initialValue;

  // Create a mutex to protect the semaphore's value
  pthread_mutex_init(&sem->mutex, NULL);

  return sem;
}

void deleteSemaphore(Semaphore *sem) {
  // Free memory for the semaphore struct
  free(sem->name);
  pthread_mutex_destroy(&sem->mutex);
  free(sem);
}

int synchronizeSemaphore(Semaphore *sem, int newValue) {
  // Acquire the mutex to update the semaphore's value
  pthread_mutex_lock(&sem->mutex);

  // Update the semaphore's value
  sem->value = newValue;

  // Release the mutex
  pthread_mutex_unlock(&sem->mutex);

  return 0;
}

int acquireSemaphore(Semaphore *sem) {
  // Acquire the mutex to update the semaphore's value
  pthread_mutex_lock(&sem->mutex);

  // Check if the semaphore's value is greater than zero
  if (sem->value <= 0) {
    // Release the mutex and return an error code
    pthread_mutex_unlock(&sem->mutex);
    return -1;
  }

  // Decrement the semaphore's value by one
  sem->value--;

  // Release the mutex
  pthread_mutex_unlock(&sem->mutex);

  return 0;
}

int releaseSemaphore(Semaphore *sem) {
  // Acquire the mutex to update the semaphore's value
  pthread_mutex_lock(&sem->mutex);

  // Increment the semaphore's value by one
  sem->value++;

  // Release the mutex
  pthread_mutex_unlock(&sem->mutex);

  return 0;
}
```
