const asyncArrayReduce = (array, initialValue, callback) => {
  const semaphore = new Semaphore(5); // set maximum concurrency level to 5
  let accumulatedValue = initialValue;
  const progressCallback = () => {}; // default progress reporting function
  const errorCallback = () => {}; // default error handling function

  return new Promise((resolve, reject) => {
    array.forEach(async (element, index) => {
      if (index === 0) {
        accumulatedValue = element;
      } else {
        await semaphore.acquire(); // acquire semaphore to prevent overwhelming system resources
        try {
          const result = await callback(accumulatedValue, element);
          if (result instanceof Error) {
            reject(result);
          } else {
            accumulatedValue = result;
          }
        } catch (error) {
          errorCallback(error);
        } finally {
          semaphore.release(); // release semaphore after external API call completes
        }
      }
    });
    resolve(accumulatedValue);
  }).then((result) => {
    progressCallback(array.length, accumulatedValue); // report progress
    return result;
  }).catch((error) => {
    errorCallback(error);
    throw error;
  });
};
