    public class AsyncXmlReducer
    {
        private readonly string _baseUrl;
        private readonly string _token;
        private readonly int _throttlingRate;
        private readonly List<string> _namespaces;
        private readonly XPathExpression _xpathExpression;
        private readonly Func<XmlNode, object> _accumulator;
        private readonly bool _validateAgainstSchema;
        private readonly bool _customLogic;
        private readonly int _concurrentOperations;
        private readonly Action<int, int> _progressCallback;

        public AsyncXmlReducer(string baseUrl, string token, int throttlingRate, List<string> namespaces, XPathExpression xpathExpression, Func<XmlNode, object> accumulator, bool validateAgainstSchema, bool customLogic, int concurrentOperations, Action<int, int> progressCallback)
        {
            _baseUrl = baseUrl;
            _token = token;
            _throttlingRate = throttlingRate;
            _namespaces = namespaces;
            _xpathExpression = xpathExpression;
            _accumulator = accumulator;
            _validateAgainstSchema = validateAgainstSchema;
            _customLogic = customLogic;
            _concurrentOperations = concurrentOperations;
            _progressCallback = progressCallback;
        }

        public async Task<object> ReduceAsync(List<string> xmlDocuments, object initialValue)
        {
            var accumulatedValue = initialValue;
            var tasks = new List<Task<object>>();
            var completedTasks = 0;

            foreach (var xmlDocument in xmlDocuments)
            {
                tasks.Add(ReduceXmlDocumentAsync(xmlDocument));
            }

            while (tasks.Count > 0)
            {
                await Task.Delay(_throttlingRate);

                var completedTask = tasks.FirstOrDefault(t => t.IsCompleted);

                if (completedTask != null)
                {
                    accumulatedValue = _accumulator(completedTask.Result, accumulatedValue);
                    completedTasks++;
                    _progressCallback(completedTasks, xmlDocuments.Count);

                    tasks.Remove(completedTask);
                }
            }

            return accumulatedValue;
        }

        private async Task<object> ReduceXmlDocumentAsync(string xmlDocument)
        {
            var node = XPathNavigator.Create(xmlDocument, _namespaces);
            var result = await ValidateAndExtractDataAsync(node);

            return result;
        }

        private async Task<object> ValidateAndExtractDataAsync(XPathNavigator node)
        {
