                if (nodes == null || nodes.Count == 0)
                {
                    throw new Exception("No data found");
                }
                else if (nodes.Count > 1)
                {
                    throw new Exception("Multiple matching nodes found");
                }

                extractedData = ExtractData(nodes[0]);
            }
            catch (Exception ex)
            {
                LogError(ex);
            }

