    'https://api.example.com/oauth2/token', // Token URL
    process.env.CLIENT_ID, // Client ID
    process.env.CLIENT_SECRET, // Client Secret
    '1.0', // OAuth version
    null, // callback URL (not used)
    'HMAC-SHA1' // Signature method
);

