    cert: fs.readFileSync('cert.pem'),
    key: fs.readFileSync('key.pem')
});

// Define express app and routes
const app = express();
app.use(express.json());

app.post('/api/inventory', async (req, res) => {
    // Get product ID and stock level from request body
    const { productId, stockLevel } = req.body;

    // Fetch private key and certificate from OAuth client
    const { accessToken } = await oauthClient.getAccessToken();
    const pemFile = path.join(__dirname, 'certs', `private-key-${accessToken}.pem`);
    const certFile = path.join(__dirname, 'certs', `public-certificate-${accessToken}.cer`);

    // Combine private key and certificate into a single PEM file
    fs.writeFileSync(pemFile, `${fs.readFileSync(keyFile)}\n${fs.readFileSync(certFile)}`);

    // Convert input JPEG file to PDF using third-party tool
    const pdfFile = path.join(__dirname, 'output', `inventory-update-${productId}.pdf`);
    try {
        await httpsClient.post('https://api.example.com/jpeg-to-pdf', {
            params: {
                input_file: req.files.inputJPEG.path,
                output_file: pdfFile
            }
        });
    } catch (error) {
        console.log(error);
        return res.status(500).json({
            status: 'error',
            message: `Failed to convert JPEG file due to ${error}`,
            data: null
        });
    }

    // Update inventory level and revenue in database
    const newRevenue = stockLevel * 10;
    try {
        await redisClient.set(`product-${productId}-stock`, JSON.stringify(stockLevel));
        await redisClient.set(`product-${productId}-revenue`, JSON.stringify(newRevenue));
        await redisClient.set(`product-${productId}-last-updated-by`, req.user);
    } catch (error) {
        console.log(error);
        return res.status(500).json({
            status: 'error',
            message: `Failed to update inventory due to ${error}`,
            data: null
        });
    }

    // Send response with updated inventory level and revenue
    return res.json({
        status: 'success',
        message: 'Inventory updated successfully',
        data: {
            productId,
            stockLevel,
            revenue: newRevenue,
            lastUpdatedBy: req.user
        }
    });
});

app.listen(3000, () => console.log('Server started on port 3000'));
