import java.io.BufferedReader;
import java.io.IOException;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.util.Scanner;

public class ConnectionEstablisher {
  public static void main(String[] args) throws IOException, InterruptedException {
    // Create a URI object for the remote address
    URI uri = new URI("https://example.com");

    // Establish a connection to the remote address using a Java Channel
    AsynchronousSocketChannel channel = AsynchronousSocketChannel.open();
    CompletableFuture<Void> connectFuture = channel.connect(uri);

    // Wait for the connection to be established
    connectFuture.get();

    // Read data from the remote address using a BufferedReader
    BufferedReader reader = new BufferedReader(new InputStreamReader(channel.inputStream(), StandardCharsets.UTF_8));

    // Print the data read from the remote address
    String line;
    while ((line = reader.readLine()) != null) {
      System.out.println(line);
    }
  }
}
