Here is a sample implementation of the C function that takes a JSON object as a string and verifies that it contains the required fields and values for an OAuth2 access token response:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

int isValidOAuth2AccessTokenResponse(const char* json) {
  // Create a JSON object from the input string
  json_t* root = json_loads(json, JSON_DECODE_ANY);

  if (root == NULL) {
    // The input string does not contain valid JSON data
    return false;
  }

  const char* access_token = json_object_get_string(root, "access_token");
  if (access_token == NULL) {
    // The input string does not contain an access token field
    json_decref(root);
    return false;
  }

  int expires_in = json_object_get_int(root, "expires_in");
  if (expires_in <= 0) {
    // The input string does not contain a valid value for the expiration time field
    json_decref(root);
    return false;
  }

  const char* token_type = json_object_get_string(root, "token_type");
  if (token_type == NULL || strcmp(token_type, "Bearer") != 0) {
    // The input string does not contain a valid value for the token type field or the token type is not 'Bearer'
    json_decref(root);
    return false;
  }

  if (json_object_get_string(root, "refresh_token") == NULL) {
    // The input string does not contain a refresh token field
    json_decref(root);
    return false;
  }

  // All required fields are present and have valid values
  json_decref(root);
  return true;
}
```
This C function uses the `json-c` library to parse the input string as a JSON object. It then checks that the JSON object contains all the required fields (access token, expiration time, token type, and refresh token) and that they have valid values. If any of these conditions are not met, the function returns false. Otherwise, it returns true.

