  windowMs: 1000, // 1 second window
  max: 100, // limit each IP to 100 requests per windowMs
}));

// Set up API endpoints
app.get('/oldtestament_books', (req, res) => {
  const books = cache.get(cacheKey);
  if (!books) {
    logger.info('Cache miss: fetching old testament books from database');
    // Fetch books from external database and store in cache for 10 minutes
    const booksFromDatabase = fetchOldTestamentBooks();
    cache.put(cacheKey, booksFromDatabase, 600000);
  }
  logger.info('Returning old testament books');
  res.json(books);
});

