using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

namespace SecureDataProcessor
{
    public class SecureDataProcessor
    {
        private readonly ILogger _logger;

        public SecureDataProcessor(ILogger logger)
        {
            _logger = logger;
        }

        public Task<string> GenerateMd5Async(string input)
        {
            return GenerateHashAsync(input, MD5.Create());
        }

        public Task<string> GenerateSha1Async(string input)
        {
            return GenerateHashAsync(input, SHA1.Create());
        }

        public Task<string> GenerateSha256Async(string input)
        {
            return GenerateHashAsync(input, SHA256.Create());
        }

        public Task<byte[]> GenerateMd5BytesAsync(byte[] input)
        {
            return GenerateHashBytesAsync(input, MD5.Create());
        }

        public Task<byte[]> GenerateSha1BytesAsync(byte[] input)
        {
            return GenerateHashBytesAsync(input, SHA1.Create());
        }

        public Task<byte[]> GenerateSha256BytesAsync(byte[] input)
        {
            return GenerateHashBytesAsync(input, SHA256.Create());
        }

        private async Task<string> GenerateHashAsync(string input, HashAlgorithm hashAlgorithm)
        {
            if (input == null)
                throw new ArgumentNullException(nameof(input));

            var bytes = Encoding.UTF8.GetBytes(input);

            using var memoryStream = new MemoryStream();
            await memoryStream.WriteAsync(bytes, 0, bytes.Length).ConfigureAwait(false);
            memoryStream.Position = 0;

            using var hashAlgorithm = SHA256.Create();
            var hashBytes = await hashAlgorithm.ComputeHashAsync(memoryStream).ConfigureAwait(false);

            return BitConverter.ToString(hashBytes).Replace("-", "");
        }

        private async Task<byte[]> GenerateHashBytesAsync(byte[] input, HashAlgorithm hashAlgorithm)
        {
            if (input == null)
                throw new ArgumentNullException(nameof(input));

            using var memoryStream = new MemoryStream();
            await memoryStream.WriteAsync(input, 0, input.Length).ConfigureAwait(false);
            memoryStream.Position = 0;

            using var hashAlgorithm = SHA256.Create();
            return await hashAlgorithm.ComputeHashAsync(memoryStream).ConfigureAwait(false);
        }
    }
}
