  static size_t num_semaphores = 0;
  static pthread_mutex_t semaphore_lock = PTHREAD_MUTEX_INITIALIZER;

  // Define thread-safe queue for pending semaphore requests
  typedef struct {
    SemaphoreRequest* buffer;
    size_t capacity;
    size_t head;
    size_t tail;
    pthread_mutex_t lock;
  } PendingQueue;

  // Define thread-safe queue for completed semaphore requests
  typedef struct {
    SemaphoreResponse* buffer;
    size_t capacity;
    size_t head;
    size_t tail;
    pthread_mutex_t lock;
  } CompletedQueue;

