  // Function to create a semaphore with the given name and initial value
  int create_semaphore(const char* name, int value) {
    SemaphoreRequest request;
    SemaphoreResponse response;

    // Create a new semaphore with the specified name and initial value
    request.operation = OPERATION_CREATE;
    request.name = strdup(name);
    request.value = value;

    // Send request to semaphore management service
