      LOG_ERROR("Failed to send create semaphore request");
      return 0;
    }

    // Receive response from semaphore management service
    if (!receive_response(&response)) {
      LOG_ERROR("Failed to receive create semaphore response");
      return 0;
    }

    // Check for errors in response
    if (response.status != 201) {
      LOG_ERROR("Create semaphore failed with error: %s", response.error_message);
      return 0;
    }

    // Add new semaphore to internal array
    InternalSemaphore* new_semaphore = malloc(sizeof(InternalSemaphore));
    new_semaphore->name = strdup(name);
    new_semaphore->value = value;
    pthread_mutex_lock(&semaphore_lock);
    semaphores[num_semaphores++] = new_semaphore;
    pthread_mutex_unlock(&semaphore_lock);

    // Free memory for request and response structures
    free(request.name);
    free(response.error_message);

    return 1;
  }

  // Function to delete a semaphore with the given name
  int delete_semaphore(const char* name) {
    SemaphoreRequest request;
    SemaphoreResponse response;

    // Create a new semaphore with the specified name and initial value
    request.operation = OPERATION_DELETE;
    request.name = strdup(name);

    // Send request to semaphore management service
    if (!send_request(SERVICE_ENDPOINT, &request)) {
      LOG_ERROR("Failed to send delete semaphore request");
      return 0;
    }

    // Receive response from semaphore management service
    if (!receive_response(&response)) {
      LOG_ERROR("Failed to receive delete semaphore response");
      return 0;
    }

    // Check for errors in response
    if (response.status != 200) {
      LOG_ERROR("Delete semaphore failed with error: %s", response.error_message);
      return 0;
    }

    // Remove deleted semaphore from internal array
    pthread_mutex_lock(&semaphore_lock);
    for (int i = 0; i < num_semaphores; i++) {
      if (strcmp(name, semaphores[i].name) == 0) {
        free(semaphores[i].name);
        semaphores[i] = semaphores[num_semaphores - 1];
        num_semaphores--;
        break;
      }
    }
    pthread_mutex_unlock(&semaphore_lock);

    // Free memory for request and response structures
    free(request.name);
    free(response.error_message);

    return 1;
  }

