using System;
using System.Security.Cryptography;
using System.Text;

namespace Cryptography
{
    public static class TripleDesEncryption
    {
        private const string Key = "your_key";
        private const string Iv = "your_iv";

        public static string DecryptAndValidate(string encryptedMessage)
        {
            try
            {
                // Validate the Base64-encoded message
                if (!IsBase64Encoded(encryptedMessage))
                {
                    throw new ArgumentException("The message is not a valid Base64 encoding.");
                }

                // Decrypt the message using Triple DES encryption with the given key and IV
                byte[] decryptedBytes = Decrypt(Convert.FromBase64String(encryptedMessage), Key, Iv);

                // Validate the HMAC of the decrypted message
                if (!ValidateHmac(decryptedBytes))
                {
                    throw new AuthenticationException("The authentication failed.");
                }

                return Encoding.UTF8.GetString(decryptedBytes);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error occurred while decrypting and validating the message: {ex.Message}");
                throw;
            }
        }

        private static bool IsBase64Encoded(string message)
        {
            try
            {
                Convert.FromBase64String(message);
                return true;
            }
            catch (FormatException)
            {
                return false;
            }
        }

        private static byte[] Decrypt(byte[] encryptedBytes, string key, string iv)
        {
            using (TripleDESCryptoServiceProvider tripleDes = new TripleDESCryptoServiceProvider())
            {
                tripleDes.Key = Encoding.UTF8.GetBytes(key);
                tripleDes.IV = Encoding.UTF8.GetBytes(iv);

                return tripleDes.CreateDecryptor().TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);
            }
        }

        private static bool ValidateHmac(byte[] decryptedBytes)
        {
            using (HMACSHA256 hmac = new HMACSHA256())
            {
                hmac.Key = Encoding.UTF8.GetBytes(Key);

                return hmac.ComputeHash(decryptedBytes).SequenceEqual(decryptedBytes.SkipLast(32));
            }
        }
    }
}
