using System;
using System.Data;
using System.Net.Sockets;
using System.Threading;
using System.Threading.Tasks;

public class LargeByteArrayHandler
{
    private readonly int _connectionPoolSize = 5;
    private readonly string _databaseServerAddress = "localhost";
    private readonly int _databaseServerPort = 1433;
    private readonly string _databaseName = "MyDatabase";
    private readonly string _userName = "myusername";
    private readonly string _password = "mypassword";
    private readonly string _queryTemplate = "SELECT * FROM MyTable WHERE ColumnA IN ({0}) AND ColumnB LIKE '%{1}%'";

    public async Task<DataTableReader> HandleLargeByteArrayAsync(byte[] largeByteArray)
    {
        if (largeByteArray == null || largeByteArray.Length == 0)
            throw new ArgumentNullException("largeByteArray");

        try
        {
            using (var connection = await GetConnectionAsync())
            {
                var query = _queryTemplate.Replace("{0}", string.Join(",", largeByteArray));
                var command = connection.CreateCommand();
                command.CommandText = query;

                var reader = await command.ExecuteReaderAsync();
                return reader;
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error: " + ex.Message);
            throw;
        }
    }

    private async Task<SqlConnection> GetConnectionAsync()
    {
        var connectionString = $"Server={_databaseServerAddress};Port={_databaseServerPort};Database={_databaseName};User Id={_userName};Password={_password};";

        if (_connectionPoolSize > 0)
        {
            return new SqlConnection(connectionString, _connectionPoolSize);
        }
        else
        {
            return new SqlConnection(connectionString);
        }
    }
}
```
