public class PokemonWeaknessDetector {
  private final Database database;
  private final ApiClient apiClient;

  public PokemonWeaknessDetector(Database database, ApiClient apiClient) {
    this.database = database;
    this.apiClient = apiClient;
  }

  public String detectWeaknesses(Pokemon pokemon) {
    // Fetch weakness data from the API
    Map<String, Weakness> weaknessData = null;
    try {
      weaknessData = apiClient.getWeaknessData(pokemon);
    } catch (ApiException e) {
      // Handle API exception gracefully
      System.out.println("Error fetching weakness data from the API: " + e.getMessage());
      return "Unknown weaknesses";
    }

    // Fetch detailed information about each weakness
    Map<String, WeaknessDetails> weaknessDetails = new HashMap<>();
    for (Weakness weakness : weaknessData.values()) {
      try {
        weaknessDetails.put(weakness.getName(), database.getWeaknessDetails(weakness));
      } catch (DatabaseException e) {
        // Handle database exception gracefully
        System.out.println("Error fetching weakness details from the database: " + e.getMessage());
        break;
      }
    }

    // Build the final string of weaknesses and associated moves
    StringBuilder weaknessesString = new StringBuilder();
    for (WeaknessDetails weaknessDetails : weaknessDetails.values()) {
      weaknessesString.append(weaknessDetails.getName()).append(" (").append(weaknessDetails.getStrength()).append("), ");
      if (!weaknessDetails.getExploitMoves().isEmpty()) {
        weaknessesString.append("exploited by ").append(weaknessDetails.getExploitMoves()).append(", ");
      }
    }

    // Return the final string of weaknesses and associated moves
    return weaknessesString.toString().trim();
  }
}

interface Database {
  WeaknessDetails getWeaknessDetails(Weakness weakness) throws DatabaseException;
}

interface ApiClient {
  Map<String, Weakness> getWeaknessData(Pokemon pokemon) throws ApiException;
}

