use std::env;
use reqwest::blocking::get;
use std::collections::HashMap;
use serde_json::from_value;

fn main() {
    let args = env::args();
    let city = &args[1];

    // Create a cache of API responses to reduce load on the external service.
    let mut cache: HashMap<String, String> = HashMap::new();

    // Fetch current weather conditions and forecast for next 24 hours.
    let (current_weather, forecast) = fetch_weather(city);

    // Display the weather data.
    println!("Current weather: {}", current_weather);
    println!("Forecast for next 24 hours:");
    for day in forecast {
        println!("{}: {}", day.day, day.temperature);
    }
}

// Fetch weather data from an API using Tokio.
async fn fetch_weather(city: &str) -> (String, Vec<Forecast>) {
    let api_key = "YOUR_API_KEY"; // Replace with your own API key.
    let url = format!("https://api.openweathermap.org/data/2.5/weather?q={}&appid={}", city, api_key);

    // Use the reqwest crate to make a GET request to the API.
    let response = get(url).await;

    // Handle rate limiting and potential API request failures gracefully.
    if response.status().is_success() {
        let data: WeatherResponse = from_value(response.json()).unwrap();
        return (data.weather[0].description, data.forecast);
    } else {
        println!("API request failed with status code: {}", response.status());
        return ("".to_string(), vec![]);
    }
}

// A struct to represent the weather forecast for a day.
struct Forecast {
    day: String,
    temperature: f32,
}

// A struct to represent the API response containing current weather and forecast data.
struct WeatherResponse {
    weather: Vec<Weather>,
    forecast: Vec<Forecast>,
}

// A struct to represent the weather data from the API.
struct Weather {
    description: String,
}
```
