import java.io.File;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Collections;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.function.Consumer;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class FileHasher {
    private static final Logger logger = LoggerFactory.getLogger(FileHasher.class);

    private final int maxThreads;
    private final int cacheSize;
    private final ExecutorService threadPool;
    private final Map<String, String> cache;

    public FileHasher(int maxThreads, int cacheSize) {
        this.maxThreads = maxThreads;
        this.cacheSize = cacheSize;
        this.threadPool = Executors.newFixedThreadPool(maxThreads);
        this.cache = Collections.synchronizedMap(new ConcurrentHashMap<String, String>(cacheSize));
    }

    public String hashFile(String filePath) throws NoSuchAlgorithmException {
        // Validate input file path
        if (!isValidFilePath(filePath)) {
            logger.error("Invalid file path: {}", filePath);
            throw new IllegalArgumentException("Invalid file path");
        }

        // Check cache for hash value
        String cachedHash = cache.get(filePath);
        if (cachedHash != null) {
            return cachedHash;
        }

        // Compute hash in separate thread using non-blocking thread pool
        CompletableFuture<String> future = CompletableFuture.supplyAsync(() -> computeFileHash(filePath), threadPool);

        // Wait for hash computation to complete or timeout
        try {
            return future.get(10, TimeUnit.SECONDS);
        } catch (TimeoutException e) {
            logger.error("Hash computation timed out: {}", filePath);
            throw new HashComputationTimeoutException("Hash computation timed out");
        } catch (ExecutionException e) {
            logger.error("Error computing hash for file: {}", filePath, e);
            throw new RuntimeException(e);
        }
    }

    private String computeFileHash(String filePath) throws NoSuchAlgorithmException {
        // Read file and compute MD5 hash
        MessageDigest md = MessageDigest.getInstance("MD5");
        try (InputStream inputStream = new FileInputStream(new File(filePath))) {
            byte[] buffer = new byte[1024];
            int read;
            while ((read = inputStream.read(buffer)) != -1) {
                md.update(buffer, 0, read);
            }
        } catch (IOException e) {
            logger.error("Error reading file: {}", filePath, e);
            throw new RuntimeException(e);
        }

        // Add hash to cache and return it
        String hash = bytesToHexString(md.digest());
        cache.put(filePath, hash);
        return hash;
    }

    private boolean isValidFilePath(String filePath) {
        if (filePath == null || filePath.isEmpty()) {
            return false;
        }

        File file = new File(filePath);
        return file.exists() && file.isFile() && !file.isDirectory();
    }

    private String bytesToHexString(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < bytes.length; i++) {
            sb.append(String.format("%02x", bytes[i]));
        }
        return sb.toString();
    }
}
```
