// Regex patterns for matching book names in the Bible
const regex OLD_TESTAMENT_BOOKS("(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)");
const regex NEW_TESTAMENT_BOOKS("(Matthew|Mark|Luke|John|Acts|Romans|1 Corinthians|2 Corinthians|Galatians|Ephesians|Philippians|Colossians|1 Thessalonians|2 Thessalonians|1 Timothy|2 Timothy|Titus|Philemon|Hebrews|James|1 Peter|2 Peter|1 John|2 John|3 John|Jude|Revelation)");

// Registry of factory functions for creating subclasses
unordered_map<string, function<unique_ptr<BibleTextAnalyzer>(const string&)>> registry;

class BibleTextAnalyzer {
private:
    // Mutex for thread-safe access to the analyzer
    mutex mtx;

    // Lock for protecting the analyzer's state during asynchronous testing
    lock_guard<mutex> lg;

    // Input string to be analyzed
    string input;

    // Vector of book names extracted from the input
    vector<string> books;

    // Database of biblical books
    unordered_map<string, bool> biblicalBooks;

    // Regex patterns for matching book names in the Bible
    regex oldTestamentBooksRegex;
    regex newTestamentBooksRegex;

public:
    // Constructor that initializes the analyzer with a string input
    explicit BibleTextAnalyzer(const string& input) : input{input} {
        // Initialize the vector of book names extracted from the input
        books = extractBookNames();

        // Initialize the database of biblical books
        initializeBiblicalBooksDatabase();

        // Register the factory functions for creating subclasses
        registry["Old Testament"] = [this]() { return make_unique<BibleTextAnalyzer>(input, OLD_TESTAMENT_BOOKS); };
        registry["New Testament"] = [this]() { return make_unique<BibleTextAnalyzer>(input, NEW_TESTAMENT_BOOKS); };
    }

    // Constructor that initializes the analyzer with a string input and regex patterns for matching book names
    BibleTextAnalyzer(const string& input, const regex& booksRegex) : input{input}, oldTestamentBooksRegex{booksRegex} {
        books = extractBookNames();
        initializeBiblicalBooksDatabase();
    }

    // Extract the book names from the input string and return a vector of strings
    vector<string> extractBookNames() {
        vector<string> result;

        // Match the regex patterns to find all occurrences of book names in the input string
        smatch matches;
        while (regex_search(input, matches, booksRegex)) {
            result.push_back(matches[0].str());
            input = matches.suffix().str();
        }

        return result;
    }

    // Initialize the database of biblical books with the book names extracted from the input string
    void initializeBiblicalBooksDatabase() {
        for (const auto& book : books) {
            biblicalBooks[book] = true;
        }
    }

    // Run asynchronous tests using a given module label, test labels, and test functions
    void runTests(const string& moduleLabel, const vector<string>& testLabels, const vector<function<void()>>& testFunctions) {
        // Initialize the mocking library for isolation between tests
        blueslip::init();

        for (const auto& test : testLabels) {
            try {
                // Create a future to handle asynchronous DNS queries
                future<bool> dnsFuture = async(launch::async, [this]() -> bool {
                    return verifyBookInDatabase(test);
                });

                // Wait for the future to complete or timeout after 5 seconds
                if (dnsFuture.wait_for(chrono::seconds(5)) == std::future_status::timeout) {
                    throw runtime_error("DNS query timed out");
                }
            } catch (const exception& e) {
                // Log the error message to the console
                cerr << moduleLabel << ": " << test << " : " << e.what() << endl;
            }
        }
    }

    // Verify whether a given book name is present in the database of biblical books
    bool verifyBookInDatabase(const string& book) {
        return biblicalBooks[book];
    }
};
