function validatePassword($password) {
    // Check the length of the password
    if (strlen($password) < 8) {
        return false;
    }

    // Check for at least one uppercase letter, lowercase letter, digit, and special character
    $uppercase = preg_match('/[A-Z]/', $password);
    $lowercase = preg_match('/[a-z]/', $password);
    $digit = preg_match('/\d/', $password);
    $specialChar = preg_match('/[!@#$%^&*]/', $password);
    if (!$uppercase || !$lowercase || !$digit || !$specialChar) {
        return false;
    }

    // Check that the password does not contain the username or any part of it
    if (strpos($password, strtolower($user_id)) !== false) {
        return false;
    }

    // Check that the password is not the same as the old password
    if ($password === $oldPassword) {
        return false;
    }

    return true;
}

