#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <openssl/des.h>
#include <openssl/evp.h>
#include <openssl/modes.h>

// Enum for supported cipher modes
enum CipherMode {
    ECB,
    EDE,
    EDE3,
    CFB,
};

// Struct for storing configuration options
struct ConfigOptions {
    enum CipherMode mode;
    int iv_length;
    unsigned char key[8];
};

// Function to handle command-line arguments and configuring the utility
void configure(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc < 2) {
        fprintf(stderr, "Usage: %s [options]\n", argv[0]);
        exit(1);
    }

    // Initialize config options
    struct ConfigOptions options;
    options.mode = ECB;
    options.iv_length = 8;
    memset(options.key, 0, sizeof(options.key));

    // Parse mode option
    if (strcmp(argv[1], "-m") == 0) {
        if (argc < 3) {
            fprintf(stderr, "Error: missing argument for -m\n");
            exit(1);
        }

        // Parse mode string
        if (strcmp(argv[2], "ecb") == 0) {
            options.mode = ECB;
        } else if (strcmp(argv[2], "ede") == 0) {
            options.mode = EDE;
        } else if (strcmp(argv[2], "ede3") == 0) {
            options.mode = EDE3;
        } else if (strcmp(argv[2], "cfb") == 0) {
            options.mode = CFB;
        } else {
            fprintf(stderr, "Error: invalid mode specified\n");
            exit(1);
        }
    }

    // Parse IV length option
    if (strcmp(argv[1], "-i") == 0) {
        if (argc < 3) {
            fprintf(stderr, "Error: missing argument for -i\n");
            exit(1);
        }

        // Parse IV length string
        char *iv_length_str = argv[2];
        unsigned long iv_length;
        if (!sscanf(iv_length_str, "%lu", &iv_length)) {
            fprintf(stderr, "Error: invalid IV length specified\n");
            exit(1);
        }

        // Check that IV length is valid
        if (iv_length > 32) {
            fprintf(stderr, "Error: invalid IV length specified\n");
            exit(1);
        }

        options.iv_length = iv_length;
    }

    // Parse key option
    if (strcmp(argv[1], "-k") == 0) {
        if (argc < 3) {
            fprintf(stderr, "Error: missing argument for -k\n");
            exit(1);
        }

        // Parse key string
        char *key_str = argv[2];
        size_t key_len = strlen(key_str);

        // Check that key length is valid
        if (key_len > 8) {
            fprintf(stderr, "Error: invalid key length specified\n");
            exit(1);
        }

        memset(options.key, 0, sizeof(options.key));
        memcpy(options.key, key_str, key_len);
    }

    // Print configuration options
    printf("Configured options:\n");
    printf("Mode: %s\n", options.mode == ECB ? "ECB" : (options.mode == EDE ? "EDE" : (options.mode == EDE3 ? "EDE3" : "CFB")));
    printf("IV length: %d bytes\n", options.iv_length);
    printf("Key: ");
    for (int i = 0; i < sizeof(options.key); ++i) {
        printf("%02x", options.key[i]);
    }
    printf("\n");
}

// Function to perform encryption or decryption operation using DES
void encrypt_decrypt(unsigned char *input, unsigned char *output, int len, struct ConfigOptions options) {
    // Check that input and output buffers are not null
    if (input == NULL || output == NULL) {
        fprintf(stderr, "Error: invalid input or output buffer specified\n");
        exit(1);
    }

    // Check that input length is valid
    if (len > 64) {
        fprintf(stderr, "Error: input length is too large\n");
        exit(1);
    }

    // Initialize DES context
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        fprintf(stderr, "Error: unable to initialize DES context\n");
        exit(1);
    }

    // Setup key and IV for encryption or decryption operation
    unsigned char key[8];
    memcpy(key, options.key, sizeof(key));
    unsigned char iv[options.iv_length];
    memset(iv, 0, sizeof(iv));

    // Initialize DES context with key and IV
    if (!EVP_EncryptInit_ex(ctx, EVP_des_cbc(), NULL, key, iv)) {
        fprintf(stderr, "Error: unable to initialize DES encryption\n");
        exit(1);
    }

    // Perform encryption or decryption operation
    if (options.mode == ECB) {
        if (!EVP_EncryptUpdate(ctx, output, &len, input, len)) {
            fprintf(stderr, "Error: unable to perform DES encryption\n");
            exit(1);
        }
    } else if (options.mode == EDE) {
        if (!EVP_EncryptUpdate(ctx, output, &len, input, len)) {
            fprintf(stderr, "Error: unable to perform DES encryption\n");
            exit(1);
        }
    } else if (options.mode == EDE3) {
        if (!EVP_EncryptUpdate(ctx, output, &len, input, len)) {
            fprintf(stderr, "Error: unable to perform DES encryption\n");
            exit(1);
        }
    } else if (options.mode == CFB) {
        if (!EVP_EncryptUpdate(ctx, output, &len, input, len)) {
            fprintf(stderr, "Error: unable to perform DES encryption\n");
            exit(1);
        }
    }

    // Clean up DES context
    EVP_CIPHER_CTX_free(ctx);
}

// Main function for the command-line utility
int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Error: missing arguments\n");
        exit(1);
    }

    // Parse configuration options
    struct ConfigOptions options;
    configure_options(argc, argv, &options);

    // Perform encryption or decryption operation using DES
    unsigned char *input = NULL;
    unsigned char *output = NULL;
    size_t len = 0;
    if (!read_file(&input, &len)) {
        fprintf(stderr, "Error: unable to read input file\n");
        exit(1);
    }

    output = (unsigned char *)malloc(len);
    if (output == NULL) {
        fprintf(stderr, "Error: unable to allocate memory for output buffer\n");
        exit(1);
    }

    encrypt_decrypt(input, output, len, options);

    // Write output file
    FILE *out = fopen("output.txt", "wb");
    if (out == NULL) {
        fprintf(stderr, "Error: unable to open output file\n");
        exit(1);
    }
    fwrite(output, len, 1, out);
    fclose(out);
}

