public class SecurePasswordManager {
    private static final Map<String, FactoryFunction> factoryFunctions = new HashMap<>();
    private static final String DEFAULT_FACTORY_ID = "default";

    public static void registerFactoryFunction(String id, FactoryFunction factoryFunction) {
        factoryFunctions.put(id, factoryFunction);
    }

    public static void unregisterFactoryFunction(String id) {
        factoryFunctions.remove(id);
    }

    public static SecurePasswordManager getInstance() {
        return new SecurePasswordManager();
    }

    public String generateRandomString() {
        // Generate a random string using the Java Secure Random API
        byte[] bytes = new byte[16];
        new java.security.SecureRandom().nextBytes(bytes);
        return new String(bytes, StandardCharsets.UTF_8);
    }

    public void hashPassword(String password) throws NoSuchAlgorithmException {
        // Hash the password using a secure password hashing algorithm like bcrypt or Argon2
        byte[] salt = new byte[16];
        new java.security.SecureRandom().nextBytes(salt);
        String hashedPassword = BCrypt.hashpw(password, salt);
    }

    public void verifyHashedPassword(String password, String hashedPassword) throws NoSuchAlgorithmException {
        // Verify the password against the hashed password using a secure password verification algorithm like bcrypt or Argon2
        byte[] salt = new byte[16];
        new java.security.SecureRandom().nextBytes(salt);
        String hashedPasswordFromVerification = BCrypt.hashpw(password, salt);
        if (!hashedPasswordFromVerification.equals(hashedPassword)) {
            throw new NoSuchAlgorithmException("The password does not match the hashed password");
        }
    }

    public void validateCharacterSet(String password) throws NoSuchAlgorithmException {
        // Validate the character set of the password against a list of allowed characters
        String[] allowedCharacters = new String[] {"a", "b", "c"};
        for (char c : password.toCharArray()) {
            if (!allowedCharacters.contains(String.valueOf(c))) {
                throw new NoSuchAlgorithmException("The character set of the password is not allowed");
            }
        }
    }

    public void setSaltRoundCount(int saltRoundCount) throws NoSuchAlgorithmException {
        // Set the salt round count for the secure password hashing algorithm
        if (saltRoundCount <= 0) {
            throw new NoSuchAlgorithmException("The salt round count must be greater than zero");
        }
    }

    public void resetPassword(String oldPassword, String newPassword) throws NoSuchAlgorithmException {
