        if (!verifyHashedPassword(oldPassword, hashedPassword)) {
            throw new NoSuchAlgorithmException("The old password does not match the hashed password");
        }
        validateCharacterSet(newPassword);
        String hashedNewPassword = BCrypt.hashpw(newPassword, saltRoundCount);
    }

