import json
from collections import defaultdict
from concurrent.futures import ThreadPoolExecutor

class GraphDatabaseService:
    def __init__(self):
        self.vertices = {}
        self.edges = defaultdict(list)
        self.executor = ThreadPoolExecutor()
        self.properties_manager = ExternalPropertyManagementSystem()

    def add_vertex(self, vertex_id, properties):
        self.vertices[vertex_id] = properties

    def remove_vertex(self, vertex_id):
        del self.vertices[vertex_id]

    def update_vertex(self, vertex_id, new_properties):
        self.vertices[vertex_id].update(new_properties)

    def add_edge(self, edge_id, source_vertex_id, target_vertex_id, properties):
        self.edges[source_vertex_id].append((target_vertex_id, properties))

    def remove_edge(self, edge_id):
        for vertex_id in self.edges[edge_id]:
            self.remove_edge(vertex_id)

    def update_edge(self, edge_id, new_properties):
        for vertex_id in self.edges[edge_id]:
            self.update_edge(vertex_id, new_properties)

    def get_vertices(self):
        return list(self.vertices.keys())

    def get_edges(self, source_vertex_id):
        return [edge for edge in self.edges[source_vertex_id]]

    def get_properties(self, vertex_id):
        return self.vertices.get(vertex_id, {})

    def set_properties(self, vertex_id, new_properties):
        self.vertices[vertex_id].update(new_properties)

    def get_all_properties(self):
        all_properties = {}
        for vertex in self.vertices:
            all_properties[vertex] = self.get_properties(vertex)
        return all_properties

    def set_all_properties(self, new_properties):
        for vertex in new_properties:
            self.set_properties(vertex, new_properties[vertex])

    def get_edges_with_properties(self, source_vertex_id):
        edges = {}
        for edge in self.get_edges(source_vertex_id):
            edges[edge] = self.get_properties(edge)
        return edges

    def set_edges_with_properties(self, source_vertex_id, new_edges):
        for edge in new_edges:
            self.set_edge_with_properties(source_vertex_id, edge)

    def get_all_edges_with_properties(self):
        all_edges = {}
        for vertex in self.vertices:
            all_edges[vertex] = self.get_edges_with_properties(vertex)
        return all_edges

    def set_all_edges_with_properties(self, new_edges):
        for vertex in new_edges:
            self.set_edges_with_properties(vertex, new_edges[vertex])

    def get_neighbors(self, source_vertex_id):
        return [target_vertex_id for target_vertex_id in self.get_edges(source_vertex_id)]

    def get_all_neighbors(self):
        all_neighbors = {}
        for vertex in self.vertices:
            all_neighbors[vertex] = self.get_neighbors(vertex)
        return all_neighbors

    def set_all_neighbors(self, new_neighbors):
        for vertex in new_neighbors:
            self.set_neighbors(vertex, new_neighbors[vertex])

    def get_graph_configuration(self):
        return {
            "vertices": list(self.vertices.keys()),
            "edges": self.get_all_edges_with_properties()
        }

    def set_graph_configuration(self, new_configuration):
        for vertex in new_configuration["vertices"]:
            self.add_vertex(vertex)
        for edge in new_configuration["edges"]:
            self.add_edge(edge)
