cache.set('booksCache', {});

// Endpoint to process incoming text data and identify references to books in both testaments
app.post('/process-text', (req, res) => {
  const text = req.body.text;
  if (!text) {
    return res.status(400).json({ message: 'Missing required parameter: text' });
  }

  // Use regular expressions to match book names in the text, ignoring punctuation and special characters
  const regex = /(?<![\w])\b(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)\b/gi;
  const match = text.match(regex);

  // If no matches found, return an empty object
  if (!match) {
    return res.json({});
  }

  // Get a list of book names from the database
  const books = [];
  pool.query('SELECT * FROM books', (err, results) => {
    if (err) {
      console.log(err);
      return;
    }
    results.rows.forEach((row) => {
      books.push(row.name);
    });
  });

  // Get the count of each book name found in the text
  const counts = {};
  match.forEach((bookName) => {
    if (books.includes(bookName)) {
      const count = counts[bookName] || 0;
      counts[bookName] = count + 1;
    }
  });

  // Return the count of each book name found in the text
  res.json(counts);
});

// Endpoint to retrieve a list of books from both testaments
app.get('/books', (req, res) => {
  const cacheKey = 'booksCache';
  const cacheValue = cache.get(cacheKey);

  if (cacheValue) {
    return res.json(cacheValue);
  }

  pool.query('SELECT * FROM books', (err, results) => {
