namespace YourProjectNameSpace
{
    public class HttpPostRequestHandler : IHttpPostRequestHandler
    {
        private readonly IPageSectionService _pageSectionService;
        private readonly IElementService _elementService;
        private readonly ISignalRNotifier _signalRNotifier;

        public HttpPostRequestHandler(IPageSectionService pageSectionService, IElementService elementService, ISignalRNotifier signalRNotifier)
        {
            _pageSectionService = pageSectionService;
            _elementService = elementService;
            _signalRNotifier = signalRNotifier;
        }

        public async Task<IActionResult> HandleHttpPostRequest(int pageSectionId, int elementId, string htmlContent)
        {
            if (string.IsNullOrEmpty(htmlContent))
            {
                return BadRequest("Invalid HTML content");
            }

            // Check if user has permission to update the specified element
            var currentUser = HttpContext.Current.User;
            if (!currentUser.HasPermissionToUpdateElement(elementId))
            {
                return Forbid();
            }

            try
            {
                // Update element's HTML content in the database
                await _pageSectionService.UpdateElementHtmlContentAsync(pageSectionId, elementId, htmlContent);

                // Asynchronously notify all connected clients via SignalR that the page should be refreshed
                await _signalRNotifier.NotifyRefreshPageAsync();

                return Ok("Element updated successfully");
            }
            catch (DbUpdateConcurrencyException ex)
            {
                return Conflict(ex.Message);
            }
            catch (InvalidOperationException ex)
            {
                return BadRequest(ex.Message);
            }
        }
    }
}
