// Define a function to store and retrieve NFAPI_CRC_INDICATION_PDU_T structures from the distributed database system
void dynamicTestLoader(int numStructures) {
  // Lock the mutex for thread safety
  pthread_mutex_lock(&mutex);

  // Initialize the list of structures if it is not already initialized
  if (crcList == NULL) {
    crcList = malloc(numStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    crcListSize = numStructures;
  }

  // Generate unique CRCFLAG values for each structure in the list
  for (int i = 0; i < crcListSize; ++i) {
    generateCRCFlag(&crcList[i]);
  }

  // Store the structures in the distributed database system
  sqlite3_open("mydb.sqlite", &mydb);
  for (int i = 0; i < crcListSize; ++i) {
    char *insertSQL = "INSERT INTO mytable VALUES(?, ?)";
    sqlite3_prepare(mydb, insertSQL, -1, &stmt, NULL);
    sqlite3_bind_int(stmt, 1, crcList[i].CRCFLAG);
    sqlite3_bind_text(stmt, 2, "mydata", -1, SQLITE_STATIC);
    if (sqlite3_step(stmt) != SQLITE_DONE) {
      printf("Error: %s\n", sqlite3_errmsg(mydb));
      sqlite3_finalize(stmt);
      sqlite3_close(mydb);
    }
  }
  sqlite3_finalize(stmt);
  sqlite3_close(mydb);

  // Retrieve the structures from the distributed database system
  sqlite3_open("mydb.sqlite", &mydb);
  for (int i = 0; i < crcListSize; ++i) {
    char *selectSQL = "SELECT CRCFLAG FROM mytable WHERE ID = ?";
    sqlite3_prepare(mydb, selectSQL, -1, &stmt, NULL);
    sqlite3_bind_int(stmt, 1, i + 1);
    if (sqlite3_step(stmt) == SQLITE_ROW) {
      crcList[i].CRCFLAG = sqlite3_column_int(stmt, 0);
    } else {
      printf("Error: %s\n", sqlite3_errmsg(mydb));
      sqlite3_finalize(stmt);
      sqlite3_close(mydb);
    }
  }
  sqlite3_finalize(stmt);
  sqlite3_close(mydb);

  // Unlock the mutex for thread safety
  pthread_mutex_unlock(&mutex);
}

