import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Future;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class MD5Hasher {
    private static final Logger logger = LoggerFactory.getLogger(MD5Hasher.class);

    // Cache to store previously computed hashes
    private static ConcurrentHashMap<String, String> cache;

    // Thread pool for computing hashes in separate threads
    private static ExecutorService executorService;

    // Maximum number of threads in the thread pool
    private static int maxThreads;

    // Cache size limit
    private static int cacheSize;

    // Constructor with parameters
    public MD5Hasher(int maxThreads, int cacheSize) {
        this.maxThreads = maxThreads;
        this.cacheSize = cacheSize;
        executorService = Executors.newFixedThreadPool(maxThreads);
        cache = new ConcurrentHashMap<>(cacheSize);
    }

    // Method to hash a string using MD5 algorithm
    public String hashString(String input) {
        if (input == null || input.length() > 1000) {
            logger.warn("Invalid input string: {}", input);
            return null;
        }

        // Check cache for previously computed hash
        String cachedHash = cache.get(input);
        if (cachedHash != null) {
            logger.debug("Found cached MD5 hash for input string: {}", input);
            return cachedHash;
        }

        // Compute MD5 hash in a separate thread
        Future<String> future = executorService.submit(() -> computeMD5(input));

        // Add the new hash to the cache
        try {
            String hash = future.get();
            cache.put(input, hash);
            return hash;
        } catch (InterruptedException | ExecutionException e) {
            logger.error("Error computing MD5 hash for input string: {}", input, e);
            return null;
        }
    }

    // Compute MD5 hash using a standard library function
    private static String computeMD5(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] bytes = md.digest(input.getBytes());
            return DatatypeConverter.printHexBinary(bytes);
        } catch (NoSuchAlgorithmException e) {
            logger.error("Error computing MD5 hash for input string: {}", input, e);
            return null;
        }
    }

    // Method to generate SHA-256 hashes alongside MD5 hashes
    public String hashStringSHA256(String input) {
        if (input == null || input.length() > 1000) {
            logger.warn("Invalid input string: {}", input);
            return null;
        }

        // Check cache for previously computed hash
        String cachedHash = cache.get(input);
        if (cachedHash != null) {
            logger.debug("Found cached SHA-256 hash for input string: {}", input);
            return cachedHash;
        }

        // Compute SHA-256 hash in a separate thread
        Future<String> future = executorService.submit(() -> computeSHA256(input));

        // Add the new hash to the cache
        try {
            String hash = future.get();
            cache.put(input, hash);
            return hash;
        } catch (InterruptedException | ExecutionException e) {
            logger.error("Error computing SHA-256 hash for input string: {}", input, e);
            return null;
        }
    }

    // Compute SHA-256 hash using a standard library function
    private static String computeSHA256(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] bytes = md.digest(input.getBytes());
            return DatatypeConverter.printHexBinary(bytes);
        } catch (NoSuchAlgorithmException e) {
            logger.error("Error computing SHA-256 hash for input string: {}", input, e);
            return null;
        }
    }

    // Method to periodically check and update the cache with new, pre-computed hashes from a batch processing job
    public void updateCache(List<String> inputs) {
        for (String input : inputs) {
            if (input == null || input.length() > 1000) {
                logger.warn("Invalid input string: {}", input);
                continue;
            }
            cache.putIfAbsent(input, computeMD5(input));
        }
    }

    // Method to handle the case where the string is very large efficiently, without loading the entire string into memory at once
    private static String computeHashForLargeString(String input) {
