package com.example.financialdata;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Bean;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.web.bind.annotation.*;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.google.gson.Gson;

import reactor.core.publisher.Flux;
import reactor.core.scheduler.Schedulers;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

@RestController
public class FinancialDataController {

    @Autowired
    private FinancialDataService financialDataService;

    @Bean
    public ExecutorService executor() {
        return Executors.newFixedThreadPool(10);
    }

    @GetMapping("/api/v1/financial-data")
    public Flux<String> getFinancialData(@RequestParam String criteria) {
        // Implement rate limiting and throttling to manage the number of requests from different clients and prevent overload
        if (criteria == null || criteria.isEmpty()) {
            return Flux.empty();
        }

        List<String> data = new ArrayList<>();

        financialDataService.getFinancialData(criteria)
                .doOnNext(data::add)
                .subscribeOn(Schedulers.fromExecutor(executor()))
                .subscribe();

        return Flux.fromIterable(data);
    }

    @PostMapping("/api/v1/financial-data")
    public HttpStatus postFinancialData(@RequestBody String data) {
        // Implement efficient data ingestion mechanisms using reactive programming and asynchronous processing
        if (data == null || data.isEmpty()) {
            return HttpStatus.BAD_REQUEST;
        }

        financialDataService.saveFinancialData(data);

        return HttpStatus.OK;
    }
}
