Here is a Java function that takes a JSON string containing multiple encrypted messages, each with its own unique key and initialization vector (IV), decrypts them using AES encryption, validates their authenticity using HMAC SHA256, and returns a list of decrypted messages along with their validation status (successful or failed) as a JSON string:
```java
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;

import org.apache.commons.codec.binary.Base64;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

public class DecryptAndValidateMessages {
  private static final Logger logger = LogManager.getLogger(DecryptAndValidateMessages.class);

  public static String decryptAndValidateMessages(String jsonString) throws Exception {
    // Parse the JSON string to a map of messages with their respective metadata
    Map<String, Object> messageMap = new Gson().fromJson(jsonString, new TypeToken<Map<String, Object>>() {}.getType());

    // Initialize the AES cipher and HMAC SHA256 key specs
    Cipher aesCipher = Cipher.getInstance("AES/CTR/NoPadding");
    SecretKeySpec aesKeySpec = new SecretKeySpec(Base64.decodeBase64("YOUR_ENCRYPTION_KEY".getBytes()), "AES");
    SecretKeySpec hmacKeySpec = new SecretKeySpec(Base64.decodeBase64("YOUR_HMAC_KEY".getBytes()), "HmacSHA256");

    // Initialize the list of decrypted messages and their validation statuses
    List<DecryptedMessage> decryptedMessages = new ArrayList<>();

    for (Map.Entry<String, Object> entry : messageMap.entrySet()) {
      String messageId = entry.getKey();
      Map<String, Object> messageMetadata = (Map<String, Object>) entry.getValue();

      // Decrypt the message using AES/CTR/NoPadding and get the decrypted message bytes
      Cipher cipher = Cipher.getInstance("AES/CTR/NoPadding");
      cipher.init(Cipher.DECRYPT_MODE, aesKeySpec, new IvParameterSpec(Base64.decodeBase64((String) messageMetadata.get("iv"))));
      byte[] decryptedMessageBytes = cipher.doFinal((byte[]) messageMetadata.get("message"));

      // Validate the HMAC of the decrypted message using HmacSHA256 and get the validation status
      String hmacValidationStatus = HmacUtils.validateHmacSha256(decryptedMessageBytes, hmacKeySpec);

      // Add the decrypted message to the list with its corresponding validation status
      DecryptedMessage decryptedMessage = new DecryptedMessage(messageId, decryptedMessageBytes, hmacValidationStatus);
      decryptedMessages.add(decryptedMessage);
    }

    // Return the list of decrypted messages as a JSON string
    return new Gson().toJson(decryptedMessages);
  }

  public static class DecryptedMessage {
    private String messageId;
    private byte[] decryptedMessageBytes;
    private String hmacValidationStatus;

    public DecryptedMessage(String messageId, byte[] decryptedMessageBytes, String hmacValidationStatus) {
      this.messageId = messageId;
      this.decryptedMessageBytes = decryptedMessageBytes;
      this.hmacValidationStatus = hmacValidationStatus;
    }
  }
}
