```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <errno.h>

// Define a struct to hold the parsed filename and its extension
typedef struct {
    char* filename;
    char* extension;
} file_info_t;

// Function to parse a filename and determine its extension
file_info_t parse_filename(const char* filename) {
    // Allocate memory for the parsed filename and extension
    file_info_t info = {NULL, NULL};
    info.filename = malloc(strlen(filename) + 1);
    info.extension = malloc(strlen(filename) + 1);

    // Copy the original filename to the parsed filename
    strcpy(info.filename, filename);

    // Get the extension of the filename
    char* ext_ptr = strrchr(filename, '.');

    // Check if the filename has an extension
    if (ext_ptr != NULL) {
        // Calculate the length of the extension
        size_t ext_len = strlen(ext_ptr + 1);

        // Allocate memory for the extension
        info.extension = malloc(ext_len + 1);

        // Copy the extension to the parsed extension
        strcpy(info.extension, ext_ptr + 1);
    } else {
        // No extension found, set the extension to NULL
        info.extension = NULL;
    }

    return info;
}

// Function to modify a filename's extension and add digits
char* modify_filename(const char* filename, const int num_digits) {
    // Parse the filename and determine its extension
    file_info_t info = parse_filename(filename);

    // Check if the filename has an extension
    if (info.extension == NULL) {
        // No extension found, return an error code
        fprintf(stderr, "Invalid filename: %s\n", filename);
        return NULL;
    }

    // Get the length of the original filename and extension
    size_t orig_len = strlen(info.filename) + 1;
    size_t ext_len = strlen(info.extension) + 1;

    // Calculate the new file name length based on the number of digits
    int new_len = orig_len + num_digits * (sizeof(int) - 1);

    // Allocate memory for the new filename
    char* new_filename = malloc(new_len);

    // Copy the original filename to the new filename, but replace the extension with a new one
    strcpy(new_filename, info.filename);
    strcat(new_filename, ".");
    for (int i = 0; i < num_digits; i++) {
        char buffer[3];
        sprintf(buffer, "%d", rand() % 10);
        strcat(new_filename, buffer);
    }
    strcat(new_filename, info.extension);

    // Free the memory allocated for the parsed filename and extension
    free(info.filename);
    free(info.extension);

    return new_filename;
}

int main() {
    char* filename = "test.txt";
    int num_digits = 3;
    char* new_filename = modify_filename(filename, num_digits);
    printf("New filename: %s\n", new_filename);
    free(new_filename);
    return 0;
}
```
