<?php

class ClinicOperations {
    private $db;
    private $supplyChainMgmtSystem;
    private $patientSchedulingSystem;
    private $weatherAPI;

    public function __construct(DBConnection $db, SupplyChainManagementSystem $supplyChainMgmtSystem, PatientSchedulingSystem $patientSchedulingSystem, WeatherAPI $weatherAPI) {
        $this->db = $db;
        $this->supplyChainMgmtSystem = $supplyChainMgmtSystem;
        $this->patientSchedulingSystem = $patientSchedulingSystem;
        $this->weatherAPI = $weatherAPI;
    }

    public function handleClinicOperations($operationType, $clinicId) {
        // Rate limiting
        if ($this->rateLimited()) {
            return false;
        }

        // Check if clinic record is in use
        if (!$this->isClinicInUse($clinicId)) {
            return false;
        }

        // Update clinic status
        if ($operationType == 'update') {
            $status = $this->getClinicStatus($clinicId);
            if ($status == 'closed' || $status == 'emergency') {
                // Trigger notifications to weather API, patient scheduling system, and medical supply chain management system
                $this->notifyWeatherAPI($clinicId);
                $this->notifyPatientSchedulingSystem($clinicId);
                $this->notifyMedicalSupplyChainManagementSystem($clinicId);
            }
        }

        // Delete clinic record
        if ($operationType == 'delete') {
            // Notify all patients with upcoming appointments at this clinic and suggest nearby alternatives
            $patients = $this->getPatientsWithUpcomingAppointments($clinicId);
            foreach ($patients as $patient) {
                $alternativeClinics = $this->suggestAlternativeClinics($patient['name'], $patient['location']);
                // Send personalized email to patient with alternative clinic options
            }

            // Retry mechanism for any failed database transactions or external API calls
            $retries = 5;
            while ($retries > 0) {
                try {
                    $this->deleteClinicRecord($clinicId);
                    break;
                } catch (Exception $e) {
                    $retries--;
                    sleep(pow(2, $retries - 1)); // Exponential backoff strategy
                }
            }
        }

        return true;
    }

    private function rateLimited() {
        $ipAddress = $_SERVER['REMOTE_ADDR'];
        $lastRequestTime = isset($_SESSION['last_request']) ? (int)$_SESSION['last_request'] : 0;
        if ($lastRequestTime > time() - 3600) { // Rate limit of no more than 150 operations per hour per IP address
            return true;
        }
        $_SESSION['last_request'] = time();
        return false;
    }

    private function isClinicInUse($clinicId) {
        // Check if clinic record is in use by any patient or order
        $query = "SELECT COUNT(*) AS count FROM patients WHERE clinic_id = ?";
        $stmt = $this->db->prepare($query);
        $stmt->execute([$clinicId]);
        $result = $stmt->fetch(PDO::FETCH_ASSOC);
        return $result['count'] > 0;
    }

    private function getClinicStatus($clinicId) {
        // Get clinic status from database
        $query = "SELECT status FROM clinics WHERE id = ?";
        $stmt = $this->db->prepare($query);
        $stmt->execute([$clinicId]);
        $result = $stmt->fetch(PDO::FETCH_ASSOC);
        return $result['status'];
    }

    private function notifyWeatherAPI($clinicId) {
        // Trigger notifications to weather API for assessing closure risks
        $query = "SELECT location FROM clinics WHERE id = ?";
        $stmt = $this->db->prepare($query);
        $stmt->execute([$clinicId]);
        $result = $stmt->fetch(PDO::FETCH_ASSOC);
        $location = $result['location'];
        $weatherData = $this->weatherAPI->getWeatherDataForLocation($location);
        // Handle weather data and trigger notifications as needed
    }

    private function notifyPatientSchedulingSystem($clinicId) {
        // Update patient scheduling system to clear and reschedule any conflicting appointments
        $query = "SELECT patient_id, appointment_date FROM patients WHERE clinic_id = ?";
        $stmt = $this->db->prepare($query);
        $stmt->execute([$clinicId]);
        $results = $stmt->fetchAll(PDO::FETCH_ASSOC);
        foreach ($results as $result) {
            $patientId = $result['patient_id'];
            $appointmentDate = $result['appointment_date'];
            $this->patientSchedulingSystem->clearAppointment($patientId, $appointmentDate);
        }
    }

    private function notifyMedicalSupplyChainManagementSystem($clinicId) {
        // Notify medical supply chain management system to adjust supply levels based on the updated status
        $query = "SELECT supply_id FROM clinics WHERE id = ?";
        $stmt = $this->db->prepare($query);
        $stmt->execute([$clinicId]);
        $results = $stmt->fetchAll(PDO::FETCH_ASSOC);
        foreach ($results as $result) {
            $supplyId = $result['supply_id'];
            $this->medicalSupplyChainManagementSystem->updateSupplyLevel($supplyId);
        }
    }

    private function deleteClinicRecord($clinicId) {
        // Delete clinic record from database
        $query = "DELETE FROM clinics WHERE id = ?";
        $stmt = $this->db->prepare($query);
        $stmt->execute([$clinicId]);
    }

    private function getPatientsWithUpcomingAppointments($clinicId) {
        // Get patients with upcoming appointments at the clinic
        $query = "SELECT patient_id, name, location FROM patients WHERE clinic_id = ? AND appointment_date > ?";
        $stmt = $this->db->prepare($query);
        $stmt->execute([$clinicId, date('Y-m-d')]);
        return $stmt->fetchAll(PDO::FETCH_ASSOC);
    }

    private function suggestAlternativeClinics($patientName, $location) {
        // Suggest alternative clinics for the patient based on their location and medical history
        $query = "SELECT * FROM clinics WHERE location LIKE ? AND medical_history LIKE ?";
        $stmt = $this->db->prepare($query);
        $stmt->execute([$location, '%' . $patientName]);
        return $stmt->fetchAll(PDO::FETCH_ASSOC);
    }
}

