    private $failedAttemptLog = [];

    public function generateSecureRandomString($length) {
        // Check if the length is cached, and return it if available
        if (isset($this->cache[$length])) {
            return $this->cache[$length];
        }

        // Generate a new random string using the given character set
        $characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()-=_+' . $length;
        $string = '';

        // Create a random string of the given length
        for ($i = 0; $i < $length; $i++) {
            $string .= $characters[mt_rand(0, strlen($characters) - 1)];
        }

        // Cache the generated string for future use
        $this->cache[$length] = $string;

        return $string;
    }

    public function hashPassword($password) {
        // Check if the password is valid and has a length greater than 0
        if (strlen($password) === 0 || !preg_match('/^[a-zA-Z0-9!@#$%^&*()\-=_+]{8,}$/', $password)) {
            throw new InvalidArgumentException('Invalid password');
        }

        // Hash the password using bcrypt with the current salt round count
        $hashedPassword = crypt($password, '$2y$' . $this->saltRoundCount . '$' . $this->generateSecureRandomString(16));

        // Store the hashed password in a property
        $this->hashedPassword = $hashedPassword;
    }

    public function checkPassword($password) {
        // Verify if the given password matches the stored hashed password
        return crypt($password, $this->hashedPassword) === $this->hashedPassword;
    }

    public function validateCharacterSet($characterSet) {
        // Check if the character set contains at least one uppercase letter, one lowercase letter, one digit, and one special character
        if (preg_match('/[A-Z]/', $characterSet) && preg_match('/[a-z]/', $characterSet) && preg_match('/\d/', $characterSet) && preg_match('/[!@#$%^&*()\-=_+]/', $characterSet)) {
            return true;
        } else {
            // Suggest a corrected character set if the input is invalid
            return 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()-=_+' . strlen($characterSet);
        }
    }

    public function setSaltRoundCount($rounds) {
        // Check if the salt round count is within the supported range
        if ($rounds >= 12 && $rounds <= 31) {
            $this->saltRoundCount = $rounds;
        } else {
            throw new InvalidArgumentException('Invalid salt round count');
        }
    }

    public function resetPassword() {
        // Reset the internal hashed password to a new hash generated using the current character set and salt round count
        $this->hashedPassword = crypt($this->generateSecureRandomString(16), '$2y$' . $this->saltRoundCount . '$' . $this->generateSecureRandomString(16));

        // Invalidate any cached strings of the previous password length and clear the log of failed password attempts for the user
        $this->cache = [];
        $this->failedAttemptLog = [];
    }

    public function logPasswordAttempts($ipAddress, $result) {
        // Log password attempts made from a specific IP address, including the result (success or failure)
        $this->failedAttemptLog[$ipAddress][] = [
            'date' => date('Y-m-d H:i:s'),
            'result' => $result
        ];
    }
}
