public static string DecryptAndConvertImage(string encryptedMessage, string inputJpegFilePath, string outputPdfFilePath)
{
    // Initialize variables
    byte[] key = null;
    byte[] iv = null;
    string decryptedMessage = null;
    bool conversionSuccessful = false;

    try
    {
        // Decrypt the message using Triple DES encryption with a given key and initialization vector (IV)
        key = Encoding.UTF8.GetBytes("your-key");
        iv = Encoding.UTF8.GetBytes("your-iv");
        decryptedMessage = TripleDES.DecryptString(encryptedMessage, key, iv);

        // Fetch the private key and certificate from a location specified in the decrypted OAuth request
        string privateKeyFilePath = Path.Combine(decryptedMessage, "private-key.pem");
        string certificateFilePath = Path.Combine(decryptedMessage, "certificate.cer");

        // Combine the private key and certificate into a single PEM file
        File.WriteAllBytes(outputPdfFilePath + ".pem", CombinePrivateKeyAndCertificate(privateKeyFilePath, certificateFilePath));

        // Use a third-party tool to convert the input JPEG file to a PDF file and save it with the specified output file name
        using (var converter = new Converter())
        {
            conversionSuccessful = await converter.Convert(inputJpegFilePath, outputPdfFilePath);
        }
    }
    catch (Exception e)
    {
        // Log error message and return error message indicating which step failed
        Console.WriteLine("Error: " + e.Message);
        return "Conversion failed";
    }

    if (!conversionSuccessful)
    {
        // Return error message indicating conversion failed
        return "Conversion failed";
    }
    else
    {
        // Return decrypted message
        return decryptedMessage;
    }
}

public static byte[] CombinePrivateKeyAndCertificate(string privateKeyFilePath, string certificateFilePath)
{
    var combinedBytes = new List<byte>();

    // Read the contents of the private key and certificate files into byte arrays
    using (var privateKeyReader = new StreamReader(privateKeyFilePath))
    {
        var privateKeyContents = privateKeyReader.ReadToEnd();
        var privateKeyBytes = Encoding.UTF8.GetBytes(privateKeyContents);
        combinedBytes.AddRange(privateKeyBytes);
    }

    using (var certificateReader = new StreamReader(certificateFilePath))
    {
        var certificateContents = certificateReader.ReadToEnd();
        var certificateBytes = Encoding.UTF8.GetBytes(certificateContents);
        combinedBytes.AddRange(certificateBytes);
    }

    // Return the combined byte array
    return combinedBytes.ToArray();
}
