import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class DistributedLoggingService {
    private final ScheduledExecutorService scheduler;
    private final LogProcessorFactory logProcessorFactory;
    private final LogAggregator logAggregator;
    private final LogStore logStore;

    public DistributedLoggingService(ScheduledExecutorService scheduler, LogProcessorFactory logProcessorFactory, LogAggregator logAggregator, LogStore logStore) {
        this.scheduler = scheduler;
        this.logProcessorFactory = logProcessorFactory;
        this.logAggregator = logAggregator;
        this.logStore = logStore;
    }

    public void startLogging() {
        // Schedule the logging process to run every 10 seconds with a delay of 5 seconds
        scheduler.scheduleAtFixedRate(() -> {
            try {
                // Start the logging process
                logAggregator.start();

                // Process the logs and send them to the log store
                logStore.sendLogs(logAggregator.getAggregatedLogs());

                // Stop the logging process after a delay of 5 seconds
                scheduler.schedule(() -> logAggregator.stop(), 5, TimeUnit.SECONDS);
            } catch (Exception e) {
                System.err.println("Error occurred while starting the logging service: " + e.getMessage());
            }
        }, 5, 10, TimeUnit.SECONDS);
    }

    public void stopLogging() {
        // Stop the scheduled tasks
        scheduler.shutdown();
    }
}
```

