class MersenneTwister extends Random {
    private long[] gen;

    public MersenneTwister() {
        this.gen = new long[56];
    }

    public int nextInt() {
        return (int)((this.gen[(this.i + 19) & 0x3f] << 16 | this.gen[(this.i + 28) & 0x3f]) >>> 1);
    }
}

