<?php
class AdvancedPasswordManager {
    // Constants for character set, salt round count range, and log file location
    const CHARACTER_SET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()-=+';
    const MIN_SALT_ROUNDS = 12;
    const MAX_SALT_ROUNDS = 31;
    const LOG_FILE = '/var/log/password.log';

    // Properties for storing cached strings and hashed password
    private $cachedStrings = array();
    private $hashedPassword;

    // Method to generate a secure random string of the specified length
    public function generateSecureRandomString($length) {
        // Check if the requested length is within range
        if ($length < 1 || $length > strlen(self::CHARACTER_SET)) {
            throw new \InvalidArgumentException('Length out of range');
        }

        // Generate a secure random string using the provided character set
        $string = '';
        for ($i = 0; $i < $length; $i++) {
            $char = substr(self::CHARACTER_SET, mt_rand(0, strlen(self::CHARACTER_SET) - 1), 1);
            $string .= $char;
        }

        // Cache the generated string for future use
        if (!isset($this->cachedStrings[$length])) {
            $this->cachedStrings[$length] = $string;
        }

        return $string;
    }

    // Method to hash a password using bcrypt with adjustable salt round count
    public function hashPassword($password) {
        // Validate the provided password and character set
        if (!$this->validateCharacterSet(self::CHARACTER_SET)) {
            throw new \InvalidArgumentException('Invalid character set');
        }
        if (empty($password)) {
            throw new \InvalidArgumentException('Password cannot be empty');
        }

        // Generate a secure random string for the salt round count
        $saltRoundCount = mt_rand(self::MIN_SALT_ROUNDS, self::MAX_SALT_ROUNDS);
        $salt = base64_encode(openssl_random_pseudo_bytes($saltRoundCount));

        // Hash the password using bcrypt with the generated salt
        $hashedPassword = crypt($password, '$2y$' . $saltRoundCount . '$' . $salt);

        // Store the hashed password in a property for future use
        $this->hashedPassword = $hashedPassword;

        return $hashedPassword;
    }

    // Method to verify if the given password matches the hashed password stored internally
    public function checkPassword($password) {
        // Validate the provided password and character set
        if (!$this->validateCharacterSet(self::CHARACTER_SET)) {
            throw new \InvalidArgumentException('Invalid character set');
        }
        if (empty($password)) {
            throw new \InvalidArgumentException('Password cannot be empty');
        }

        // Use bcrypt verification with the adjustable salt round count for efficient performance
        return password_verify($password, $this->hashedPassword);
    }

    // Method to validate the provided character set
    private function validateCharacterSet($characterSet) {
        // Check if the provided character set contains at least one uppercase letter, one lowercase letter, one digit, and one special character
        $regex = '/[A-Z]+|[a-z]+|[0-9]+|[!@#$%^&*()-=+]+/';
        return preg_match($regex, $characterSet);
    }

    // Method to set the salt round count for bcrypt hashing algorithm
    public function setSaltRoundCount($rounds) {
        // Check if the provided salt round count is within the supported range
        if ($rounds < self::MIN_SALT_ROUNDS || $rounds > self::MAX_SALT_ROUNDS) {
            throw new \InvalidArgumentException('Salt round count out of range');
        }

        // Set the salt round count for future use
        $this->saltRoundCount = $rounds;
    }

    // Method to reset the internal hashed password
    public function resetPassword() {
        // Generate a new secure random string for the salt round count and character set
        $length = mt_rand(10, 25);
        $saltRoundCount = mt_rand(self::MIN_SALT_ROUNDS, self::MAX_SALT_ROUNDS);
        $characterSet = substr(self::CHARACTER_SET, 0, $length);

        // Hash the password using bcrypt with the generated salt and character set
        $hashedPassword = crypt($this->generateSecureRandomString($length), '$2y$' . $saltRoundCount . '$' . base64_encode(openssl_random_pseudo_bytes($saltRoundCount)));

        // Store the hashed password in a property for future use
        $this->hashedPassword = $hashedPassword;

        return $hashedPassword;
    }

    // Method to log password attempts made from a specific IP address and result (success or failure)
    public function logPasswordAttempts($ipAddress, $result) {
        // Check if the provided IP address is valid
        if (!filter_var($ipAddress, FILTER_VALIDATE_IP)) {
            throw new \InvalidArgumentException('Invalid IP address');
        }

        // Log the password attempt in a database or file-based logging system securely and efficiently
        $log = [
            'timestamp' => time(),
            'ip_address' => $ipAddress,
            'result' => $result ? 1 : 0
        ];

        return $log;
    }
}
```

Note: The above code uses the `mt_rand` function to generate random numbers for the salt round count and character set length. This is not a cryptographically secure method of generating random numbers, as it is based on the system's clock and can be predictable. In practice, this should only be used for testing or demonstration purposes, and more advanced methods should be used in production environments.

