package com.example;

import java.util.*;
import java.util.concurrent.*;
import org.json.*;

public class DynamicServiceManager {
    private final Map<String, ServiceFactory> factories = new ConcurrentHashMap<>();
    private final Map<String, ServiceInstance> instances = new ConcurrentHashMap<>();
    private final Random random = new Random();

    public void addService(String id, Class<? extends Service> serviceClass) {
        try {
            ServiceFactory factory = new ServiceFactory(serviceClass);
            factories.put(id, factory);
        } catch (Exception e) {
            throw new RuntimeException("Error adding service", e);
        }
    }

    public void removeService(String id) {
        instances.remove(id);
        factories.remove(id);
    }

    public ServiceInstance getServiceInstance(String id) {
        return instances.get(id);
    }

    public String getServiceConfiguration(String id) {
        ServiceFactory factory = factories.get(id);
        if (factory == null) {
            throw new RuntimeException("No service with ID " + id);
        }
        return factory.toJson();
    }

    public void startService(String id, JSONObject config) throws Exception {
        ServiceFactory factory = factories.get(id);
        if (factory == null) {
            throw new RuntimeException("No service with ID " + id);
        }
        ServiceInstance instance = factory.create(config);
        instances.put(id, instance);
    }

    public void stopService(String id) throws Exception {
        ServiceInstance instance = instances.get(id);
        if (instance == null) {
            throw new RuntimeException("No service with ID " + id);
        }
        instance.stop();
        instances.remove(id);
    }

    private static class ServiceFactory {
        private final Class<? extends Service> serviceClass;

        public ServiceFactory(Class<? extends Service> serviceClass) {
            this.serviceClass = serviceClass;
        }

        public ServiceInstance create(JSONObject config) throws Exception {
            return (ServiceInstance) serviceClass.getConstructor(JSONObject.class).newInstance(config);
        }

        public String toJson() {
            return "{}"; // TODO: implement this method
        }
    }

    private static class ServiceInstance {
        private final Service service;

        public ServiceInstance(Service service) {
            this.service = service;
        }

        public void start() throws Exception {
            service.start();
        }

        public void stop() throws Exception {
            service.stop();
        }
    }
}

interface Service {
    void start();
    void stop();
}
