// Define the session variable name for authenticated user information
const AUTHENTICATED_USER = 'authenticatedUser';

/**
 * Authenticate a user using OAuth 2.0 client credentials flow
 * @param array $authConfig Authentication configuration data (e.g., client ID and secret)
 */
function authenticateUser(array $authConfig): string {
    // Use the Guzzle HTTP client to make a POST request to the authentication URL
    $response = \GuzzleHttp\Client::post(AUTH_URL, [
        'form_params' => [
            'grant_type' => 'client_credentials',
            'client_id' => $authConfig['clientId'],
            'client_secret' => $authConfig['clientSecret'],
            'scope' => '', // Add any additional scopes here, separated by spaces
        ],
    ]);

    // Get the access token from the response body
    $accessToken = json_decode($response->getBody(), true)['access_token'];

    // Store the access token in a session variable for future use
    $_SESSION[AUTHENTICATED_USER]['accessToken'] = $accessToken;

    return $accessToken;
}

/**
 * Update the status of one or more clinics using OAuth 2.0 client credentials flow
 * @param array $clinicStatusArray Array of clinic status data (e.g., name, address, etc.)
 */
function updateClinicStatus(array $clinicStatusArray): void {
    // Use the Guzzle HTTP client to make a POST request to the update clinic status URL
    \GuzzleHttp\Client::post(UPDATE_CLINIC_STATUS_URL, [
        'json' => $clinicStatusArray,
    ]);
}

/**
 * Calculate the hash of a file using OAuth 2.0 client credentials flow
 * @param string $filePath Path to the file on disk
 */
function calculateFileHash(string $filePath): string {
    // Use the Guzzle HTTP client to make a POST request to the calculate file hash URL
    $response = \GuzzleHttp\Client::post(CALCULATE_FILE_HASH_URL, [
        'multipart' => [
            [
                'name' => 'file',
                'contents' => fopen($filePath, 'r'),
            ],
        ],
    ]);

    // Get the file hash from the response body
    $hash = json_decode($response->getBody(), true)['hash'];

    return $hash;
}

