import json
import threading
from collections import defaultdict

class GraphDatabaseService(object):
    def __init__(self, config=None):
        self.vertices = {}
        self.edges = {}
        self.properties = {}
        self.property_versions = {}
        self.lock = threading.Lock()

    def add_vertex(self, vertex_id, properties={}):
        with self.lock:
            if vertex_id in self.vertices:
                raise ValueError("Vertex already exists")

            self.vertices[vertex_id] = {**properties}

    def add_edge(self, edge_id, source_id, target_id):
        with self.lock:
            if not (source_id in self.vertices and target_id in self.vertices):
                raise ValueError("Invalid vertex ID")

            self.edges[edge_id] = (source_id, target_id)

    def set_property(self, vertex_id, property_name, value):
        with self.lock:
            if not (vertex_id in self.vertices and property_name in self.properties[vertex_id]):
                raise ValueError("Invalid property name")

            self.properties[vertex_id][property_name] = value

    def get_historical_state(self, vertex_id, timestamp=None):
        with self.lock:
            if not (vertex_id in self.vertices and timestamp in self.timestamps):
                raise ValueError("Invalid vertex ID or timestamp")

            return self.timestamps[vertex_id][timestamp]

    def get_property_versions(self, property_name):
        with self.lock:
            if not (property_name in self.properties):
                raise ValueError("Invalid property name")

            return list(self.property_versions[property_name].keys())

    def update_property_version(self, property_name, version):
        with self.lock:
            if not (property_name in self.properties and version in self.property_versions[property_name]):
                raise ValueError("Invalid property name or version")

            self.properties[property_name][version] = self.property_versions[property_name][version]

    def connect_to_external_system(self, external_system):
        with self.lock:
            if not (external_system in self.external_systems):
                raise ValueError("Invalid external system")

            self.external_systems[external_system] = {}

    def query_historical_state(self, vertex_id, timestamp=None):
        with self.lock:
            if not (vertex_id in self.vertices and timestamp in self.timestamps):
                raise ValueError("Invalid vertex ID or timestamp")

            return self.timestamps[vertex_id][timestamp]

    def get_property_version(self, property_name, version):
        with self.lock:
            if not (property_name in self.properties and version in self.property_versions[property_name]):
                raise ValueError("Invalid property name or version")

            return self.properties[property_name][version]

    def handle_update(self, update_json):
        with self.lock:
            operation = update_json["operation"]
            parameters = update_json["parameters"]

            if operation == "add_vertex":
                vertex_id = parameters["vertex_id"]
                properties = parameters["properties"]

                self.add_vertex(vertex_id, properties)

            elif operation == "add_edge":
                edge_id = parameters["edge_id"]
                source_id = parameters["source_id"]
                target_id = parameters["target_id"]

                self.add_edge(edge_id, source_id, target_id)

            elif operation == "set_property":
                vertex_id = parameters["vertex_id"]
                property_name = parameters["property_name"]
                value = parameters["value"]

                self.set_property(vertex_id, property_name, value)

            elif operation == "get_historical_state":
                vertex_id = parameters["vertex_id"]
                timestamp = parameters["timestamp"]

                return self.get_historical_state(vertex_id, timestamp)

            elif operation == "update_property_version":
                property_name = parameters["property_name"]
                version = parameters["version"]

                self.update_property_version(property_name, version)

            elif operation == "connect_to_external_system":
                external_system = parameters["external_system"]

                self.connect_to_external_system(external_system)

            elif operation == "query_historical_state":
                vertex_id = parameters["vertex_id"]
                timestamp = parameters["timestamp"]

                return self.query_historical_state(vertex_id, timestamp)

            elif operation == "get_property_version":
                property_name = parameters["property_name"]
                version = parameters["version"]

                return self.get_property_version(property_name, version)

    def handle_external_system_update(self, external_system, update_json):
        with self.lock:
            operation = update_json["operation"]
            parameters = update_json["parameters"]

            if operation == "add_vertex":
                vertex_id = parameters["vertex_id"]
                properties = parameters["properties"]

                self.vertices[vertex_id] = {**properties}

            elif operation == "add_edge":
                edge_id = parameters["edge_id"]
                source_id = parameters["source_id"]
                target_id = parameters["target_id"]

                self.edges[edge_id] = {**self.vertices[source_id], **self.vertices[target_id]}

            elif operation == "set_property":
                vertex_id = parameters["vertex_id"]
                property_name = parameters["property_name"]
                value = parameters["value"]

                self.vertices[vertex_id][property_name] = value

            elif operation == "update_property_version":
                property_name = parameters["property_name"]
                version = parameters["version"]

                self.property_versions[property_name][version] = self.vertices[vertex_id][property_name]

    def handle_query(self, query_json):
        with self.lock:
            operation = query_json["operation"]
            parameters = query_json["parameters"]

            if operation == "get_vertex":
                vertex_id = parameters["vertex_id"]

                return self.vertices[vertex_id]

            elif operation == "get_edge":
                edge_id = parameters["edge_id"]

                return self.edges[edge_id]

            elif operation == "get_property":
                vertex_id = parameters["vertex_id"]
                property_name = parameters["property_name"]

                return self.vertices[vertex_id][property_name]

    def run(self):
        while True:
            update_json = self.receive_update()

            if update_json is None:
                break

            operation = update_json["operation"]

            if operation == "handle_update":
                self.handle_update(update_json)

            elif operation == "handle_external_system_update":
                external_system = update_json["parameters"]["external_system"]
                update_json = self.receive_update()

                while update_json is not None and update_json["operation"] != "end_of_stream":
                    self.handle_external_system_update(external_system, update_json)

                    update_json = self.receive_update()

            elif operation == "handle_query":
                query_json = self.receive_update()

                while query_json is not None and query_json["operation"] != "end_of_stream":
                    result = self.handle_query(query_json)

                    if result is not None:
                        self.send_result(result)

                    query_json = self.receive_update()

            else:
                raise ValueError("Invalid operation")
