### 3.3 Sending and receiving messages

The `Message` class represents a message that can be sent or received by the vertex. The `Vertex` class has methods to send and receive messages, which take in the destination vertex ID and the message as input. The `Vertex` class also maintains a list of incoming messages and outgoing messages for each edge.

```python
class Message:
    def __init__(self, content):
        self.content = content
        self.destination_vertex_id = None
        self.source_vertex_id = None

    def get_content(self):
        return self.content
```

```python
class Vertex:
    def __init__(self, vertex_id, outgoing_edges=None, incoming_messages=None, incoming_edge_labels=None, messages_to_send=None):
        self.vertex_id = vertex_id
        self.outgoing_edges = outgoing_edges if outgoing_edges is not None else {}
        self.incoming_messages = incoming_messages if incoming_messages is not None else {}
        self.incoming_edge_labels = incoming_edge_labels if incoming_edge_labels is not None else {}
        self.messages_to_send = messages_to_send if messages_to_send is not None else []

    def send_message(self, destination_vertex_id, message):
        if destination_vertex_id in self.outgoing_edges:
            self.outgoing_edges[destination_vertex_id].append(message)
        else:
            self.outgoing_edges[destination_vertex_id] = [message]

    def receive_message(self, source_vertex_id, message):
        if source_vertex_id in self.incoming_messages:
            self.incoming_messages[source_vertex_id].append(message)
        else:
            self.incoming_messages[source_vertex_id] = [message]

    def get_outgoing_edge_labels(self):
        return list(self.outgoing_edges.keys())

    def get_incoming_edge_labels(self):
        return list(self.incoming_messages.keys())

    def get_outgoing_messages(self, destination_vertex_id):
        if destination_vertex_id in self.outgoing_edges:
            return self.outgoing_edges[destination_vertex_id]
        else:
            return None

    def get_incoming_messages(self, source_vertex_id):
        if source_vertex_id in self.incoming_messages:
            return self.incoming_messages[source_vertex_id]
        else:
            return None
```

### 3.4 Graph data structure

The `Graph` class represents a graph data structure, which consists of vertices and edges. The `Graph` class provides methods to add and remove vertices and edges, as well as methods to access the vertices and edges in the graph.

```python
class Graph:
    def __init__(self):
        self.vertices = {}

    def add_vertex(self, vertex):
        if vertex.vertex_id not in self.vertices:
            self.vertices[vertex.vertex_id] = vertex

    def remove_vertex(self, vertex_id):
        if vertex_id in self.vertices:
            del self.vertices[vertex_id]

    def add_edge(self, edge):
        if edge.source_vertex_id not in self.vertices:
            raise ValueError("Source vertex does not exist")

        if edge.destination_vertex_id not in self.vertices:
            raise ValueError("Destination vertex does not exist")

        if edge.edge_label not in self.vertices[edge.source_vertex_id].outgoing_edges:
            self.vertices[edge.source_vertex_id].outgoing_edges[edge.edge_label] = []

        self.vertices[edge.source_vertex_id].outgoing_edges[edge.edge_label].append(edge)

    def remove_edge(self, source_vertex_id, destination_vertex_id, edge_label):
        if source_vertex_id not in self.vertices:
            raise ValueError("Source vertex does not exist")

        if destination_vertex_id not in self.vertices:
            raise ValueError("Destination vertex does not exist")

        if edge_label not in self.vertices[source_vertex_id].outgoing_edges:
            raise ValueError("Edge label does not exist")

        for edge in self.vertices[source_vertex_id].outgoing_edges[edge_label]:
            if edge.destination_vertex_id == destination_vertex_id:
                del self.vertices[source_vertex_id].outgoing_edges[edge_label]
                break

    def get_vertices(self):
        return list(self.vertices.keys())

    def get_vertices_with_labels(self, labels):
        result = []

        for vertex in self.vertices:
            if all(label in self.vertices[vertex].outgoing_edges for label in labels):
                result.append(vertex)

        return result

    def get_edges(self, source_vertex_id=None, destination_vertex_id=None, edge_label=None):
        if source_vertex_id is None and destination_vertex_id is None and edge_label is None:
            result = []

            for vertex in self.vertices:
                for edge in self.vertices[vertex].outgoing_edges:
                    result.append(edge)

            return result
        else:
            if source_vertex_id not in self.vertices:
                raise ValueError("Source vertex does not exist")

            if destination_vertex_id is not None and destination_vertex_id not in self.vertices:
                raise ValueError("Destination vertex does not exist")

            if edge_label is not None and edge_label not in self.vertices[source_vertex_id].outgoing_edges:
                raise ValueError("Edge label does not exist")

            result = []

            for edge in self.vertices[source_vertex_id].outgoing_edges:
                if destination_vertex_id is None or destination_vertex_id == edge.destination_vertex_id:
                    if edge_label is None or edge_label == edge.edge_label:
                        result.append(edge)

            return result
```

### 3.5 Example usage

Here's an example of how to use the `Graph` class to create a simple graph, add and remove vertices and edges, and perform graph traversal operations:

```python
g = Graph()

# Add vertices and edges to the graph
v1 = Vertex("A")
v2 = Vertex("B")
v3 = Vertex("C")
v4 = Vertex("D")
e1 = Edge(v1, v2, "friend")
e2 = Edge(v2, v3, "friend")
g.add_vertex(v1)
g.add_vertex(v2)
g.add_vertex(v3)
g.add_edge(e1)
g.add_edge(e2)

# Remove vertices and edges from the graph
g.remove_vertex("A")
g.remove_edge("B", "C", "friend")

# Perform graph traversal operations
print(g.get_vertices()) # Output: ["B", "C", "D"]
print(g.get_edges()) # Output: [Edge(Vertex('B', {}), Vertex('C', {}), 'friend')]
```

