#include <fcntl.h>
#include <errno.h>
#include <pthread.h>
#include <curl/curl.h>

#define MAX_LOG_FILES 10
#define CLEANUP_INTERVAL 60 // in seconds

struct log_file {
    char *path;
    time_t last_accessed;
};

struct log_files {
    struct log_file files[MAX_LOG_FILES];
    int num_files;
};

void *cleanup_thread(void *arg) {
    struct log_files *logs = (struct log_files *) arg;

    while (1) {
        sleep(CLEANUP_INTERVAL);
        for (int i = 0; i < logs->num_files; i++) {
            if (!logs->files[i].path) {
                continue;
            }
            time_t now = time(NULL);
            if ((now - logs->files[i].last_accessed) > MAX_LOG_FILES) {
                unlink(logs->files[i].path);
                free(logs->files[i].path);
                logs->files[i].path = NULL;
                logs->num_files--;
            }
        }
    }
}

int create_log_file(char *filename, char *output) {
    struct log_files *logs = (struct log_files *) arg;

    // check if the file exists and is not a directory
    struct stat st;
    if (stat(filename, &st) == 0 && !S_ISDIR(st.st_mode)) {
        return -1;
    }

    int fd = open(filename, O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR);
    if (fd < 0) {
        return -2;
    }

    // update the environment variable pointing to the current log file
    char *env = malloc(strlen(filename) + strlen(output) + 1);
    strcpy(env, filename);
    strcat(env, output);
    setenv("CURRENT_LOG_FILE", env, 1);
    free(env);

    // create a new log file structure
    struct log_file *log = malloc(sizeof(struct log_file));
    log->path = strdup(filename);
    log->last_accessed = time(NULL);

    // add the new log file to the list of files
    logs->files[logs->num_files++] = log;

    return 0;
}

int convert_jpeg_to_pdf(char *filename, char *output) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        return -1;
    }

    // set the URL for the JPEG file
    char url[strlen(filename) + 1];
    strcpy(url, filename);
    curl_easy_setopt(curl, CURLOPT_URL, url);

    // set the output path for the PDF file
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, output);

    // perform the conversion
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to convert JPEG to PDF: %s\n", curl_easy_strerror(res));
        return -2;
    }

    // clean up
    curl_easy_cleanup(curl);

    return 0;
}

int create_pdf_from_jpeg(char *filename, char *output) {
    // check if the input file exists and is not a directory
    struct stat st;
    if (stat(filename, &st) == 0 && !S_ISDIR(st.st_mode)) {
        return -1;
    }

    // create a new log file for this conversion
    char *log_file = malloc(strlen(filename) + strlen(output) + 1);
    sprintf(log_file, "%s%s", filename, output);
    int res = create_log_file(log_file, output);
    free(log_file);
    if (res < 0) {
        return -2;
    }

    // perform the conversion
    res = convert_jpeg_to_pdf(filename, output);
    if (res < 0) {
        return -3;
    }

    // update the last accessed time for the new log file
    struct log_file *log = get_log_file(output);
    if (log) {
        log->last_accessed = time(NULL);
    }

    return 0;
}

