import datetime
import json
import os
import sqlite3
from collections import deque
from enum import Enum

class DataType(Enum):
    VERTEX = 0
    EDGE = 1

class GraphDatabase:
    def __init__(self, database_path):
        self.database_path = database_path
        self.conn = sqlite3.connect(database_path)
        self.cur = self.conn.cursor()
        self.create_tables()

    def create_tables(self):
        self.cur.execute('CREATE TABLE IF NOT EXISTS vertices (id INTEGER PRIMARY KEY, properties TEXT)')
        self.cur.execute('CREATE TABLE IF NOT EXISTS edges (source_id INTEGER, target_id INTEGER, properties TEXT)')
        self.conn.commit()

    def add_vertex(self, properties):
        self.cur.execute("INSERT INTO vertices (properties) VALUES (?)", [json.dumps(properties)])
        self.conn.commit()

    def add_edge(self, source_id, target_id, properties):
        self.cur.execute("INSERT INTO edges (source_id, target_id, properties) VALUES (?, ?, ?)", [source_id, target_id, json.dumps(properties)])
        self.conn.commit()

    def get_vertices(self):
        return self.cur.execute('SELECT * FROM vertices').fetchall()

    def get_edges(self):
        return self.cur.execute('SELECT * FROM edges').fetchall()

class GraphService:
    def __init__(self, database_path):
        self.database = GraphDatabase(database_path)
        self.queue = deque()
        self.lock = threading.Lock()

    def add_vertex(self, properties):
        with self.lock:
            self.database.add_vertex(properties)
            self.queue.append((DataType.VERTEX, properties))

    def add_edge(self, source_id, target_id, properties):
        with self.lock:
            self.database.add_edge(source_id, target_id, properties)
            self.queue.append((DataType.EDGE, (source_id, target_id, properties)))

    def get_vertices(self):
        return self.database.get_vertices()

    def get_edges(self):
        return self.database.get_edges()

    def update_queue(self):
        with self.lock:
            while self.queue:
                data_type, data = self.queue.popleft()
                if data_type == DataType.VERTEX:
                    properties = json.loads(data)
                    self.database.add_vertex(properties)
                elif data_type == DataType.EDGE:
                    source_id, target_id, properties = json.loads(data)
                    self.database.add_edge(source_id, target_id, properties)
            self.conn.commit()
```
