// Helper function to find the largest integer in an array of integers
int findLargest(const std::vector<int>& numbers) {
    int largest = numbers[0];
    for (size_t i = 1; i < numbers.size(); ++i) {
        if (numbers[i] > largest) {
            largest = numbers[i];
        }
    }
    return largest;
}

// Python script to parse a grammar and generate LLVM IR code
import subprocess

def parseGrammar(file_path):
    # Run sed commands on the input file to modify it
    sed_commands = [
        "s/\\n/ /g",  # Replace all newline characters with spaces
        "s/\\t/ /g"  # Replace all tab characters with spaces
    ]
    for command in sed_commands:
        try:
            subprocess.run(["sed", "-i", command, file_path])
        except:
            raise Exception("Error running sed command")

    # Parse the modified input file using a lexer and parser
    lexer = Lexer()
    parser = Parser()
    try:
        tree = parser.parse(lexer.tokenize(file_path))
    except:
        raise Exception("Error parsing grammar")

    # Print debugging statements for the parsed nodes and generated LLVM IR code
    print("Parsed nodes:")
    for node in tree.nodes():
        print("  " + str(node))

    print("\nGenerated LLVM IR code:")
    for instruction in tree.instructions():
        print("  " + str(instruction))
