```
# Imports
import json
import requests
from collections import defaultdict

# Data structures for user preferences and item ratings
user_preferences = defaultdict(lambda: defaultdict(int))
item_ratings = defaultdict(float)

# Function to update user preferences
def update_preferences(user, items):
    global user_preferences
    for item in items:
        user_preferences[user][item] += 1

# Function to update item ratings
def update_ratings(items):
    global item_ratings
    for item in items:
        item_ratings[item] = float(sum(user_preferences[user].get(item, 0) for user in user_preferences)) / len(user_preferences)

# Function to retrieve recommendations
def get_recommendations(user):
    global user_preferences, item_ratings
    recommended_items = []
    for item in item_ratings:
        if item not in user_preferences[user]:
            continue
        score = float(sum(user_preferences[user].get(item, 0) / len(user_preferences) for user in user_preferences))
        recommended_items.append((score, item))
    return sorted(recommended_items, key=lambda x: x[0], reverse=True)[:10]

# RESTful API endpoints
@app.route('/update_preferences', methods=['POST'])
def update_preferences():
    user = request.json['user']
    items = request.json['items']
    update_preferences(user, items)
    return jsonify({'success': True})

@app.route('/update_ratings', methods=['POST'])
def update_ratings():
    items = request.json['items']
    update_ratings(items)
    return jsonify({'success': True})

@app.route('/get_recommendations', methods=['GET'])
def get_recommendations():
    user = request.args.get('user')
    recommended_items = get_recommendations(user)
    return jsonify({'success': True, 'recommended_items': recommended_items})
```
