import requests
import json
from time import sleep
from threading import Thread

class PushNotificationModule:
    def __init__(self):
        self.devices = {}
        self.protocols = {
            "APNs": {"url": "https://api.push.apple.com/3/device/", "auth_key": "your_auth_key"},
            "FCM": {"url": "https://fcm.googleapis.com/v1/projects/your_project_id/messages:send", "auth_key": "your_auth_key"}
        }

    def add_device(self, device):
        self.devices[device["token"]] = device

    def remove_device(self, token):
        if token in self.devices:
            del self.devices[token]

    def send_notification(self, message, token):
        protocol = "APNs" if token.startswith("ios") else "FCM"
        device = self.devices[token]
        headers = {
            "Content-Type": "application/json",
            "Authorization": f"Bearer {self.protocols[protocol]['auth_key']}"
        }
        data = json.dumps({"to": token, "data": message})
        response = requests.post(f"{self.protocols[protocol]['url']}/{device['id']}", headers=headers, data=data)
        if response.status_code == 200:
            return True
        elif response.status_code == 400:
            print("Bad request")
            return False
        else:
            sleep(5)
            return self.send_notification(message, token)

    def send_notifications(self, messages):
        threads = []
        for message in messages:
            thread = Thread(target=self.send_notification, args=(message,))
            threads.append(thread)
        for thread in threads:
            thread.start()
        for thread in threads:
            thread.join()

    def cache_device(self, device):
        self.devices[device["token"]] = device

    def get_cached_device(self, token):
        return self.devices[token] if token in self.devices else None

    def log_request(self, request):
        print("Request:", request)

    def log_response(self, response):
        print("Response:", response)
