        // Integrate with an external email service to send a notification email to the user after a successful update. The email should include a confirmation link that allows the user to verify the update, and the link should expire within 24 hours.
        if ($credentialType === 'email') {
            $emailService = new EmailService();
            $emailService->sendUpdateEmail($userId, $newValue);
        }
    }
}
