const httpsClient = new https.Agent({ rejectUnauthorized: false });

// Set up caching mechanism
const cache = new Map();
const cacheTime = 60 * 1000; // 1 minute in milliseconds

// Set up logger
const log = require('log');
log.info('Starting up!');

// Define endpoints and HTTP methods
app.get('/books', (req, res) => {
    // Use cache if possible
    const cachedResponse = cache.get(req.url);
    if (cachedResponse) {
        log.info(`Serving response from cache: ${cachedResponse}`);
        return res.json(cachedResponse);
    }

    // Make API request to external service
    const url = new URL('https://external-service.com/books');
    httpsClient.get(url, (err, response) => {
        if (err) {
            log.error(`Error retrieving books: ${err}`);
            return res.status(500).json({ error: err });
        }

        // Handle response
        const bookList = JSON.parse(response.body);
        cache.set(req.url, bookList);
        log.info(`Serving response from external service: ${bookList}`);
        return res.json(bookList);
    });
});

// Define error handling middleware
