} NFAPI_CRC_INDICATION_PDU_T;

void dynamicTestLoader(NFAPI_CRC_INDICATION_PDU_T *list, int size) {
    // Initialize list and lock
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
    int i;

    // Generate unique CRCFLAG values and populate list
    for (i = 0; i < size; i++) {
        pthread_mutex_lock(&mutex);
        while (1) {
            unsigned long random = rand() % 1000;
            if (!checkDuplicate(list, size, random)) {
                list[i].crcFlag = random;
                break;
            }
        }
        pthread_mutex_unlock(&mutex);
    }

    // Store list in distributed database system
    storeListInDatabase(pdu, size);

    // Retrieve list from distributed database system and append to list
    retrieveListFromDatabase(pdu, size);
}

// Check if a given CRCFLAG value is already present in the list
bool checkDuplicate(NFAPI_CRC_INDICATION_PDU_T *list, int size, unsigned long crcFlag) {
    int i;
    for (i = 0; i < size; i++) {
        if (list[i].crcFlag == crcFlag) {
            return true;
        }
    }
    return false;
