class AdvancedWebPageManager {
  private $saltRoundCount = 12;
  private $cachedRandomStrings = array();
  private $hashedPassword;

  public function generateSecureRandomString($length) {
    // validate input length and character set
    if (!isset($length) || !is_int($length) || $length < 1) {
      throw new \Exception('Invalid input length');
    }
    $charSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+-={}[]:\'"|';
    // check if the requested length is cached
    if (isset($this->cachedRandomStrings[$length])) {
      return $this->cachedRandomStrings[$length];
    }
    // generate a new random string
    $randomString = '';
    for ($i = 0; $i < $length; $i++) {
      $randomString .= $charSet[mt_rand(0, strlen($charSet) - 1)];
    }
    return $randomString;
  }

  public function hashPassword($password) {
    // validate input password
    if (!isset($password) || !is_string($password)) {
      throw new \Exception('Invalid password');
    }
    $this->hashedPassword = password_hash($password, PASSWORD_BCRYPT, ['cost' => $this->saltRoundCount]);
  }

  public function checkPassword($password) {
    // validate input password
    if (!isset($password) || !is_string($password)) {
      throw new \Exception('Invalid password');
    }
    return password_verify($password, $this->hashedPassword);
  }

  public function validateCharacterSet($characterSet) {
    // validate input character set
    if (!isset($characterSet) || !is_string($characterSet)) {
      throw new \Exception('Invalid character set');
    }
    $charSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+-={}[]:\'"|';
    if (strlen($characterSet) < 4) {
      return false;
    } else if (preg_match('/[A-Z]/', $characterSet) === 0) {
      return false;
    } else if (preg_match('/[a-z]/', $characterSet) === 0) {
      return false;
    } else if (preg_match('/\d/', $characterSet) === 0) {
      return false;
    } else if (preg_match('/[!@#$%^&*()_+-={}[]:\'"|]/', $characterSet) === 0) {
      return false;
    }
    return true;
  }

  public function setSaltRoundCount($rounds) {
    // validate input salt round count
    if (!isset($rounds) || !is_int($rounds) || $rounds < 12 || $rounds > 31) {
      throw new \Exception('Invalid salt round count');
    }
    $this->saltRoundCount = $rounds;
  }

  public function resetPassword() {
    // generate a new random string
    $newRandomString = $this->generateSecureRandomString(32);
    // hash the new password
    $this->hashPassword($newRandomString);
    // invalidate any cached strings of the previous password length
    $this->cachedRandomStrings = array();
  }

