```java
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import com.jcraft.jsch.*;

public class Deployer {
    private final JSch jsch = new JSch();
    private final Session session;
    private final String user;
    private final String host;
    private final int port;
    private final String password;
    private final Map<String, Container> containers = new HashMap<>();
    private final List<Server> servers = new ArrayList<>();

    public Deployer(String host, int port, String user, String password) {
        this.host = host;
        this.port = port;
        this.user = user;
        this.password = password;
        this.session = jsch.getSession(this.user, this.host, this.port);
    }

    public void addContainer(String name, String image) {
        Container container = new Container(name, image);
        containers.put(name, container);
    }

    public void addServer(String host, int port) {
        Server server = new Server(host, port);
        servers.add(server);
    }

    private Session getSession() throws JSchException {
        return jsch.getSession(user, host, port);
    }

    public void deployContainers() throws Exception {
        for (Server server : servers) {
            Container container = containers.get(server.getName());
            if (container == null) {
                continue;
            }
            String command = "docker run --name " + container.getName() + " -e " + container.getEnvironmentVariables().entrySet().stream()
                    .map(e -> e.getKey() + "=" + e.getValue())
                    .collect(Collectors.joining(";"));
            if (server.getVolumeMounts().size() > 0) {
                command += " -v " + server.getVolumeMounts().entrySet().stream()
                        .map(e -> e.getKey() + ":" + e.getValue())
                        .collect(Collectors.joining(";"));
            }
            command += " " + container.getImage();
            Session session = getSession();
            Channel channel = session.openChannel("exec");
            ((ChannelExec)channel).setCommand(command);
            channel.connect();
        }
    }
}

class Container {
    private String name;
    private String image;
    private Map<String, String> environmentVariables = new HashMap<>();

    public Container(String name, String image) {
        this.name = name;
        this.image = image;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getImage() {
        return image;
    }

