    // Generate unique CRCFLAG values for each structure
    int crcflag = 0;
    while (crcflag < 1000000) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu->crcflag = crcflag;
        redis_client_set(client, "crcflags", crcflag, pdu);
        free(pdu);
        crcflag++;
