    }
    if (mysql_real_connect(conn, databaseHost.c_str(), databaseUsername.c_str(), databasePassword.c_str(),
                           databaseName.c_str(), databasePort, nullptr, 0) == nullptr) {
        cerr << "Failed to connect to MySQL database" << endl;
        mysql_close(conn);
        return;
    }

    // Create a prepared statement for inserting transactions
    auto stmt = mysql_stmt_init(conn);
    if (!stmt) {
        cerr << "Failed to initialize MySQL statement" << endl;
        mysql_close(conn);
        return;
    }
    const char* query = "INSERT INTO transactions (account, type, amount) VALUES (?, ?, ?)";
    if (mysql_stmt_prepare(stmt, query, strlen(query)) != 0) {
        cerr << "Failed to prepare MySQL statement" << endl;
        mysql_stmt_close(stmt);
        mysql_close(conn);
        return;
    }

    // Bind and execute the prepared statement for each transaction
    int error = 0;
    while (!error) {
        error = mysql_stmt_bind_param(stmt, transaction.accountNumber.c_str(), transaction.transactionType.c_str(), &transaction.amount);
        if (error != 0) {
            cerr << "Failed to bind MySQL statement parameters" << endl;
            break;
        }
        error = mysql_stmt_execute(stmt);
        if (error != 0) {
            cerr << "Failed to execute MySQL statement" << endl;
            break;
        }
    }
    mysql_stmt_close(stmt);
    mysql_close(conn);
}

// Function for logging transactions to a file
void logToFile(const TransactionData& transaction) {
    // Open the log file in append mode
    fstream logFile;
    logFile.open(logFilePath, ios::app);
    if (!logFile) {
        cerr << "Failed to open log file" << endl;
        return;
    }

    // Write the transaction data to the file
    stringstream ss;
    ss << setfill('0') << setw(4) << right << chrono::duration_cast<chrono::milliseconds>(chrono::system_clock::now().time_since_epoch()).count() << " ";
    ss << transaction.accountNumber << " " << transaction.transactionType << " " << fixed << setprecision(2) << transaction.amount << endl;
    logFile << ss.str();

    // Close the file
    logFile.close();
}

// Function for logging transactions to an external payment processing system
void logToPaymentProcessor(const TransactionData& transaction) {
    // Send a POST request to the payment processor API with the transaction data as JSON payload
    auto client = cpprest::http_client(paymentProcessorUrl);
    json::value body;
    body[L"account"] = utility::conversions::to_string_t(transaction.accountNumber);
    body[L"type"] = utility::conversions::to_string_t(transaction.transactionType);
    body[L"amount"] = transaction.amount;
    auto request = cpprest::http_request();
    request.set_method(cpprest::methods::POST);
    request.set_body(body);
    client.request(request).then([](const web::http::http_response& response) {
        // Handle the API response and log any errors
        if (response.status_code() != 201) {
            cerr << "Failed to process payment with payment processor" << endl;
        } else {
            cout << "Successfully processed payment with payment processor" << endl;
        }
    });
}

// Function for handling transaction recording and logging
void recordTransaction(const TransactionData& transaction) {
    // Cache the transaction for faster processing in the future
    cacheMutex.lock();
    accountCache[transaction.accountNumber].push_back(transaction);
    cv.notify_one();
    cacheMutex.unlock();

    // Log the transaction to the database, file, or external payment processor based on runtime configuration
    switch (getenv("TRANSACTION_LOGGER_MODE")) {
        case "database":
            logToDatabase(transaction);
            break;
        case "file":
            logToFile(transaction);
            break;
        case "payment_processor":
            logToPaymentProcessor(transaction);
            break;
    }
}

// Main function for handling transactions and logging them to the appropriate destination
void processTransaction(const TransactionData& transaction) {
    // Handle failures in database connections, log file write operations, and payment processing system API calls
    int attempts = 0;
    while (attempts < retryAttempts) {
        try {
            recordTransaction(transaction);
            break;
        } catch (const exception& e) {
            ++attempts;
            if (attempts == retryAttempts) {
                cerr << "Failed to process transaction after " << attempts << " retries" << endl;
                return;
            }
            this_thread::sleep_for(chrono::milliseconds(retryDelayMS));
        }
    }
}

// Function for caching transactions and processing them later
void cacheAndProcessTransaction(const TransactionData& transaction) {
    // Cache the transaction for faster processing in the future
    cacheMutex.lock();
    accountCache[transaction.accountNumber].push_back(transaction);
    cv.notify_one();
    cacheMutex.unlock();
}

// Function for retrieving and processing transactions from the cache
void processCachedTransactions() {
    // Loop until there are no more cached transactions
    while (true) {
        // Check if there are any cached transactions
        cacheMutex.lock();
        if (accountCache.empty()) {
            cacheMutex.unlock();
            break;
        }

        // Get the first transaction from the cache and process it
        auto& account = accountCache[0];
        for (const auto& transaction : account) {
            processTransaction(transaction);
        }

        // Remove the processed transactions from the cache
        account.clear();
        if (accountCache.size() == 1) {
            accountCache.erase(accountCache.begin());
        }

        // Notify any waiting threads that there are no more cached transactions
        cv.notify_all();
        cacheMutex.unlock();
    }
}

// Function for handling new transactions and processing them immediately or caching them for later processing
void handleNewTransaction(const TransactionData& transaction) {
    // Check if the transaction is a cached transaction
    cacheMutex.lock();
    if (accountCache.find(transaction.accountNumber) != accountCache.end()) {
        cacheAndProcessTransaction(transaction);
        return;
    }
    cacheMutex.unlock();

    // Process the transaction immediately
    processTransaction(transaction);
}

// Main function for handling new transactions and caching them for later processing
void handleNewTransactions() {
    while (true) {
        // Get the next transaction from the input stream
        TransactionData transaction;
        cin >> transaction.accountNumber >> transaction.transactionType >> transaction.amount;
        if (!cin) {
            break;
        }

        // Handle the transaction and cache it for later processing if necessary
        handleNewTransaction(transaction);
    }
}

// Main function for handling transactions and logging them to the appropriate destination
void main() {
    // Start a thread for handling new transactions immediately
    thread handleTransactionsThread = thread(handleNewTransactions);

    // Start a thread for processing cached transactions later
    thread processCachedTransactionsThread = thread(processCachedTransactions);

    // Wait for the threads to finish
    handleTransactionsThread.join();
    processCachedTransactionsThread.join();
}

