```java
import java.io.IOException;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import com.auth0.jwt.JWTVerifier;
import com.auth0.jwt.algorithms.Algorithm;
import com.auth0.jwt.interfaces.DecodedJWT;
import org.apache.commons.io.FileUtils;

public class JWTProcessor {
  private static final String ISSUER = "https://example.com";
  private static final String AUDIENCE = "example-audience";
  private static final int CACHE_SIZE = 1000; // adjust as needed
  private static final long CACHE_EXPIRY = TimeUnit.MINUTES.toMillis(30); // adjust as needed
  private static final String CONFIG_FILE_PATH = "path/to/config.json";
  private Map<String, DecodedJWT> cache;
  private JWTVerifier verifier;

  public JWTProcessor() {
    cache = new HashMap<>();
    try {
      verifier = Algorithm.HMAC256("secret").build();
    } catch (IOException e) {
      // handle exception
    }
  }

  public void processJWT(String jwt) throws JWTValidationException {
    if (!cache.containsKey(jwt)) {
      DecodedJWT decodedJWT = null;
      try {
        decodedJWT = verifier.verify(jwt);
      } catch (JWTVerificationException e) {
        // handle exception
      }
      if (decodedJWT != null) {
        String username = decodedJWT.getClaim("username").asString();
        List<String> roles = decodedJWT.getClaim("roles").asArray(String.class);
        long expirationTime = decodedJWT.getClaim("exp").asDate().getTime();
        cache.put(jwt, new DecodedJWT(username, roles, expirationTime));
      } else {
        // handle exception
      }
    }
  }

  public void clearCache() {
    cache.clear();
  }
}
