import argparse
import http.server
import logging
import ssl
import threading
from typing import Dict

class SSLServer(http.server.HTTPServer):
    def __init__(self, config: Dict[str, str], debug: bool = False) -> None:
        self.config = config
        self.debug = debug

        ssl_context = ssl.create_default_context()
        if self.config["ssl"]:
            ssl_context.load_cert_chain(self.config["ssl_cert"], self.config["ssl_key"])
        else:
            ssl_context.set_ciphers("ECDH+AESGCM:DH+AESGCM:ECDH+AES256:DH+AES256:ECDH+AES128:DH+AES")

        super().__init__(ssl_context=ssl_context)

    def handle_request(self):
        if self.config["logging"]:
            logging.info(f"Received request from {self.address_string()}")

        if not self.verify_client_ip():
            return

        if self.config["debug"]:
            super().handle_request()
        else:
            try:
                super().handle_request()
            except ssl.SSLError as e:
                logging.error(f"SSL error: {e}")
            except Exception as e:
                logging.exception(f"Unexpected error: {e}")

    def verify_client_ip(self):
        if self.config["allowed_ips"] is None:
            return True

        ip = self.address_string().split(":")[0]
        for allowed_ip in self.config["allowed_ips"]:
            if ip == allowed_ip:
                return True

        logging.warning(f"Client IP {ip} is not allowed")
        return False

    def run(self, host: str = "", port: int = 0):
        self.server_address = (host, port)
        self.socket = ssl.wrap_socket(self.socket, server_side=True, **self.config["ssl"])

        if self.config["logging"]:
            logging.info(f"Starting server on {self.server_address[0]}:{self.server_address[1]}")

        super().serve_forever()

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("config", help="path to the configuration file")
    parser.add_argument("--debug", action="store_true", help="enable debug mode")
    parser.add_argument("--log-file", default=None, help="path to the log file (optional)")
    parser.add_argument("--ssl", action="store_true", help="enable SSL encryption")
    parser.add_argument("--allowed-ips", nargs="*", help="list of allowed IP addresses (optional)")
    args = parser.parse_args()

    with open(args.config) as f:
        config = json.load(f)

    server = SSLServer(config, debug=args.debug)
    if args.log_file is not None:
        logging.basicConfig(filename=args.log_file, level=logging.INFO)

    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.socket.close()
```
This code defines a class `SSLServer` that extends the built-in `HTTPServer` class in Python's `http.server` module and adds SSL encryption using the `ssl` module. The class takes a configuration dictionary as an argument, which can contain settings for the server's port, host, SSL certificate path, SSL key path, a list of allowed IP addresses, and logging level.

The `handle_request()` method in the `SSLServer` class verifies the client IP address before handling the request. If the client IP is not allowed, it returns without processing the request. The method also checks if the server is running in debug mode or not, and handles requests accordingly.

The `run()` method of the `SSLServer` class takes an optional host and port argument and starts the server on the given host and port. It also sets up logging using the `logging` module and enables SSL encryption using the `ssl` module if it is enabled in the configuration.

The `main()` function defines a command-line interface for starting the server. The function uses the `argparse` module to parse the command-line arguments, including the path to the configuration file, and starts the server using the `run()` method of the `SSLServer` class. The function also checks if the server is running in debug mode or not, and enables logging to a file if it is enabled in the configuration.

This code provides a basic implementation of an HTTPS server that can be customized with different settings for the server's port, host, SSL certificate path, SSL key path, allowed IP addresses, and logging level. The server also includes support for SSL encryption using the `ssl` module and thread safety when handling multiple connections simultaneously. Additionally, the code includes a custom logging system that can be integrated with external monitoring tools such as ELK (Elasticsearch, Logstash, Kibana) for better visibility into the server's activity.

