```php
<?php

// AuthenticateUser function
function authenticateUser($username, $password) {
    // Validate input parameters
    if (!$username || !$password) {
        return array("error" => "Invalid username or password");
    }

    // Check if user is already logged in
    if (isset($_SESSION['user'])) {
        return array("error" => "User is already logged in");
    }

    // Authenticate with IDP
    $auth_url = 'https://idp.example.com/oauth2/token';
    $client_id = 'your-client-id';
    $client_secret = 'your-client-secret';

    $data = array(
        "grant_type" => "password",
        "username" => $username,
        "password" => $password,
        "client_id" => $client_id,
        "client_secret" => $client_secret,
    );

    $options = array(
        'http' => array(
            'method' => 'POST',
            'content' => http_build_query($data),
            'header' => 'Content-Type: application/x-www-form-urlencoded'
        )
    );

    $context = stream_context_create($options);
    $response = file_get_contents($auth_url, false, $context);

    // Validate response and store access token in session variable
    if ($response === false) {
        return array("error" => "Failed to connect to IDP");
    } else {
        $response = json_decode($response);
        if (!$response->access_token) {
            return array("error" => "Invalid username or password");
        } else {
            $_SESSION['user'] = $username;
            $_SESSION['accessToken'] = $response->access_token;
            return array("success" => true);
        }
    }
}

// UpdateClinicStatus function
function updateClinicStatus($clinicId, $status) {
    // Validate input parameters
    if (!$clinicId || !$status) {
        return array("error" => "Invalid clinic ID or status");
    }

    // Connect to database and retrieve clinic data
    try {
        $db = new PDO('mysql:host=localhost;dbname=your-database', 'username', 'password');
        $stmt = $db->prepare("SELECT * FROM clinics WHERE id = :id");
        $stmt->execute(array(':id' => $clinicId));
        $row = $stmt->fetch();
    } catch (PDOException $e) {
        return array("error" => "Failed to connect to database: " . $e->getMessage());
    }

    // Update clinic status and last modified data
    if ($row) {
        try {
            $db->beginTransaction();
            $stmt = $db->prepare("UPDATE clinics SET status = :status, last_modified_ip = :last_modified_ip, last_modified_date = NOW() WHERE id = :id");
            $stmt->execute(array(':status' => $status, ':last_modified_ip' => $_SERVER['REMOTE_ADDR'], ':id' => $clinicId));
            $db->commit();
        } catch (PDOException $e) {
            $db->rollBack();
            return array("error" => "Failed to update clinic status: " . $e->getMessage());
        }
    } else {
        return array("error" => "Clinic ID not found");
    }
}

// CalculateFileHash function
function calculateFileHash($filePath) {
    // Validate input parameter
    if (!$filePath) {
        return array("error" => "Invalid file path");
    }

    // Read file in chunks to manage memory usage effectively
    $chunkSize = 1024 * 1024; // 1 MB
    $hash = hash_init('sha256');
    $fp = fopen($filePath, 'rb');
    while (!feof($fp)) {
        $data = fread($fp, $chunkSize);
        if ($data === false) {
            break;
        }
        hash_update($hash, $data);
    }
    fclose($fp);

    // Calculate final file hash and return result
    return array("success" => true, "fileHash" => hash_final($hash));
}
```
