            printf("%s: %s\n", hash_function->name, "Not Supported");
        }
    }

    // Gracefully handle edge cases such as duplicate algorithm names, unsupported configurations, and missing dependencies by providing appropriate error messages and fallback mechanisms
    if (check_duplicate_algorithms(sclib)) {
        printf("Error: Duplicate algorithms found in configuration file\n");
        return;
