        public static async Task<object> ReduceAsync(IEnumerable<XmlDocument> documents, object initialValue, Func<object, object, object> accumulator, Func<object, object, bool> comparator, int? concurrency = null, int? throttleRate = null, TimeSpan? timeout = null, Action<int, object> progressCallback = null)
