}

void sendMessages(std::shared_ptr<MessagingService> service, const Messages &messages) {
    service->sendMessages(messages);
}

Response sendRequests(const std::vector<Request> &requests) {
    Response response;
    for (auto request : requests) {
        auto service = getMessagingService(request.second); // get MessagingService for recipient
        if (service != nullptr) {
            response[request] = service->sendRequests({request});
        }
    }
    return response;
}

// Helper Functions
