    if (recipient == "Twilio") {
        return std::make_shared<TwilioMessagingService>(ACCOUNT_SID, AUTH_TOKEN);
    } else if (recipient == "Slack") {
        return std::make_shared<SlackMessagingService>(TOKEN);
    }
