// JWT处理类
class JwtHandler {
  constructor() {
    this.jwksUri = null;
    this.issuer = null;
  }

  async init(options) {
    // 初始化JWKs URI和发行人
    const { jwksUri, issuer } = options;
    this.jwksUri = jwksUri;
    this.issuer = issuer;
  }

  async validateToken(token) {
    // 验证JWT中的发行人和受众声明
    const decoded = jwt.decode(token);
    if (!decoded || !decoded.iss || !decoded.aud) {
      throw new Error('Invalid JWT token');
    }

    if (this.issuer !== decoded.iss) {
      throw new Error(`Invalid issuer: ${decoded.iss}`);
    }

    // 验证JWT签名
    const jwk = await this.fetchJWK(decoded.header.kid);
    if (!jwk) {
      throw new Error('Failed to fetch JWK');
    }

    try {
      const result = jwt.verify(token, jwk.publicKey, {
        algorithms: ['RS256'],
        issuer: this.issuer,
        audience: decoded.aud
      });
      return result;
    } catch (err) {
      throw new Error('Invalid JWT token');
    }
  }

  async fetchJWK(kid) {
    // 获取JWKs URI中的JWK
    const jwks = await this.fetchJWKS();
    return jwks[kid];
  }

  async fetchJWKS() {
    // 获取JWKS URI中的JSON Web Key集合
    try {
      const response = await axios.get(this.jwksUri);
      const jwks = response.data;
      return jwks;
    } catch (err) {
      throw new Error('Failed to fetch JWKS');
    }
  }
}

