// Function for converting images to a PDF
int convertImagesToPDF(const char *input_dir, const char *output_dir, const char *pattern) {
    // Check if input directory and file names are valid
    if (!isValidInputDirectory(input_dir)) {
        return -1;
    }

    // List all matching image files in the input directory based on the provided pattern
    struct Image images[MAX_IMAGES];
    int num_images = listImages(input_dir, pattern, images);
    if (num_images <= 0) {
        return -1;
    }

    // Create a single PDF file containing all images in the specified order
    struct PDF pdf = createPDF(output_dir, DEFAULT_DPI);
    if (!pdf.path) {
        return -1;
    }

    // Implement a progress callback mechanism to inform the user of the conversion status
    printf("Converting images to PDF...\n");

