    int num_threads = MIN(MAX_THREADS, num_images);
    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; ++i) {
        struct Image *image = &images[i];
        struct PDF *pdf = &pdfs[i];
        pthread_create(&threads[i], NULL, convertImageToPDF, image);
    }

    // Join all threads and handle any errors from the third-party tool gracefully
    for (int i = 0; i < num_threads; ++i) {
        struct Image *image = &images[i];
        struct PDF *pdf = &pdfs[i];
        pthread_join(threads[i], NULL);
        if (!pdf->path) {
            free(image);
            return -1;
        }
    }

    // Implement a caching mechanism to store intermediate results and reduce redundant processing
    struct Image *cache = malloc(sizeof(struct Image) * num_images);
    for (int i = 0; i < num_threads; ++i) {
        struct Image *image = &images[i];
        struct PDF *pdf = &pdfs[i];
        cache[i] = *image;
        free(pdf->path);
    }

    // Use dynamic resizing of the output PDF to fit all images without overlapping, maintaining aspect ratios
    resizePDF(output_dir, pdf.path, num_images, num_threads);

    // Log any errors that occurred during the conversion process
    for (int i = 0; i < num_threads; ++i) {
        struct Image *image = &cache[i];
        if (image->error) {
            printf("Error converting image %s: %s\n", image->path, image->error);
        }
    }

    // Clean up any resources allocated during the conversion process and return the PDF path
    free(cache);
    return pdf.path;
}

// Function for updating a user's password in a MySQL database
int updateUserPassword(const char *username, const char *new_password) {
    // Check if new password meets the validation criteria
    if (!isValidPassword(new_password)) {
        return -1;
    }

    // Ensure that username and new password cannot contain any part of the username
    if (strstr(username, new_password) || strstr(new_password, username)) {
        return -1;
    }

    // Use a DAO class to update the user's password in the MySQL database
    struct UserDAO *dao = createUserDAO();
    if (!dao->updatePassword(username, new_password)) {
        free(dao);
        return -1;
    }

    // Log all password update attempts, including success and failure, with timestamps, IP addresses, and user agent information
    struct PasswordUpdateAttempt attempt = {
        .username = username,
        .new_password = new_password,
        .timestamp = getCurrentTimestamp(),
        .ip_address = getClientIPAddress(),
        .user_agent = getClientUserAgent()
    };
    logPasswordUpdateAttempt(attempt);

    // Handle concurrent password updates efficiently using appropriate mechanisms to manage database connections and avoid race conditions
    int num_retries = 0;
    while (!dao->updatePassword(username, new_password)) {
        if (num_retries >= MAX_RETRIES) {
            free(dao);
            return -1;
        }
        ++num_retries;
        delayForRetry();
    }

    // Clean up any resources allocated during the password update process and return success
    free(dao);
    return 0;
}
