        params = source["params"] if "params" in source else {}

        try:
            response = await self._make_request(url, method, headers=headers, params=params)
            data = response.json()
            self._merge_data(source, data)
        except requests.RequestException as e:
            logger.error(f"Error fetching data from {source['name']}: {e}")

    async def _make_request(self, url, method, headers=None, params=None):
