    private String type;

    public Pokemon(String name, String type) {
        this.name = name;
        this.type = type;
    }

    public String getName() {
        return name;
    }

    public String getType() {
        return type;
    }
}

public class PokemonWeaknessChecker {
    public static PokemonWeaknessResult getWeaknesses(Pokemon pokemon, String directoryPath) {
        // Check if the web.config file exists in the provided directory path
        File configFile = new File(directoryPath + "/web.config");
        boolean webConfigExists = configFile.exists();

        // Return null if the web.config file does not exist
        if (!webConfigExists) {
            return new PokemonWeaknessResult(false, null, "Web config file does not exist.");
        }

        // Use a switch statement to determine the weaknesses of the Pokemon based on its type
        List<String> weaknesses = new ArrayList<>();
        switch (pokemon.getType()) {
            case "Fire":
                weaknesses.add("Water");
                break;
            case "Water":
                weaknesses.add("Fire");
                break;
            case "Grass":
                weaknesses.add("Poison");
                break;
            case "Poison":
                weaknesses.add("Grass");
                break;
            default:
                // Handle other types as needed
        }

        return new PokemonWeaknessResult(webConfigExists, weaknesses, null);
    }
}
