import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;

import java.io.IOException;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;

public class JSONParser {
    private static final Logger logger = Logger.getLogger(JSONParser.class.getName());

    // Cache for storing previously parsed results
    private static Map<String, ObjectNode> cache = new ConcurrentHashMap<>();

    // Maximum size of the cache in megabytes
    private static int cacheSizeInMB = 10;

    /**
     * Parses and extracts data from a JSON document using the Jackson library.
     * Supports nested structures and allows for extracting multiple levels of child nodes.
     * @param jsonPath The JSON path to query
     * @param json The JSON document to parse
     * @return The extracted data as a Java object
     */
    public static ObjectNode parse(String jsonPath, String json) {
        // Check if the cache already contains the result for this JSON path
        ObjectNode cachedResult = cache.get(jsonPath);
        if (cachedResult != null) {
            logger.info("Cache hit for JSON path: " + jsonPath);
            return cachedResult;
        } else {
            logger.info("Cache miss for JSON path: " + jsonPath);
        }

        ObjectNode result = null;
        try {
            // Parse the JSON document using Jackson library
            JsonNode rootNode = new ObjectMapper().readTree(json);

            // Traverse the JSON tree to extract the data at the specified path
            result = (ObjectNode) rootNode.at(jsonPath).traverse();

            if (result == null) {
                // Handle no data found for this JSON path
                logger.warning("No data found for JSON path: " + jsonPath);
            } else if (result.size() > 1) {
                // Handle multiple matching nodes for this JSON path
                logger.warning("Multiple matching nodes found for JSON path: " + jsonPath);
            }

        } catch (IOException e) {
            // Handle exceptions gracefully
            logger.severe("Error parsing JSON document: " + e.getMessage());
        }

        // Add the result to the cache if it is not null and the cache size has not reached its limit
        if (result != null && cache.size() < cacheSizeInMB) {
            cache.put(jsonPath, result);
            logger.info("Added result for JSON path: " + jsonPath + " to cache");
        } else {
            logger.warning("Cache size reached its limit or result is null. Not adding to cache.");
        }

        return result;
    }

