    public CloudStorageClient() {
        this.httpClient = new OkHttpClient.Builder()
                .connectionPool(new ConnectionPool(MAX_CONNECTIONS, CONNECTION_TIMEOUT, READ_TIMEOUT, WRITE_TIMEOUT))
                .build();
        this.mapper = new ObjectMapper();
