import requests
from typing import List
from concurrent.futures import ThreadPoolExecutor

class RiskAssessmentModule:
    def __init__(self):
        self.risk_api_urls = [
            "https://api1.example.com",
            "https://api2.example.com",
            "https://api3.example.com"
        ]

    def get_risks(self, product: dict) -> List[dict]:
        """
        Evaluates potential risks for a given product based on its categories, prices, and quantities.
        Returns a list of dictionaries with risk information.
        """
        # Try to fetch risks from each API in parallel
        with ThreadPoolExecutor(max_workers=len(self.risk_api_urls)) as executor:
            future_risks = [
                executor.submit(self._fetch_risks, api_url, product) for api_url in self.risk_api_urls
            ]
            risks = []
            for future_risk in future_risks:
                try:
                    risks += future_risk.result()
                except Exception as e:
                    print(f"API call failed: {e}")

        # Handle API failures and ensure data consistency and integrity
        if not risks:
            return None

        # Combine risk information from multiple APIs
        combined_risks = {}
        for risk in risks:
            for key, value in risk.items():
                if key not in combined_risks:
                    combined_risks[key] = value
                else:
                    combined_risks[key] += value

        return list(combined_risks.values())

    def _fetch_risks(self, api_url: str, product: dict) -> List[dict]:
        """
        Fetches potential risks for a given product from an external risk assessment API.
        Returns a list of dictionaries with risk information.
        """
        # Send request to API and parse response
        try:
            response = requests.get(api_url, params=product)
            if response.status_code == 200:
                return response.json()
            else:
                print(f"API call failed with status code {response.status_code}")
                return None
        except Exception as e:
            print(f"API call failed: {e}")
            return None
