// Structure to hold information about a CRC flag and its associated data
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T crc; // CRC flag structure
    void *data; // Data associated with the CRC flag
} crc_flag_t;

// List of all CRC flags and their associated data
static crc_flag_t *flags = NULL;

// Mutex for synchronizing access to the list of CRC flags
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to generate a unique CRC flag value
unsigned int generateCrcFlag() {
    unsigned int crc = 0;
    for (int i = 0; i < 32; i++) {
        if (rand() % 2) {
            crc |= 1 << i;
        } else {
            crc &= ~(1 << i);
        }
    }
    return crc;
}

// Function to update the CRC flags in the list based on the rules defined in the configuration file
void updateCrcFlags() {
    FILE *file = fopen(CONFIG_FILE, "r");
    if (!file) {
        perror("Error opening configuration file");
        return;
    }
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Skip comments and blank lines
        if (line[0] == '#' || line[0] == '\n') {
            continue;
        }
        // Extract the CRC flag value and the associated data from the line
        char *token = strtok(line, " ");
        unsigned int crc = atoi(token);
        token = strtok(NULL, " ");
        void *data = (void *)atoi(token);
        // Update the CRC flag in the list if it exists
        for (int i = 0; i < MAX_STRUCTURES; i++) {
            if (flags[i].crc.crc == crc) {
                flags[i].data = data;
                break;
            }
        }
    }
    fclose(file);
}

