```java
import java.io.*;
import java.nio.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class SocketServer {
    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final ConcurrentHashMap<SocketChannel, String> connections = new ConcurrentHashMap<>();

    public void handleConnection(SocketChannel channel) throws IOException {
        // Handle incoming connection
        System.out.println("New connection from " + channel.getRemoteAddress());
        executor.submit(() -> {
            try {
                // Read data from the socket
                ByteBuffer buffer = ByteBuffer.allocate(1024);
                while (channel.read(buffer) > 0) {
                    buffer.flip();
                    String message = new String(buffer.array(), "UTF-8");
                    System.out.println("Received message: " + message);
                    buffer.clear();
                }
                // Close the socket channel
                channel.close();
            } catch (IOException e) {
                // Handle exception
                e.printStackTrace();
            }
        });
    }
}
