```cpp
#include <iostream>
#include <forward_list>
#include <string>
#include <chrono>

void insertStringAfter(std::forward_list<std::string>& list, const std::string& before, const std::string& after) {
    // Find the first occurrence of the first string argument in the forward list
    auto it = list.begin();
    while (it != list.end()) {
        if (*it == before) {
            break;
        }
        ++it;
    }
    if (it == list.end()) {
        // Insert the second string argument at the end of the forward list if the first string argument is not found
        list.push_front(after);
    } else {
        // Insert the second string argument after the first string argument in the forward list
        list.insert_after(it, after);
    }
}
