```python
import uuid
import hashlib
from datetime import datetime
from urllib.parse import unquote
from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
from flask_jwt import JWTManager

app = Flask(__name__)
app.config["SQLALCHEMY_DATABASE_URI"] = "sqlite:///resources.db"
app.config["JWT_SECRET_KEY"] = "your-secret-key"
db = SQLAlchemy(app)
jwt = JWTManager(app)

class Resource(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    uuid = db.Column(db.String(36), nullable=False, unique=True)
    version = db.Column(db.Integer, default=0)
    updated_at = db.Column(db.DateTime, default=datetime.utcnow)
    data = db.Column(db.String, nullable=False)

class FileHash(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    file_path = db.Column(db.String, nullable=False)
    hash = db.Column(db.String, nullable=False)
    updated_at = db.Column(db.DateTime, default=datetime.utcnow)

@app.route("/resources", methods=["POST"])
def create_resource():
    data = request.get_json()
    uuid = str(uuid.uuid4())
    version = 0
    updated_at = datetime.utcnow()
    resource = Resource(uuid=uuid, version=version, updated_at=updated_at, data=data)
    db.session.add(resource)
    db.session.commit()
    return jsonify({"id": resource.id})

@app.route("/resources/<int:id>", methods=["PUT"])
def update_resource(id):
    data = request.get_json()
    resource = Resource.query.get(id)
    if not resource:
        return jsonify({"error": "Resource does not exist"}), 404
    version = resource.version + 1
    updated_at = datetime.utcnow()
    resource.data = data
    resource.version = version
    resource.updated_at = updated_at
    db.session.commit()
    return jsonify({"id": id, "version": version})

@app.route("/resources/<int:id>", methods=["GET"])
def get_resource(id):
    resource = Resource.query.get(id)
    if not resource:
        return jsonify({"error": "Resource does not exist"}), 404
    return jsonify({"id": id, "version": resource.version, "data": resource.data})

@app.route("/resources/<int:id>", methods=["DELETE"])
def delete_resource(id):
    resource = Resource.query.get(id)
    if not resource:
        return jsonify({"error": "Resource does not exist"}), 404
    db.session.delete(resource)
    db.session.commit()
    return jsonify({"message": "Resource deleted successfully"})

@app.route("/files/<path:file_path>", methods=["GET"])
def get_file(file_path):
    file_path = unquote(file_path)
    try:
        with open(file_path, "rb") as f:
            return jsonify({"data": f.read()})
    except FileNotFoundError:
        return jsonify({"error": "File does not exist"}), 404

@app.route("/files/<path:file_path>", methods=["PUT"])
def update_file(file_path):
    file_path = unquote(file_path)
    data = request.get_json()
    try:
        with open(file_path, "wb") as f:
            f.write(data)
        return jsonify({"message": "File updated successfully"}), 201
    except FileNotFoundError:
        return jsonify({"error": "File does not exist"}), 404
    except IOError:
        return jsonify({"error": "Failed to update file"}), 500

@app.route("/files/<path:file_path>/hash", methods=["GET"])
def get_file_hash(file_path):
    file_path = unquote(file_path)
    try:
        with open(file_path, "rb") as f:
            hash = hashlib.md5(f.read()).hexdigest()
            return jsonify({"hash": hash})
    except FileNotFoundError:
        return jsonify({"error": "File does not exist"}), 404

@app.route("/files/<path:file_path>/hash", methods=["PUT"])
def update_file_hash(file_path):
    file_path = unquote(file_path)
    data = request.get_json()
    try:
        with open(file_path, "wb") as f:
            f.write(data)
        return jsonify({"message": "File updated successfully"}), 201
    except FileNotFoundError:
        return jsonify({"error": "File does not exist"}), 404
    except IOError:
        return jsonify({"error": "Failed to update file"}), 500
