import requests
from datetime import datetime, timedelta

# Set up caching mechanism
cache = {}
cache_time = 10  # minutes

def get_weather(location):
    """Fetch current weather data for a given location"""
    # Check if the location is in the cache
    if location in cache:
        # Return cached data if it's still valid
        if datetime.now() - cache[location]["time"] < timedelta(minutes=cache_time):
            return cache[location]["data"]

    # Fetch new data from the weather API if not in the cache or cache is expired
    api_url = f"https://api.openweathermap.org/data/2.5/weather?q={location}&appid=YOUR_API_KEY"
    response = requests.get(api_url)
    data = response.json()

    # Store new data in the cache
    cache[location] = {
        "time": datetime.now(),
        "data": data,
    }

    return data
