#include <fcntl.h>
#include <errno.h>

// Global variables
static int aes_enabled = 0;
static int camellia_enabled = 0;
static int md5_enabled = 0;
static int sha1_enabled = 0;
static int sha256_enabled = 0;
static pthread_rwlock_t lock;
static ENGINE* engine = NULL;
static EVP_PKEY_CTX *pctx = NULL;
static EVP_PKEY *pkey = NULL;
static unsigned char key[32] = {0};

// Function prototypes
void init_engine();
int add_cipher(const char* name);
int remove_cipher(const char* name);
int is_cipher_available(const char* name);
int encrypt(const unsigned char* data, const size_t len);
int decrypt(const unsigned char* data, const size_t len);
int generate_key();
void cleanup();

// Main function
int main(int argc, char** argv) {
  // Initialize the engine and key context
  init_engine();
  pctx = EVP_PKEY_CTX_new(pkey, NULL);

  // Check for command-line arguments
  if (argc > 1) {
    char* cmd = argv[1];
    if (!strcmp(cmd, "add")) {
      const char* name = argv[2];
      add_cipher(name);
    } else if (!strcmp(cmd, "remove")) {
      const char* name = argv[2];
      remove_cipher(name);
    } else if (!strcmp(cmd, "encrypt")) {
      const unsigned char* data = (const unsigned char*)argv[2];
      size_t len = strlen(data);
      encrypt(data, len);
    } else if (!strcmp(cmd, "decrypt")) {
      const unsigned char* data = (const unsigned char*)argv[2];
      size_t len = strlen(data);
      decrypt(data, len);
    }
  }

  // Clean up resources and exit
  cleanup();
  return 0;
}

// Initialize the engine and key context
void init_engine() {
  // Load the OpenSSL library
  SSL_load_error_strings();
  ERR_load_BIO_strings();
  SSL_library_init();

  // Set up the engine
  ENGINE* engine = ENGINE_by_id("dynamic");
  if (engine == NULL) {
    printf("Failed to load dynamic engine\n");
    return;
  }

  // Load the cryptographic modules
  add_cipher("aes-128-cbc");
  add_cipher("aes-192-cbc");
  add_cipher("aes-256-cbc");
  add_cipher("camellia-128-cbc");
  add_cipher("camellia-192-cbc");
  add_cipher("camellia-256-cbc");
  add_cipher("md5");
  add_cipher("sha1");
  add_cipher("sha256");

  // Set the engine as the default
  if (ENGINE_set_default(engine, ENGINE_METHOD_ALL) == 0) {
    printf("Failed to set default engine\n");
    return;
  }
}

// Add a cipher to the library
int add_cipher(const char* name) {
  // Check if the cipher is already available
  if (is_cipher_available(name)) {
    printf("Cipher %s is already available\n", name);
    return -1;
  }

  // Get the EVP context for the new cipher
  EVP_PKEY_CTX* ctx = NULL;
  if (EVP_PKEY_CTX_new(pkey, &ctx) == 0) {
    printf("Failed to create EVP context\n");
    return -1;
  }

  // Set the cipher and key length for the new cipher
  if (EVP_PKEY_CTX_ctrl(ctx, -1, EVP_PKEY_OP_ENCRYPT, EVP_PKEY_CTRL_CIPHER, strlen(name), name) == 0) {
    printf("Failed to set cipher %s\n", name);
    return -1;
  }

  // Generate a new key for the new cipher
  if (generate_key() == -1) {
    printf("Failed to generate key for cipher %s\n", name);
    return -1;
  }

  // Add the new cipher to the library
  pctx = EVP_PKEY_CTX_new(pkey, NULL);
  if (pctx == NULL) {
    printf("Failed to create EVP context\n");
    return -1;
  }

  // Set the new cipher as the default
  if (ENGINE_set_default(engine, ENGINE_METHOD_ALL) == 0) {
    printf("Failed to set default engine\n");
    return -1;
  }

  return 0;
}

// Remove a cipher from the library
int remove_cipher(const char* name) {
  // Check if the cipher is already available
  if (!is_cipher_available(name)) {
    printf("Cipher %s is not available\n", name);
    return -1;
  }

  // Get the EVP context for the new cipher
  EVP_PKEY_CTX* ctx = NULL;
  if (EVP_PKEY_CTX_new(pkey, &ctx) == 0) {
    printf("Failed to create EVP context\n");
    return -1;
  }

  // Set the cipher and key length for the new cipher
  if (EVP_PKEY_CTX_ctrl(ctx, -1, EVP_PKEY_OP_ENCRYPT, EVP_PKEY_CTRL_CIPHER, strlen(name), name) == 0) {
    printf("Failed to set cipher %s\n", name);
    return -1;
  }

  // Remove the new cipher from the library
  pctx = EVP_PKEY_CTX_new(pkey, NULL);
  if (pctx == NULL) {
    printf("Failed to create EVP context\n");
    return -1;
  }

  // Set the new cipher as the default
  if (ENGINE_set_default(engine, ENGINE_METHOD_ALL) == 0) {
    printf("Failed to set default engine\n");
    return -1;
  }

  return 0;
}

// Check if a cipher is available in the library
int is_cipher_available(const char* name) {
  // Get the EVP context for the new cipher
  EVP_PKEY_CTX* ctx = NULL;
  if (EVP_PKEY_CTX_new(pkey, &ctx) == 0) {
    printf("Failed to create EVP context\n");
    return -1;
  }

  // Set the cipher and key length for the new cipher
  if (EVP_PKEY_CTX_ctrl(ctx, -1, EVP_PKEY_OP_ENCRYPT, EVP_PKEY_CTRL_CIPHER, strlen(name), name) == 0) {
    printf("Failed to set cipher %s\n", name);
    return -1;
  }

  // Check if the new cipher is available
  int available = 0;
  if (EVP_PKEY_CTX_ctrl(ctx, -1, EVP_PKEY_OP_ENCRYPT, EVP_PKEY_CTRL_IS_SETUP, 0, &available) == 0) {
    printf("Failed to check if cipher is available\n");
    return -1;
  }

  // Return the result of the check
  if (available == 1) {
    return 1;
  } else {
    return 0;
  }
}

// Encrypt data using a cipher in the library
int encrypt(const unsigned char* data, const size_t len) {
  // Check if the cipher is available
  if (!is_cipher_available("aes-128-cbc")) {
    printf("Cipher not available\n");
    return -1;
  }

  // Get the EVP context for the new cipher
  EVP_PKEY_CTX* ctx = NULL;
  if (EVP_PKEY_CTX_new(pkey, &ctx) == 0) {
    printf("Failed to create EVP context\n");
    return -1;
  }

  // Set the cipher and key length for the new cipher
  if (EVP_PKEY_CTX_ctrl(ctx, -1, EVP_PKEY_OP_ENCRYPT, EVP_PKEY_CTRL_CIPHER, strlen("aes-128-cbc"), "aes-128-cbc") == 0) {
    printf("Failed to set cipher\n");
    return -1;
  }

  // Set the key and iv for the new cipher
  if (EVP_PKEY_CTX_ctrl(ctx, -1, EVP_PKEY_OP_ENCRYPT, EVP_PKEY_CTRL_SET_IV, 0, "key") == 0) {
    printf("Failed to set key\n");
    return -1;
  }

  // Encrypt the data
  int outlen = 0;
  unsigned char* out = NULL;
  if (EVP_PKEY_CTX_ctrl(ctx, -1, EVP_PKEY_OP_ENCRYPT, EVP_PKEY_CTRL_ENCRYPT, len, data, &outlen, &out) == 0) {
    printf("Failed to encrypt data\n");
    return -1;
  }

  // Return the encrypted data
  return outlen;
}

// Decrypt data using a cipher in the library
int decrypt(const unsigned char* data, const size_t len) {
  // Check if the cipher is available
  if (!is_cipher_available("aes-128-cbc")) {
    printf("Cipher not available\n");
    return -1;
  }

  // Get the EVP context for the new cipher
  EVP_PKEY_CTX* ctx = NULL;
  if (EVP_PKEY_CTX_new(pkey, &ctx) == 0) {
    printf("Failed to create EVP context\n");
    return -1;
  }

  // Set the cipher and key length for the new cipher
  if (EVP_PKEY_CTX_ctrl(ctx, -1, EVP_PKEY_OP_DECRYPT, EVP_PKEY_CTRL_CIPHER, strlen("aes-128-cbc"), "aes-128-cbc") == 0) {
    printf("Failed to set cipher\n");
    return -1;
  }

  // Set the key and iv for the new cipher
  if (EVP_PKEY_CTX_ctrl(ctx, -1, EVP_PKEY_OP_DECRYPT, EVP_PKEY_CTRL_SET_IV, 0, "key") == 0) {
    printf("Failed to set key\n");
    return -1;
  }

  // Decrypt the data
  int outlen = 0;
  unsigned char* out = NULL;
  if (EVP_PKEY_CTX_ctrl(ctx, -1, EVP_PKEY_OP_DECRYPT, EVP_PKEY_CTRL_ENCRYPT, len, data, &outlen, &out) == 0) {
    printf("Failed to decrypt data\n");
    return -1;
  }

  // Return the decrypted data
  return outlen;
}

