// Function to insert a string after the first occurrence of another string in a list of strings
void insertStringAfter(forwardList* list, const char* searchString, const char* insertString) {
    // Find the index of the first occurrence of searchString in the list
    int index = findFirstIndexOf(list, searchString);

    // If searchString is not found, insert insertString at the end of the list
    if (index == -1) {
        appendToEnd(list, insertString);
    } else {
        // Insert insertString after searchString in the list
        insertIntoList(list, index + 1, insertString);
    }
}

// Function to find the first occurrence of a string in a list of strings
int findFirstIndexOf(forwardList* list, const char* searchString) {
    for (int i = 0; i < list->size; i++) {
        if (strcmp(list->data[i], searchString) == 0) {
            return i;
        }
    }
    // If searchString is not found, return -1
    return -1;
}

// Function to append a string to the end of a list of strings
void appendToEnd(forwardList* list, const char* string) {
    int newSize = list->size + 1;

    // Reallocate memory for the list if necessary
    if (newSize > list->capacity) {
        list->data = realloc(list->data, newSize * sizeof(char*));
        list->capacity = newSize;
    }

    // Copy the contents of string to a new node in the list
    char* node = malloc(sizeof(char*) + strlen(string) + 1);
    strcpy(node, string);
    list->data[list->size++] = node;
}

// Function to insert a string into a list of strings at a specific index
void insertIntoList(forwardList* list, int index, const char* string) {
    // Check if the index is out of bounds
    if (index < 0 || index > list->size) {
        printf("Error: Index %d out of bounds\n", index);
        return;
    }

    // Reallocate memory for the list if necessary
    int newSize = list->size + 1;
    if (newSize > list->capacity) {
        list->data = realloc(list->data, newSize * sizeof(char*));
        list->capacity = newSize;
    }

    // Move the contents of the list to make room for the new node
    for (int i = list->size - 1; i >= index; i--) {
        list->data[i + 1] = list->data[i];
    }

    // Copy the contents of string to a new node in the list
    char* node = malloc(sizeof(char*) + strlen(string) + 1);
    strcpy(node, string);
    list->data[index] = node;
}

int main(int argc, char* argv[]) {
    // Check if the user has provided any command line arguments
    if (argc < 2) {
        printf("Usage: %s [input file]\n", argv[0]);
        return 1;
    }

    // Open the input file and read its contents
    FILE* inputFile = fopen(argv[1], "r");
    if (inputFile == NULL) {
        printf("Error: Could not open input file\n");
        return 1;
    }

    // Create a list to store the lines of the input file
    forwardList* lineList = createEmptyList();

    // Read each line of the input file and add it to the list
    char buffer[BUFSIZ];
    while (fgets(buffer, BUFSIZ, inputFile) != NULL) {
        insertIntoList(lineList, -1, buffer);
    }

    // Close the input file
    fclose(inputFile);

    // Process each line of the list and perform the desired action
    for (int i = 0; i < lineList->size; i++) {
        char* line = lineList->data[i];

        // Check if the line is a command to insert a string after another string in the list
        if (strncmp(line, "insert", 6) == 0) {
            // Find the first occurrence of the second argument in the list
            const char* searchString = strchr(line, ' ');
            while (*searchString != '\n' && *searchString != '\0') {
                searchString++;
            }

            // Insert the third argument after the second argument in the list
            const char* insertString = strchr(searchString, ' ');
            while (*insertString != '\n' && *insertString != '\0') {
                insertString++;
            }
            insertStringAfter(lineList, searchString, insertString);
        } else if (strncmp(line, "compress", 8) == 0) {
            // Compress the contents of the list into a single string
            char* compressedLine = compressLines(lineList);

            // Write the compressed line to the output file
            FILE* outputFile = fopen("output.txt", "w");
            fprintf(outputFile, "%s\n", compressedLine);
            fclose(outputFile);
        } else if (strncmp(line, "decompress", 10) == 0) {
            // Decompress the contents of the list into a single string
            char* decompressedLine = decompressLines(lineList);

            // Write the decompressed line to the output file
            FILE* outputFile = fopen("output.txt", "w");
            fprintf(outputFile, "%s\n", decompressedLine);
            fclose(outputFile);
        } else {
            // If the line is not a command, print an error message
            printf("Error: Invalid command\n");
        }
    }

    // Free the memory used by the list
    freeList(lineList);

    return 0;
}

// Function to create an empty list of strings
forwardList* createEmptyList() {
    forwardList* list = malloc(sizeof(forwardList));
    list->size = 0;
    list->capacity = 1;
    list->data = malloc(list->capacity * sizeof(char*));

    return list;
}

// Function to free the memory used by a list of strings
void freeList(forwardList* list) {
    for (int i = 0; i < list->size; i++) {
        free(list->data[i]);
    }

    free(list->data);
    free(list);
}

// Function to compress the contents of a list of strings into a single string
char* compressLines(forwardList* lineList) {
    // Create a buffer to store the compressed data
    char* buffer = malloc(1024 * sizeof(char));

    // Compress each line of the list and add it to the buffer
    for (int i = 0; i < lineList->size; i++) {
        char* line = lineList->data[i];
        size_t lineLength = strlen(line);

        // Add the length of the line to the buffer
        int bytesWritten = snprintf(buffer, 1024, "%lu", lineLength);
        buffer += bytesWritten;

        // Copy the line to the buffer
        memcpy(buffer, line, lineLength * sizeof(char));
        buffer += lineLength;
    }

    // Add a null terminator to the end of the buffer
    *buffer = '\0';

    return buffer;
}

// Function to decompress the contents of a list of strings into a single string
char* decompressLines(forwardList* lineList) {
    // Create a buffer to store the decompressed data
    char* buffer = malloc(1024 * sizeof(char));

    // Decompress each line of the list and add it to the buffer
    for (int i = 0; i < lineList->size; i++) {
        char* line = lineList->data[i];

        // Get the length of the line from the buffer
        size_t lineLength = strtol(line, NULL, 10);

        // Copy the line to the buffer
        memcpy(buffer, line, lineLength * sizeof(char));
        buffer += lineLength;
    }

    // Add a null terminator to the end of the buffer
    *buffer = '\0';

    return buffer;
}
