#include <forward_list>
#include <string>
#include <iostream>
#include <stdexcept>
#include <mutex>

using namespace std;

// Forward list of strings to be searched
forward_list<string> searchList;

// Mutex for thread safety
mutex mtx;

void updateSearchList(const forward_list<string>& list, const string& searchString, const string& updateString) {
    // Lock the mutex before updating the list
    lock_guard<mutex> lck(mtx);

    // Find the first occurrence of the search string in the list
    auto iter = find(list.begin(), list.end(), searchString);

    // If the search string is not found, append the update string to the end of the list
    if (iter == list.end()) {
        searchList.push_back(updateString);
    } else {
        // Insert the update string after the first occurrence of the search string in the list
        iter = next(iter);
        searchList.insert_after(iter, updateString);
    }
}

int main() {
    // Initialize the forward list with some sample strings
    searchList.push_back("apple");
    searchList.push_back("banana");
    searchList.push_back("cherry");

    // Update the list with a new string
    updateSearchList(searchList, "orange", "new fruit");

    // Print the updated list
    for (const auto& str : searchList) {
        cout << str << endl;
    }

    return 0;
}
```
