class Weakness {
    private String name;
    private int strength;
    private List<String> associatedMoves;

    public Weakness(String name, int strength, List<String> associatedMoves) {
        this.name = name;
        this.strength = strength;
        this.associatedMoves = associatedMoves;
    }

    public String getName() {
        return name;
    }

    public int getStrength() {
        return strength;
    }

    public List<String> getAssociatedMoves() {
        return associatedMoves;
    }
}

class WeaknessManager {
    private static final int MAX_RETRY_ATTEMPTS = 3;
    private static final long BACKOFF_DELAY_MILLIS = TimeUnit.SECONDS.toMillis(5);

    private MoSTState state;
    private DatabaseConnection database;
    private PokemonAPI api;

    public WeaknessManager(MoSTState state, DatabaseConnection database, PokemonAPI api) {
        this.state = state;
        this.database = database;
        this.api = api;
    }

    public List<Weakness> getWeaknessesForPokemon(String pokemonName) {
        try {
            // Retry the API call up to 3 times if it fails due to network issues or temporary unavailability.
            for (int attempt = 0; attempt < MAX_RETRY_ATTEMPTS; attempt++) {
                List<Weakness> weaknesses = getWeaknessesForPokemonFromAPI(pokemonName);
                if (weaknesses != null) {
                    return weaknesses;
                } else {
                    TimeUnit.MILLISECONDS.sleep(BACKOFF_DELAY_MILLIS);
                }
            }
        } catch (InterruptedException e) {
            // TODO: Handle the exception more gracefully.
        }
        return null;
    }

    private List<Weakness> getWeaknessesForPokemonFromAPI(String pokemonName) {
        String type = api.getPokemonType(pokemonName);
        switch (type) {
            case "fire":
                return List.of(new Weakness("water", 2, List.of("Hydro Pump")));
            case "water":
                return List.of(new Weakness("fire", 2, List.of("Flamethrower")));
            case "grass":
                return List.of(new Weakness("ground", 1, List.of()));
            case "electric":
                return List.of(new Weakness("steel", 2, List.of()));
            default:
                return null;
        }
    }
}
