package com.example.jsonconfig;

import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Level;
import java.util.logging.Logger;

public class JsonConfigManager {
    private static final Logger LOGGER = Logger.getLogger(JsonConfigManager.class.getName());
    private static final int MAX_CONCURRENT_REQUESTS = 100;
    private static final long CACHE_EXPIRATION_TIME = 30 * 60 * 1000; // 30 minutes

    private ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();

    public void fetchConfig(String configId) {
        if (cache.containsKey(configId)) {
            LOGGER.log(Level.INFO, "Fetching JSON configuration from cache");
            return;
        }

        // Fetch JSON configuration from external data source
        String json = fetchFromCMDB(configId);

        if (json != null) {
            cache.put(configId, json);
            LOGGER.log(Level.INFO, "Fetched JSON configuration from CMDB and added to cache");
        } else {
            LOGGER.log(Level.WARNING, "Failed to fetch JSON configuration from CMDB");
        }
    }

    public void applyConfig(String configId) {
        if (!cache.containsKey(configId)) {
            LOGGER.log(Level.WARNING, "Configuration with ID '" + configId + "' is not in the cache");
            return;
        }

        // Apply JSON configuration to application instance
        applyConfigToInstance(configId);
    }

    private String fetchFromCMDB(String configId) {
        // Fetch JSON configuration from CMDB using REST API
        try {
            return HttpClient.get("http://cmdb/api/v1/configs/" + configId, null);
        } catch (IOException e) {
            LOGGER.log(Level.WARNING, "Failed to fetch JSON configuration from CMDB", e);
            return null;
        }
    }

    private void applyConfigToInstance(String configId) {
        // Apply JSON configuration to application instance using REST API
        try {
            HttpClient.post("http://instance/api/v1/configs/" + configId, cache.get(configId));
        } catch (IOException e) {
            LOGGER.log(Level.WARNING, "Failed to apply JSON configuration to application instance", e);
        }
    }
}
