char* loadAndExecuteJSFiles(const char* base_filename, const char* js_files[], int num_files) {
    // Initialize variables
    char* filename = NULL;
    size_t filename_len = 0;
    int i = 0;

    // Check if the input is valid
    if (base_filename == NULL || js_files == NULL || num_files <= 0) {
        fprintf(stderr, "Invalid input provided\n");
        return NULL;
    }

    // Get the filename length
    filename_len = strlen(base_filename);

    // Loop through each JS file and load/execute it
    for (i = 0; i < num_files; i++) {
        char* js_file = js_files[i];
        if (js_file == NULL) continue;

        // Append the filename to the base filename
        filename = realloc(filename, filename_len + strlen(js_file) + 1);
        if (filename == NULL) {
            fprintf(stderr, "Error allocating memory for new filename\n");
            return NULL;
        }
        strcat(filename, js_file);

        // Load and execute the JS file in the context of a web page
        // ... (code to load and execute the JS file)
    }

    // Return the dynamically allocated string containing the new filename
    return filename;
}
