```
// Bible Text Analyzer

class BibleTextAnalyzer {
  // Regular expressions for identifying books in the Bible
  static OLD_TESTAMENT_BOOKS = /(?:Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1 Samuel|2 Samuel|1 Kings|2 Kings|1 Chronicles|2 Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)/i;
  static NEW_TESTAMENT_BOOKS = /(?:Matthew|Mark|Luke|John|Acts|Romans|1 Corinthians|2 Corinthians|Galatians|Ephesians|Philippians|Colossians|1 Thessalonians|2 Thessalonians|1 Timothy|2 Timothy|Titus|Philemon|Hebrews|James|1 Peter|2 Peter|1 John|2 John|3 John|Jude|Revelation)/i;

  // Exclude books not found in either the Old or New Testament
  static EXCLUDED_BOOKS = /(?:Psalms|Ecclesiastes|Song of Solomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)/i;

  // Caching mechanism to store previously analyzed texts and their results
  static cache = {};

  // Function to identify and extract the names of books from a given string of text
  static extractBooks(text) {
    // Ignore any punctuation or special characters in the input text
    text = text.replace(/[^\w\s]/g, '');

    // Match whole words only (ignore case sensitivity)
    let books = text.match(this.OLD_TESTAMENT_BOOKS);
    if (!books) {
      books = text.match(this.NEW_TESTAMENT_BOOKS);
    }

    // Exclude books not found in either the Old or New Testament
    books = books.filter((book) => !this.EXCLUDED_BOOKS.test(book));

    return books;
  }

  // Function to categorize the extracted books into their respective Testaments
  static categorizeBooks(books) {
    let oldTestament = [], newTestament = [];
    books.forEach((book) => {
      if (this.OLD_TESTAMENT_BOOKS.test(book)) {
        oldTestament.push(book);
      } else if (this.NEW_TESTAMENT_BOOKS.test(book)) {
        newTestament.push(book);
      }
    });
    return [oldTestament, newTestament];
  }

  // Function to generate reports based on the analysis
  static generateReports() {
    let mostFrequentBooks = [];
    let frequencyByBook = {};
    this.cache.forEach((value, key) => {
      value.books.forEach((book) => {
        if (!frequencyByBook[book]) {
          frequencyByBook[book] = 0;
        }
        frequencyByBook[book]++;
      });
    });
    mostFrequentBooks = Object.keys(frequencyByBook).sort((a, b) => frequencyByBook[b] - frequencyByBook[a]);

    return {
      mostFrequentBooks: mostFrequentBooks,
      frequencyByBook: frequencyByBook,
    };
  }
}

// Function to run tests asynchronously and log information to the console
async function runTests(moduleLabel, testLabels, testFunctions) {
  const mockingLibrary = require('blueslip');

  // Load the module using the `require` function
  const module = require(moduleLabel);

  // Run each test asynchronously and handle failures during testing
  for (let i = 0; i < testLabels.length; i++) {
    try {
      await testFunctions[i](module);
      console.log(`Test passed: ${testLabels[i]}`);
    } catch (error) {
      console.error(`Test failed: ${testLabels[i]}:`, error);
    } finally {
      // Reset the mocking library to maintain test isolation
      mockingLibrary.reset();
    }
  }

  // Ensure proper cleanup even in the presence of errors
  console.log(`All tests completed for ${moduleLabel}`);
}
```
