```
import argparse
import json
import logging
import os
from pathlib import Path
from typing import Dict, Optional

from aiohttp.web import Application, AppRunner, HttpServer
from aiohttp.client import ClientSession
from aiohttp.log import access_logger


class ServerConfig:
    def __init__(self, config: Dict[str, str]):
        self.config = config

    @property
    def port(self) -> int:
        return int(self.config["port"])

    @property
    def host(self) -> str:
        return self.config["host"]

    @property
    def log_file_path(self) -> Optional[str]:
        if "log_file_path" in self.config:
            return self.config["log_file_path"]
        else:
            return None

    @property
    def ssl_certificate_path(self) -> Optional[str]:
        if "ssl_certificate_path" in self.config:
            return self.config["ssl_certificate_path"]
        else:
            return None


class Server:
    def __init__(self, config: ServerConfig):
        self.config = config
        self.server = HttpServer(host=config.host, port=config.port)

    async def start(self):
        runner = AppRunner(self.server)
        await runner.setup()
        site = Site(runner, self.server)
        self.app = Application(site)
        if self.config.ssl_certificate_path:
            ssl_context = SSLContext(PROTOCOL_TLSv1_2)
            ssl_context.load_cert_chain(self.config.ssl_certificate_path, keyfile=None)
            self.app["runner"].update(["--ssl-context", ssl_context])
        await self.app.start()
        access_logger.setLevel(logging.INFO)
        access_logger.addFilter("server")

    async def stop(self):
        await self.app.stop()


class Site:
    def __init__(self, runner: AppRunner, server: HttpServer):
        self.runner = runner
        self.server = server

    async def __call__(self, request: aiohttp.web.Request):
        pass  # add your logic here


class SSLContext(ssl.SSLContext):
    def __init__(self, protocol=None):
        super().__init__(protocol or PROTOCOL_TLSv1_2)
        self._ctx = ssl.create_default_context()

    def load_cert_chain(self, certfile: str, keyfile: Optional[str] = None) -> None:
        with open(certfile, "rb") as f:
            cert_data = f.read()
        with open(keyfile or certfile, "rb") as f:
            key_data = f.read()
        self._ctx.load_cert_chain(cert_data, key_data)

    def wrap_socket(self, sock: socket, server_side=False, server_hostname=None):
        return ssl.wrap_socket(sock, self._ctx, server_side, server_hostname)


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--config", type=str, help="Path to the configuration JSON file")
    args = parser.parse_args()

    if not os.path.isfile(args.config):
        logging.error(f"Configuration file '{args.config}' does not exist!")
        sys.exit(1)

    with open(args.config, "r") as f:
        config = json.load(f)

    server_config = ServerConfig(config)
    server = Server(server_config)

    try:
        await server.start()
    except Exception as e:
        logging.error(f"Error starting server: {e}")
        sys.exit(1)
```
