from pathlib import Path
import hashlib
import os
import threading
import time

class FileAggregator:
    def __init__(self, config):
        self.config = config
        self.services = {}
        for service in config["services"]:
            self.services[service] = self._get_service(service)
        self.checksums = {}

    def _get_service(self, service_name):
        if service_name == "AWS S3":
            return AWS()
        elif service_name == "Google Cloud Storage":
            return GCS()
        elif service_name == "Azure Blob Storage":
            return ABS()
        else:
            raise ValueError(f"Invalid service name: {service_name}")

    def add_file(self, filepath):
        filename = Path(filepath).name
        if self.config["checksum"]:
            hash_algorithm = self.config["hash_algorithm"]
            checksum = hashlib.new(hash_algorithm)
            with open(filepath, "rb") as f:
                while True:
                    data = f.read(1024 * 1024)
                    if not data:
                        break
                    checksum.update(data)
            checksum_value = checksum.hexdigest()
        else:
            checksum_value = None
        for service in self.services:
            try:
                self.services[service].upload_file(filepath, filename)
                if checksum_value is not None:
                    self.checksums[filename] = checksum_value
            except Exception as e:
                print(f"Error uploading file to {service}: {e}")

    def get_files(self):
        files = []
        for service in self.services:
            try:
                files += self.services[service].get_files()
            except Exception as e:
                print(f"Error getting files from {service}: {e}")
        if self.config["checksum"]:
            return [(filename, checksum) for filename, checksum in self.checksums.items()]
        else:
            return files

