typedef struct {
    int *array;
    size_t length;
} ArrayData;

typedef struct {
    int result;
    bool is_finalized;
    pthread_mutex_t mutex;
} ReductionResult;

// callback function for asynchronous array reduction
void asyncArrayReduce(ArrayData *array_data, size_t offset, size_t length, void *result) {
    ReductionResult *reduction_result = (ReductionResult *)result;
    int sum = 0;
    for (int i = 0; i < length; i++) {
        if (array_data->array[offset + i] != NULL) {
            sum += array_data->array[offset + i];
        }
    }
    pthread_mutex_lock(&reduction_result->mutex);
    reduction_result->result = sum;
    reduction_result->is_finalized = true;
    pthread_mutex_unlock(&reduction_result->mutex);
}

// validate and log async function
void validate_and_log_async(Password *password, Connection *connection, void (*callback)(int)) {
    // check that the password is not empty or NULL
