public void UpdateUserConfig(int userId, string configName, object newValue)
{
    // Check if the configuration exists in the database
    bool configExists = DoesConfigurationExist(configName);

    // If the configuration does not exist, create it
    if (!configExists)
    {
        CreateConfiguration(userId, configName, newValue);
    }
    else
    {
        // Update the existing configuration value
        UpdateConfiguration(userId, configName, newValue);
    }

    // Check if the configuration is a theme bitmap and if it needs to be recycled
    bool isThemeBitmap = IsThemeBitmap(configName);
    bool shouldRecycle = ShouldRecycleThemeBitmap(newValue);

    // If the configuration is a theme bitmap and needs to be recycled, recycle it
    if (isThemeBitmap && shouldRecycle)
    {
        RecycleThemeBitmap();
    }

    // Check if the configuration value is null and if it needs to be set to null
    bool isNullValue = IsNullValue(newValue);
    bool shouldSetToNull = ShouldSetToNull(configName, newValue);

    // If the configuration value is null and needs to be set to null, set it to null
    if (isNullValue && shouldSetToNull)
    {
        SetConfigurationToNull(userId, configName);
    }

    // Check for concurrent access and update the configuration value safely
    lock (_lockObject)
    {
        // Update the configuration value in the database
        UpdateDatabaseConfiguration(userId, configName, newValue);

        // Update the cached theme bitmap if necessary
        if (isThemeBitmap && shouldRecycle)
        {
            RecycleCachedThemeBitmap();
        }

        // Update the cached configuration value if necessary
        if (!isNullValue && !shouldSetToNull)
        {
            UpdateCachedConfiguration(userId, configName, newValue);
        }
    }
}
