#include <openssl/rsa.h>
#include <openssl/pem.h>
#include <openssl/err.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <dirent.h>
#include <unistd.h>
#include <pthread.h>

// Define a structure to hold information about an image file
typedef struct {
    char *path; // path to the image file
    int dpi; // DPI for the converted image within the PDF
} ImageFile;

// Define a structure to hold information about a thread
typedef struct {
    pthread_t tid; // thread ID
    ImageFile *imageFile; // pointer to an image file
} ThreadData;

// Function to convert an image file to a PDF page
int convertImageToPDF(ImageFile *imageFile) {
    // Initialize variables
    int ret = 0;
    FILE *fpIn = NULL, *fpOut = NULL;
    char *pathIn = imageFile->path;
    char pathOut[256];
    sprintf(pathOut, "%s.pdf", pathIn);

    // Open the input and output files
    fpIn = fopen(pathIn, "rb");
    if (!fpIn) {
        perror("fopen");
        return -1;
    }
    fpOut = fopen(pathOut, "wb");
    if (!fpOut) {
        perror("fopen");
        fclose(fpIn);
        return -1;
    }

    // Convert the image to a PDF page
    ret = convertImageToPDFPage(fpIn, fpOut, imageFile->dpi);
    if (ret) {
        perror("convertImageToPDFPage");
    }

    // Close the input and output files
    fclose(fpIn);
    fclose(fpOut);

    return ret;
}

// Function to convert an image file to a PDF page, using OpenSSL for RSA encryption/decryption
int convertImageToPDFPage(FILE *fpIn, FILE *fpOut, int dpi) {
    // Initialize variables
    int ret = 0;
    unsigned char *encryptedData = NULL;
    size_t encryptedLen = 0;
    RSA *rsa = NULL;
    BIO *bioMem = NULL;
    PKCS7 *p7 = NULL;
    PKCS12 *p12 = NULL;

    // Load the private key and create an RSA context for encryption/decryption
    p12 = d2i_PKCS12_fp(fpIn, NULL);
    if (!p12) {
        printf("Error: unable to load PKCS12 file\n");
        return -1;
    }
    rsa = EVP_PKEY_get1_RSA(PKCS12_get_privatekey(p12));
    if (!rsa) {
        printf("Error: unable to extract RSA key from PKCS12 file\n");
        return -1;
    }

    // Encrypt the image data using RSA encryption
    encryptedData = RSA_public_encrypt(0, NULL, rsa, RSA_PKCS1_OAEP_PADDING);
    if (!encryptedData) {
        printf("Error: unable to encrypt image data\n");
        return -1;
    }

    // Create a PKCS7 structure for the encrypted data
    p7 = PKCS7_new();
    if (!p7) {
        printf("Error: unable to create new PKCS7 structure\n");
        return -1;
    }
    ret = PKCS7_set_type(p7, NID_pkcs7_data);
    if (ret <= 0) {
        printf("Error: unable to set type of PKCS7 structure\n");
        return -1;
    }
    ret = PKCS7_set_content(p7, encryptedData, encryptedLen);
    if (ret <= 0) {
        printf("Error: unable to set content of PKCS7 structure\n");
        return -1;
    }

    // Free the RSA context and BIO memory
    EVP_PKEY_free(rsa);
    rsa = NULL;
    BIO_free_all(bioMem);
    bioMem = NULL;

    // Create a new BIO memory for the encrypted PKCS7 data
    bioMem = BIO_new(BIO_s_mem());
    if (!bioMem) {
        printf("Error: unable to create new BIO memory\n");
        return -1;
    }

    // Write the encrypted PKCS7 data to the BIO memory
    ret = i2d_PKCS7_bio(bioMem, p7);
    if (ret <= 0) {
        printf("Error: unable to write encrypted PKCS7 data to BIO memory\n");
        return -1;
    }

    // Create a new PDF document
    pdfDoc = pdf_doc_new();
    if (!pdfDoc) {
        printf("Error: unable to create new PDF document\n");
        return -1;
    }

    // Add the encrypted PKCS7 data as a page in the PDF document
    pdfPage = pdf_page_create(pdfDoc);
    if (!pdfPage) {
        printf("Error: unable to create new PDF page\n");
        return -1;
    }
    ret = pdf_doc_add_page(pdfDoc, pdfPage);
    if (ret < 0) {
        printf("Error: unable to add encrypted PKCS7 data as a page in the PDF document\n");
        return -1;
    }

    // Free the BIO memory and PDF document
    BIO_free_all(bioMem);
    bioMem = NULL;
    pdf_doc_free(pdfDoc);
    pdfDoc = NULL;

    return 0;
}

// Function to list all matching image files in a directory based on a provided pattern, case-insensitively
int listImages(char *dirPath, char *pattern) {
    // Initialize variables
    int ret = 0;
    struct dirent *entry = NULL;
    DIR *dir = NULL;
    ImageFile *imageFiles = NULL;
    size_t numImageFiles = 0;
    size_t i = 0;

    // Open the directory
    dir = opendir(dirPath);
    if (!dir) {
        perror("opendir");
        return -1;
    }

    // Read each entry in the directory and check if it matches the pattern
    while ((entry = readdir(dir))) {
        char *path = NULL;
        path = dirPath + strlen(dirPath) + 1;
        if (strcasestr(entry->d_name, pattern)) {
            imageFiles[numImageFiles].path = path;
            numImageFiles++;
        }
    }

    // Close the directory
    closedir(dir);
    dir = NULL;

    return ret;
}

// Function to convert a PDF document into an encrypted PKCS7 structure
int pdfToEncryptedPkcs7(char *pdfPath, char *encryptionPassword) {
    // Initialize variables
    int ret = 0;
    struct pdf_doc *pdfDoc = NULL;
    struct pdf_page *pdfPage = NULL;
    struct d2i_pkcs12_fp *p12File = NULL;
    struct evp_pkey *evpPkey = NULL;
    struct rsa_st *rsaKey = NULL;
    struct bio_st *bioMem = NULL;
    size_t encryptedDataLen = 0;
    unsigned char *encryptedData = NULL;
    struct pkcs7_st *pkcs7 = NULL;

    // Load the PDF document
    pdfDoc = pdf_doc_new();
    if (!pdfDoc) {
        printf("Error: unable to create new PDF document\n");
        return -1;
    }
    ret = pdf_doc_load(pdfDoc, pdfPath);
    if (ret < 0) {
        printf("Error: unable to load PDF document\n");
        return -1;
    }

    // Get the first page of the PDF document
    pdfPage = pdf_doc_get_page(pdfDoc, 0);
    if (!pdfPage) {
        printf("Error: unable to get first page of PDF document\n");
        return -1;
    }

    // Encrypt the content of the page using AES encryption
    ret = pdf_page_encrypt(pdfDoc, pdfPage, encryptionPassword);
    if (ret < 0) {
        printf("Error: unable to encrypt PDF page\n");
        return -1;
    }

    // Create a new PKCS7 structure for the encrypted data
    pkcs7 = PKCS7_new();
    if (!pkcs7) {
        printf("Error: unable to create new PKCS7 structure\n");
        return -1;
    }
    ret = PKCS7_set_type(pkcs7, NID_pkcs7_data);
    if (ret <= 0) {
        printf("Error: unable to set type of PKCS7 structure\n");
        return -1;
    }
    ret = PKCS7_set_content(pkcs7, NULL, 0);
    if (ret <= 0) {
        printf("Error: unable to set content of PKCS7 structure\n");
        return -1;
    }

    // Free the PDF document and page
    pdf_doc_free(pdfDoc);
    pdfDoc = NULL;
    pdf_page_free(pdfPage);
    pdfPage = NULL;

    // Return the encrypted PKCS7 structure
    return pkcs7;
}

// Function to write an encrypted PKCS7 structure to a file
int writeEncryptedPkcs7ToFile(struct pkcs7_st *pkcs7, char *outputPath) {
    // Initialize variables
    int ret = 0;
    struct bio_st *bioMem = NULL;
    FILE *file = NULL;

    // Create a new BIO memory for the encrypted PKCS7 data
    bioMem = BIO_new(BIO_s_mem());
    if (!bioMem) {
        printf("Error: unable to create new BIO memory\n");
        return -1;
    }

    // Write the encrypted PKCS7 data to the BIO memory
    ret = i2d_PKCS7_bio(bioMem, pkcs7);
    if (ret <= 0) {
        printf("Error: unable to write encrypted PKCS7 data to BIO memory\n");
        return -1;
    }

    // Open the output file
    file = fopen(outputPath, "wb");
    if (!file) {
        perror("fopen");
        return -1;
    }

    // Write the encrypted PKCS7 data to the output file
    ret = BIO_write(bioMem, file);
    if (ret <= 0) {
        printf("Error: unable to write encrypted PKCS7 data to output file\n");
        return -1;
    }

    // Close the output file
    fclose(file);
    file = NULL;

    // Return success
    return ret;
}

int main() {
  char *encryptionPassword = "password";
  char *pdfPath = "input.pdf";
  char *outputPath = "output.p7s";

  // Convert the PDF document into an encrypted PKCS7 structure
  struct pkcs7_st *pkcs7 = pdfToEncryptedPkcs7(pdfPath, encryptionPassword);
  if (!pkcs7) {
    printf("Error: unable to convert PDF document into encrypted PKCS7 structure\n");
    return -1;
  }

  // Write the encrypted PKCS7 structure to a file
  int ret = writeEncryptedPkcs7ToFile(pkcs7, outputPath);
  if (ret < 0) {
    printf("Error: unable to write encrypted PKCS7 data to output file\n");
    return -1;
  }

  // Free the memory allocated for the PKCS7 structure
  PKCS7_free(pkcs7);

  return ret;
}

