import java.util.Random;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.client.methods.HttpGet;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.json.JSONObject;

public class ServiceManager {
  private static final String SERVICE_BASE_URL = "https://external-service-api.com/";
  private static final int MIN_DELAY = 1000; // Minimum delay between service operations (in ms)
  private static final int MAX_DELAY = 30000; // Maximum delay between service operations (in ms)
  private static final int RETRY_ATTEMPTS = 3; // Number of retries for each operation before giving up
  private static final int HEALTH_CHECK_INTERVAL = 10; // Health check interval in minutes
  private static final int MAX_INSTANCES = 50; // Maximum number of service instances to manage
  private static final boolean USE_GEOMETRIC_DELAYS = true; // Use geometric delays for fairness and load balancing
  private static final ExecutorService executor = Executors.newFixedThreadPool(MAX_INSTANCES); // Thread pool for managing service instances
  private static final List<ServiceInstance> instances = new ArrayList<>(); // List of managed service instances
  private static final Map<String, ServiceStatus> statuses = new HashMap<>(); // Status map for each service instance
  private static final CloseableHttpClient httpClient = HttpClients.createDefault(); // HTTP client for making requests to the external API
  private static final Random random = new Random(); // Random object for generating delays and retry intervals

  public static void main(String[] args) {
    initServiceInstances();
    startMonitoringThreads();
    executor.shutdown();
  }

  private static void initServiceInstances() {
    instances.clear();
    for (int i = 0; i < MAX_INSTANCES; i++) {
      ServiceInstance instance = new ServiceInstance(i);
      instances.add(instance);
      statuses.put(instance.getName(), new ServiceStatus());
    }
  }

  private static void startMonitoringThreads() {
    for (ServiceInstance instance : instances) {
      executor.submit(() -> monitorService(instance));
    }
  }

  private static void monitorService(ServiceInstance instance) {
    while (!executor.isShutdown()) {
      try {
        startService(instance);
        Thread.sleep(randomDelay());
        stopService(instance);
        Thread.sleep(randomDelay());
        checkHealth(instance);
      } catch (InterruptedException e) {
        // Handle interrupt exception
      }
    }
  }

  private static void startService(ServiceInstance instance) throws InterruptedException {
    System.out.println("Starting service " + instance.getName());
    HttpGet request = new HttpGet(SERVICE_BASE_URL + "/start");
    CloseableHttpResponse response = httpClient.execute(request);
    int statusCode = response.getStatusLine().getStatusCode();
    if (statusCode != 200) {
      System.out.println("Error starting service " + instance.getName() + ": " + statusCode);
      return;
    }
    JSONObject json = new JSONObject(EntityUtils.toString(response.getEntity()));
    instance.setStarted(true);
    statuses.put(instance.getName(), new ServiceStatus(json));
  }

  private static void stopService(ServiceInstance instance) throws InterruptedException {
    System.out.println("Stopping service " + instance.getName());
    HttpGet request = new HttpGet(SERVICE_BASE_URL + "/stop");
    CloseableHttpResponse response = httpClient.execute(request);
    int statusCode = response.getStatusLine().getStatusCode();
    if (statusCode != 200) {
      System.out.println("Error stopping service " + instance.getName() + ": " + statusCode);
      return;
    }
    JSONObject json = new JSONObject(EntityUtils.toString(response.getEntity()));
    instance.setStarted(false);
    statuses.put(instance.getName(), new ServiceStatus(json));
  }

  private static void checkHealth(ServiceInstance instance) throws InterruptedException {
    System.out.println("Checking health of service " + instance.getName());
    HttpGet request = new HttpGet(SERVICE_BASE_URL + "/health");
    CloseableHttpResponse response = httpClient.execute(request);
    int statusCode = response.getStatusLine().getStatusCode();
    if (statusCode != 200) {
      System.out.println("Error checking health of service " + instance.getName() + ": " + statusCode);
      return;
    }
    JSONObject json = new JSONObject(EntityUtils.toString(response.getEntity()));
    ServiceStatus status = new ServiceStatus(json);
    if (status.isHealthy()) {
      System.out.println("Service " + instance.getName() + " is healthy");
      statuses.put(instance.getName(), status);
    } else {
      System.out.println("Service " + instance.getName() + " is unhealthy");
    }
  }

  private static int randomDelay() {
    if (USE_GEOMETRIC_DELAYS) {
      return (int) Math.round(MIN_DELAY * Math.pow(2, random.nextInt(RETRY_ATTEMPTS - 1)));
    } else {
      return random.nextInt(MAX_DELAY - MIN_DELAY + 1) + MIN_DELAY;
    }
  }
}

