```
// DynamicXmlTransactionHandler.cpp
#include "DynamicXmlTransactionHandler.h"

DynamicXmlTransactionHandler::DynamicXmlTransactionHandler(const std::string& xmlDocumentPath) :
        xmlDocumentPath_(xmlDocumentPath), cacheSize_(0), initialized_(false) {}

DynamicXmlTransactionHandler::~DynamicXmlTransactionHandler() {
    if (initialized_) {
        std::lock_guard<std::mutex> lock(mutex_);
        parsedDocuments_.clear();
    }
}

void DynamicXmlTransactionHandler::initialize() {
    if (!initialized_) {
        std::lock_guard<std::mutex> lock(mutex_);
        initialized_ = true;
        parseAndCacheXmlDocuments();
    }
}

void DynamicXmlTransactionHandler::parseAndCacheXmlDocuments(size_t maxSize) {
    if (maxSize == 0 || parsedDocuments_.size() < maxSize) {
        std::ifstream xmlFile(xmlDocumentPath_, std::ios::binary);
        if (!xmlFile.is_open()) {
            throw std::runtime_error("Failed to open XML document: " + xmlDocumentPath_);
        }

        // Parse the XML document using libxml2
        xmlDocPtr doc = xmlReadMemory(xmlFile.rdbuf(), xmlFile.gcount());
        if (!doc) {
            throw std::runtime_error("Failed to parse XML document: " + xmlDocumentPath_);
        }

        // Cache the parsed document
        auto document = std::make_shared<XmlDocument>(doc);
        parsedDocuments_.emplace(xmlDocumentPath_, std::vector<std::shared_ptr<xmlNode>>{document});
    }
}

std::shared_ptr<xmlNode> DynamicXmlTransactionHandler::getFirstElementByName(const std::string& elementName, const std::string& documentPath) const {
    if (!initialized_) {
        throw std::runtime_error("DynamicXmlTransactionHandler is not initialized");
    }

    std::lock_guard<std::mutex> lock(mutex_);
    auto it = parsedDocuments_.find(documentPath);
    if (it == parsedDocuments_.end()) {
        throw std::runtime_error("Failed to find XML document: " + documentPath);
    }

    // Use XPath queries to get the first element with the specified name
    xmlXPathContextPtr xpathCtx = xmlXPathNewContext(it->second[0]->doc());
    if (!xpathCtx) {
        throw std::runtime_error("Failed to create XPath context");
    }

    xmlXPathObjectPtr result = xmlXPathEvalExpression(reinterpret_cast<const xmlChar*>(elementName.c_str()), xpathCtx);
    if (!result) {
        throw std::runtime_error("Failed to evaluate XPath expression: " + elementName);
    }

    // Check if the result is an empty set
    if (xmlXPathNodeSetIsEmpty(result->nodesetval)) {
        xmlXPathFreeObject(result);
        throw std::runtime_error("No elements found with name: " + elementName);
    }

    // Get the first element from the result set
    auto node = xmlXPathNodeSetItem(result->nodesetval, 0);
    if (!node) {
        xmlXPathFreeObject(result);
        throw std::runtime_error("Failed to get element from XPath result");
    }

    // Create a shared pointer to the XML node
    auto element = std::make_shared<xmlNode>(node);
    xmlXPathFreeObject(result);

    return element;
}

void DynamicXmlTransactionHandler::handleTransactionEvent(const TransactionEvent& transactionEvent) {
    // Implement handling of transaction events here
}

void DynamicXmlTransactionHandler::setCacheSize(size_t cacheSize) {
    if (cacheSize == 0) {
        throw std::runtime_error("Invalid cache size");
    }

    std::lock_guard<std::mutex> lock(mutex_);
    cacheSize_ = cacheSize;
}

size_t DynamicXmlTransactionHandler::getCacheSize() const {
    return cacheSize_;
}

bool DynamicXmlTransactionHandler::isInitialized() const {
    return initialized_;
}
