using System.Runtime.Serialization.Formatters.Binary;
using Newtonsoft.Json;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Configuration;

public class DataLoader
{
    private readonly ILogger<DataLoader> _logger;
    private readonly IConfiguration _configuration;

    public DataLoader(ILogger<DataLoader> logger, IConfiguration configuration)
    {
        _logger = logger;
        _configuration = configuration;
    }

    public async Task<object> LoadAsync(string filePath)
    {
        var deserializer = GetDeserializer();

        try
        {
            using (var stream = new FileStream(filePath, FileMode.Open))
            {
                return await deserializer.DeserializeAsync(stream);
            }
        }
        catch (FileNotFoundException ex)
        {
            _logger.LogError(ex, "Data file not found");
            throw;
        }
        catch (IOException ex)
        {
            _logger.LogError(ex, "Data file is corrupt or inaccessible");
            throw;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while deserializing the data");
            throw;
        }
    }

    private IDeserializer GetDeserializer()
    {
        var serializationFormat = _configuration["SerializationFormat"];
        switch (serializationFormat)
        {
            case "BinaryFormatter":
                return new BinaryFormatter();
            case "JSON":
                return new Newtonsoft.Json.JsonSerializer();
            default:
                throw new NotSupportedException($"Serialization format '{serializationFormat}' is not supported");
        }
    }
}
