// Define a function for handling rate limiting
const handleRateLimiting = async (req, res, next) => {
  // Acquire the semaphore to prevent concurrent processing
  await semaphore.acquire();

  try {
    // Check if the request has exceeded the rate limit
    const rateLimitExceeded = checkRateLimit(req);

    // If the rate limit has been exceeded, return an error message
    if (rateLimitExceeded) {
      return res.status(429).json({ message: 'Rate limit exceeded' });
    }

    // Release the semaphore to allow other requests to process
    await semaphore.release();
  } catch (err) {
    console.error('Error handling rate limiting:', err);
    return res.status(500).send('Internal server error');
  }
};

