  // Acquire the semaphore to prevent concurrent processing
  await semaphore.acquire();

  try {
    // Get the current rate limit for the specified IP address
    const rateLimit = req.rateLimit.limit;

    // Release the semaphore to allow other requests to process
    await semaphore.release();

    return res.json({ message: `Current rate limit is ${rateLimit}` });
  } catch (err) {
    console.error('Error getting current rate limit:', err);
    return res.status(500).send('Internal server error');
  }
};

// Define a function for resetting the rate limit
const resetRateLimit = async (req, res) => {
  // Acquire the semaphore to prevent concurrent processing
  await semaphore.acquire();

  try {
    // Reset the rate limit for the specified IP address
    const rateLimit = req.rateLimit.reset;

    // Release the semaphore to allow other requests to process
    await semaphore.release();

    return res.json({ message: `Rate limit reset at ${rateLimit}` });
  } catch (err) {
    console.error('Error resetting rate limit:', err);
    return res.status(500).send('Internal server error');
  }
};
