namespace SecureDataProcessor
{
    public class SecureDataProcessor
    {
        private readonly IKeyManagementService _keyManagementService;
        private readonly ICryptographicServiceProvider _csp;
        private readonly ConcurrentDictionary<string, object> _decryptionContexts = new();
        private readonly ConcurrentDictionary<string, object> _processingTasks = new();

        public SecureDataProcessor(IKeyManagementService keyManagementService, ICryptographicServiceProvider csp)
        {
            _keyManagementService = keyManagementService;
            _csp = csp;
        }

        public async Task<ProcessingResult> ProcessMessageAsync(byte[] messageBytes, ClearanceLevel clearanceLevel, CancellationToken cancellationToken = default)
        {
            var decryptionContext = GetDecryptionContext(clearanceLevel);
            if (decryptionContext == null)
            {
                throw new ArgumentException("Invalid clearance level", nameof(clearanceLevel));
            }

            var key = await _keyManagementService.GetKeyAsync(decryptionContext, cancellationToken).ConfigureAwait(false);
            if (key == null)
            {
                throw new KeyNotFoundException($"No key found for clearance level: {clearanceLevel}");
            }

            var iv = await _csp.GetIVAsync(decryptionContext, cancellationToken).ConfigureAwait(false);
            if (iv == null)
            {
                throw new IVNotFoundException($"No initialization vector found for clearance level: {clearanceLevel}");
            }

            var message = await _csp.DecryptAsync(messageBytes, key, iv, cancellationToken).ConfigureAwait(false);
            if (message == null)
            {
                throw new DecryptionFailedException($"Failed to decrypt message for clearance level: {clearanceLevel}");
            }

            var result = ProcessMessageInternal(message, clearanceLevel);
            return result;
        }

        public async Task<ProcessingResult> ProcessMessageAsync(byte[] messageBytes, string sourceIdentifier, CancellationToken cancellationToken = default)
        {
            var decryptionContext = GetDecryptionContextForSource(sourceIdentifier);
            if (decryptionContext == null)
            {
                throw new ArgumentException("Invalid source identifier", nameof(sourceIdentifier));
            }

            var key = await _keyManagementService.GetKeyAsync(decryptionContext, cancellationToken).ConfigureAwait(false);
            if (key == null)
            {
                throw new KeyNotFoundException($"No key found for source identifier: {sourceIdentifier}");
            }

            var iv = await _csp.GetIVAsync(decryptionContext, cancellationToken).ConfigureAwait(false);
            if (iv == null)
            {
                throw new IVNotFoundException($"No initialization vector found for source identifier: {sourceIdentifier}");
            }

            var message = await _csp.DecryptAsync(messageBytes, key, iv, cancellationToken).ConfigureAwait(false);
            if (message == null)
            {
                throw new DecryptionFailedException($"Failed to decrypt message for source identifier: {sourceIdentifier}");
            }

            var result = ProcessMessageInternal(message, clearanceLevel);
            return result;
        }

        private async Task<ProcessingResult> ProcessMessageInternal(byte[] messageBytes, ClearanceLevel clearanceLevel)
        {
            var processingTask = _processingTasks.GetOrAdd(clearanceLevel, new());
            var result = await processingTask.ProcessAsync(messageBytes, cancellationToken).ConfigureAwait(false);
            return result;
        }

        private DecryptionContext GetDecryptionContext(ClearanceLevel clearanceLevel)
        {
            var decryptionContext = _decryptionContexts.GetOrAdd(clearanceLevel, new());
            return decryptionContext;
        }

        private DecryptionContext GetDecryptionContextForSource(string sourceIdentifier)
        {
            // TODO: Implement logic to retrieve the decryption context for a specific source identifier
            throw new NotImplementedException();
        }
    }
}
