class AdvancedPasswordManager {
    private $hashedPassword;
    private $saltRoundCount = 12;
    private $cachedStrings = array();
    private $characterSet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()-=_+'

    public function generateSecureRandomString($length) {
        if (isset($this->cachedStrings[$length])) {
            return $this->cachedStrings[$length];
        } else {
            $randomString = '';
            for ($i = 0; $i < $length; $i++) {
                $randomString .= $this->characterSet[rand(0, strlen($this->characterSet) - 1)];
            }
            return $randomString;
        }
    }

    public function hashPassword($password) {
        if (strlen($password) < 8) {
            throw new Exception('Password must be at least 8 characters long');
        }
        $hash = password_hash($password, PASSWORD_BCRYPT, ['cost' => $this->saltRoundCount]);
        if (!$hash) {
            throw new Exception('Hashing failed');
        }
        return $hash;
    }

    public function checkPassword($password) {
        return password_verify($password, $this->hashedPassword);
    }

    public function validateCharacterSet($characterSet) {
        if (!preg_match('/^[A-Za-z0-9!@#$%\^&*()-=_+]{8,}$/', $characterSet)) {
            throw new Exception('Invalid character set');
        }
    }

    public function setSaltRoundCount($rounds) {
        if ($rounds < 12 || $rounds > 31) {
            throw new Exception('Salt round count must be between 12 and 31');
        }
        $this->saltRoundCount = $rounds;
    }

    public function resetPassword() {
        $newHashedPassword = $this->hashPassword($this->generateSecureRandomString(8));
        $this->hashedPassword = $newHashedPassword;
        unset($this->cachedStrings);
        $this->cachedStrings = array();
    }

    public function logPasswordAttempts($ipAddress, $result) {
        // Implement logging here
    }

    public function enforceTwoFactorAuthentication() {
        // Implement 2FA mechanism here
    }
}
