import json
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs
import ssl
import logging

class Server:
    def __init__(self, config):
        self.config = config
        self.host = config["host"]
        self.port = config["port"]
        self.log_file = config["log_file"]
        self.error_handling_modes = config["error_handling_modes"]
        self.api_urls = {}
        for api in config["apis"]:
            self.api_urls[api["name"]] = api["url"]

    def run(self):
        httpd = HTTPServer((self.host, self.port), RequestHandler)
        httpd.serve_forever()

class RequestHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        parsed_path = urlparse(self.path)
        query_params = parse_qs(parsed_path.query)
        api_name = query_params["api"][0]
        if api_name in self.server.api_urls:
            url = self.server.api_urls[api_name] + "?" + parsed_path.query
            try:
                response = urllib.request.urlopen(url)
                self.send_response(200)
                self.end_headers()
                self.wfile.write(response.read())
            except Exception as e:
                self.handle_error(e)
        else:
            self.send_error(400, "Invalid API name")

    def handle_error(self, error):
        logging.exception(f"Error handling request: {error}")
        if self.server.error_handling_modes == "fallback":
            self.send_error(500)
        else:
            self.send_error(400, "Invalid API name")

if __name__ == "__main__":
    config = {
        "host": "localhost",
        "port": 8000,
        "log_file": "server.log",
        "apis": [
            {"name": "api1", "url": "https://api1.com"},
            {"name": "api2", "url": "https://api2.com"}
        ],
        "error_handling_modes": "fallback"
    }
    server = Server(config)
    server.run()

