            // Decrypt the message with AES-256-CBC and PKCS7 padding
            var decryptedText = AesDecrypt(cipherText, aesKey);
            Console.WriteLine("Decrypted text: {0}", decryptedText);
        }

        public static string AesEncrypt(string plainText, byte[] key)
        {
            // Create an AES object with the specified key
            using (var aes = new AesCryptoServiceProvider())
            {
                aes.Key = key;
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;

                // Create an encryptor object
                var encryptor = aes.CreateEncryptor();

                // Encrypt the plain text and return the cipher text
                using (var msEncrypt = new MemoryStream())
                {
                    using (var csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
                    {
                        var plainTextBytes = Encoding.UTF8.GetBytes(plainText);
                        csEncrypt.Write(plainTextBytes, 0, plainTextBytes.Length);
                        csEncrypt.FlushFinalBlock();
                        return Convert.ToBase64String(msEncrypt.ToArray());
                    }
                }
            }
        }

        public static string AesDecrypt(string cipherText, byte[] key)
        {
            // Create an AES object with the specified key
            using (var aes = new AesCryptoServiceProvider())
            {
                aes.Key = key;
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;

                // Create a decryptor object
                var decryptor = aes.CreateDecryptor();

                // Decrypt the cipher text and return the plain text
                using (var msDecrypt = new MemoryStream(Convert.FromBase64String(cipherText)))
                {
                    using (var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        var plainTextBytes = new byte[1024];
                        var count = csDecrypt.Read(plainTextBytes, 0, plainTextBytes.Length);
                        return Encoding.UTF8.GetString(plainTextBytes, 0, count);
                    }
                }
            }
        }
    }
}
