// AES encryption/decryption example in PHP
<?php

function encrypt($data, $key) {
    // The initialization vector (IV) must be unique
    // for each message.
    // Here we are using a static IV
    // which is not recommended. You should
    // generate the IV randomly.
    $iv = '1234567890abcdef';

    $encryption_key = base64_decode($key);

    // Create the cipher object and encrypt the data.
    $cipher = openssl_encrypt(
        $data,
        'aes-256-cbc',
        $encryption_key,
        true,
        $iv
    );

    return base64_encode($iv . $cipher);
}

function decrypt($data, $key) {
    // The initialization vector (IV) must be unique
    // for each message.
    // Here we are using a static IV
    // which is not recommended. You should
    // generate the IV randomly.
    $iv = substr($data, 0, 16);
    $cipher_text = substr($data, 16);

    $encryption_key = base64_decode($key);

    // Create the cipher object and decrypt the data.
    $plaintext = openssl_decrypt(
        $cipher_text,
        'aes-256-cbc',
        $encryption_key,
        true,
        $iv
    );

    return $plaintext;
}

