// AES encryption/decryption example in JavaScript
function encrypt(input, key) {
  // The initialization vector (IV) must be unique
  // for each message.
  // Here we are using a static IV
  // which is not recommended. You should
  // generate the IV randomly.
  const iv = '1234567890abcdef';

  const encryptionKey = base64urldecode(key);

  // Create the cipher object and encrypt the data.
  const cipher = AESCipher(encryptionKey, iv);
  cipher.update(input);
  return base64urlencode(cipher.final());
}

function decrypt(input, key) {
  // The initialization vector (IV) must be unique
  // for each message.
  // Here we are using a static IV
  // which is not recommended. You should
  // generate the IV randomly.
  const iv = input.substring(0, 16);
  const cipherText = input.substring(16);

  const encryptionKey = base64urldecode(key);

  // Create the cipher object and decrypt the data.
  const decipher = AESCipher(encryptionKey, iv);
  return decipher.update(cipherText);
}

