// Define the structure to store information about each image file
struct ImageFile {
    char* filename;
    int width, height;
};

// Define the structure to store information about the PDF document
struct PdfDocument {
    int numPages;
    float dpi;
    char* pdfFilename;
};

// Define the function to convert an image file to a PDF page
void ConvertImageToPdf(const char* imageFile, const struct ImageFile* imgInfo, const struct PdfDocument* pdfDoc) {
    // Use the imagemagick command line tool to convert the image to PDF
    // The command is: magick convert <input> -units PixelsPerInch -density <dpi> -resize <width>x<height> <output>
    char cmd[1024];
    sprintf(cmd, "magick convert %s -units PixelsPerInch -density %.2f -resize %dx%d %s", imageFile, pdfDoc->dpi, imgInfo->width, imgInfo->height, pdfDoc->pdfFilename);
    system(cmd);
}

// Define the function to list all image files in a given directory and subdirectories
void ListImageFiles(const char* dirname, const char* pattern, struct ImageFile** images) {
    // Use the scandir function to list all files in the directory
    // The function returns an array of pointers to dirent structures, each representing a file or subdirectory
    struct dirent **namelist;
    int n = scandir(dirname, &namelist, NULL, alphasort);
    if (n < 0) {
        perror("scandir");
        return;
    }

    // Loop through the files and check for image extensions
    struct ImageFile* currentImage = NULL;
    for (int i = 0; i < n; i++) {
        if (strcasestr(namelist[i]->d_name, pattern)) {
            if (currentImage == NULL) {
                currentImage = malloc(sizeof(struct ImageFile));
                currentImage->filename = strdup(namelist[i]->d_name);
                currentImage->width = 0;
                currentImage->height = 0;
            } else {
                // Add the image to the list
                struct ImageFile* newImage = malloc(sizeof(struct ImageFile));
                newImage->filename = strdup(namelist[i]->d_name);
                newImage->width = 0;
                newImage->height = 0;
                currentImage->next = newImage;
                currentImage = newImage;
            }
        } else {
            // Skip files that do not match the pattern
            continue;
        }
    }

    // Free the memory allocated for the directory listing
    free(namelist);
}

// Define the function to create a PDF document from a list of images
void CreatePdfDocument(const struct ImageFile* images, const char* pdfFilename) {
    // Use the imagemagick command line tool to create a new PDF file from the image files
    // The command is: magick convert <input1> <input2> ... <output> -units PixelsPerInch -density <dpi> -resize <width>x<height>
    char cmd[1024];
    sprintf(cmd, "magick convert");
    for (const struct ImageFile* image = images; image != NULL; image = image->next) {
        strcat(cmd, " ");
        strcat(cmd, image->filename);
    }
    strcat(cmd, " -units PixelsPerInch -density 72 -resize %dx%d ", images->width, images->height);
    strcat(cmd, pdfFilename);
    system(cmd);
}

// Define the function to handle errors from the third-party tool gracefully
void HandleError(const char* errMsg) {
    // Log the error message
    fprintf(stderr, "ERROR: %s\n", errMsg);
}

// Define the main entry point for the program
int main(int argc, char** argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <input directory> <output PDF file>\n", argv[0]);
        return 1;
    }

    const char* inputDir = argv[1];
    const char* pdfFilename = argv[2];

    // Initialize the structures for image files and PDF document
    struct ImageFile* images = NULL;
    struct PdfDocument pdfDoc;
    pdfDoc.numPages = 0;
    pdfDoc.dpi = 72.0f;
    pdfDoc.pdfFilename = strdup(pdfFilename);

    // List all image files in the input directory and subdirectories that match the pattern "*.jpg" or "*.png" or "*.gif"
    ListImageFiles(inputDir, "*.jpg", &images);
    if (images == NULL) {
        ListImageFiles(inputDir, "*.png", &images);
    }
    if (images == NULL) {
        ListImageFiles(inputDir, "*.gif", &images);
    }
    if (images == NULL) {
        fprintf(stderr, "No image files found in the input directory\n");
        return 1;
    }

    // Create a new PDF document from the list of images
    for (const struct ImageFile* image = images; image != NULL; image = image->next) {
        if (image->width == 0 || image->height == 0) {
            char cmd[1024];
            sprintf(cmd, "magick identify %s", image->filename);
            FILE* fp = popen(cmd, "r");
            if (fp != NULL) {
                // Parse the output of the command to get the image dimensions
                char buf[1024];
                while (fgets(buf, sizeof(buf), fp) != NULL) {
                    int width = 0;
                    int height = 0;
                    sscanf(buf, "%d x %d", &width, &height);
                    if (width > 0 && height > 0) {
                        image->width = width;
                        image->height = height;
                        break;
                    }
                }
                pclose(fp);
            }
        }
    }
    CreatePdfDocument(images, pdfFilename);

    // Free the memory allocated for the PDF document and the list of images
    free(pdfDoc.pdfFilename);
    while (images != NULL) {
        struct ImageFile* currentImage = images;
        images = images->next;
        free(currentImage->filename);
        free(currentImage);
    }

    return 0;
}
