// Multi-threaded image processing using a thread pool
const { Pool } = require('threads');
const pool = new Pool(10); // 10 threads

function convertImagesToPdf(images) {
  const pdfPath = path.join(__dirname, 'output.pdf');

  return pool.queue(() => {
