function handleClinicUpdateRequest(request) {
  const { body } = request;
  const { clinicId, updates } = JSON.parse(body);

  // Validate clinic ID and updates
  if (!clinicId || !updates || !Object.keys(updates).length) {
    return Promise.reject(new Error('Invalid clinic update request'));
  }

  // Update clinic record in database
  return db.query(`UPDATE clinics SET ${JSON.stringify(updates)} WHERE id = $1`, [clinicId])
    .then(() => {
      // Log updated clinic record to audit log
      const auditLogEntry = {
        type: 'clinic-update',
        userId: request.userId,
        clinicId,
        updates,
        timestamp: new Date().toISOString()
      };
      return db.query(`INSERT INTO audit_log (entry) VALUES ($1)`, [JSON.stringify(auditLogEntry)]);
    })
    .then(() => {
      // Notify user interface of updated clinic record
      const notification = {
        type: 'clinic-update',
        clinicId,
        updates,
        timestamp: new Date().toISOString()
      };
      return sendNotification(notification);
    });
}

function handleClinicDeletionRequest(request) {
  const { body } = request;
  const { clinicId } = JSON.parse(body);

  // Validate clinic ID and check if it exists in database
  if (!clinicId || !db.query(`SELECT id FROM clinics WHERE id = $1`, [clinicId])) {
    return Promise.reject(new Error('Invalid clinic deletion request'));
  }

  // Delete clinic record from database
  return db.query(`DELETE FROM clinics WHERE id = $1`, [clinicId])
    .then(() => {
      // Log deleted clinic record to audit log
      const auditLogEntry = {
        type: 'clinic-delete',
        userId: request.userId,
        clinicId,
        timestamp: new Date().toISOString()
      };
      return db.query(`INSERT INTO audit_log (entry) VALUES ($1)`, [JSON.stringify(auditLogEntry)]);
    })
    .then(() => {
      // Notify user interface of deleted clinic record
      const notification = {
        type: 'clinic-delete',
        clinicId,
        timestamp: new Date().toISOString()
      };
      return sendNotification(notification);
    });
}
