import time
import random
import requests
from threading import Thread

# Struct for storing script objects
class Script:
    def __init__(self, url, type):
        self.url = url
        self.type = type

# List of script objects
scripts = [
    Script('https://example.com/script1.js', 'text/javascript'),
    Script('https://example.com/script2.js', 'application/javascript'),
]

# Function to generate a footer section for a web page
def generate_footer(scripts):
    # Prioritize scripts based on their type and load them asynchronously
    script_types = ['text/javascript', 'application/javascript']
    async_scripts = [Script('https://example.com/script1.js', 'text/javascript')]
    sync_scripts = [Script('https://example.com/script2.js', 'application/javascript')]
    for script in scripts:
        if script.type in script_types:
            async_scripts.append(script)
        else:
            sync_scripts.append(script)

    # Generate the footer HTML
    html = '<footer>'
    for script in async_scripts:
        html += f'<script src="{script.url}" async></script>'
    for script in sync_scripts:
        html += f'<script src="{script.url}"></script>'
    html += '</footer>'
    return html

# Function to handle caching and external configuration updates
def handle_cache(scripts):
    # Check if the cache is up-to-date
    if time.time() - 60 > int(os.environ['CACHE_TIME']):
        # Update the cache with the latest scripts
        update_cache(scripts)

# Function to handle HTTP request throttling
def throttle_requests():
    # Check if there are any active requests
    if len(active_requests) >= 5:
        # Wait for an active request to finish before making a new one
        while len(active_requests) > 0:
            time.sleep(1)

# Function to update the cache with the latest scripts
def update_cache(scripts):
    # Clear the existing cache
    cache = {}

    # Fetch and store each script in the cache
    for script in scripts:
        url = script.url
        type = script.type
        response = requests.get(url)
        if response.status_code == 200:
            cache[url] = {'type': type, 'content': response.content}

    # Set the new cache time
    os.environ['CACHE_TIME'] = int(time.time())

# Function to fetch and return a script from the cache
def get_script_from_cache(url):
    # Check if the URL is in the cache
    if url in cache:
        # Return the cached script
        return cache[url]
    else:
        # Fetch and store the script in the cache
        response = requests.get(url)
        if response.status_code == 200:
            cache[url] = {'type': type, 'content': response.content}
        return None

# Function to fetch and return a script from an external CDN service
def get_script_from_cdn(url):
    # Fetch the script from the CDN service
    response = requests.get(url)

    # Check if the request was successful
    if response.status_code == 200:
        # Return the fetched script
        return response.content
    else:
        # Return None if the request failed
        return None

# Function to load a script asynchronously and cache it
def load_script(url):
    # Fetch and store the script in the cache
    response = requests.get(url)
    if response.status_code == 200:
        cache[url] = {'type': 'text/javascript', 'content': response.content}

    # Return the fetched script
    return response.content

# Main function to load and generate a footer section for a web page
def main(scripts):
    # Load and cache any scripts that are not already in the cache
    for script in scripts:
        if script.url not in cache:
            load_script(script.url)

    # Generate the footer HTML
    html = '<footer>'
    for script in scripts:
        html += f'<script src="{script.url}"></script>'
    html += '</footer>'
    return html
```
In this Python function, we first define a `Script` class to store information about each script object. We then create a list of script objects and use the `generate_footer()` function to generate a footer section for a web page. The `handle_cache()`, `throttle_requests()`, and `update_cache()` functions are used to handle caching, external configuration updates, and HTTP request throttling, respectively. The `get_script_from_cache()` and `get_script_from_cdn()` functions are used to fetch and return scripts from the cache or an external CDN service, respectively. Finally, the `load_script()` function is used to load and cache any scripts that are not already in the cache.

