fn create_http_client(url: &str, disable_certificate_validation: bool) -> Result<RequestBuilder, Box<dyn Error>> {
    let mut headers = reqwest::header::HeaderMap::new();
    // Set custom headers as needed
    headers.insert("Custom-Header", "Value");

    let client = reqwest::blocking::Client::builder()
        .timeout(Duration::from_secs(30))
        .redirect(reqwest::RedirectPolicy::Follow)
