#include <string.h>
#include <stdlib.h>
#include <stdio.h>
#include <assert.h>

#define MAX_WORD_LENGTH 1024
#define MAX_WORDS_TO_TRIM 10
#define AVERAGE_WORD_LENGTH 5
#define MEMORY_LIMIT 10 * 1024 * 1024 // 10 MB

char* dynamicTrimAndCapitalize(const char* input) {
    size_t input_length = strlen(input);
    int words_to_trim = (int)((float)input_length / AVERAGE_WORD_LENGTH);
    if (words_to_trim > MAX_WORDS_TO_TRIM) {
        words_to_trim = MAX_WORDS_TO_TRIM;
    }

    size_t adjusted_size = input_length - words_to_trim * AVERAGE_WORD_LENGTH;
    char* output = malloc(adjusted_size + 1); // + 1 for the null terminator
    if (output == NULL) {
        printf("Error: Out of memory\n");
        return NULL;
    }

    size_t index = 0;
    for (int i = 0; i < words_to_trim; ++i) {
        int word_length = AVERAGE_WORD_LENGTH;
        if (input[index] == ' ') {
            while (word_length > 0 && input[index + word_length] == ' ') {
                --word_length;
            }
        }

        memcpy(output, &input[index], word_length);
        output += word_length;
        index += word_length + 1; // + 1 for the space character
    }

    *output = '\0';
    return output;
}
