<?php

// Include necessary libraries and configuration files
include 'config.php';
include 'database.php';
include 'oauth2.php';

// Define routes for different HTTP methods
$router->get('/', function () {
    // Home page
});

$router->post('/authenticateUserAndUpdateClinicStatus', function ($request, $response) {
    // Authenticate user and update clinic status using OAuth 2.0

    // Validate input parameters and handle error cases
    if (!isset($request->username)) {
        return $response->withJson([
            'error' => 'Missing required parameter: username'
        ], 400);
    } else if (!isset($request->password)) {
        return $response->withJson([
            'error' => 'Missing required parameter: password'
        ], 400);
    } else if (!isset($request->clinicStatus)) {
        return $response->withJson([
            'error' => 'Missing required parameter: clinicStatus'
        ], 400);
    }

    // Authenticate user using OAuth 2.0
    try {
        $oauthClient = new \OAuth\Client($config['oauth_provider']);
        $token = $oauthClient->getAccessToken([
            'grant_type' => 'password',
            'username' => $request->username,
            'password' => $request->password,
        ]);
    } catch (Exception $e) {
        return $response->withJson([
            'error' => $e->getMessage()
        ], 401);
    }

    // Update clinic status in database
    try {
        $database->updateClinicStatus($token['access_token'], $request->clinicStatus);
    } catch (Exception $e) {
        return $response->withJson([
            'error' => $e->getMessage()
        ], 401);
    }

    // Return successful response with updated clinic status
    return $response->withJson([
        'success' => true,
        'message' => 'Clinic status updated successfully',
        'clinicStatus' => $request->clinicStatus,
    ]);
});
