import json
from collections import defaultdict
from typing import Dict, List, Type

class JSONBase:
    def __init__(self):
        self.data = {}

    def to_json(self) -> str:
        return json.dumps(self.data)

    @staticmethod
    def from_json(json_string: str) -> 'JSONBase':
        data = json.loads(json_string)
        return JSONBase(data=data)

class SubclassRegistry:
    def __init__(self):
        self.subclasses = defaultdict(list)
        self.factory_functions = {}

    def register_subclass(self, subclass: Type[JSONBase]):
        self.subclasses[subclass.__name__].append(subclass)
        self.factory_functions[subclass.__name__] = subclass().to_json

    def create_instance(self, subclass_id: str) -> JSONBase:
        if subclass_id not in self.factory_functions:
            raise ValueError(f"Subclass {subclass_id} is not registered.")
        return self.factory_functions[subclass_id]()

    def discover_subclasses(self, directory: str):
        for file in os.listdir(directory):
            if file.endswith(".py"):
                module = importlib.import_module("." + file[:-3], "subclasses")
                for name, obj in vars(module).items():
                    if isinstance(obj, type) and issubclass(obj, JSONBase):
                        self.register_subclass(obj)

    def cleanup(self):
        for subclass in list(self.subclasses):
            if not self.factory_functions[subclass].keep():
                del self.subclasses[subclass]
                del self.factory_functions[subclass]
