import yaml
from pathlib import Path

class YAMLRegistry:
    def __init__(self):
        self.file_path = None
        self.registry = {}

    def load(self, file_path: str):
        with open(file_path) as f:
            self.registry = yaml.safe_load(f)

    def save(self, file_path: str):
        with open(file_path, "w") as f:
            yaml.dump(self.registry, f, default_flow_style=False)

    def register(self, subclass: Type[JSONBase]):
        self.registry[subclass.__name__] = {
            "factory": subclass().to_json,
            "schema": subclass.get_schema()
        }

    def create(self, subclass_id: str):
        if subclass_id not in self.registry:
            raise ValueError(f"Subclass {subclass_id} is not registered.")
        return self.registry[subclass_id]["factory"]()
