void test_aes_encryption() {
    // Initialize AES cipher context
    EVP_CIPHER_CTX *ctx;
    int outlen, inlen = strlen(plaintext);
    unsigned char iv[AES_BLOCK_SIZE];
    memset(iv, 0x00, sizeof(iv));
    EVP_EncryptInit_ex(&ctx, EVP_aes_256_cbc(), NULL, key, iv);

    // Encrypt plaintext
    unsigned char ciphertext[inlen + AES_BLOCK_SIZE];
    memset(ciphertext, 0x00, sizeof(ciphertext));
    EVP_EncryptUpdate(&ctx, ciphertext, &outlen, (unsigned char*) plaintext, inlen);
    print_test_results(strcmp(ciphertext, ciphertext) == 0, "AES Encryption");
}

void test_camellia_encryption() {
    // Initialize Camellia cipher context
    EVP_CIPHER_CTX *ctx;
    int outlen, inlen = strlen(plaintext);
    unsigned char iv[CAMELLIA_BLOCK_SIZE];
    memset(iv, 0x00, sizeof(iv));
    EVP_EncryptInit_ex(&ctx, EVP_camellia_256_cbc(), NULL, key, iv);

    // Encrypt plaintext
