    EVP_MD_CTX *ctx;
    unsigned char digest[EVP_MAX_MD_SIZE];
    memset(digest, 0x00, sizeof(digest));
    EVP_DigestInit_ex(&ctx, EVP_md5(), NULL);

    // Hash plaintext
    int outlen;
    EVP_DigestUpdate(&ctx, (unsigned char*) plaintext, strlen(plaintext));
    EVP_DigestFinal_ex(&ctx, digest, &outlen);
    print_test_results(strcmp(digest, digest) == 0, "MD5 Hashing");
