import React from 'react';
import { useState } from 'react';
import axios from 'axios';

const App = () => {
  const [channels, setChannels] = useState([]);
  const [messages, setMessages] = useState([]);
  const [selectedChannel, setSelectedChannel] = useState('');
  const [user, setUser] = useState({});
  const [offlineMessages, setOfflineMessages] = useState([]);

  // Fetch channels and messages on mount
  useEffect(() => {
    axios.get('/api/channels')
      .then((res) => {
        setChannels(res.data);
      })
      .catch((err) => console.error(err));

    axios.get(`/api/messages?channel=${selectedChannel}`)
      .then((res) => {
        setMessages(res.data);
      })
      .catch((err) => console.error(err));
  }, []);

  // Subscribe to channel updates on channel change
  useEffect(() => {
    if (selectedChannel) {
      axios.get(`/api/messages?channel=${selectedChannel}`)
        .then((res) => {
          setMessages(res.data);
        })
        .catch((err) => console.error(err));
    }
  }, [selectedChannel]);

  // Handle user presence and message delivery acknowledgement
  useEffect(() => {
    if (user.id) {
      axios.post(`/api/users/${user.id}/presence`)
        .then((res) => {
          setUser(res.data);
        })
        .catch((err) => console.error(err));

      axios.get(`/api/messages?channel=${selectedChannel}`)
        .then((res) => {
          setMessages(res.data);
        })
        .catch((err) => console.error(err));
    }
  }, [user]);

  // Handle offline message queuing
  useEffect(() => {
    if (offlineMessages.length > 0) {
      axios.post(`/api/messages?channel=${selectedChannel}`)
        .then((res) => {
          setMessages(res.data);
        })
        .catch((err) => console.error(err));
    }
  }, [offlineMessages]);

  return (
    <div className="app">
      <header>Chat App</header>
      <main>
        {/* Channel selection */}
        <select onChange={(e) => setSelectedChannel(e.target.value)}>
          {channels.map((channel) => (
            <option key={channel._id} value={channel._id}>{channel.name}</option>
          ))}
        </select>
        {/* Message list */}
        <ul>
          {messages.map((message) => (
            <li key={message._id}>{message.user.username}: {message.text}</li>
          ))}
        </ul>
      </main>
      <footer>
        {/* User presence indicator */}
        {user.presence && user.presence === 'online' ? (
          <span className="status-indicator online" />
        ) : (
          <span className="status-indicator offline" />
        )}
        {/* Message input field */}
        <form onSubmit={(e) => {
          e.preventDefault();
          const text = e.target[0].value;
          axios.post(`/api/messages?channel=${selectedChannel}`, {text})
            .then((res) => {
              setMessages([...messages, res.data]);
            })
            .catch((err) => console.error(err));
        }}>
          <input type="text" name="text" placeholder="Type your message..." />
          <button type="submit">Send</button>
        </form>
      </footer>
    </div>
  );
};
