@Controller
@RequestMapping("/password-manager")
public class PasswordManagerController {
    private final Logger logger = LoggerFactory.getLogger(PasswordManagerController.class);

    @Autowired
    private UserAccountService userAccountService;

    @Autowired
    private FactoryFunctionRegistry factoryFunctionRegistry;

    @Autowired
    private PasswordResetManager passwordResetManager;

    @PostMapping("/reset-password")
    public ResponseEntity<Void> resetPassword(@RequestBody @Validated ResetPasswordRequest request) {
        try {
            userAccountService.updatePassword(request.getUsername(), passwordResetManager.resetPassword(request.getNewPassword()));
            return new ResponseEntity<>(HttpStatus.OK);
        } catch (UserNotFoundException | PasswordResetFailedException e) {
            logger.error("Error resetting password", e);
            return new ResponseEntity<>(HttpStatus.INTERNAL_SERVER_ERROR);
        }
    }

    @GetMapping("/validate-password")
    public ResponseEntity<Void> validatePassword(@RequestBody @Validated ValidatePasswordRequest request) {
        try {
            userAccountService.validatePassword(request.getUsername(), request.getPassword());
            return new ResponseEntity<>(HttpStatus.OK);
        } catch (UserNotFoundException | PasswordValidationFailedException e) {
            logger.error("Error validating password", e);
            return new ResponseEntity<>(HttpStatus.INTERNAL_SERVER_ERROR);
        }
    }
}

