interface FactoryFunctionRegistry {
    public void registerFactoryFunction(@NotNull String id, @NotNull FactoryFunction function);
    public void deregisterFactoryFunction(@NotNull String id);
    public Object createObject(@NotNull String id, Map<String, Object> args);
}

class FactoryFunctionRegistryImpl implements FactoryFunctionRegistry {
    private final Map<String, FactoryFunction> registry = new HashMap<>();

    @Override
    public void registerFactoryFunction(@NotNull String id, @NotNull FactoryFunction function) {
        if (registry.containsKey(id)) {
            throw new IllegalArgumentException("Cannot re-register factory function with the same ID");
        }
        registry.put(id, function);
    }

    @Override
    public void deregisterFactoryFunction(@NotNull String id) {
        if (!registry.containsKey(id)) {
            throw new IllegalArgumentException("Cannot deregister non-existent factory function");
        }
        registry.remove(id);
    }

    @Override
    public Object createObject(@NotNull String id, Map<String, Object> args) {
        if (!registry.containsKey(id)) {
            throw new IllegalArgumentException("No factory function registered with ID " + id);
        }
        return registry.get(id).createObject(args);
    }
}

interface FactoryFunction {
    public Object createObject(Map<String, Object> args);
}

class DefaultFactoryFunction implements FactoryFunction {
    @Override
    public Object createObject(Map<String, Object> args) {
        // Implement default factory function behavior
    }
}

