#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

// Define a structure to hold the configuration for the function
typedef struct {
    int digit_count; // Number of digits in the new extension
    char *file_type; // File type (e.g., ".txt", ".jpg")
} config_t;

// Function to modify the filename and return the modified filename
char* modify_filename(const char *filename, config_t *config) {
    // Create a copy of the original filename
    char *new_filename = strdup(filename);

    // Get the extension of the original filename
    const char *extension = strrchr(filename, '.');
    if (!extension) {
        return NULL;
    }

    // Increment the digit count for the file type
    config->digit_count++;

    // Create a new extension with the updated digit count
    char new_extension[16];
    sprintf(new_extension, "%0*d%s", config->digit_count, config->file_type);

    // Replace the old extension with the new one
    size_t extension_len = strlen(new_extension);
    memcpy(new_filename + (new_filename - filename), new_extension, extension_len);

    return new_filename;
}

int main() {
    // Test cases for the function
    const char *test_filenames[] = {"file.txt", "image.jpg", "document.pdf"};
    config_t configs[] = {{3, ".txt"}, {5, ".jpg"}, {7, ".pdf"}};

    // Iterate over the test cases and call the function
    for (int i = 0; i < sizeof(test_filenames) / sizeof(const char*); i++) {
        config_t *config = &configs[i];
        char *modified_filename = modify_filename(test_filenames[i], config);
        printf("Modified filename: %s\n", modified_filename);
    }

    return 0;
}
