            std::smatch match = *iter;
            if (old_testament_books.find(match[0]) != old_testament_books.end()) {
                // Add the reference to the vector of references
                references.push_back(match[0]);
            }

            // Increment the iterator
            ++iter;
        }
    }

    // Print the list of references
    std::cout << "References to Old Testament books:" << std::endl;
    for (const auto& reference : references) {
        std::cout << "- " << reference << std::endl;
    }
}

