class SecurePasswordManager {
  private $hashedPassword;
  private $saltRoundCount = 12;
  private $characterSet;

  public function generateRandomString($length) {
    $characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()-_=+';
    $randomString = '';

    for ($i = 0; $i < $length; $i++) {
      $index = rand(0, strlen($characters) - 1);
      $randomString .= $characters[$index];
    }

    return $randomString;
  }

  public function hashPassword($password) {
    if (!$this->validateCharacterSet($password)) {
      throw new \Exception('Invalid character set');
    }

    return password_hash(
      $this->generateRandomString(16),
      PASSWORD_BCRYPT,
      ['salt' => $this->generateSalt(), 'rounds' => $this->saltRoundCount]
    );
  }

  public function checkPassword($password) {
    if (!$this->validateCharacterSet($password)) {
      throw new \Exception('Invalid character set');
    }

    return password_verify(
      $password,
      $this->hashedPassword,
      ['salt' => $this->generateSalt(), 'rounds' => $this->saltRoundCount]
    );
  }

  public function validateCharacterSet($characterSet) {
    return preg_match('/^[A-Za-z0-9!@#\$%\^\&*\(\)-_\=+]{8,}$/', $characterSet);
  }

  public function setSaltRoundCount($rounds) {
    if (!is_int($rounds)) {
      throw new \Exception('Invalid salt round count');
    }

    $this->saltRoundCount = max(4, min(31, $rounds));
  }

  public function resetPassword() {
    $this->hashedPassword = null;
    $this->setSaltRoundCount(12);
  }

  public function secureSave($hashedPassword) {
    if (!$this->validateCharacterSet($hashedPassword)) {
      throw new \Exception('Invalid character set');
    }

    $query = 'INSERT INTO users (hashed_password) VALUES (:hashed_password)';
    $stmt = $this->db->prepare($query);
    $stmt->bindParam(':hashed_password', $hashedPassword, PDO::PARAM_STR);
    $stmt->execute();
  }

  public function secureLoad($userId) {
    $query = 'SELECT hashed_password FROM users WHERE id = :id';
    $stmt = $this->db->prepare($query);
    $stmt->bindParam(':id', $userId, PDO::PARAM_INT);
    $stmt->execute();
    return $stmt->fetchColumn();
  }
}
