using System;
using UnityEngine;

public class ValueGenerator
{
    private float minimumValue;
    private float maximumValue;
    private int seed;

    public ValueGenerator(float min, float max)
    {
        this.minimumValue = min;
        this.maximumValue = max;
        this.seed = UnityEngine.Random.Range(0, Int32.MaxValue);
    }

    public float GenerateRandomFloat()
    {
        return UnityEngine.Random.Range(this.minimumValue, this.maximumValue);
    }

    public int GenerateRandomInt()
    {
        return UnityEngine.Random.Range((int)this.minimumValue, (int)this.maximumValue);
    }

    public Vector3 GenerateRandomVector3(float minX = float.MinValue, float maxX = float.MaxValue, float minY = float.MinValue, float maxY = float.MaxValue, float minZ = float.MinValue, float maxZ = float.MaxValue)
    {
        return new Vector3(UnityEngine.Random.Range(minX, maxX), UnityEngine.Random.Range(minY, maxY), UnityEngine.Random.Range(minZ, maxZ));
    }

    public override string ToString()
    {
        return $"{this.minimumValue} - {this.maximumValue}";
    }

    // Additional methods:

    public void SetSeed(int seed)
    {
        this.seed = seed;
    }

    public bool ValidateRandomValue(float value, float toleranceRange)
    {
        return Mathf.Abs(value - UnityEngine.Random.Range(this.minimumValue, this.maximumValue)) < toleranceRange;
    }

    public void SaveRandomValuesToFile(string filePath, CompressionFormat compressionFormat = CompressionFormat.Uncompressed)
    {
        // Implement a method to save the generated random values in a compressed format (e.g., GZip) to reduce storage space.
    }
}
