#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <semaphore.h>
#include <pthread.h>

// Define a struct to represent a node in the queue
typedef struct QueueNode {
    char* url;
    struct QueueNode* next;
} QueueNode;

// Define a struct to represent the queue
typedef struct Queue {
    QueueNode* head;
    QueueNode* tail;
    int size;
    sem_t mutex;
    sem_t enqueue_sem;
    sem_t dequeue_sem;
} Queue;

// Initialize the queue with a given capacity
void initQueue(int capacity) {
    // Create a new queue node to serve as the head and tail of the list
    QueueNode* head = malloc(sizeof(QueueNode));
    QueueNode* tail = malloc(sizeof(QueueNode));
    if (head == NULL || tail == NULL) {
        perror("Error allocating memory for queue nodes");
        exit(EXIT_FAILURE);
    }
    head->next = tail;
    tail->next = NULL;
    // Initialize the mutex, enqueue semaphore, and dequeue semaphore
    if (sem_init(&mutex, 0, 1) == -1 ||
        sem_init(&enqueue_sem, 0, capacity) == -1 ||
        sem_init(&dequeue_sem, 0, 0) == -1) {
        perror("Error initializing queue semaphores");
        exit(EXIT_FAILURE);
    }
    // Set the head and tail pointers to the new nodes
    head->next = NULL;
    tail->next = NULL;
    size = 0;
}

// Enqueue a URL on the queue
void enqueue(char* url) {
    // Acquire the mutex and check if the queue is full
    sem_wait(&mutex);
    if (size == capacity) {
        perror("Queue is full");
        exit(EXIT_FAILURE);
    }
    // Create a new node to store the URL
    QueueNode* new_node = malloc(sizeof(QueueNode));
    if (new_node == NULL) {
        perror("Error allocating memory for queue node");
        exit(EXIT_FAILURE);
    }
    // Set the URL and next pointer of the new node
    new_node->url = url;
    new_node->next = NULL;
    // If the queue is empty, set the head to the new node
    if (head == NULL) {
        head = tail = new_node;
    } else {
        tail->next = new_node;
        tail = new_node;
    }
    size++;
    // Release the mutex and signal that an item has been enqueued
    sem_post(&enqueue_sem);
}

// Dequeue a URL from the queue
char* dequeue() {
    // Acquire the mutex and check if the queue is empty
    sem_wait(&mutex);
    if (size == 0) {
        perror("Queue is empty");
        exit(EXIT_FAILURE);
    }
    // Get the URL of the head node
    char* url = head->url;
    // Remove the head node from the queue
    QueueNode* temp = head;
    head = head->next;
    size--;
    // Release the mutex and signal that an item has been dequeued
    sem_post(&dequeue_sem);
    return url;
}

// Check if the queue is empty
int isQueueEmpty() {
    // Acquire the mutex and check if the size of the queue is 0
    sem_wait(&mutex);
    int is_empty = (size == 0);
    // Release the mutex
    sem_post(&mutex);
    return is_empty;
}

// Terminate all threads gracefully when a stop signal is received
void terminateThreads() {
    // Acquire the mutex and set the size of the queue to 0
    sem_wait(&mutex);
    size = 0;
    // Release the mutex
    sem_post(&mutex);
    // Signal that the enqueue and dequeue semaphores should be released
    sem_post(&enqueue_sem);
    sem_post(&dequeue_sem);
}

// Clean up all resources when the program exits
void cleanup() {
    // Release the mutex, enqueue, and dequeue semaphores
    sem_destroy(&mutex);
    sem_destroy(&enqueue_sem);
    sem_destroy(&dequeue_sem);
    // Clean up all nodes in the queue
    while (head != NULL) {
        QueueNode* temp = head;
        head = head->next;
        free(temp);
    }
}
