  const clinic = JSON.parse(redisClient.hget(`clinics:${req.params.name}`));
  if (!clinic) {
    return res.status(404).send('Clinic not found');
  }
  res.json(clinic);
});

app.put('/clinics/:name', (req, res) => {
  const clinic = JSON.parse(redisClient.hget(`clinics:${req.params.name}`));
  if (!clinic) {
    return res.status(404).send('Clinic not found');
  }
  const updates = req.body;
  clinic.name = updates.name || clinic.name;
  clinic.address = updates.address || clinic.address;
  redisClient.hset(`clinics:${req.params.name}`, JSON.stringify(clinic));
  wss.clients.forEach((client) => {
    client.send(`"update clinic ${req.params.name}"`);
  });
  res.status(200).send();
});

app.delete('/clinics/:name', (req, res) => {
  const clinic = JSON.parse(redisClient.hget(`clinics:${req.params.name}`));
  if (!clinic) {
    return res.status(404).send('Clinic not found');
  }
  redisClient.hdel(`clinics:${req.params.name}`);
  wss.clients.forEach((client) => {
    client.send(`"delete clinic ${req.params.name}"`);
  });
  res.status(200).send();
});

// Define the PDF generation endpoint
app.post('/pdf', async (req, res) => {
  const pdfData = await pdfConverter.convertImagesToPdf(req.body.images);
  res.send(pdfData);
});

// Define the inventory integration endpoints
app.get('/inventory/products', async (req, res) => {
  const products = await inventorySystem.getProducts();
  res.json(products);
});

app.post('/inventory/products/:id', async (req, res) => {
