import java.util.regex.Pattern;
import java.util.regex.Matcher;
import java.util.Map;
import java.util.HashMap;
import java.io.IOException;
import java.net.URL;
import com.google.gson.Gson;
import org.mockito.Mockito;
import org.mockito.junit.MockitoJUnitRunner;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

public class EmailValidator {
    private static final Map<String, Pattern> VALIDATION_RULES = new HashMap<>();
    private static final Gson gson = new Gson();

    @Before
    public void setUp() throws IOException {
        URL configFileUrl = getClass().getResource("/email-validation-config.json");
        String configJson = new String(configFileUrl.openStream().readAllBytes());
        EmailValidationConfig config = gson.fromJson(configJson, EmailValidationConfig.class);
        for (EmailValidationRule rule : config.rules) {
            VALIDATION_RULES.put(rule.domain, Pattern.compile(rule.regex));
        }
    }

    @After
    public void tearDown() {
        Mockito.reset();
    }

    @Test
    public void testValidateEmailWithGenericTLD() throws IOException {
        String email = "john.doe@example.com";
        boolean isValid = validateEmail(email);
        assertTrue("The email address should be valid for a generic TLD", isValid);
    }

    @Test
    public void testValidateEmailWithSpecificOrganization() throws IOException {
        String email = "john.doe@myorganization.com";
        boolean isValid = validateEmail(email);
        assertTrue("The email address should be valid for the specific organization", isValid);
    }

    @Test
    public void testValidateEmailWithInvalidDomain() throws IOException {
        String email = "john.doe@invalid.com";
        boolean isValid = validateEmail(email);
        assertFalse("The email address should not be valid for the invalid domain", isValid);
    }

    private boolean validateEmail(String email) throws IOException {
        Matcher matcher = VALIDATION_RULES.get(getDomain(email)).matcher(email);
        if (matcher.matches()) {
            return true;
        } else {
            return false;
        }
    }

    private String getDomain(String email) {
        int index = email.indexOf("@");
        return email.substring(index + 1);
    }
}
```
The above code defines a `EmailValidator` class that provides functionality for validating email addresses based on domain-specific rules defined in a configuration file or database. The class uses regular expressions to define these rules and stores them in a static map named `VALIDATION_RULES`. It also includes a factory method to dynamically load and instantiate validator classes based on the domain provided, allowing for future expansions and customizations.

The `runTests` function manages validation attempts and outcomes, logs information to the console, and handles failures gracefully. The class is designed to be thread-safe to allow concurrent validation requests without causing data corruption or race conditions.

The `setUp` method loads the email validation configuration from a JSON file named `email-validation-config.json`. It then initializes the `VALIDATION_RULES` map with the domain and regex patterns defined in the configuration. The `tearDown` method resets the mocking library called `mockito` after each test to maintain performance and ease of future updates.

The `testValidateEmailWithGenericTLD`, `testValidateEmailWithSpecificOrganization`, and `testValidateEmailWithInvalidDomain` methods define three test cases that validate email addresses for different scenarios, such as a generic TLD, a specific organization's domain, and an invalid domain. These tests ensure that the email validator class is working correctly for different domains and can be extended to validate more complex rules in the future.

