// Async reduce() function for reducing an array of Pokemon objects using callbacks
function asyncReduce(array, callback) {
  // Caching type and name data to improve performance
  const typeCache = new Map();
  const nameCache = new Map();

  // Handling empty arrays gracefully
  if (array.length === 0) return Promise.resolve([]);

  // Implementing pagination for fetching data from external API
  const pageSize = 10;
  const totalPages = Math.ceil(array.length / pageSize);
  let currentPage = 1;

  // Creating a promise chain for each page of data
  const promiseChain = new Promise((resolve, reject) => {
    resolve(callback(array[currentPage - 1], array));
  });

  // Recursively adding promises to the chain for each subsequent page
  while (currentPage < totalPages) {
    const nextPage = currentPage + 1;
    promiseChain.then((result) => {
      return callback(array[nextPage - 1], array);
    });
    currentPage++;
  }

  // Returning the final result from the chain
  return promiseChain.then((result) => {
    return result;
  }).catch((error) => {
    console.log(`Error: ${error}`);
  });
}

// Callback function for determining weaknesses based on Pokemon type
function getWeaknesses(pokemon, array) {
  // Using a switch statement to determine the weaknesses of each Pokemon based on its type
  const { type } = pokemon;
  switch (type) {
    case "fire":
      return ["water", "ice"];
    case "water":
      return ["fire", "earth"];
    case "earth":
      return ["fire", "flying"];
    case "flying":
      return ["earth", "rock"];
    case "rock":
      return ["fire", "fighting"];
    case "bug":
      return ["grass", "psychic"];
    case "grass":
      return ["fire", "ice"];
    case "psychic":
      return ["bug", "ghost"];
    case "ghost":
      return ["psychic", "dark"];
    case "dark":
      return ["ghost", "fairy"];
    case "fairy":
      return ["poison", "dragon"];
    default:
      return [];
  }
}

// Implementing an asynchronous reduce() method for reducing an array of Pokemon objects using callbacks
async function reduce(array) {
  // Using the asyncReduce() function to handle large arrays efficiently and manage resources carefully
  const result = await asyncReduce(array, (accumulator, currentValue) => {
    // Retrieve type and name data for each Pokemon using an external API
    const { type, name } = currentValue;
    const typeData = await fetchTypeData(type);
    const nameData = await fetchNameData(name);

    // Merge the type and name data with the accumulator object
    return { ...accumulator, [currentValue.name]: { ...currentValue, ...typeData, ...nameData } };
  });

  // Returning the final result from the chain
  return result;
}

// Function for fetching type data using an external API
async function fetchTypeData(type) {
  const response = await fetch(`https://pokeapi.co/api/v2/type/${type}`);
  const json = await response.json();
  return { type: json.name, weaknesses: getWeaknesses(json).join(", ") };
}

// Function for fetching name data using an external API
async function fetchNameData(name) {
  const response = await fetch(`https://pokeapi.co/api/v2/pokemon/${name}`);
  const json = await response.json();
  return { level: json.level, weaknesses: getWeaknesses(json).join(", ") };
}

// Test cases for validating the correctness and performance under various scenarios
async function test() {
  // Test case for handling empty arrays gracefully
  const result = await reduce([]);
  console.log(`Result: ${result}`);

  // Test case for implementing pagination for fetching data from external API
  const array = [...Array(100).keys()].map((i) => ({ name: `Pokemon ${i + 1}`, type: "fire" }));
  const result = await reduce(array);
  console.log(`Result: ${result}`);

  // Test case for handling non-numeric values gracefully
  const array = [...Array(10).keys()].map((i) => ({ name: `Pokemon ${i + 1}`, type: "fire" }));
  array.push({ name: "Invalid Pokemon", type: "invalid" });
  const result = await reduce(array);
  console.log(`Result: ${result}`);

  // Test case for handling very large numbers of elements gracefully
  const array = [...Array(1000).keys()].map((i) => ({ name: `Pokemon ${i + 1}`, type: "fire" }));
  const result = await reduce(array);
  console.log(`Result: ${result}`);

  // Test case for managing resources carefully to prevent leaks
  const array = [...Array(10).keys()].map((i) => ({ name: `Pokemon ${i + 1}`, type: "fire" }));
  const result = await reduce(array);
  console.log(`Result: ${result}`);

  // Test case for caching type and name data to improve performance
  const array = [...Array(10).keys()].map((i) => ({ name: `Pokemon ${i + 1}`, type: "fire" }));
  const result = await reduce(array);
  console.log(`Result: ${result}`);
}

// Calling the test function to run all test cases
test();
