#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>
#include <mqueue.h>

// Environment variables for semaphore configuration
#define SEMAPHORE_MAX 10 // maximum number of semaphores
#define SEMAPHORE_INITIAL 5 // initial value of semaphores

// Semaphore structure
struct Semaphore {
    int value; // current value of the semaphore
    int max_value; // maximum value of the semaphore
};

// Semaphore map for dynamic creation, deletion, and manipulation
static std::map<std::string, struct Semaphore> semaphores;

// Messaging queue for asynchronous communication between nodes
static mqd_t message_queue;

// Function to create a new semaphore
int CreateSemaphore(const char* name, int initial_value, int max_value) {
    // Check if the semaphore already exists
    if (semaphores.find(name) != semaphores.end()) {
        return -1;
    }

    // Create a new semaphore structure and add it to the map
    struct Semaphore new_semaphore = {initial_value, max_value};
    semaphores[name] = new_semaphore;

    return 0;
}

// Function to delete a semaphore
int DeleteSemaphore(const char* name) {
    // Check if the semaphore exists
    if (semaphores.find(name) == semaphores.end()) {
        return -1;
    }

    // Remove the semaphore from the map and destroy it
    semaphores.erase(name);

    return 0;
}

// Function to manipulate a semaphore
int ManipulateSemaphore(const char* name, int value) {
    // Check if the semaphore exists
    if (semaphores.find(name) == semaphores.end()) {
        return -1;
    }

    // Update the semaphore's value and send a message to all nodes in the cluster
    struct Semaphore* semaphore = &semaphores[name];
    semaphore->value = value;
    char message[50];
    sprintf(message, "Semaphore %s updated to %d", name, value);
    mq_send(message_queue, message, strlen(message), 0);

    return 0;
}

// Function to wait for a semaphore
int WaitSemaphore(const char* name) {
    // Check if the semaphore exists
    if (semaphores.find(name) == semaphores.end()) {
        return -1;
    }

    // Lock the semaphore and decrement its value
    struct Semaphore* semaphore = &semaphores[name];
    pthread_mutex_lock(&semaphore->mutex);
    semaphore->value--;

    return 0;
}

// Function to signal a semaphore
int SignalSemaphore(const char* name) {
    // Check if the semaphore exists
    if (semaphores.find(name) == semaphores.end()) {
        return -1;
    }

    // Unlock the semaphore and increment its value
    struct Semaphore* semaphore = &semaphores[name];
    pthread_mutex_unlock(&semaphore->mutex);
    semaphore->value++;

    return 0;
}

// Main function for the distributed semaphore management system
int main() {
    // Initialize the messaging queue and map of semaphores
    message_queue = mq_open("semaphore_queue", O_CREAT | O_RDONLY, 0644, NULL);
    semaphores = new std::map<std::string, struct Semaphore>();

    // Create a thread for each node in the cluster
    pthread_t threads[NODES];
    for (int i = 0; i < NODES; i++) {
        pthread_create(&threads[i], NULL, &ProcessMessageQueue, NULL);
    }

    // Wait for the threads to finish
    for (int i = 0; i < NODES; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

// Thread function for processing messages from the messaging queue
void* ProcessMessageQueue(void* args) {
    // Read messages from the message queue and process them
    while (1) {
        char message[50];
        mq_receive(message_queue, message, 50, NULL);
        printf("Received message: %s\n", message);

        // Parse the message to determine which semaphore is being updated
        std::string semaphore_name = "";
        int value = -1;
        sscanf(message, "Semaphore %s updated to %d", &semaphore_name, &value);

        // Update the semaphore's value if it exists
        struct Semaphore* semaphore = &semaphores[semaphore_name];
        if (semaphore != NULL) {
            pthread_mutex_lock(&semaphore->mutex);
            semaphore->value = value;
            pthread_mutex_unlock(&semaphore->mutex);
        }
    }
}
