class FileMerger:
    def __init__(self, file_paths, destination_file_path):
        self.file_paths = file_paths
        self.destination_file_path = destination_file_path
        self.logger = logging.getLogger(__name__)

    def merge(self):
        with open(self.destination_file_path, "wb") as output_file:
            for file_path in self.file_paths:
                try:
                    with open(file_path, "rb") as input_file:
                        while True:
                            chunk = input_file.read(1024)
                            if not chunk:
                                break
                            output_file.write(chunk)
                            self.logger.info("Merging file {}".format(file_path))
                except Exception as e:
                    self.logger.error("Error merging file {}: {}".format(file_path, str(e)))
                    continue

class FileMergerThread(threading.Thread):
    def __init__(self, file_paths, destination_file_path):
        threading.Thread.__init__(self)
        self.file_paths = file_paths
        self.destination_file_path = destination_file_path
        self.logger = logging.getLogger(__name__)

    def run(self):
        with open(self.destination_file_path, "ab") as output_file:
            for file_path in self.file_paths:
                try:
                    with open(file_path, "rb") as input_file:
                        while True:
                            chunk = input_file.read(1024)
                            if not chunk:
                                break
                            output_file.write(chunk)
                            self.logger.info("Merging file {}".format(file_path))
                except Exception as e:
                    self.logger.error("Error merging file {}: {}".format(file_path, str(e)))
                    continue

class FileMergerPoolExecutor(ThreadPoolExecutor):
    def __init__(self, file_paths, destination_file_path, max_workers=None):
        ThreadPoolExecutor.__init__(self, max_workers=max_workers)
        self.file_paths = file_paths
        self.destination_file_path = destination_file_path
        self.logger = logging.getLogger(__name__)

    def merge(self):
        with open(self.destination_file_path, "wb") as output_file:
            for file_path in self.file_paths:
                try:
                    with open(file_path, "rb") as input_file:
                        while True:
                            chunk = input_file.read(1024)
                            if not chunk:
                                break
                            output_file.write(chunk)
                            self.logger.info("Merging file {}".format(file_path))
                except Exception as e:
                    self.logger.error("Error merging file {}: {}".format(file_path, str(e)))
                    continue
