import json
from datetime import datetime
from decimal import Decimal
from uuid import UUID

class JSONSerializable:
    _factory_functions = {}

    @classmethod
    def add_factory_function(cls, id_, func):
        cls._factory_functions[id_] = func

    @classmethod
    def create_instance_from_id(cls, id_):
        if id_ not in cls._factory_functions:
            raise ValueError(f"Factory function with ID {id_} not found.")
        return cls._factory_functions[id_]()

    @classmethod
    def to_json(cls, obj):
        return json.dumps(obj)

    @classmethod
    def from_json(cls, json_str):
        data = json.loads(json_str)
        if "id" in data:
            id_ = data["id"]
            instance = cls.create_instance_from_id(id_)
            for key, value in data.items():
                setattr(instance, key, value)
            return instance
        else:
            raise ValueError("Invalid JSON input.")

    def __init__(self):
        self._uuid = UUID()
        self._datetime = datetime.now()
        self._decimal = Decimal("10")

    @property
    def uuid(self):
        return self._uuid

    @property
    def datetime(self):
        return self._datetime

    @property
    def decimal(self):
        return self._decimal
```
