public class OptimizeImageCompression {
  public static void main(String[] args) throws Exception {
    // Read input image file and convert to OpenCV Mat object
    String inputFilePath = "path/to/input/image.jpg";
    File inputFile = new File(inputFilePath);
    Mat inputMat = Imgcodecs.imread(inputFilePath, Imgcodecs.IMREAD_COLOR);

    // Define target file size and maximum allowed quality reduction percentage
    int targetFileSize = 1024 * 1024; // 1 MB
    double maxQualityReductionPercentage = 50; // 50%

    // Analyze image content and adjust compression settings to meet target file size while maintaining acceptable image quality
    Map<String, Object> compressionSettings = analyzeImageContent(inputMat);
    compressionSettings.put("targetFileSize", targetFileSize);
    compressionSettings.put("maxQualityReductionPercentage", maxQualityReductionPercentage);

    // Compress image using chosen compression algorithm and save to output path
    String outputPath = "path/to/output/image.jpg";
    compressImage(inputMat, compressionSettings, outputPath);
  }

  /**
   * Analyze image content and adjust compression settings to meet target file size while maintaining acceptable image quality.
   */
  public static Map<String, Object> analyzeImageContent(Mat inputMat) {
    // Determine image format and compression algorithm based on file extension or MIME type
    String fileExtension = "jpg"; // default to JPEG
    if (inputFilePath.endsWith(".png")) {
      fileExtension = "png";
    } else if (inputFilePath.endsWith(".bmp")) {
      fileExtension = "bmp";
    }

    // Determine image size and resolution
    int width = inputMat.width();
    int height = inputMat.height();
    double aspectRatio = width / height;

    // Determine optimal compression settings based on image content and file size requirements
    Map<String, Object> compressionSettings = new HashMap<>();
    compressionSettings.put("fileFormat", fileExtension);
    compressionSettings.put("imageWidth", width);
    compressionSettings.put("imageHeight", height);
    compressionSettings.put("aspectRatio", aspectRatio);
    compressionSettings.put("targetFileSize", 1024 * 1024); // default to 1 MB
    compressionSettings.put("maxQualityReductionPercentage", 50); // default to 50%

    return compressionSettings;
  }

  /**
   * Compress image using chosen compression algorithm and save to output path.
   */
  public static void compressImage(Mat inputMat, Map<String, Object> compressionSettings, String outputPath) {
    // Choose compression algorithm based on file format and compression settings
    String fileFormat = (String)compressionSettings.get("fileFormat");
    double targetFileSize = (double)compressionSettings.get("targetFileSize");
    double maxQualityReductionPercentage = (double)compressionSettings.get("maxQualityReductionPercentage");
    if ("jpg".equals(fileFormat)) {
      compressJpegImage(inputMat, compressionSettings, outputPath);
    } else if ("png".equals(fileFormat)) {
      compressPngImage(inputMat, compressionSettings, outputPath);
    } else if ("bmp".equals(fileFormat)) {
      compressBmpImage(inputMat, compressionSettings, outputPath);
    }
  }

  /**
   * Compress JPEG image using lossy compression and save to output path.
   */
  public static void compressJpegImage(Mat inputMat, Map<String, Object> compressionSettings, String outputPath) {
    // Convert OpenCV Mat object to BufferedImage for compression
    BufferedImage inputImage = matToBufferedImage(inputMat);

    // Set JPEG compression parameters based on compression settings
    int quality = 100 - (int)(maxQualityReductionPercentage * 100 / 2); // default to 50%
    ImageWriter writer = new ImageIO.getImageWritersByFormatName("jpeg").next();
    ImageWriteParam writeParams = writer.getDefaultWriteParam();
    writeParams.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
    writeParams.setCompressionQuality(quality / 100f); // range [0, 1]

    // Write compressed image to output path
    File outputFile = new File(outputPath);
    ImageOutputStream outputStream = null;
    try {
      outputStream = new FileImageOutputStream(outputFile);
      writer.setOutput(outputStream);
      IIOImage ioImage = new IIOImage(inputImage, null, null);
      writer.write(null, ioImage, writeParams);
      outputStream.close();
    } catch (IOException e) {
      System.err.println("Error writing compressed JPEG image to file: " + e.getMessage());
    } finally {
      if (outputStream != null) {
        try {
