// Semaphore management functions

struct semaphore {
    int value;
    pthread_mutex_t lock;
};

int create_semaphore(const char *name) {
    struct semaphore *sema = malloc(sizeof(struct semaphore));
    sema->value = 0;
    pthread_mutex_init(&sema->lock, NULL);
    return 0;
}

int delete_semaphore(const char *name) {
    struct semaphore *sema = malloc(sizeof(struct semaphore));
    pthread_mutex_destroy(&sema->lock);
    free(sema);
    return 0;
}

int increment_semaphore(const char *name) {
    struct semaphore *sema = malloc(sizeof(struct semaphore));
    pthread_mutex_lock(&sema->lock);
    sema->value++;
    pthread_mutex_unlock(&sema->lock);
    return 0;
}

int decrement_semaphore(const char *name) {
    struct semaphore *sema = malloc(sizeof(struct semaphore));
    pthread_mutex_lock(&sema->lock);
    sema->value--;
    pthread_mutex_unlock(&sema->lock);
    return 0;
}

