function createClinic($dbConnection, $clinicName) {
  // Check if clinic name is unique and within character limit
  $query = "SELECT COUNT(*) AS total FROM clinics WHERE name = :name";
  $statement = $dbConnection->prepare($query);
  $statement->bindParam(':name', $clinicName, PDO::PARAM_STR);
  $statement->execute();
  if ($statement->fetchColumn() > 0) {
    return false;
  }

  // Insert new clinic record into database
  $query = "INSERT INTO clinics (name, status, location, capacity) VALUES (:name, :status, :location, :capacity)";
  $statement = $dbConnection->prepare($query);
  $statement->bindParam(':name', $clinicName, PDO::PARAM_STR);
  $statement->bindParam(':status', 'open', PDO::PARAM_STR);
  $statement->bindParam(':location', 'Unknown', PDO::PARAM_STR);
  $statement->bindParam(':capacity', 10, PDO::PARAM_INT);
  $statement->execute();

  // Get clinic ID and return success
  $query = "SELECT id FROM clinics WHERE name = :name";
  $statement = $dbConnection->prepare($query);
  $statement->bindParam(':name', $clinicName, PDO::PARAM_STR);
  $statement->execute();
  return $statement->fetchColumn();
}

function updateClinic($dbConnection, $clinicName, $status, $lastModifiedIpAddress, $lastModifiedDate) {
  // Check if clinic exists and is within character limit
  $query = "SELECT COUNT(*) AS total FROM clinics WHERE name = :name";
  $statement = $dbConnection->prepare($query);
  $statement->bindParam(':name', $clinicName, PDO::PARAM_STR);
  $statement->execute();
  if ($statement->fetchColumn() == 0) {
    return false;
  }

  // Update clinic record in database
  $query = "UPDATE clinics SET status = :status, last_modified_ip_address = :lastModifiedIpAddress, last_modified_date = :lastModifiedDate WHERE name = :name";
  $statement = $dbConnection->prepare($query);
  $statement->bindParam(':status', $status, PDO::PARAM_STR);
  $statement->bindParam(':lastModifiedIpAddress', $lastModifiedIpAddress, PDO::PARAM_STR);
  $statement->bindParam(':lastModifiedDate', $lastModifiedDate, PDO::PARAM_STR);
  $statement->bindParam(':name', $clinicName, PDO::PARAM_STR);
  $statement->execute();

  // Return success
  return true;
}

function deleteClinic($dbConnection, $clinicName) {
  // Check if clinic exists and is within character limit
  $query = "SELECT COUNT(*) AS total FROM clinics WHERE name = :name";
  $statement = $dbConnection->prepare($query);
  $statement->bindParam(':name', $clinicName, PDO::PARAM_STR);
  $statement->execute();
  if ($statement->fetchColumn() == 0) {
    return false;
