  // Delete clinic record from database
  $query = "DELETE FROM clinics WHERE name = :name";
  $statement = $dbConnection->prepare($query);
  $statement->bindParam(':name', $clinicName, PDO::PARAM_STR);
  $statement->execute();

  // Return success
  return true;
}
