const asyncReduceArray = (array, initialValue, callback) => {
  return new Promise((resolve, reject) => {
    let result = initialValue;
    array.forEach((num, i) => {
      setTimeout(() => {
        const accumulator = result + num;
        if (accumulator < 0) {
          // Handle negative numbers by resetting the accumulator to 0
          accumulator = 0;
        }
        result = callback(accumulator, num);
      }, i * 100);
    });
    resolve(result);
  });
};

