const combineCertificates = (transactions) => {
  return new Promise((resolve, reject) => {
    const combinedCertificate = [];
    transactions.forEach(transaction => {
      if (transaction.certificate && transaction.certificate.length > 0) {
        combinedCertificate.push(...transaction.certificate);
      }
    });
    resolve(combinedCertificate);
  });
};

const validateCertificates = (combinedCertificate) => {
  return new Promise((resolve, reject) => {
    if (combinedCertificate.length === 0) {
      reject(new Error('No certificates found'));
    } else {
      combinedCertificate.forEach(certificate => {
        if (!validateCertificate(certificate)) {
          reject(new Error(`Invalid certificate: ${JSON.stringify(certificate)}`));
        }
      });
      resolve(combinedCertificate);
    }
  });
};

