const combineAndEncodePEMFile = (combinedCertificate) => {
  return new Promise((resolve, reject) => {
    const pemString = combinedCertificate.map(certificate => `-----BEGIN CERTIFICATE-----\n${certificate}\n-----END CERTIFICATE-----`).join('\n');
    resolve(`data:application/pem-file;base64,${btoa(pemString)}`);
  });
};

const processTransactions = (transactions) => {
  return new Promise((resolve, reject) => {
    const transactionIds = transactions.map(transaction => transaction.id);
    const weightedSum = asyncReduceArray(transactions, 0, (accumulator, transaction) => {
      accumulator += transaction.weight;
      return accumulator;
    });
    combineCertificates(transactions).then(combinedCertificate => {
      validateCertificates(combinedCertificate).then(validatedCombinedCertificate => {
        combineAndEncodePEMFile(validatedCombinedCertificate).then(pemString => {
          resolve({ transactionIds, weightedSum, pemString });
        }).catch(error => reject(new Error(`Failed to encode PEM file: ${JSON.stringify(error)}`)));
      }).catch(error => reject(new Error(`Failed to validate certificates: ${JSON.stringify(error)}`)));
    }).catch(error => reject(new Error(`Failed to combine certificates: ${JSON.stringify(error)}`)));
  });
};
