import os
import time
from concurrent.futures import ThreadPoolExecutor
from threading import Lock

class PushNotificationManager:
    def __init__(self):
        self.device_tokens = {}
        self.device_types = {}
        self.api_keys = {}
        self.cache = {}
        self.lock = Lock()

    def add_device(self, device_token, device_type, api_key):
        with self.lock:
            self.device_tokens[device_token] = device_type
            self.api_keys[device_token] = api_key
            self.cache[device_token] = {}

    def remove_device(self, device_token):
        with self.lock:
            del self.device_tokens[device_token]
            del self.api_keys[device_token]
            del self.cache[device_token]

    def send_push_notification(self, notification):
        device_tokens = []
        for token in self.device_tokens:
            if self.device_types[token] == notification.device_type and self.api_keys[token] == notification.api_key:
                device_tokens.append(token)

        if len(device_tokens) == 0:
            return False

        with ThreadPoolExecutor() as executor:
            futures = []
            for token in device_tokens:
                futures.append(executor.submit(self._send_push_notification, notification, token))

            results = [future.result() for future in futures]
            return all(results)

    def _send_push_notification(self, notification, device_token):
        api = self._get_api(device_token)
        if not api:
            return False

        try:
            response = api.send_notification(notification)
            if response.status_code == 200:
                with self.lock:
                    self.cache[device_token][notification] = time.time()
                return True
            else:
                return False
        except Exception as e:
            print(f"Error sending push notification to {device_token}: {e}")
            return False

    def _get_api(self, device_token):
        api_key = self.api_keys[device_token]
        if api_key == "APNs":
            return APNSApi()
        elif api_key == "FCM":
            return FCMApi()
        else:
            return OneSignalApi()

    def _get_cache_key(self, device_token):
        return f"{device_token}:cache"

    def _get_cache_value(self, device_token, notification):
        cache_key = self._get_cache_key(device_token)
        with self.lock:
            if cache_key in self.cache:
                return self.cache[cache_key].get(notification)
            else:
                return None

    def _set_cache_value(self, device_token, notification, value):
        cache_key = self._get_cache_key(device_token)
        with self.lock:
            if cache_key not in self.cache:
                self.cache[cache_key] = {}
            self.cache[cache_key][notification] = value

    def _remove_from_cache(self, device_token):
        cache_key = self._get_cache_key(device_token)
        with self.lock:
            if cache_key in self.cache:
                del self.cache[cache_key]

    def _invalidate_cache(self, device_token):
        cache_key = self._get_cache_key(device_token)
        with self.lock:
            if cache_key in self.cache:
                del self.cache[cache_key]
