#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>

// Define the structure to store HTTP request information
typedef struct {
    char *ip_address;
    time_t request_time;
    int response_status_code;
} http_request_info;

// Function to read and process a chunk of the log file
void process_chunk(char *filepath, size_t chunk_size) {
    // Open the log file for reading
    FILE *fp = fopen(filepath, "r");
    if (fp == NULL) {
        printf("Error opening file: %s\n", strerror(errno));
        return;
    }

    // Allocate memory for a line buffer
    char *line_buffer = malloc(chunk_size);
    if (line_buffer == NULL) {
        printf("Error allocating memory for line buffer: %s\n", strerror(errno));
        return;
    }

    // Read the next chunk of the log file into the line buffer
    size_t bytes_read = fread(line_buffer, 1, chunk_size, fp);
    if (bytes_read == 0) {
        printf("Error reading from file: %s\n", strerror(errno));
        return;
    }

    // Process each line in the chunk
    char *line = line_buffer;
    while (line < line_buffer + bytes_read) {
        // Skip over blank lines
        if (*line == '\n' || *line == '\r') {
            line++;
            continue;
        }

        // Allocate memory for the current request information
        http_request_info *req = malloc(sizeof(http_request_info));
        if (req == NULL) {
            printf("Error allocating memory for HTTP request info: %s\n", strerror(errno));
            return;
        }

        // Parse the current line and extract relevant information
        char *ip = strtok(line, " ");
        req->ip_address = ip;
        char *time = strtok(NULL, " ");
        req->request_time = atoi(time);
        char *status = strtok(NULL, " ");
        req->response_status_code = atoi(status);

        // Print the current request information in comma-separated format
        printf("%s,%ld,%d\n", req->ip_address, req->request_time, req->response_status_code);

        // Free the memory allocated for the current request information
        free(req);

        // Advance to the next line in the chunk
        line += strlen(line) + 1;
    }

    // Free the memory allocated for the line buffer
    free(line_buffer);

    // Close the log file
    fclose(fp);
}

// Function to handle potential errors during processing
void error_handler(char *message, int errno) {
    printf("Error: %s\n", message);
    printf("Error number: %d\n", errno);
    // Log the error to a separate file for further analysis
}

// Main function that processes the entire log file
int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <log_file_path>\n", argv[0]);
        return 1;
    }

    // Set the path to the log file
    char *filepath = argv[1];

    // Define the chunk size for reading the log file
    size_t chunk_size = 1024 * 1024; // 1 MB

    // Process each chunk of the log file
    while (process_chunk(filepath, chunk_size));

    return 0;
}
