// CombatManager.cpp
#include "CombatManager.h"
#include "Attack.h"
#include <algorithm>

CombatManager::CombatManager(std::shared_ptr<Character> character, std::shared_ptr<WeatherService> weatherService) {
    m_character = character;
    m_weatherService = weatherService;
}

void CombatManager::selectAttack() {
    // Lock attack mutex to prevent race conditions in high-concurrency combat scenarios
    std::lock_guard<std::mutex> lock(m_character->getAttackMutex());

    // Get current weather data
    bool isRaining = m_weatherService->isRaining();
    float windSpeed = m_weatherService->getWindSpeed();

    // Select an attack based on the character's state and environmental conditions
    std::vector<std::unique_ptr<Attack>> attacks = m_character->getAttacks();
    Attack* selectedAttack = nullptr;
    for (auto& attack : attacks) {
        if (!attack->isOnCooldown()) {
            // Check attack effectiveness based on weather conditions
            bool isEffectiveAgainstRainingWeather = attack->getDamage() > 0 && isRaining;
            bool isEffectiveAgainstHighWindWeather = attack->getDamage() > 0 && windSpeed > 2.0f;
            if (isEffectiveAgainstRainingWeather || isEffectiveAgainstHighWindWeather) {
                selectedAttack = attack.get();
                break;
            }
        }
    }

    // Default to a non-attack action if all attacks are on cooldown
    if (selectedAttack == nullptr) {
        m_character->setEnergy(m_character->getEnergy() - 1);
    } else {
        selectedAttack->performAttack();
    }
}

#endif // COMBATMANAGER_H

class ImageConverter {
private:
    std::string inputFilePath;
    std::string outputFilePath;
    FormatType formatType;
    int qualityLevel;
    bool isConverting = false;
    std::vector<std::thread> conversionThreads;
    std::mutex conversionMutex;
    std::condition_variable conversionCV;
    std::unordered_map<std::string, ImageMetadata> metadataMap;
    int ongoingConversions = 0;
    int maxConcurrentConversions = 10;
public:
    ImageConverter(const std::string& inputFilePath, const std::string& outputFilePath, FormatType formatType) :
        inputFilePath(inputFilePath),
        outputFilePath(outputFilePath),
        formatType(formatType) {}

    ~ImageConverter() {
        if (isConverting) {
            cancelConversions();
        }
    }

    void convertAndSave(const std::string& inputFilePath, const std::string& outputFilePath, FormatType formatType, int qualityLevel = 80) {
        std::lock_guard<std::mutex> lock(conversionMutex);

        // Check if there are any ongoing conversions and block until all of them complete
        while (ongoingConversions > 0) {
            conversionCV.wait(lock);
        }

        // Increment the number of ongoing conversions
        ++ongoingConversions;

        // Create a new thread to handle the conversion
        conversionThreads.emplace_back([this, inputFilePath, outputFilePath, formatType, qualityLevel]() {
            try {
                // Perform the actual conversion using an external library (e.g., ImageMagick)
                convertImage(inputFilePath, outputFilePath, formatType, qualityLevel);
            } catch (const std::exception& e) {
                // Log the error and decrement the number of ongoing conversions if an exception is thrown
                std::cerr << "Error during conversion: " << e.what() << std::endl;
                --ongoingConversions;
            }

            // Notify all waiting threads that a conversion has completed
            conversionCV.notify_all();
        });
    }

    void cancelConversions() {
        std::lock_guard<std::mutex> lock(conversionMutex);

        // Stop all ongoing conversions and join the corresponding threads
        for (auto& thread : conversionThreads) {
            if (thread.joinable()) {
                thread.detach();
            }
        }

        // Reset the number of ongoing conversions to 0
        ongoingConversions = 0;
    }

    std::string getConversionStatus() const {
        if (isConverting) {
            return "Conversion in progress";
        } else {
            return "Idle";
        }
    }

    void reportProgress(int percentage, const std::string& statusMessage = "") {
        // Implement a method to report the current conversion progress and any intermediate status messages
    }

    int getOngoingConversions() const {
        return ongoingConversions;
    }

    void setMaxConcurrentConversions(int maxConcurrentConversions) {
        this->maxConcurrentConversions = maxConcurrentConversions;
    }

    std::unordered_map<std::string, ImageMetadata> getMetadataMap() const {
        return metadataMap;
    }

private:
    void convertImage(const std::string& inputFilePath, const std::string& outputFilePath, FormatType formatType, int qualityLevel) {
        // Perform the conversion using an external library (e.g., ImageMagick) and save the resulting image to disk
    }

    void extractMetadata(const std::string& inputFilePath) {
        // Implement a method to extract metadata from the input file (e.g., EXIF data)
    }
};

ImageConverter::ImageConverter(const std::string& inputFilePath, const std::string& outputFilePath, FormatType formatType) :
