// Define a caching mechanism for Bible references
const bibleReferenceCache = {};

async function fetchBibleReference(ref) {
  const cacheKey = ref;
  if (bibleReferenceCache[cacheKey]) {
    return bibleReferenceCache[cacheKey];
  }
  const url = new URL(`${BIBLE_API_URL}/references/${ref}`);
  const options = {};
  try {
    const response = await https.request(url, options);
    if (response.statusCode === 200) {
      const data = await response.json();
      bibleReferenceCache[cacheKey] = data;
      return data;
    } else {
      throw new Error(`${response.statusCode}: ${response.statusMessage}`);
    }
  } catch (error) {
    logger.error(error);
    throw error;
  }
}

// Define a HTTP client for fetching data from external APIs
class HttpClient {
  constructor(options = {}) {
    this.url = options.url || '';
    this.method = options.method || 'GET';
    this.headers = options.headers || {};
    this.certificateValidation = options.certificateValidation || false;
    this.timeout = options.timeout || TIMEOUT;
  }

  async fetch(url, options) {
    const fullUrl = `${this.url}${url}`;
    const requestOptions = {
      ...options,
      method: this.method,
      headers: this.headers,
      timeout: this.timeout,
      cert: this.certificateValidation ? options.cert : undefined,
      key: this.certificateValidation ? options.key : undefined,
      ca: this.certificateValidation ? options.ca : undefined,
    };
    const startTime = Date.now();
    try {
      const response = await http.request(fullUrl, requestOptions);
      if (response.statusCode === 200) {
        logger.info(`Fetched ${fullUrl} in ${Date.now() - startTime}ms`);
        return response;
      } else {
        throw new Error(`${response.statusCode}: ${response.statusMessage}`);
      }
    } catch (error) {
      logger.error(`Failed to fetch ${fullUrl}: ${error}`);
      throw error;
    }
  }
}

