#include <iostream>
#include <fstream>
#include <nlohmann/json.hpp>
#include <memory>
#include <set>

class NetworkDeviceSettings {
public:
    NetworkDeviceSettings(const std::string& file_path) : settings_(nullptr), observers_() {
        load_settings(file_path);
    }

    ~NetworkDeviceSettings() = default;

    void add_observer(std::function<void(const nlohmann::json&)> observer) {
        observers_.insert(observer);
    }

    void notify_observers() {
        for (auto& observer : observers_) {
            observer(settings_);
        }
    }

    const nlohmann::json& get_setting(const std::string& key) {
        auto it = settings_.find(key);
        if (it == settings_.end()) {
            throw std::runtime_error("Setting not found: " + key);
        }
        return it->second;
    }

    void set_setting(const std::string& key, const nlohmann::json& value) {
        auto it = settings_.find(key);
        if (it == settings_.end()) {
            throw std::runtime_error("Setting not found: " + key);
        }
        it->second = value;
    }

    void save_settings() {
        std::ofstream ofs(file_path_, std::ios::trunc);
        if (!ofs.good()) {
            throw std::runtime_error("Failed to open settings file for writing: " + file_path_);
        }
        ofs << std::setw(4) << settings_;
    }

private:
    void load_settings(const std::string& file_path) {
        std::ifstream ifs(file_path, std::ios::binary);
        if (!ifs.good()) {
            throw std::runtime_error("Failed to open settings file for reading: " + file_path);
        }
        nlohmann::json j;
        try {
            ifs >> j;
        } catch (nlohmann::json::parse_error& e) {
            throw std::runtime_error("Failed to parse settings file: " + file_path + ", error: " + e.what());
        }
        settings_ = j;
    }

    std::string file_path_;
    nlohmann::json settings_;
    std::set<std::function<void(const nlohmann::json&)>> observers_;
};
