using System;
using System.Security.Cryptography;
using System.Text;

namespace DecryptionAndValidation
{
    public class TripleDesDecrypter
    {
        private const string Key = "YourKeyHere";
        private const string Iv = "YourIvHere";

        public static string Decrypt(string message)
        {
            try
            {
                byte[] decryptedMessage = TripleDes.Decrypt(message, Encoding.UTF8.GetBytes(Key), Encoding.UTF8.GetBytes(Iv));
                return Encoding.UTF8.GetString(decryptedMessage);
            }
            catch (Exception ex)
            {
                throw new AuthenticationException("Invalid message or key/IV", ex);
            }
        }

        public static void Validate(string decryptedMessage)
        {
            try
            {
                string hash = Hmac.Hash(decryptedMessage, Encoding.UTF8.GetBytes(Key));
                if (hash != decryptedMessage)
                {
                    throw new AuthenticationException("Invalid message or key/IV");
                }
            }
            catch (Exception ex)
            {
                throw new AuthenticationException("Invalid message or key/IV", ex);
            }
        }
    }
}
