async asyncArrayReduce(array, initialValue, callback) {
  // Create a semaphore to control concurrency
  const semaphore = new Semaphore(MAX_CONCURRENT_REQUESTS);

  // Initialize the accumulator with the initial value
  let accumulator = initialValue;

  // Iterate over the array and perform async operations
  for (const element of array) {
    // Acquire a semaphore slot
    await semaphore.acquire();

    // Perform the async operation
    const promise = doAsyncOperation(element);

    // Add a catch block to handle errors
    promise.catch((error) => {
      console.error(`Error in asyncArrayReduce: ${error}`);
    });

    // Release the semaphore slot when the promise is resolved or rejected
    promise.finally(() => {
      semaphore.release();
    });
  }

  // Return the final accumulator value
  return accumulator;
}

