import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.context.annotation.Bean;
import org.springframework.scheduling.annotation.EnableScheduling;
import org.springframework.scheduling.annotation.Scheduled;

import com.google.common.base.Stopwatch;
import com.google.common.cache.CacheBuilder;
import com.google.common.cache.CacheLoader;
import com.google.common.cache.LoadingCache;

@SpringBootApplication
@EnableScheduling
public class WeatherDataAggregator {

  @Autowired
  private WeatherApiService weatherApiService;

  @Bean
  public LoadingCache<String, String> cache() {
    return CacheBuilder.newBuilder()
        .expireAfterWrite(10, TimeUnit.MINUTES)
        .maximumSize(1000)
        .build(new CacheLoader<String, String>() {
          @Override
          public String load(String key) throws Exception {
            return weatherApiService.getWeatherData(key);
          }
        });
  }

  @Cacheable("weather-data")
  public String getWeatherData(String location) {
    Stopwatch stopwatch = Stopwatch.createStarted();
    try {
      return cache().get(location);
    } finally {
      stopwatch.stop();
      System.out.println("Get weather data for " + location + ": " + stopwatch.elapsed(TimeUnit.MILLISECONDS) + "ms");
    }
  }

  @Scheduled(fixedDelay = 300000, initialDelay = 15000)
  public void updateWeatherData() {
    Stopwatch stopwatch = Stopwatch.createStarted();
    try {
      for (String location : cache().asMap().keySet()) {
        weatherApiService.getWeatherData(location);
      }
    } finally {
      stopwatch.stop();
      System.out.println("Update weather data: " + stopwatch.elapsed(TimeUnit.MILLISECONDS) + "ms");
    }
  }

}
