import time

    def exponential_backoff(attempts):
        min_wait = 1
        max_wait = 32
        factor = 2
        return min_wait + random.uniform(0, factor) * (max_wait - min_wait)

    def handle_api_failure(response, error_message):
        if response.status_code == 429:
            # Too many requests
            time.sleep(exponential_backoff(attempts))
            return True
        elif response.status_code == 503:
            # Service unavailable
            time.sleep(exponential_backoff(attempts))
            return True
        else:
            print(error_message)
            return False

    def record_transaction(record_type, transaction_details):
        if record_type == "database":
            try:
                database_manager.record_transaction(transaction_id, details)
            except Exception as e:
                print("Failed to record transaction in database", e)
                return False
        elif record_type == "logfile":
            try:
                log_file_manager.record_transaction(transaction_id, details)
            except Exception as e:
                print("Failed to record transaction in log file", e)
                return False
        else:
            raise ValueError("Invalid record type")

