        if response.status_code == 200:
            break
        elif handle_api_failure(response, "Failed to verify transaction"):
            continue
        else:
            return False
    if should_record:
        record_type = config["record_type"]
        try:
            record_transaction(record_type, transaction_details)
        except Exception as e:
            print("Failed to record transaction", e)
            return False
    return True
