import json
from typing import Dict, List

class Resource:
    def __init__(self, id: str, data: Dict[str, any]):
        self.id = id
        self.data = data

    @staticmethod
    def from_dict(d: Dict[str, any]) -> "Resource":
        return Resource(d["id"], d["data"])

    def to_dict(self) -> Dict[str, any]:
        return {"id": self.id, "data": self.data}

class UpdateResourceRequest:
    def __init__(self, id: str, data: Dict[str, any]):
        self.id = id
        self.data = data

    @staticmethod
    def from_dict(d: Dict[str, any]) -> "UpdateResourceRequest":
        return UpdateResourceRequest(d["id"], d["data"])

    def to_dict(self) -> Dict[str, any]:
        return {"id": self.id, "data": self.data}

class DeleteResourceRequest:
    def __init__(self, id: str):
        self.id = id

    @staticmethod
    def from_dict(d: Dict[str, any]) -> "DeleteResourceRequest":
        return DeleteResourceRequest(d["id"])

    def to_dict(self) -> Dict[str, any]:
        return {"id": self.id}

class ResourceService:
    def __init__(self, db: Dict[str, List[Dict[str, any]]]):
        self.db = db

    def update_resource(self, request: UpdateResourceRequest) -> Resource:
        resource = self.get_resource(request.id)
        if not resource:
            raise ValueError("Invalid ID")
        resource.data = request.data
        return resource

    def delete_resource(self, request: DeleteResourceRequest) -> Resource:
        resource = self.get_resource(request.id)
        if not resource:
            raise ValueError("Invalid ID")
        resource.data = {"deleted": True}
        return resource

    def get_resource(self, id: str) -> Resource:
        resources = self.db[id]
        if not resources:
            return None
        return Resource.from_dict(resources[0])

class AuthenticationService:
    def __init__(self, db: Dict[str, List[Dict[str, any]]], auth_service):
        self.db = db
        self.auth_service = auth_service

    def validate_user_permissions(self, request: UpdateResourceRequest) -> bool:
        user = self.auth_service.get_authenticated_user()
        if not user:
            return False
        resource = self.get_resource(request.id)
        if not resource:
            raise ValueError("Invalid ID")
        if resource.data["owner"] != user.username:
            return False
        return True

    def validate_user_permissions(self, request: DeleteResourceRequest) -> bool:
        user = self.auth_service.get_authenticated_user()
        if not user:
            return False
        resource = self.get_resource(request.id)
        if not resource:
            raise ValueError("Invalid ID")
        if resource.data["owner"] != user.username:
            return False
        return True

class CacheService:
    def __init__(self, db: Dict[str, List[Dict[str, any]]], cache):
        self.db = db
        self.cache = cache

    def get_resource(self, id: str) -> Resource:
        resources = self.db[id]
        if not resources:
            return None
        resource = Resource.from_dict(resources[0])
        self.cache.set(id, json.dumps(resource))
        return resource

class SoftDeleteService:
    def __init__(self, db: Dict[str, List[Dict[str, any]]]):
        self.db = db

    def delete_resource(self, request: DeleteResourceRequest) -> Resource:
        resource = self.get_resource(request.id)
        if not resource:
            raise ValueError("Invalid ID")
        resource.data["deleted"] = True
        return resource

class LoggingService:
    def __init__(self, db: Dict[str, List[Dict[str, any]]], logging):
        self.db = db
        self.logging = logging

    def log_request(self, request: UpdateResourceRequest) -> None:
        resource = self.get_resource(request.id)
        if not resource:
            raise ValueError("Invalid ID")
        self.logging.info(f"User {resource.data['owner']} updated resource {request.id}")

    def log_request(self, request: DeleteResourceRequest) -> None:
        resource = self.get_resource(request.id)
        if not resource:
            raise ValueError("Invalid ID")
        self.logging.info(f"User {resource.data['owner']} deleted resource {request.id}")

class ValidationService:
    def __init__(self, db: Dict[str, List[Dict[str, any]]]):
        self.db = db

    def validate_request(self, request: UpdateResourceRequest) -> None:
        if not isinstance(request.data, dict):
            raise ValueError("Invalid data type")
        for key, value in request.data.items():
            if not isinstance(value, (str, int, float)):
                raise ValueError("Invalid data format")

    def validate_request(self, request: DeleteResourceRequest) -> None:
        if not isinstance(request.id, str):
            raise ValueError("Invalid ID type")

class ResourceController:
    def __init__(self, resource_service: ResourceService, authentication_service: AuthenticationService, cache_service: CacheService, soft_delete_service: SoftDeleteService, logging_service: LoggingService, validation_service: ValidationService):
        self.resource_service = resource_service
        self.authentication_service = authentication_service
        self.cache_service = cache_service
        self.soft_delete_service = soft_delete_service
        self.logging_service = logging_service
        self.validation_service = validation_service

    def update_resource(self, request: UpdateResourceRequest) -> Resource:
        self.authentication_service.validate_user_permissions(request)
        self.validation_service.validate_request(request)
        resource = self.resource_service.update_resource(request)
        self.cache_service.get_resource(resource.id)
        self.logging_service.log_request(request)
        return resource

    def delete_resource(self, request: DeleteResourceRequest) -> Resource:
        self.authentication_service.validate_user_permissions(request)
        self.validation_service.validate_request(request)
        resource = self.soft_delete_service.delete_resource(request)
        self.cache_service.get_resource(resource.id)
        self.logging_service.log_request(request)
        return resource
```
In this example, we have a `ResourceController` class that handles the requests for updating and deleting resources. It takes several services as dependencies in its constructor: `ResourceService`, `AuthenticationService`, `CacheService`, `SoftDeleteService`, `LoggingService`, and `ValidationService`. These services are used to perform the actual work of updating and deleting resources, as well as logging the requests and validating the data.

The `ResourceController` class has two methods: `update_resource` and `delete_resource`. Both of these methods take a `Request` object as an argument, which contains the necessary information to perform the operation. The `update_resource` method uses the `ResourceService` to update the resource, and then uses the `CacheService` and `LoggingService` to update the cache and log the request. Similarly, the `delete_resource` method uses the `SoftDeleteService` to delete the resource, and then uses the `CacheService` and `LoggingService` to update the cache and log the request.

The `ResourceController` class also has two dependencies: `AuthenticationService` and `ValidationService`. These services are used to validate the user's permissions to perform the operation, as well as validate the data passed in the request. If the validation fails, an error is raised and handled by the calling code.

The `ResourceController` class is designed to be highly configurable and extensible. It can be easily integrated with any existing application or framework, and can be customized to fit the specific needs of the application. Additionally, it provides a clear separation of concerns between the business logic and the technical implementation details, making it easier to test and maintain.

