class ReligiousTextAnalyzer {
  constructor(customRegexes = null) {
    this.books = {
      Bible: /(\b[Bb][Ii][Bb][Ll][Ee]\b)/gi,
      Quran: /(\b[Qq][Uu][Rr][Aa][Nn]\b)/gi,
      Torah: /(\b[Tt][Oo][Rr][Aa][Hh]\b)/gi,
      Vedas: /(\b[Vv][Ee][Dd][Aa][Ss]\b)/gi
    }
    this.regexes = customRegexes || {};
  }

  extractBookNames(text) {
    if (!text || typeof text !== 'string') return [];
    let matches = [];
    for (let [book, regex] of Object.entries(this.books)) {
      const foundMatches = text.match(regex);
      if (foundMatches) matches.push(...foundMatches);
    }
    return matches;
  }

  categorizeBooks(matches) {
    const bookCounts = {};
    for (const match of matches) {
      const bookName = this.getBookName(match);
      if (!bookCounts[bookName]) bookCounts[bookName] = 0;
      bookCounts[bookName]++;
    }
    return bookCounts;
  }

  getBookName(match) {
    const [bookName] = match.split('/');
    return bookName.toLowerCase();
  }

  async verifyExistenceInDatabase(bookNames, externalApi) {
    try {
      const response = await externalApi.get(`/books/${bookNames.join(',')}`);
      if (response.status === 200) return true;
      else throw new Error('Invalid response');
    } catch (error) {
      console.log(error);
      return false;
    }
  }

  async analyzeText(text, externalApi = null) {
    const matches = this.extractBookNames(text);
    const bookCounts = this.categorizeBooks(matches);
    if (externalApi) {
      const bookNames = Object.keys(bookCounts).join(',');
      const isValid = await this.verifyExistenceInDatabase(bookNames, externalApi);
      if (!isValid) throw new Error('Invalid books in database');
    }
    return bookCounts;
  }

  async runTests() {
    const moduleLabel = 'ReligiousTextAnalyzer';
    const testLabels = [
      'Test 1: Verify existence of Bible, Quran, Torah, and Vedas',
      'Test 2: Verify absence of non-existent books',
      'Test 3: Verify case sensitivity',
      'Test 4: Verify punctuation handling'
    ];
    const testFunctions = [
      this.verifyExistenceInDatabase(['Bible', 'Quran', 'Torah', 'Vedas']),
      this.verifyExistenceInDatabase(['Book1', 'Book2', 'Book3']),
      this.verifyCaseSensitivity(),
      this.verifyPunctuationHandling()
    ];
    try {
      const results = [];
      for (const [testLabel, testFunction] of Object.entries(testFunctions)) {
        await blueslip.mock('info', () => {});
        const result = await testFunction();
        console.log(`${moduleLabel} - ${testLabel}:`, result);
        results.push(result);
      }
    } catch (error) {
      console.log(error);
    } finally {
      blueslip.resetMocks();
    }
    return results;
  }
}
```
