// WeatherDataFetcher.js
const axios = require('axios');
const logger = require('./logger');

class WeatherDataFetcher {
  constructor(apiKeys, cache) {
    this.apiKeys = apiKeys;
    this.cache = cache;
  }

  async fetchWeatherData(location) {
    const currentTime = Date.now();
    const keyRotationInterval = 12 * 60 * 60 * 1000; // 12 hours in milliseconds
    let apiKey = this.apiKeys[0];
    if (this.cache.has(location)) {
      const cachedData = this.cache.get(location);
      if (currentTime - cachedData.timestamp < keyRotationInterval) {
        return cachedData.data;
      } else {
        apiKey = this.rotateApiKeys();
      }
    }

    try {
      const response = await axios.get(`https://weather-api.com/${location}?key=${apiKey}`);
      if (response.status === 200) {
        const weatherData = this.processWeatherData(response.data);
        this.cache.set(location, { data: weatherData, timestamp: currentTime });
        return weatherData;
      } else {
        throw new Error(`${response.status} ${response.statusText}`);
      }
    } catch (error) {
      logger.warn(`Failed to fetch weather data for location ${location}: ${error.message}`);
      return null;
    }
  }

  rotateApiKeys() {
    const nextKeyIndex = this.apiKeys.findIndex((key, index) => index + 1 < this.apiKeys.length && key === this.apiKeys[index + 1]);
    if (nextKeyIndex >= 0) {
      return this.apiKeys[nextKeyIndex + 1];
    } else {
      return this.apiKeys[0];
    }
  }

  processWeatherData(weatherData) {
    // TODO: implement your own weather data processing logic here
    return {};
  }
}

module.exports = WeatherDataFetcher;
