Here is an example implementation of a C++ program that defines a class `SecureBinaryFileProcessor` and includes methods for reading a binary file, parsing its contents, and generating an output file based on a set of transformation rules:
```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <map>
#include <memory>
#include <stdexcept>
#include <utility>
#include <thread>
#include <chrono>

using namespace std;

class SecureBinaryFileProcessor {
private:
    ifstream input_file; // Input binary file stream
    ofstream output_file; // Output binary file stream
    map<string, function<void(const string&)>> factory_functions; // Registry of factory functions keyed by ID

public:
    SecureBinaryFileProcessor(const string& input_file_path, const string& output_file_path);
    ~SecureBinaryFileProcessor();

    void readInputFile();
    void parseInputData();
    void generateOutputFile();

    // Factory functions registry
    void registerFactoryFunction(const string& id, function<void(const string&)> factory_function);
    void unregisterFactoryFunction(const string& id);
    bool isFactoryFunctionRegistered(const string& id) const;

    // JSON schema validation
    bool validateJsonSchema(const string& json_schema, const string& json_data) const;

    // Logging
    void log(const string& message) const;
};

SecureBinaryFileProcessor::SecureBinaryFileProcessor(const string& input_file_path, const string& output_file_path) {
    input_file.open(input_file_path, ifstream::binary);
    output_file.open(output_file_path, ofstream::binary);
}

SecureBinaryFileProcessor::~SecureBinaryFileProcessor() {
    input_file.close();
    output_file.close();
}

void SecureBinaryFileProcessor::readInputFile() {
    if (!input_file) {
        throw runtime_error("Error reading input file");
    }
    vector<char> buffer(1024 * 1024); // 1 MB buffer
    while (input_file.read(&buffer[0], buffer.size())) {
        for (auto& byte : buffer) {
            parseInputData(byte);
        }
    }
}

void SecureBinaryFileProcessor::parseInputData() {
    // Parse input data and store in a vector of strings
    vector<string> parsed_data;
    for (const auto& byte : buffer) {
        parsed_data.push_back(byte);
    }
}

void SecureBinaryFileProcessor::generateOutputFile() {
    if (!output_file) {
        throw runtime_error("Error generating output file");
    }
    for (const auto& data : parsed_data) {
        output_file << data;
    }
}

void SecureBinaryFileProcessor::registerFactoryFunction(const string& id, function<void(const string&)> factory_function) {
    if (factory_functions.count(id)) {
        throw runtime_error("Duplicate factory function ID");
    }
    factory_functions[id] = move(factory_function);
}

void SecureBinaryFileProcessor::unregisterFactoryFunction(const string& id) {
    if (!factory_functions.count(id)) {
        throw runtime_error("Factory function not found");
    }
    factory_functions.erase(id);
}

bool SecureBinaryFileProcessor::isFactoryFunctionRegistered(const string& id) const {
    return factory_functions.count(id);
}

// JSON schema validation
bool SecureBinaryFileProcessor::validateJsonSchema(const string& json_schema, const string& json_data) const {
    // Implement JSON schema validation using a third-party library or write your own implementation
    return true;
}

// Logging
void SecureBinaryFileProcessor::log(const string& message) const {
    cout << message << endl;
}
```
