// JavaScript program that loads and executes multiple specified JavaScript files in the context of a web page, ensuring they are processed in the correct order and implementing error handling for each file load and execution
const fs = require('fs');
const path = require('path');
const http = require('http');
const https = require('https');
const url = require('url');
const { promisify } = require('util');

// Dynamic configuration management system
const configManager = {
  // List of files to load and execute
  fileList: [],

  // Add a new file to the list
  addFile: (filePath) => {
    this.fileList.push(filePath);
  },

  // Remove a file from the list
  removeFile: (filePath) => {
    const index = this.fileList.indexOf(filePath);
    if (index > -1) {
      this.fileList.splice(index, 1);
    }
  },

  // Get the current list of files to load and execute
  getFileList: () => {
    return this.fileList;
  },
};

// Method for processing a single file
const processFile = async (filePath) => {
  try {
    const content = await fs.promises.readFile(filePath, 'utf8');
    // Execute the file's JavaScript code in the context of the web page
    eval(content);
  } catch (error) {
    console.error(`Error processing file ${filePath}:`, error);
  }
};

// Method for processing a list of files
const processFileList = async () => {
  try {
    const filesToProcess = configManager.getFileList();
    for (const file of filesToProcess) {
      await processFile(file);
    }
  } catch (error) {
    console.error(`Error processing file list:`, error);
  }
};

// Method for handling HTTP requests to the web page
const handleRequest = async (req, res) => {
  try {
    // Process any dynamic updates to the file list
    configManager.processFileList();

    // Render the web page and execute any JavaScript code in it
    res.writeHead(200, { 'Content-Type': 'text/html' });
    res.end(`
      <html>
        <body>
          <!-- Execute the JavaScript code in this file -->
          <script src="./main.js"></script>
        </body>
      </html>
    `);
  } catch (error) {
    console.error('Error handling request:', error);
  }
};

// Start the web server and begin processing files
const server = http.createServer(handleRequest);
server.listen(8080, () => {
  console.log('Web server started on port 8080');
});
processFileList();
