import java.io.File;
  import java.util.concurrent.ConcurrentHashMap;
  import javax.xml.parsers.DocumentBuilder;
  import javax.xml.parsers.DocumentBuilderFactory;
  import org.w3c.dom.Document;
  import org.w3c.dom.Element;
  import org.w3c.dom.NodeList;
  import java.io.FileNotFoundException;
  import java.util.regex.Matcher;
  import java.util.regex.Pattern;

  public class XMLMapUpdater {
    private static final Pattern KEY_PREFIX = Pattern.compile("^[a-zA-Z0-9]+$");
    private ConcurrentHashMap<String, String> map;
    private File xmlFile;
    private String keyPrefix;

    public XMLMapUpdater(ConcurrentHashMap<String, String> map, File xmlFile, String keyPrefix) {
      this.map = map;
      this.xmlFile = xmlFile;
      this.keyPrefix = keyPrefix;
    }

    public void updateMap() throws Exception {
      if (!KEY_PREFIX.matcher(this.keyPrefix).matches()) {
        throw new IllegalArgumentException("Invalid key prefix");
      }
      if (!xmlFile.exists()) {
        throw new FileNotFoundException("XML file does not exist");
      }

      DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
      DocumentBuilder db = dbf.newDocumentBuilder();
      Document doc = db.parse(this.xmlFile);
      Element root = doc.getDocumentElement();
      NodeList nodeList = root.getElementsByTagName("*");

      for (int i = 0; i < nodeList.getLength(); i++) {
        Element element = (Element) nodeList.item(i);
        String key = this.keyPrefix + element.getLocalName();
        String value = element.getTextContent().trim();
        map.put(key, value);
      }
    }
  }
  public void close() throws Exception {
    if (map != null) {
      map.clear();
    }
  }
}

