const net = require('net');
const redis = require('redis');
const logger = require('./logger');

class TcpServer {
  constructor() {
    this.server = new net.createServer();
    this.server.on('connection', this.handleConnection.bind(this));
    this.server.listen(3000, () => logger.info('TCP server started on port 3000'));
  }

  handleConnection(socket) {
    // Handle incoming connection
    socket.on('data', (data) => {
      // Process data received from the client
      const message = JSON.parse(data);
      // Cache the data for later use
      redis.set(`message:${message.id}`, JSON.stringify(message));
      logger.info(`Received message with id ${message.id}`);
    });
    socket.on('close', () => {
      // Handle client disconnection
      logger.info('Client disconnected');
    });
  }

  shutdown() {
    // Gracefully close all active connections before exiting
    this.server.close(() => {
      logger.info('TCP server closed');
      process.exit();
    });
  }
}

const redisClient = redis.createClient();
redisClient.on('error', (err) => {
  // Handle Redis client errors
