using System;
using System.Security.Cryptography;
using System.Threading.Tasks;

namespace MessageProcessor
{
    public class BatchMessageProcessor
    {
        private const string KEY = "your_key";
        private const string IV = "your_iv";

        private readonly HMACSHA256 _hmac = new HMACSHA256(Encoding.ASCII.GetBytes(KEY));

        public async Task ProcessBatchAsync(string[] messages)
        {
            var decryptedMessages = new List<DecryptedMessage>();

            foreach (var message in messages)
            {
                try
                {
                    // Decrypt the message using Triple DES with the given key and IV.
                    var cipherText = Convert.FromBase64String(message);
                    var plainText = await DecryptAsync(cipherText, KEY, IV);

                    // Validate the authenticity of the decrypted message using HMAC SHA256.
                    var mac = GenerateMac(plainText, KEY);
                    if (!ValidateMac(mac, plainText))
                    {
                        throw new InvalidOperationException("Authentication failure");
                    }

                    // Add the decrypted message to the list of decrypted messages.
                    decryptedMessages.Add(new DecryptedMessage(plainText));
                }
                catch (Exception e)
                {
                    // Log the error and continue processing other messages.
                    Console.WriteLine($"Error processing message: {e.Message}");
                }
            }

            // Send the list of decrypted messages to a message queue system like RabbitMQ.
            await SendMessagesAsync(decryptedMessages);
        }

        private async Task<byte[]> DecryptAsync(byte[] cipherText, string key, string iv)
        {
            using var des = new TripleDESCryptoServiceProvider();
            des.Key = Encoding.ASCII.GetBytes(key);
            des.IV = Encoding.ASCII.GetBytes(iv);
            return await Task.Run(() => des.CreateDecryptor().TransformFinalBlock(cipherText, 0, cipherText.Length));
        }

        private byte[] GenerateMac(string plainText, string key)
        {
            using var hmac = new HMACSHA256(Encoding.ASCII.GetBytes(key));
            return hmac.ComputeHash(Encoding.ASCII.GetBytes(plainText));
        }

        private bool ValidateMac(byte[] mac, string plainText)
        {
            var expectedMac = GenerateMac(plainText, KEY);
            return StructuralComparisons.StructuralEqualityComparer.Equals(mac, expectedMac);
        }

        private async Task SendMessagesAsync(List<DecryptedMessage> decryptedMessages)
        {
            // Implement logic to send the list of decrypted messages to a message queue system like RabbitMQ.
        }
    }

    public class DecryptedMessage
    {
        public string PlainText { get; set; }

        public DecryptedMessage(string plainText)
        {
            PlainText = plainText;
        }
    }
}
