import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import com.auth0.jwt.JWTVerifier;
import com.auth0.jwt.algorithms.Algorithm;
import redis.clients.jedis.JedisPool;
import redis.clients.jedis.JedisPoolConfig;

public class JWTValidator {
    private static final String REDIS_URL = "redis://localhost:6379";
    private static final JedisPool jedisPool = new JedisPool(new JedisPoolConfig(), REDIS_URL);

    // Map to store validated JWTs and their associated metadata
    private static final Map<String, Object> jwtMap = new ConcurrentHashMap<>();

    public void validateJWT(String jwt) {
        try (Jedis jedis = jedisPool.getResource()) {
            // Check if the JWT is already validated and cached in Redis
            String cacheKey = "jwt-" + jwt;
            Object cachedMetadata = jedis.hget(cacheKey, "metadata");
            if (cachedMetadata != null) {
                return;
            }

            // Load JWT configuration from file
            JSONObject configJson = new JSONObject(new FileReader("config.json"));
            String issuer = configJson.getString("issuer");
            String audience = configJson.getString("audience");
            String scope = configJson.getString("scope");

            // Create JWT verifier with specified issuer and audience
            Algorithm algorithm = Algorithm.HMAC256(configJson.getString("secret"));
            JWTVerifier verifier = JWTVerifier.init()
                .setIssuer(issuer)
                .setAudience(audience)
                .build();

            // Validate JWT and extract user information
            JSONObject payload = verifier.verify(jwt);
            String username = payload.getString("username");
            List<String> roles = payload.getJSONArray("roles").toList();
            Long expirationTime = payload.getLong("exp");

            // Store validated JWT and its metadata in Redis
            jedis.hset(cacheKey, "metadata", new JSONObject()
                .put("username", username)
                .put("roles", roles)
                .put("expirationTime", expirationTime));
        } catch (Exception e) {
            // Handle exception gracefully, including retries and fallback mechanisms
            e.printStackTrace();
        }
    }
}
