import threading
import time
from collections import deque
from typing import Dict, List

class SensorDataProcessor:
    def __init__(self, config: Dict[str, str]) -> None:
        self.config = config
        self.sensor_data_streams: Dict[str, Deque] = {}
        self.sensor_threads: Dict[str, threading.Thread] = {}
        self.event_detector = EventDetector(self.config)

    def start_processing(self) -> None:
        for sensor in self.config["sensors"]:
            sensor_stream = deque()
            self.sensor_data_streams[sensor] = sensor_stream
            thread = threading.Thread(target=self.process_sensor_data, args=(sensor, sensor_stream))
            thread.start()
            self.sensor_threads[sensor] = thread

    def process_sensor_data(self, sensor: str, stream: Deque) -> None:
        while True:
            data = stream.popleft()
            if not data:
                break
            self.event_detector.process_data(data)
            self.aggregate_data(sensor, data)

    def aggregate_data(self, sensor: str, data: Dict[str, Any]) -> None:
        for key in ["temperature", "humidity"]:
            if key in data:
                self.config["aggregation_methods"][key](sensor, data[key])

    def event_detection(self) -> List[Dict[str, Any]]:
        return self.event_detector.get_events()

    def configure_event_thresholds(self, thresholds: Dict[str, float]) -> None:
        self.event_detector.configure_thresholds(thresholds)

if __name__ == "__main__":
    config = {
        "sensors": ["sensor1", "sensor2"],
        "aggregation_methods": {"temperature": lambda sensor, value: print(f"Average temperature: {value}")},
        "event_thresholds": {"temperature": 30.0}
    }
    processor = SensorDataProcessor(config)
    processor.start_processing()
