```rust
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::Duration;
use tokio::runtime::Runtime;
use tokio::task::JoinHandle;
use tokio_postgres::NoTls;
use actix_web::{get, web, App, HttpResponse, Responder};
use log::{error, info};

struct Database {
    client: tokio_postgres::Client,
}

impl Database {
    fn new(client: tokio_postgres::Client) -> Self {
        Self { client }
    }

    async fn query(&self, sql: &str, params: &[&(dyn ToSql + Sync)]) -> Result<Vec<HashMap<String, String>>, Error> {
        let mut rows = self.client.query(sql, params).await?;
        let mut results = Vec::new();
        while let Some(row) = rows.next().await {
            results.push(row?);
        }
        Ok(results)
    }
}

struct Cache {
    cache: HashMap<String, String>,
}

impl Cache {
    fn new() -> Self {
        Self {
            cache: HashMap::new(),
        }
    }

    async fn get(&self, key: &str) -> Option<String> {
        self.cache.get(key).cloned()
    }

    async fn set(&mut self, key: String, value: String) {
        self.cache.insert(key, value);
    }
}

struct Config {
    mode: Mode,
    cache_enabled: bool,
    rate_limit: Duration,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            mode: Mode::Synchronous,
            cache_enabled: false,
            rate_limit: Duration::from_secs(60),
        }
    }
}

enum Mode {
    Synchronous,
    Asynchronous,
}

#[derive(Debug)]
struct Error(String);

impl From<tokio_postgres::Error> for Error {
    fn from(err: tokio_postgres::Error) -> Self {
        Self(format!("Database error: {}", err))
    }
}

#[get("/user/{id}")]
async fn get_user(query: web::Query<HashMap<String, String>>, cache: web::Data<Cache>, db: web::Data<Database>, config: web::Data<Config>) -> impl Responder {
    let id = query.id.parse::<i32>().unwrap();
    let sql = "SELECT * FROM users WHERE id = $1";
    let params = &[&id];
    let mut results = Vec::new();

    if config.cache_enabled && cache.get(id).await.is_some() {
        info!("Using cached user data for ID {}", id);
        results.push(cache.get(id).await.unwrap());
    } else {
        let mut db = db.lock().await;
        if config.mode == Mode::Asynchronous {
            tokio::spawn(async move {
                match db.query(sql, params).await {
                    Ok(mut rows) => while let Some(row) = rows.next().await {
                        results.push(row?);
                    },
                    Err(err) => error!("{}", err),
                }
            });
        } else {
            match db.query(sql, params).await {
                Ok(mut rows) => while let Some(row) = rows.next().await {
                    results.push(row?);
                },
                Err(err) => error!("{}", err),
            }
        }
    }
    if !results.is_empty() {
        HttpResponse::Ok().json(results[0])
    } else {
        HttpResponse::NotFound().json(format!("User with ID {} not found.", id))
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let config = Config::default();
    let database = Database::new("host=localhost user=postgres password=password sslmode=disable".parse().unwrap());
    let mut cache = Cache::new();
    let runtime = Runtime::new().expect("Unable to create Tokio runtime");
    let address = "0.0.0.0:8080";
    info!("Starting HTTP server at {}", address);
    actix_web::HttpServer::new(move || {
        App::new()
            .data(database)
            .data(cache)
            .data(config)
            .route("/user/{id}", web::get().to(get_user))
    })
    .bind(address)?
    .run()
    .await?;
    Ok(())
}
