// NetworkPacketFilterTest.java
package com.example;

import static org.junit.jupiter.api.Assertions.*;

import java.util.Arrays;
import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

public class NetworkPacketFilterTest {
  private static final List<byte[]> TEST_PACKETS = Arrays.asList(
    new byte[] {0, 1, 2, 3, 4},
    new byte[] {5, 6, 7, 8, 9},
    new byte[] {10, 11, 12, 13, 14}
  );

  private NetworkPacketFilter filter;

  @BeforeEach
  public void setup() {
    filter = new NetworkPacketFilter();
  }

  @Test
  public void testFilterCriteria() {
    // Add filter criteria and ensure they are removed correctly
    filter.addFilterCriterion("size", 10);
    assertEquals(filter.getFilterCriteria().get("size"), 10);
    filter.removeFilterCriterion("size");
    assertNull(filter.getFilterCriteria().get("size"));

    // Add filter criteria with multiple values and ensure they are removed correctly
    filter.addFilterCriterion("source_ip", new int[] {1, 2});
    assertEquals(filter.getFilterCriteria().get("source_ip"), new int[] {1, 2});
    filter.removeFilterCriterion("source_ip");
    assertNull(filter.getFilterCriteria().get("source_ip"));
  }

  @Test
  public void testShouldFilterPacket() {
    // Ensure packets are filtered correctly based on filter criteria
    filter.addFilterCriterion("size", 5);
    assertTrue(filter.shouldFilterPacket(new byte[] {0, 1, 2, 3, 4}));
    assertFalse(filter.shouldFilterPacket(new byte[] {0, 1, 2, 3, 4, 5}));
    filter.removeFilterCriterion("size");

    // Ensure packets are filtered correctly based on source IP address
    filter.addFilterCriterion("source_ip", new int[] {1, 2});
    assertTrue(filter.shouldFilterPacket(new byte[] {0, 1, 2, 3, 4}));
    assertFalse(filter.shouldFilterPacket(new byte[] {0, 1, 2, 3, 4, 5}));
    filter.removeFilterCriterion("source_ip");

    // Ensure packets are filtered correctly based on destination port
    filter.addFilterCriterion("destination_port", new int[] {80, 443});
    assertTrue(filter.shouldFilterPacket(new byte[] {0, 1, 2, 3, 4}));
    assertFalse(filter.shouldFilterPacket(new byte[] {0, 1, 2, 3, 4, 5}));
    filter.removeFilterCriterion("destination_port");

    // Ensure packets are filtered correctly based on packet arrival time
    filter.addFilterCriterion("arrival_time", System.currentTimeMillis());
    assertTrue(filter.shouldFilterPacket(new byte[] {0, 1, 2, 3, 4}));
    assertFalse(filter.shouldFilterPacket(new byte[] {0, 1, 2, 3, 4, 5}));
    filter.removeFilterCriterion("arrival_time");
  }

  @Test
  public void testHandlePacket() {
    // Ensure packets are handled correctly based on filter criteria
    filter.addFilterCriterion("size", 5);
    assertTrue(filter.shouldFilterPacket(new byte[] {0, 1, 2, 3, 4}));
    filter.handlePacket(new byte[] {0, 1, 2, 3, 4});
    assertFalse(filter.shouldFilterPacket(new byte[] {0, 1, 2, 3, 4}));
    filter.removeFilterCriterion("size");

    // Ensure packets are handled correctly based on source IP address
    filter.addFilterCriterion("source_ip", new int[] {1, 2});
    assertTrue(filter.shouldFilterPacket(new byte[] {0, 1, 2, 3, 4}));
    filter.handlePacket(new byte[] {0, 1, 2, 3, 4});
    assertFalse(filter.shouldFilterPacket(new byte[] {0, 1, 2, 3, 4}));
    filter.removeFilterCriterion("source_ip");

    // Ensure packets are handled correctly based on destination port
    filter.addFilterCriterion("destination_port", new int[] {80, 443});
    assertTrue(filter.shouldFilterPacket(new byte[] {0, 1, 2, 3, 4}));
    filter.handlePacket(new byte[] {0, 1, 2, 3, 4});
    assertFalse(filter.shouldFilterPacket(new byte[] {0, 1, 2, 3, 4}));
    filter.removeFilterCriterion("destination_port");

    // Ensure packets are handled correctly based on packet arrival time
    filter.addFilterCriterion("arrival_time", System.currentTimeMillis());
    assertTrue(filter.shouldFilterPacket(new byte[] {0, 1, 2, 3, 4}));
    filter.handlePacket(new byte[] {0, 1, 2, 3, 4});
    assertFalse(filter.shouldFilterPacket(new byte[] {0, 1, 2, 3, 4}));
    filter.removeFilterCriterion("arrival_time");
  }
}
