#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <getopt.h>
#include <signal.h>

#define MAX_LINE_LENGTH 1024
#define MAX_NUM_LINES 1000000

// Define the signal handler function to handle SIGINT
void signalHandler(int sig) {
    printf("Caught SIGINT\n");
    exit(0);
}

// Define a struct to store command line arguments
struct args {
    char *input_file;
    char *output_file;
    int verbose;
    int help;
};

int main(int argc, char *argv[]) {
    // Initialize the signal handler for SIGINT
    signal(SIGINT, signalHandler);

    // Define the command line options and their corresponding short codes
    struct option long_options[] = {{"help", no_argument, NULL, 'h'},
                                   {"verbose", no_argument, NULL, 'v'},
                                   {"output-file", required_argument, NULL, 'o'},
                                   {NULL, 0, NULL, 0}};
    int c, option_index = 0;

    // Initialize the struct to store command line arguments
    struct args args;
    memset(&args, 0, sizeof(struct args));

    // Parse the command line arguments and handle errors
    while ((c = getopt_long(argc, argv, "hvo:", long_options, &option_index)) != -1) {
        switch (c) {
            case 'h':
                args.help = 1;
                break;
            case 'v':
                args.verbose = 1;
                break;
            case 'o':
                args.output_file = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-h] [-v] -o output-file\n", argv[0]);
                exit(1);
        }
    }

    // Check if the input file is provided and handle errors
    if (optind >= argc) {
        fprintf(stderr, "Error: No input file specified\n");
        exit(1);
    } else {
        args.input_file = argv[optind];
    }

    // Open the input file and check for errors
    FILE *input_file = fopen(args.input_file, "r");
    if (input_file == NULL) {
        perror("Error opening input file");
        exit(1);
    }

    // Define a buffer to store the lines of the input file
    char *buffer = malloc(MAX_LINE_LENGTH);
    if (buffer == NULL) {
        perror("Error allocating memory for buffer");
        exit(1);
    }

    // Initialize variables to keep track of the number of lines and the current line number
    int num_lines = 0, curr_line = 1;

    // Read the input file line by line and print the number of lines
    while (fgets(buffer, MAX_LINE_LENGTH, input_file) != NULL) {
        if (args.verbose) {
            printf("%d: %s", curr_line++, buffer);
        }
        num_lines++;
    }

    // Close the input file and check for errors
    fclose(input_file);

    // Print the number of lines to the output file if specified
    if (args.output_file != NULL) {
        FILE *output_file = fopen(args.output_file, "w");
        if (output_file == NULL) {
            perror("Error opening output file");
            exit(1);
        }
        fprintf(output_file, "%d\n", num_lines);
        fclose(output_file);
    } else {
        printf("%d\n", num_lines);
    }

    // Free the buffer and return 0 to indicate success
    free(buffer);
    return 0;
}
