class NetworkClientManager:
    def __init__(self, config_file):
        self.config = json.loads(open(config_file).read())
        self.api_gateway_url = self.config['api_gateway']['url']
        self.server_pool = []
        for server in self.config['server_pool']:
            self.server_pool.append({
                'url': server['url'],
                'weight': server['weight'],
                'healthy': True,
                'active': False,
                'last_accessed': datetime.now(),
            })
        self.load_balancer = self.config['load_balancer']['type']
        if self.load_balancer == 'round_robin':
            self.current_server = 0
        elif self.load_balancer == 'least_connections':
            self.current_server = len(self.server_pool) - 1
        self.health_check_interval = self.config['health_check']['interval']
        self.health_check_timeout = self.config['health_check']['timeout']
        self.rate_limiting = self.config['rate_limiting']['enabled']
        self.max_requests = self.config['rate_limiting']['max_requests']
        self.request_throttling = self.config['request_throttling']['enabled']
        self.max_concurrency = self.config['request_throttling']['max_concurrency']
        self.authentication_method = self.config['authentication']['method']
        self.api_key = self.config['authentication']['api_key']
        self.oauth_token = self.config['authentication']['oauth_token']
        self.basic_auth = self.config['authentication']['basic_auth']

    def connect(self):
        if len(self.server_pool) == 0:
            raise ValueError('Server pool is empty')
        for server in self.server_pool:
            try:
                conn = HTTPConnection(server['url'])
                break
            except:
                continue
        return conn

    def disconnect(self, conn):
        if conn is not None:
            conn.close()

    def send_request(self, method, url, headers=None, body=None, timeout=0):
        start_time = time.time()
        for server in self.server_pool:
            try:
                conn = self.connect()
                break
            except:
                continue
        if conn is None:
            raise ConnectionError('All servers are unreachable')
        try:
            conn.request(method, url, headers=headers, body=body)
            response = conn.getresponse()
            data = response.read().decode('utf-8')
            end_time = time.time()
            self.disconnect(conn)
            return data
        except:
            self.disconnect(conn)
            raise ConnectionError('Request failed with server {}'.format(server['url']))

    def get_response(self, url, headers=None, timeout=0):
        start_time = time.time()
        for server in self.server_pool:
            try:
                conn = self.connect()
                break
            except:
                continue
        if conn is None:
            raise ConnectionError('All servers are unreachable')
        try:
            response = conn.getresponse()
            data = response.read().decode('utf-8')
            end_time = time.time()
            self.disconnect(conn)
            return data
        except:
            self.disconnect(conn)
            raise ConnectionError('Request failed with server {}'.format(server['url']))

    def send_data(self, url, headers=None, body=None, timeout=0):
        start_time = time.time()
        for server in self.server_pool:
            try:
                conn = self.connect()
                break
            except:
                continue
        if conn is None:
            raise ConnectionError('All servers are unreachable')
        try:
            conn.request(url, headers=headers, body=body)
            response = conn.getresponse()
            data = response.read().decode('utf-8')
            end_time = time.time()
            self.disconnect(conn)
            return data
        except:
            self.disconnect(conn)
            raise ConnectionError('Request failed with server {}'.format(server['url']))

    def health_check(self):
        for server in self.server_pool:
            try:
                conn = HTTPConnection(server['url'])
                conn.request('HEAD', '/')
                response = conn.getresponse()
                if response.status == 200:
                    server['healthy'] = True
                else:
                    server['healthy'] = False
            except:
                server['healthy'] = False
        self.server_pool.sort(key=lambda s: (s['weight'], -s['last_accessed']))

    def get_active_server(self):
        if len(self.server_pool) == 0:
            raise ValueError('Server pool is empty')
        for server in self.server_pool:
            if server['healthy']:
                return server['url']
        raise ConnectionError('No active servers available')

    def get_inactive_servers(self):
        inactive_servers = []
        for server in self.server_pool:
            if not server['healthy']:
                inactive_servers.append(server['url'])
        return inactive_servers

    def load_balancer_select_server(self):
        if self.load_balancer == 'round_robin':
            self.current_server = (self.current_server + 1) % len(self.server_pool)
            return self.server_pool[self.current_server]['url']
        elif self.load_balancer == 'weighted_random':
            weights = []
            for server in self.server_pool:
                weights.append(server['weight'])
            random_index = np.random.choice(range(len(weights)), p=weights/sum(weights))
            return self.server_pool[random_index]['url']
        elif self.load_balancer == 'least_connections':
            min_conns = math.inf
            for server in self.server_pool:
                if server['conns'] < min_conns:
                    min_conns = server['conns']
                    return server['url']
        else:
            raise ValueError('Unknown load balancer method')

    def increment_connection(self, conn):
        for server in self.server_pool:
            if server['url'] == conn:
                server['conns'] += 1

    def decrement_connection(self, conn):
        for server in self.server_pool:
            if server['url'] == conn:
                server['conns'] -= 1

    def set_weight(self, url, weight):
        for server in self.server_pool:
            if server['url'] == url:
                server['weight'] = weight

    def get_weight(self, url):
        for server in self.server_pool:
            if server['url'] == url:
                return server['weight']
        raise ValueError('Server not found')

    def authentication(self, method, headers=None, body=None):
        if method == 'api_key':
            headers['API-Key'] = self.api_key
        elif method == 'oauth_token':
            headers['Authorization'] = 'Bearer {}'.format(self.oauth_token)
        elif method == 'basic_auth':
            credentials = base64.b64encode(bytes('{}:{}'.format(self.basic_auth['username'], self.basic_auth['password']), 'utf-8')).decode('utf-8')
            headers['Authorization'] = 'Basic {}'.format(credentials)
        else:
            raise ValueError('Unknown authentication method')
```
