parameters = {"username": "my_user", "password": "my_pass"}
modules = ["module1", "module2"]

# Encrypt password using Kickstart's `kick` command
encrypted_password = subprocess.check_output(["kick", "-e", parameters["password"]]).decode("utf-8")

# Replace placeholders in configuration file with actual values and encrypted password
with open("config.txt", "r") as file:
    config = file.read()
config = re.sub(r"%username%", parameters["username"], config)
config = re.sub(r"%password%", encrypted_password, config)

# Add a new line with the list of modules to be tested
modules_string = "\n".join(modules)
config += f"\n{modules_string}"

# Write updated configuration file
with open("config.txt", "w") as file:
    file.write(config)
