```
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace SecureMessageHandler
{
    public class SecureMessageHandler
    {
        // Dictionary to store the encryption context for each message
        private readonly Dictionary<string, EncryptionContext> _encryptionContexts = new Dictionary<string, EncryptionContext>();

        // Method to dynamically decrypt a Base64-encoded message using a specified encryption context
        public Task<byte[]> DecryptAsync(string encryptedMessage, string encryptionContext)
        {
            // Check if the encryption context is valid and return an error if not
            if (!_encryptionContexts.ContainsKey(encryptionContext))
            {
                throw new ArgumentException("Invalid encryption context", nameof(encryptionContext));
            }

            // Get the encryption context for the specified message
            EncryptionContext encryptionContext = _encryptionContexts[encryptionContext];

            // Decode the Base64-encoded message and decrypt it using the appropriate CSP and IV
            byte[] decodedMessage = Convert.FromBase64String(encryptedMessage);
            return DecryptAsync(decodedMessage, encryptionContext);
        }

        // Method to decrypt a message using the specified CSP and IV
        public async Task<byte[]> DecryptAsync(byte[] encryptedMessage, EncryptionContext encryptionContext)
        {
            // Check if the CSP is valid and return an error if not
            if (!encryptionContext.Csp.IsValid())
            {
                throw new ArgumentException("Invalid CSP", nameof(encryptionContext.Csp));
            }

            // Get the initialization vector (IV) for the specified message
            byte[] iv = encryptionContext.GetIv();

            // Decrypt the message using the appropriate CSP and IV
            return await encryptionContext.Csp.DecryptAsync(encryptedMessage, iv);
        }

        // Method to get the current encryption context for a specified message
        public EncryptionContext GetEncryptionContext(string encryptedMessage)
        {
            // Check if the message is valid and return an error if not
            if (string.IsNullOrEmpty(encryptedMessage))
            {
                throw new ArgumentException("Invalid message", nameof(encryptedMessage));
            }

            // Get the encryption context for the specified message
            EncryptionContext encryptionContext = _encryptionContexts[encryptedMessage];

            return encryptionContext;
        }

        // Method to add a new encryption context for a specified CSP and IV
        public void AddEncryptionContext(string cspName, byte[] iv)
        {
            // Check if the CSP is valid and return an error if not
            if (!Csp.IsValid(cspName))
            {
                throw new ArgumentException("Invalid CSP", nameof(cspName));
            }

            // Create a new encryption context for the specified CSP and IV
            EncryptionContext encryptionContext = new EncryptionContext();
            encryptionContext.Csp = Csp.GetCsp(cspName);
            encryptionContext.Iv = iv;

            // Add the encryption context to the dictionary of encryption contexts
            _encryptionContexts[encryptionContext.Id] = encryptionContext;
        }

        // Method to remove an existing encryption context for a specified message
        public void RemoveEncryptionContext(string encryptedMessage)
        {
            // Check if the message is valid and return an error if not
            if (string.IsNullOrEmpty(encryptedMessage))
            {
                throw new ArgumentException("Invalid message", nameof(encryptedMessage));
            }

            // Remove the encryption context for the specified message from the dictionary of encryption contexts
            _encryptionContexts.Remove(encryptedMessage);
        }
    }

    public class EncryptionContext
    {
        // Property to store the ID of the encryption context
        public string Id { get; set; }

        // Property to store the cryptographic service provider (CSP) for the encryption context
        public Csp Csp { get; set; }

        // Property to store the initialization vector (IV) for the encryption context
        public byte[] Iv { get; set; }

        // Method to get the initialization vector (IV) for the encryption context
        public byte[] GetIv()
        {
            return Iv;
        }
    }
}
```
The `SecureMessageHandler` class provides a flexible and extensible way to dynamically decrypt Base64-encoded messages using a specified encryption context. It supports multiple configurations, including the ability to interact seamlessly with different third-party cryptographic service providers (CSPs) and key management services (KMSs). The class also manages decryption keys and initialization vectors (IVs) in a secure and efficient manner, integrating with an external KMS for key storage and retrieval.

The `EncryptionContext` class provides the necessary information to perform encryption and decryption operations using a specific CSP and IV. The `GetIv()` method returns the initialization vector (IV) for the specified encryption context.

To use the `SecureMessageHandler` class, you can call the `DecryptAsync()` method with the encrypted message and the encryption context as parameters:
```
// Create a new SecureMessageHandler instance
var secureMessageHandler = new SecureMessageHandler();

// Add an encryption context for a specific CSP and IV
secureMessageHandler.AddEncryptionContext("AES", new byte[] { 0x00, 0x01, 0x02, 0x03 });

// Decrypt a Base64-encoded message using the specified encryption context
var decryptedMessage = await secureMessageHandler.DecryptAsync(encryptedMessage, "AES");
```
This code will dynamically decrypt the encrypted message using the AES CSP and initialization vector (IV) provided in the `AddEncryptionContext()` method.

