use std::collections::HashMap;
use std::time::Duration;
use yaml_rust::YamlLoader;
use reqwest::blocking::get;
use chrono::Utc;
use log::{info, warn};

struct WeatherData {
    temperature: f32,
    humidity: u8,
}

struct AirQualityData {
    aqi: u16,
    pollutants: Vec<Pollutant>,
}

struct Pollutant {
    name: String,
    concentration: f32,
}

struct CacheEntry {
    data: HashMap<String, WeatherData>,
    timestamp: i64,
}

fn fetch_weather_data(location: &str) -> Result<WeatherData, Error> {
    let config = read_config()?;
    let weather_api = get_weather_api(&config)?;
    let air_quality_api = get_air_quality_api(&config)?;
    let pollen_count_api = get_pollen_count_api(&config)?;
    let weather_data = fetch_weather(location, &weather_api)?;
    let air_quality_data = fetch_air_quality(location, &air_quality_api)?;
    let pollen_count_data = fetch_pollen_count(location, &pollen_count_api)?;
    Ok(WeatherData {
        temperature: weather_data.temperature,
        humidity: weather_data.humidity,
        aqi: air_quality_data.aqi,
        pollutants: air_quality_data.pollutants,
        pollen_counts: pollen_count_data.pollen_counts,
    })
}

fn read_config() -> Result<YamlLoader, Error> {
    let config = fs::read_to_string("config.yml")?;
    Ok(YamlLoader::new(&config))
}

fn get_weather_api(config: &YamlLoader) -> Result<String, Error> {
    match config.get("weather_api") {
        Some(value) => Ok(value.as_str().unwrap()),
        None => Err(Error::new(ErrorKind::InvalidInput, "Weather API not found")),
    }
}

fn get_air_quality_api(config: &YamlLoader) -> Result<String, Error> {
    match config.get("air_quality_api") {
        Some(value) => Ok(value.as_str().unwrap()),
        None => Err(Error::new(ErrorKind::InvalidInput, "Air quality API not found")),
    }
}

fn get_pollen_count_api(config: &YamlLoader) -> Result<String, Error> {
    match config.get("pollen_count_api") {
        Some(value) => Ok(value.as_str().unwrap()),
        None => Err(Error::new(ErrorKind::InvalidInput, "Pollen count API not found")),
    }
}

fn fetch_weather(location: &str, api: &str) -> Result<WeatherData, Error> {
    let url = format!("{}/{}", api, location);
    let response = get(&url)?;
    if response.status().is_success() {
        Ok(serde_json::from_slice(&response.body()).unwrap())
    } else {
        Err(Error::new(ErrorKind::InvalidInput, "Weather API error"))
    }
}

fn fetch_air_quality(location: &str, api: &str) -> Result<AirQualityData, Error> {
    let url = format!("{}/{}", api, location);
    let response = get(&url)?;
    if response.status().is_success() {
        Ok(serde_json::from_slice(&response.body()).unwrap())
    } else {
        Err(Error::new(ErrorKind::InvalidInput, "Air quality API error"))
    }
}

fn fetch_pollen_count(location: &str, api: &str) -> Result<PollenCountData, Error> {
    let url = format!("{}/{}", api, location);
    let response = get(&url)?;
    if response.status().is_success() {
        Ok(serde_json::from_slice(&response.body()).unwrap())
    } else {
        Err(Error::new(ErrorKind::InvalidInput, "Pollen count API error"))
    }
}

fn cache_data(location: &str, data: WeatherData) -> Result<(), Error> {
    let mut cache = CacheEntry {
        data: HashMap::new(),
        timestamp: Utc::now().timestamp(),
    };
    cache.data.insert(location.to_string(), data);
    Ok(())
}

fn get_cached_data(location: &str) -> Result<WeatherData, Error> {
    let mut cache = CacheEntry {
        data: HashMap::new(),
        timestamp: Utc::now().timestamp(),
    };
    if cache.data.contains_key(location) {
        Ok(cache.data[location].clone())
    } else {
        Err(Error::new(ErrorKind::InvalidInput, "Location not found in cache"))
    }
}
```
