from typing import Dict, List, Optional
from datetime import datetime

class FileAggregator:
    def __init__(self, storage_services: Dict[str, str], checksum_algorithms: List[str]):
        self.storage_services = storage_services
        self.checksum_algorithms = checksum_algorithms

    def add_file(self, file_path: str, source: Optional[str] = None):
        for service in self.storage_services:
            try:
                with open(file_path, "rb") as f:
                    data = f.read()
                    checksum = hashlib.new(self.checksum_algorithms[0], data).hexdigest()
                    size = os.stat(file_path).st_size
                    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                    if source:
                        self.storage_services[service].add_file(file_path, source, checksum, size, timestamp)
                    else:
                        self.storage_services[service].add_file(file_path, checksum, size, timestamp)
            except Exception as e:
                print(f"Error adding file to {service}: {e}")

    def get_files(self, source: Optional[str] = None):
        files = []
        for service in self.storage_services:
            try:
                if source:
                    files.extend(self.storage_services[service].get_files(source))
                else:
                    files.extend(self.storage_services[service].get_files())
            except Exception as e:
                print(f"Error getting files from {service}: {e}")
        return files

    def get_file_metadata(self, file_path: str):
        for service in self.storage_services:
            try:
                if service == "AWS S3":
                    metadata = self.storage_services[service].get_object_metadata(file_path)
                    return {"Source": service, "Timestamp": metadata["Last-Modified"], "FileSize": metadata["Content-Length"]}
                elif service == "Google Cloud Storage":
                    metadata = self.storage_services[service].get_bucket_metadata(file_path)
                    return {"Source": service, "Timestamp": metadata["TimeCreated"], "FileSize": metadata["Size"]}
                elif service == "Azure Blob Storage":
                    metadata = self.storage_services[service].get_blob_metadata(file_path)
                    return {"Source": service, "Timestamp": metadata["Last-Modified"], "FileSize": metadata["Content-Length"]}
            except Exception as e:
                print(f"Error getting file metadata from {service}: {e}")
        return {}

    def update_file_metadata(self, file_path: str):
        for service in self.storage_services:
            try:
                if service == "AWS S3":
                    metadata = self.storage_services[service].get_object_metadata(file_path)
                    checksum = hashlib.new(self.checksum_algorithms[0], data).hexdigest()
                    size = os.stat(file_path).st_size
                    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                    self.storage_services[service].update_object_metadata(file_path, {"ETag": checksum}, size, timestamp)
                elif service == "Google Cloud Storage":
                    metadata = self.storage_services[service].get_bucket_metadata(file_path)
                    checksum = hashlib.new(self.checksum_algorithms[0], data).hexdigest()
                    size = os.stat(file_path).st_size
                    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                    self.storage_services[service].update_bucket_metadata(file_path, {"ETag": checksum}, size, timestamp)
                elif service == "Azure Blob Storage":
                    metadata = self.storage_services[service].get_blob_metadata(file_path)
                    checksum = hashlib.new(self.checksum_algorithms[0], data).hexdigest()
                    size = os.stat(file_path).st_size
                    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                    self.storage_services[service].update_blob_metadata(file_path, {"ETag": checksum}, size, timestamp)
            except Exception as e:
                print(f"Error updating file metadata in {service}: {e}")

    def delete_file(self, file_path: str):
        for service in self.storage_services:
            try:
                if service == "AWS S3":
                    self.storage_services[service].delete_object(file_path)
                elif service == "Google Cloud Storage":
                    self.storage_services[service].delete_bucket(file_path)
                elif service == "Azure Blob Storage":
                    self.storage_services[service].delete_blob(file_path)
            except Exception as e:
                print(f"Error deleting file from {service}: {e}")

    def get_file_checksum(self, file_path: str):
        for service in self.storage_services:
            try:
                if service == "AWS S3":
                    data = self.storage_services[service].get_object(file_path)["Body"].read()
                elif service == "Google Cloud Storage":
                    data = self.storage_services[service].get_bucket(file_path)["Content-Length"]
                elif service == "Azure Blob Storage":
                    data = self.storage_services[service].get_blob(file_path)["Body"].read()
                checksum = hashlib.new(self.checksum_algorithms[0], data).hexdigest()
                return checksum
            except Exception as e:
                print(f"Error getting file checksum from {service}: {e}")
        return ""

    def get_file_sizes(self, source: Optional[str] = None):
        sizes = []
        for service in self.storage_services:
            try:
                if source:
                    sizes.extend(self.storage_services[service].get_file_sizes(source))
                else:
                    sizes.extend(self.storage_services[service].get_file_sizes())
            except Exception as e:
                print(f"Error getting file sizes from {service}: {e}")
        return sizes

    def get_files_updated_in_last(self, days: int):
        files = []
        for service in self.storage_services:
            try:
                if service == "AWS S3":
                    files.extend(self.storage_services[service].get_files_updated_in_last(days))
                elif service == "Google Cloud Storage":
                    files.extend(self.storage_services[service].get_buckets_updated_in_last(days))
                elif service == "Azure Blob Storage":
                    files.extend(self.storage_services[service].get_blobs_updated_in_last(days))
            except Exception as e:
                print(f"Error getting files updated in last {days} days from {service}: {e}")
        return files
