```
import requests
import json
from redis import Redis
from datetime import timedelta

redis = Redis()
cache_key = "weather_data"

def get_weather(location):
    # Check if the weather data is cached
    cached_data = redis.get(cache_key)
    if cached_data:
        return json.loads(cached_data)

    # Fetch weather data from external API
    api_url = f"https://api.openweathermap.org/data/2.5/weather?q={location}&appid=YOUR_API_KEY"
    response = requests.get(api_url)

    # Check if the API call was successful
    if not response.ok:
        raise ValueError("Failed to fetch weather data from external API")

    # Cache the weather data for 10 minutes
    redis.set(cache_key, json.dumps(response.json()), timedelta(minutes=10))

    return response.json()
