```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

char* parseAndFormatDate(const char* date, const char* format) {
    // Validate input parameters
    if (date == NULL || format == NULL) {
        printf("Invalid input provided.\n");
        return NULL;
    }

    // Parse the date string and validate it
    struct tm tm = {};
    if (strptime(date, "%Y-%m-%d", &tm) == NULL) {
        printf("Invalid date format.\n");
        return NULL;
    }

    // Allocate memory for the new string
    size_t bufsize = 0;
    char* newstr = malloc(bufsize);
    if (newstr == NULL) {
        printf("Memory allocation failure.\n");
        return NULL;
    }

    // Format the date according to the specified format
    int ret = strftime(newstr, bufsize, format, &tm);
    if (ret == 0) {
        printf("Format string not supported.\n");
        free(newstr);
        return NULL;
    }

    // Return the formatted date
    return newstr;
}
```
