    if config_dir.is_empty() {
        let dir_name = format!("{}_settings", env!("CARGO_PKG_NAME"));
        if let Ok(path) = get_config_directory_from_external_service(&dir_name) {
            config_dir.replace(path);
        } else {
            config_dir.replace(create_local_directory(&dir_name));
        }
    }
    *config_dir
}

fn get_config_directory_from_external_service(dir_name: &str) -> Result<PathBuf, Box<dyn Error>> {
    // Implement external configuration management service integration here
    Ok(PathBuf::new())
}

fn create_local_directory(dir_name: &str) -> PathBuf {
    let dir = match create_dir(&dir_name) {
        Ok(dir) => dir,
        Err(_) => match create_dir_all(&dir_name) {
            Ok(dir) => dir,
            Err(e) => return e.into(),
        },
    };
    PathBuf::from(format!("{}/{}", std::env::current_dir().unwrap().to_string_lossy(), dir))
}
