import json
from decimal import Decimal
from datetime import datetime
from uuid import UUID

class JSONSerializable:
    def __init__(self):
        self._factory_functions = {}

    def register_factory(self, data_type, factory_function):
        self._factory_functions[data_type] = factory_function

    def unregister_factory(self, data_type):
        del self._factory_functions[data_type]

    def to_json(self, obj):
        """Convert a financial data model to a JSON string."""
        if not isinstance(obj, (datetime, UUID, Decimal)):
            raise ValueError("Unsupported data type: {}".format(type(obj)))
        return json.dumps(obj)

    def from_json(self, json_string):
        """Create a new instance of a financial data model from a JSON string."""
        try:
            obj = json.loads(json_string)
            for data_type, factory in self._factory_functions.items():
                if isinstance(obj, data_type):
                    return factory(obj)
            raise ValueError("Unsupported data type: {}".format(type(obj)))
        except json.JSONDecodeError as e:
            raise ValueError("Invalid JSON input: {}".format(e))

if __name__ == "__main__":
    # Test the JSONSerializable class
    js = JSONSerializable()
    js.register_factory(datetime, lambda obj: datetime.strptime(obj, "%Y-%m-%d %H:%M:%S"))
    js.register_factory(UUID, lambda obj: UUID(obj))
    js.register_factory(Decimal, lambda obj: Decimal(obj))

    data = {"date": "2022-01-01 12:34:56", "uuid": "f81d4fae-7dec-11d0-a765-00a0c91e6bf6", "price": "123.45"}
    json_string = js.to_json(data)
    print("JSON string:", json_string)

    deserialized_data = js.from_json(json_string)
    print("Deserialized data:", deserialized_data)
