#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <unordered_map>
#include <chrono>

class Character {
    private:
        int energyLevel;
        std::unordered_map<std::string, int> cooldownTimers;
        std::vector<Attack> availableAttacks;
        std::mutex mtx;

    public:
        Character(int energyLevel) : energyLevel(energyLevel), cooldownTimers(), availableAttacks() {}

        void addAttack(const Attack& attack) {
            availableAttacks.push_back(attack);
        }

        bool canUseAttack(const std::string& attackName) {
            // Check if the attack is on cooldown and if the character has enough energy to use it
            return (cooldownTimers[attackName] == 0 && energyLevel >= availableAttacks[attackName].energyCost);
        }

        void useAttack(const std::string& attackName) {
            // Update the cooldown timer and energy level
            cooldownTimers[attackName] = availableAttacks[attackName].cooldownPeriod;
            energyLevel -= availableAttacks[attackName].energyCost;
        }

        void updateEnergyLevel(int newEnergyLevel) {
            energyLevel = newEnergyLevel;
        }
};

class Attack {
    private:
        std::string name;
        int cooldownPeriod;
        int energyCost;

    public:
        Attack(const std::string& name, int cooldownPeriod, int energyCost) : name(name), cooldownPeriod(cooldownPeriod), energyCost(energyCost) {}

        const std::string& getName() {
            return name;
        }

        int getCooldownPeriod() {
            return cooldownPeriod;
        }

        int getEnergyCost() {
            return energyCost;
        }
};

void selectAndExecuteAttack(Character& character) {
    // Randomly select an attack from the list of available attacks
    std::vector<std::string> availableAttacks = character.getAvailableAttacks();
    std::string selectedAttackName = availableAttacks[rand() % availableAttacks.size()];

    // Check if the attack can be executed based on the character's energy level and cooldown status
    if (character.canUseAttack(selectedAttackName)) {
        // Update the cooldown timer and energy level
        character.useAttack(selectedAttackName);

        // Log the successful attack attempt
        std::cout << "Attack \"" << selectedAttackName << "\" used successfully." << std::endl;
    } else {
        // Log the failed attack attempt
        std::cout << "Insufficient energy or cooldown period for attack \"" << selectedAttackName << "\". Aborting." << std::endl;
    }
}
```
