```
import json
import yaml
from typing import Dict
from pathlib import Path
from pkg_resources import get_distribution

def load_config(config_path: str) -> Dict[str, any]:
    """Loads a configuration file into a dictionary.

    Args:
        config_path (str): Path to the configuration file.

    Returns:
        Dict[str, any]: A dictionary containing the parsed configuration data.

    Raises:
        ValueError: If the MIME type of the configuration file is not recognized or
            if the configuration manager class specified in the file does not exist.
    """
    # Validate the MIME type of the configuration file
    mime_type = Path(config_path).suffix
    if mime_type == ".json":
        config = json.loads(Path(config_path).read_text())
    elif mime_type == ".yaml" or mime_type == ".yml":
        config = yaml.load(Path(config_path).read_text())
    else:
        raise ValueError(f"Unsupported MIME type '{mime_type}' for configuration file")

    # Parse the configuration data into a dictionary
    parsed_data = {}
    for key, value in config.items():
        if isinstance(value, list):
            parsed_data[key] = [parse_config_value(val) for val in value]
        else:
            parsed_data[key] = parse_config_value(value)

    # Attempt to create an instance of the specified configuration manager class
    config_manager_class = None
    if "configuration_manager" in parsed_data:
        try:
            config_manager_class = getattr(get_distribution("my_package"),
                                          parsed_data["configuration_manager"])
        except ImportError as e:
            raise ValueError(f"Configuration manager class '{parsed_data['configuration_manager']}' does not exist") from e

    if config_manager_class is None:
        raise ValueError("No configuration manager class specified in the configuration file")

    # Handle cases where the specified configuration manager class does not exist
    try:
        return config_manager_class(parsed_data)
    except ImportError as e:
        raise ValueError(f"Configuration manager class '{config_manager_class.__name__}' does not exist") from e

def parse_config_value(value: any) -> any:
    """Parses a configuration value into the appropriate type.

    Args:
        value (any): The value to be parsed.

    Returns:
        any: The parsed value in the appropriate type.
    """
    if isinstance(value, str):
        return value
    elif isinstance(value, list):
        return [parse_config_value(val) for val in value]
    else:
        return value
