// Function to expand the state list based on user-defined transitions and external state data
void expandStateList(struct fsa *fsa, int num_states) {
    // Create a pool allocator for small memory blocks
    struct pool_allocator *alloc = create_pool_allocator();
    // Iterate through the user-defined transitions and check if the new states are valid according to the transition rules
    for (int i = 0; i < num_states; ++i) {
        struct state *state = &fsa->states[i];
        bool valid = false;
        // Iterate through the external data sources and check if the new states are valid according to the transition rules
        for (int j = 0; j < fsa->num_states; ++j) {
            struct state *external_state = &fsa->states[j];
            if (external_state->id == state->id) {
                // Check if the new states are valid according to the transition rules
                for (int k = 0; k < fsa->num_transitions; ++k) {
                    struct transition *transition = &fsa->transitions[k];
                    if ((transition->from.id == state->id || transition->to.id == state->id) && transition->to.id != state->id) {
                        valid = true;
                        break;
                    }
                }
            }
        }
        // If the new states are not valid, remove them from the FSA structure
        if (!valid) {
            fsa->num_states--;
            i--;
        }
    }
    // Free the pool allocator and return
    free_pool_allocator(alloc);
}

