const express = require('express');
const redis = require('redis');
const bodyParser = require('body-parser');
const authService = require('./authService');
const paymentGateway = require('./paymentGateway');
const userManagementSystem = require('./userManagementSystem');

const app = express();
app.use(bodyParser.json());

// Redis client for caching product information
const redisClient = redis.createClient({ url: 'redis://localhost:6379' });

// Cache product information for 10 minutes
redisClient.setex('product-cache', 600, JSON.stringify(products));

// API endpoint for updating or deleting products
app.put('/api/products/:id', async (req, res) => {
  const id = req.params.id;
  const data = req.body;

  // Validate user permissions through authentication service
  if (!authService.isAuthenticated(req)) {
    return res.status(401).json({ message: 'Unauthorized' });
  }

  // Check for concurrent updates and handle conflicts appropriately
  const currentProduct = await getProductById(id);
  if (currentProduct) {
    // Partial update of product data
    const updatedProduct = { ...currentProduct, ...data };
    await updateProduct(updatedProduct);
  } else {
    // Delete product if not found
    await deleteProduct(id);
  }

  // Send response with updated/deleted product information
  res.json({ message: 'Product updated successfully' });
});

// API endpoint for creating new products
app.post('/api/products', async (req, res) => {
  const data = req.body;

  // Validate user permissions through authentication service
  if (!authService.isAuthenticated(req)) {
    return res.status(401).json({ message: 'Unauthorized' });
  }

  // Create new product and send response with created product information
  const newProduct = await createProduct(data);
  res.json({ message: 'Product created successfully', data: newProduct });
});

// API endpoint for retrieving products by ID or name
app.get('/api/products/:id?/:name?', async (req, res) => {
  const id = req.params.id;
  const name = req.params.name;

  // Check if product exists in cache
  const cachedProduct = await redisClient.get(`product-${id}-${name}`);
  if (cachedProduct) {
    return res.json({ message: 'Product retrieved from cache', data: JSON.parse(cachedProduct) });
  }

  // Retrieve product information from database and cache it
  const product = await getProductById(id);
  if (!product) {
    product = await getProductByName(name);
  }
  if (product) {
    redisClient.setex(`product-${id}-${name}`, 600, JSON.stringify(product));
  }

  // Send response with retrieved product information
  res.json({ message: 'Product retrieved successfully', data: product });
});

// API endpoint for processing inventory-related payments through payment gateway API
app.post('/api/payments', async (req, res) => {
  const data = req.body;

  // Validate user permissions through authentication service
  if (!authService.isAuthenticated(req)) {
    return res.status(401).json({ message: 'Unauthorized' });
  }

  // Process payment through payment gateway API
  const result = await paymentGateway.processPayment(data);

  // Send response with payment processing results
  res.json({ message: 'Payment processed successfully', data: result });
});

// Handle soft-deletes for products to support data recovery
async function deleteProduct(id) {
  const product = await getProductById(id);
  if (product) {
    // Soft-delete the product by setting its deletedAt property to current timestamp
    await updateProduct({ ...product, deletedAt: new Date() });
  }
}

// Handle partial updates for products
async function updateProduct(data) {
  const updatedProduct = { ...data };
  if (updatedProduct.deletedAt) {
    // Restore the product from soft-delete by removing its deletedAt property
    delete updatedProduct.deletedAt;
  }
  await userManagementSystem.updateUser(updatedProduct);
}

// Function to get a product by ID
async function getProductById(id) {
  const products = await userManagementSystem.getProducts();
  return products.find((product) => product.id === id);
}

// Function to get a product by name
async function getProductByName(name) {
  const products = await userManagementSystem.getProducts();
  return products.find((product) => product.name === name);
}
