import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.json.JSONException;
import org.json.JSONObject;

public class JSONParser {
  private static final Map<String, JsonNode> cache = new HashMap<>();
  private static final ObjectMapper mapper = new ObjectMapper();
  private static final int MAX_CACHE_SIZE = 1000;

  public static void clearCache() {
    cache.clear();
  }

  public static JsonNode parseJSON(String json) throws IOException, JSONException {
    if (cache.containsKey(json)) {
      return cache.get(json);
    } else {
      JsonNode root = mapper.readTree(json);
      cache.put(json, root);
      return root;
    }
  }

  public static ObjectNode getObject(JsonNode json, String path) throws JSONException {
    if (path == null || path.isEmpty()) {
      throw new IllegalArgumentException("Invalid path");
    }

    JsonNode node = json.findValue(path);
    if (node != null && node instanceof ObjectNode) {
      return (ObjectNode) node;
    } else {
      throw new JSONException("No matching object found at path " + path);
    }
  }

  public static List<ObjectNode> getList(JsonNode json, String path) throws JSONException {
    if (path == null || path.isEmpty()) {
      throw new IllegalArgumentException("Invalid path");
    }

    JsonNode node = json.findValue(path);
    if (node != null && node instanceof ArrayNode) {
      List<ObjectNode> list = new ArrayList<>();
      for (JsonNode item : ((ArrayNode) node)) {
        if (item instanceof ObjectNode) {
          list.add((ObjectNode) item);
        }
      }
      return list;
    } else {
      throw new JSONException("No matching list found at path " + path);
    }
  }

  public static String getString(JsonNode json, String path) throws JSONException {
    if (path == null || path.isEmpty()) {
      throw new IllegalArgumentException("Invalid path");
    }

    JsonNode node = json.findValue(path);
    if (node != null && node instanceof TextNode) {
      return ((TextNode) node).asText();
    } else {
      throw new JSONException("No matching string found at path " + path);
    }
  }

  public static int getInt(JsonNode json, String path) throws JSONException {
    if (path == null || path.isEmpty()) {
      throw new IllegalArgumentException("Invalid path");
    }

    JsonNode node = json.findValue(path);
    if (node != null && node instanceof IntNode) {
      return ((IntNode) node).asInt();
    } else {
      throw new JSONException("No matching integer found at path " + path);
    }
  }

  public static long getLong(JsonNode json, String path) throws JSONException {
    if (path == null || path.isEmpty()) {
      throw new IllegalArgumentException("Invalid path");
    }

    JsonNode node = json.findValue(path);
    if (node != null && node instanceof LongNode) {
      return ((LongNode) node).asLong();
    } else {
      throw new JSONException("No matching long found at path " + path);
    }
  }

  public static boolean getBoolean(JsonNode json, String path) throws JSONException {
    if (path == null || path.isEmpty()) {
      throw new IllegalArgumentException("Invalid path");
    }

    JsonNode node = json.findValue(path);
    if (node != null && node instanceof BooleanNode) {
      return ((BooleanNode) node).asBoolean();
    } else {
      throw new JSONException("No matching boolean found at path " + path);
    }
  }

  public static void validateJSON(String json, JSONObject schema) throws JSONException {
    if (json == null || json.isEmpty() || schema == null) {
      throw new IllegalArgumentException("Invalid JSON or schema");
    }

    JSONObject jsonObj = new JSONObject(json);
    JSONObject schemaObj = new JSONObject(schema.toString());
    JSONValidator validator = new JSONValidator();
    if (validator.validate(jsonObj, schemaObj)) {
      return;
    } else {
      throw new JSONException("JSON does not match schema");
    }
  }

  public static void rateLimitAPICall(String url) throws IOException {
    // Implement API call rate limiting mechanism here
  }

  public static String retryAPICall(String url, int numRetries) throws IOException {
    // Implement API call retry mechanism here
  }
}
