using System.Security.Cryptography;
using System.Text;

namespace CryptoProcessing
{
    public class MessageProcessor
    {
        private const string Key = "your_key";
        private const string IV = "your_iv";

        public void ProcessMessages(ConcurrentQueue<string> messages)
        {
            foreach (var message in messages.GetConsumingEnumerable())
            {
                try
                {
                    var decryptedMessage = DecryptAndValidate(message);
                    if (decryptedMessage != null)
                    {
                        // Log the decrypted message and its status
                        // ...
                    }
                    else
                    {
                        // Log an error
                        // ...
                    }
                }
                catch (Exception ex)
                {
                    // Log an error
                    // ...
                }
            }
        }

        private string DecryptAndValidate(string message)
        {
            try
            {
                var base64DecodedMessage = Convert.FromBase64String(message);
                using (var desAlgorithm = new TripleDES())
                {
                    desAlgorithm.Key = Encoding.ASCII.GetBytes(Key);
                    desAlgorithm.IV = Encoding.ASCII.GetBytes(IV);

                    var decryptedMessage = desAlgorithm.CreateDecryptor().TransformFinalBlock(base64DecodedMessage, 0, base64DecodedMessage.Length);
                    using (var hmacSha256 = new HMACSHA256(Encoding.ASCII.GetBytes(Key)))
                    {
                        var expectedHash = hmacSha256.ComputeHash(decryptedMessage);
                        if (!HmacEquals(expectedHash, decryptedMessage))
                        {
                            return null;
                        }
                    }
                }
                return Encoding.ASCII.GetString(decryptedMessage);
            }
            catch (Exception ex)
            {
                // Log an error
                // ...
                return null;
            }
        }

        private bool HmacEquals(byte[] expectedHash, byte[] actualMessage)
        {
            using (var hmacSha256 = new HMACSHA256(Encoding.ASCII.GetBytes(Key)))
            {
                var actualHash = hmacSha256.ComputeHash(actualMessage);
                return StructuralComparisons.StructuralEqualityComparer.Equals(expectedHash, actualHash);
            }
        }
    }
}
