```C#
using System;
using System.IO;
using System.Xml;
using System.Collections.Generic;
using Rust;

// C# library for loading and merging configuration settings from multiple XML files
public class ConfigManager
{
    // Priority list of XML file paths
    private List<string> xmlFiles = new List<string>();

    // Constructor to add XML file paths
    public ConfigManager(params string[] xmlFilePaths)
    {
        foreach (var filePath in xmlFilePaths)
            AddXmlFile(filePath);
    }

    // Add a single XML file path to the priority list
    private void AddXmlFile(string filePath)
    {
        if (!xmlFiles.Contains(filePath))
            xmlFiles.Add(filePath);
    }

    // Load and merge configuration settings from multiple XML files
    public Dictionary<string, object> LoadConfig()
    {
        var config = new Dictionary<string, object>();
        foreach (var file in xmlFiles)
        {
            if (!File.Exists(file))
                continue;

            // Parse the XML file and merge its settings with the current configuration
            using (XmlReader reader = XmlReader.Create(file))
            {
                while (reader.Read())
                {
                    switch (reader.NodeType)
                    {
                        case XmlNodeType.Element:
                            // Element node, add or update the setting value
                            if (!config.ContainsKey(reader.Name))
                                config[reader.Name] = reader.GetAttribute("value");
                            else
                                config[reader.Name] = reader.GetAttribute("value") + ";" + config[reader.Name];
                            break;
                        case XmlNodeType.EndElement:
                            // End element node, remove the setting value
                            if (config.ContainsKey(reader.Name))
                                config.Remove(reader.Name);
                            break;
                    }
                }
            }
        }

        return config;
    }
}
