use std::env;
use std::fs;
use std::io;
use std::path::PathBuf;
use std::time::{SystemTime, UNIX_EPOCH};
use chrono::Utc;

fn create_directory(name: &str) -> io::Result<()> {
    let mut directory_path = env::var("DIR_PATH").ok();
    if directory_path.is_none() {
        directory_path = Some(format!("{}/{}", dirs::home_dir().unwrap().display(), name));
    } else {
        directory_path = Some(format!("{}/run_{}", directory_path.unwrap(), SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs()));
    }

    let mut file_name = String::from(name);
    let mut i = 0;
    while fs::metadata(&directory_path).is_ok() {
        file_name = format!("{}_{}", name, i);
        directory_path = Some(format!("{}/run_{}", directory_path.unwrap(), i));
        i += 1;
    }

    let mut logger = Logger::new();
    logger.set_file_name("create_directory");

    match fs::create_dir(&directory_path) {
        Ok(()) => {
            env::set_var("DIR_PATH", directory_path);
            logger.log_info(format!("Created directory: {}", directory_path));
        }
        Err(e) => {
            logger.log_error(format!("Failed to create directory: {}", e));
        }
    }

    fs::create_dir(&directory_path).unwrap();

    match env::set_var("DIR_PATH", directory_path) {
        Ok(()) => {
            logger.log_info(format!("Set environment variable: DIR_PATH = {}", directory_path));
        }
        Err(e) => {
            logger.log_error(format!("Failed to set environment variable: DIR_PATH = {}", e));
        }
    }
}
```
