import os
import sys
import time
import threading
from collections import defaultdict

class LogProcessor(object):
    def __init__(self, filename):
        self.filename = filename
        self.threads = []
        self.thread_count = 4
        self.chunk_size = 1024 * 1024 # 1MB
        self.total_lines = 0
        self.processed_lines = 0
        self.aggregated_data = defaultdict(int)
        self.lock = threading.Lock()

    def start_threads(self):
        for i in range(self.thread_count):
            t = threading.Thread(target=self.process_chunk, args=(i * self.chunk_size, (i + 1) * self.chunk_size))
            self.threads.append(t)
            t.start()

    def process_chunk(self, start, end):
        with open(self.filename, "r") as f:
            for line in f.readlines()[start:end]:
                data = self.parse_line(line)
                if data is not None:
                    self.lock.acquire()
                    try:
                        self.aggregated_data[data["ip"]] += 1
                        self.processed_lines += 1
                    finally:
                        self.lock.release()

        if start + self.chunk_size < len(f):
            threading.Timer(0.5, self.process_chunk, (start + self.chunk_size, end)).start()

    def parse_line(self, line):
        data = {}
        try:
            line = line.strip().split(" ")
            if len(line) < 2:
                return None
            else:
                data["ip"] = line[0]
                data["request_time"] = time.strptime(line[1], "%Y-%m-%d %H:%M:%S")
                data["response_status"] = int(line[2])
        except ValueError:
            return None
        return data

    def calculate_average_response_time(self):
        total_responses = 0
        for ip, count in self.aggregated_data.items():
            total_responses += count

        average_response_time = total_responses / len(self.aggregated_data)
        return average_response_time

    def report_statistics(self):
        average_response_time = self.calculate_average_response_time()
        print("Average response time:", average_response_time)

        for ip, count in sorted(self.aggregated_data.items(), key=lambda x: x[1], reverse=True):
            print(ip, ":", count)

    def run(self):
        self.start_threads()
        while True:
            time.sleep(0.5)
            if self.processed_lines == len(self.aggregated_data):
                break

        self.report_statistics()
