import os
import sys
import json
from collections import defaultdict

class CryptographicFunctions(object):
    def __init__(self, filename):
        self.filename = filename
        self.functions = []
        self.cache = {}

    def load_functions(self):
        with open(self.filename, "r") as f:
            for line in f:
                name = line.strip()
                if name not in self.cache:
                    try:
                        mod = importlib.import_module("." + name, "cryptographic")
                        func = getattr(mod, name)
                        self.cache[name] = func
                    except ImportError as e:
                        print("Unable to load", name, ":", e)

    def sort_functions(self):
        return sorted(self.functions, key=lambda x: x["sequence"])

    def extract_sequence_number(self, function_name):
        for func in self.sort_functions():
            if func["name"] == function_name:
                return func["sequence"]

        raise ValueError("Function not found")
