#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <semaphore.h>
#include <pthread.h>

// Define the semaphore variables
sem_t *sem;
int num_threads = 0;

// Define the function to create a semaphore with an initial value of 1
void create_semaphore(int val) {
    sem = sem_open("mySem", O_CREAT, 0644, val);
}

// Define the function to delete the semaphore
void delete_semaphore() {
    sem_unlink("mySem");
}

// Define the function to acquire a permit from the semaphore
int acquire_permit(void) {
    return sem_wait(sem);
}

// Define the function to release a permit from the semaphore
void release_permit(void) {
    sem_post(sem);
}

// Define the function to handle errors
void error_handler(char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

// Define the function to generate a PDF report from images
int convert_images_to_pdf(char *input_dir, char *output_file, char **image_filenames, int num_images) {
    // Create a semaphore with an initial value of 1
    create_semaphore(1);

    // Declare variables for image processing and PDF generation
    FILE *pdf_file = NULL;
    char pdf_path[50];
    strcpy(pdf_path, output_file);
    strcat(pdf_path, ".pdf");
    int img_count = 0;
    int thread_id = 0;
    int i, j;

    // Iterate over each image file and generate a PDF report for it
    for (i = 0; i < num_images; ++i) {
        // Acquire a permit from the semaphore to prevent overwhelming the third-party tool with too many simultaneous requests
        if (acquire_permit()) {
            error_handler("Error: Could not acquire permit from semaphore");
        }

        // Create a new thread for image processing and PDF generation
        pthread_t thread;
        pthread_create(&thread, NULL, process_image, (void *)image_filenames[i]);

        // Increment the number of threads
        num_threads++;

        // Release the permit from the semaphore to allow other threads to proceed
        release_permit();
    }

    // Wait for all threads to complete before continuing with PDF generation
    while (num_threads > 0) {
        pthread_join(NULL, NULL);
        num_threads--;
    }

    // Close the PDF file
    if (pdf_file != NULL) {
        fclose(pdf_file);
    }

    // Delete the semaphore after use
    delete_semaphore();

    return 0;
}

// Define the function to process each image and generate a PDF report for it
void *process_image(void *args) {
    char *filename = (char *)args;
    // Declare variables for image processing and PDF generation
    FILE *pdf_file = NULL;
    char pdf_path[50];
    strcpy(pdf_path, filename);
    strcat(pdf_path, ".pdf");
    int img_count = 0;
    int thread_id = 0;

    // Open the PDF file for writing
    pdf_file = fopen(pdf_path, "wb+");
    if (pdf_file == NULL) {
        error_handler("Error: Could not open PDF file for writing");
    }

    // Generate a PDF report for each image file using the third-party tool
    char command[50];
    sprintf(command, "third-party-tool %s", filename);
    system(command);

    // Increment the number of images processed and generate a PDF report for it
    img_count++;
    if (img_count == 1) {
        fputs("%%PDF-1.7\n", pdf_file);
        fputs("%âãÏÓ\n", pdf_file);
    } else {
        fputs("\n\n\n", pdf_file);
    }
    fclose(pdf_file);

    // Release the permit from the semaphore to allow other threads to proceed
    release_permit();

    return NULL;
}
