use std::path::Path;
use std::env;
use std::fs;
use std::io;
use std::sync::Mutex;
use std::collections::HashMap;
use std::thread;
use std::time::Duration;
use std::net::SocketAddr;
use std::str::FromStr;

const MAX_LOG_FILES: u64 = 1000;
const CLEANUP_INTERVAL: Duration = Duration::from_secs(3600); // 1 hour
const RETENTION_POLICY: RetentionPolicy = {
    let mut retention_policy = HashMap::new();
    retention_policy.insert("log/server-%d/%Y%m%d.log", 7); // keep logs for 7 days
    retention_policy
};
const PATH_FORMAT: &str = "log/server-%d/%Y%m%d.log"; // log file path format
const RETENTION_THRESHOLD: u64 = 10; // number of logs to retain per server

fn main() {
    let mut servers = HashMap::new();
    for server in env::args().skip(1) {
        servers.insert(server, ServerStatus::default());
    }

    let cleanup_thread = thread::spawn(|| {
        loop {
            // run cleanup process every hour
            thread::sleep(CLEANUP_INTERVAL);
            cleanup(&servers);
        }
    });

    let mut log_files = HashMap::new();
    let mut requests = Vec::new();

    loop {
        // handle log file creation requests concurrently
        for request in &requests {
            if log_files.len() >= MAX_LOG_FILES {
                continue;
            }
            match create_log_file(&request) {
                Ok(path) => {
                    log_files.insert(path, 0); // add new log file to map with zero ref count
                }
                Err(err) => {
                    eprintln!("error creating log file: {}", err);
                }
            }
        }

        // update server status and handle failures
        for (server, status) in &servers {
            match update_server_status(server, status) {
                Ok(_) => continue,
                Err(err) => {
                    eprintln!("error updating server status: {}", err);
                    // retry failed requests after a short delay
                    thread::sleep(Duration::from_secs(5));
                    for request in &requests {
                        if let Ok(_) = update_server_status(request, status) {
                            continue;
                        } else {
                            eprintln!("error updating server status: {}", err);
                        }
                    }
                }
            }
        }

        // cleanup old log files based on retention policy
        for (path, ref_count) in &log_files {
            if *ref_count == 0 && !RETENTION_POLICY.contains(path) {
                match fs::remove_file(&path) {
                    Ok(_) => continue,
                    Err(err) => {
                        eprintln!("error removing log file: {}", err);
                    }
                }
            }
        }

        // clear requests and update server statuses
        requests.clear();
        for (server, status) in &servers {
            match update_server_status(server, status) {
                Ok(_) => continue,
                Err(err) => {
                    eprintln!("error updating server status: {}", err);
                }
            }
        }
    }
}

fn create_log_file(request: &Request) -> Result<PathBuf, std::io::Error> {
    let mut path = request.server.clone();
    path.push(format!("%Y%m%d-%H%M%S", Local::now()));
    fs::create_dir_all(&path)?;
    fs::write(path, "".as_bytes())?;
    Ok(path)
}

fn cleanup(servers: &HashMap<String, ServerStatus>) {
    let mut to_remove = Vec::new();
    for (path, ref_count) in &log_files {
        if *ref_count == 0 && !RETENTION_POLICY.contains(path) {
            to_remove.push(path);
        }
    }
    for path in to_remove {
        match fs::remove_file(&path) {
            Ok(_) => continue,
            Err(err) => {
                eprintln!("error removing log file: {}", err);
            }
        }
    }
}

fn update_server_status(server: &String, status: &ServerStatus) -> Result<(), std::io::Error> {
    let mut new_status = ServerStatus::default();
    match fs::read_to_string(&format!("{}.txt", server)) {
        Ok(contents) => new_status.parse(&contents)?,
        Err(_) => (),
    }
    if new_status != *status {
        fs::write(&format!("{}.txt", server), &new_status.to_string())?;
    }
    Ok(())
}

fn update_log_files(servers: &HashMap<String, ServerStatus>) -> Result<(), std::io::Error> {
    let mut to_update = Vec::new();
    for (server, status) in servers.iter() {
        if let Some(ref_count) = log_files.get(&format!("{}.txt", server)) {
            *ref_count += 1;
            to_update.push((server.clone(), *ref_count));
        } else {
            to_update.push((server.clone(), 0));
        }
    }
    for (server, ref_count) in &to_update {
        log_files.insert(format!("{}.txt", server), ref_count);
    }
    Ok(())
}

#[derive(Debug)]
struct ServerStatus {
    status: String,
}

impl ServerStatus {
    fn new() -> Self {
        Self {
            status: "".to_string(),
        }
    }

    fn parse(&mut self, contents: &str) -> Result<(), std::io::Error> {
        match serde_json::from_str(contents) {
            Ok(status) => {
                self.status = status;
                Ok(())
            }
            Err(err) => Err(std::io::Error::new(std::io::ErrorKind::Other, err)),
        }
    }

    fn to_string(&self) -> String {
        serde_json::to_string(&self.status).unwrap()
    }
}

