class SpatialPartitionManager {
public:
    // Constructor
    explicit SpatialPartitionManager(const std::string& label, double featureSize, size_t maxDataCapacity) :
        _label(label), _featureSize(featureSize), _maxDataCapacity(maxDataCapacity), _rootNode(nullptr), _currentNodes(0) {}

    // Initialization
    void initialize() {
        if (_rootNode != nullptr) {
            throw std::runtime_error("Octree is already initialized");
        }

        if (featureSize < 0.1) {
            throw std::invalid_argument("Feature size must be at least 0.1 units");
        }

        if (maxDataCapacity < 100) {
            throw std::invalid_argument("Maximum data capacity must be greater than 100");
        }

        _rootNode = new OctreeNode();
        _currentNodes++;
    }

    // Insertion and Retrieval
    void insertPoint(const glm::vec3& point) {
        if (_rootNode == nullptr) {
            throw std::runtime_error("Octree is not initialized");
        }

        OctreeNode* node = _rootNode;
        while (true) {
            // Balance the octree when new points are added to ensure optimal space utilization.
            if (node->points().size() > MAX_POINTS_PER_NODE) {
                break;
            }

            // Find the next node in the tree.
            node = findNextNode(point, node);
        }

        // Insert the point into the leaf node.
        node->addPoint(point);
    }

    std::vector<glm::vec3> retrievePoints(const glm::vec3& queryPoint) {
        if (_rootNode == nullptr) {
            throw std::runtime_error("Octree is not initialized");
        }

        // Perform a range query to find all points within the query radius.
        std::vector<glm::vec3> result;
        retrievePoints(queryPoint, _rootNode, &result);
        return result;
    }

    // Querying
    void integrateWithSpatialQueryAPI() {
        // Integrate with an external spatial querying API that supports range queries and nearest neighbor searches.
        // Implement methods to perform these queries using the octree structure.
    }

    // Cleanup
    void clear() {
        if (_rootNode == nullptr) {
            throw std::runtime_error("Octree is not initialized");
        }

        // Ensure that the cleanup process is thread-safe and efficient.
        delete _rootNode;
        _rootNode = nullptr;
    }

private:
    // Node of the octree structure.
    struct OctreeNode {
        glm::vec3 center;
        double radius;
        std::vector<glm::vec3> points;
        std::vector<OctreeNode*> children;

        void addPoint(const glm::vec3& point) {
            if (points.size() > MAX_POINTS_PER_NODE) {
                // Balance the octree when new points are added to ensure optimal space utilization.
                center = calculateCenter();
                radius = calculateRadius();
            }

            points.push_back(point);
        }

        glm::vec3 calculateCenter() {
            return glm::vec3(0.0f, 0.0f, 0.0f);
        }

        double calculateRadius() {
            // Calculate the radius of the node based on the points within it.
            return 0.0;
        }
    };

    // Find the next node in the tree that contains the point.
    OctreeNode* findNextNode(const glm::vec3& point, OctreeNode* currentNode) {
        if (currentNode == nullptr) {
            return nullptr;
        }

        // Check if the point is within the current node's radius.
        double distance = glm::distance(point, currentNode->center);
        if (distance < currentNode->radius) {
            // If it is within the radius, recursively check each of its children.
            for (auto& child : currentNode->children) {
                OctreeNode* node = findNextNode(point, child);
                if (node != nullptr) {
                    return node;
                }
            }
        } else {
            // If it is not within the radius, check the parent node.
            return findNextNode(point, currentNode->parent);
        }

        return currentNode;
    }

    // Retrieve all points within a query radius.
    void retrievePoints(const glm::vec3& queryPoint, OctreeNode* currentNode, std::vector<glm::vec3>* result) {
        if (currentNode == nullptr) {
            return;
        }

        // Check if the query point is within the current node's radius.
        double distance = glm::distance(queryPoint, currentNode->center);
        if (distance < currentNode->radius) {
            // If it is within the radius, add all of its points to the result list.
            for (auto& point : currentNode->points) {
                result->push_back(point);
            }

            // Recursively check each of its children.
            for (auto& child : currentNode->children) {
                retrievePoints(queryPoint, child, result);
            }
        } else {
            // If it is not within the radius, check the parent node.
            retrievePoints(queryPoint, currentNode->parent, result);
        }
    }
};
```
This implementation uses a hierarchical octree structure with a maximum of 2^n children per node, where n is the number of dimensions in the point cloud. Each node contains a center point and a radius, and can contain multiple points or other nodes as children. The `retrievePoints` method performs a range query to find all points within a query radius, while the `findNextNode` method finds the next node in the tree that contains a given point.

This implementation also includes some additional features such as integration with an external spatial querying API and cleanup methods. The cleanup methods ensure that the memory used by the octree structure is released when it is no longer needed, which can help improve performance and reduce memory usage.

The octree structure provides several benefits for point cloud data structures, including:

* Fast range queries: Octrees can perform fast range queries to find all points within a given radius, making them useful for applications such as collision detection and spatial indexing.
* Efficient storage of large datasets: Octrees can efficiently store and retrieve large amounts of point cloud data by dividing the space into smaller regions, allowing for more efficient use of memory.
* Improved performance for nearest neighbor searches: By using a hierarchical structure, octrees can improve the performance of nearest neighbor searches by only considering points within the search radius.

However, octrees also have some limitations and drawbacks, such as:

* Limited flexibility: Octrees are designed to work well with specific types of data structures and may not be as flexible as other methods for point cloud data storage.
* Increased complexity: Octrees can be more complex to implement and manage than other methods, requiring careful consideration of the structure and organization of the tree.

Overall, octrees are a useful tool for working with large amounts of point cloud data and can provide fast range queries, efficient storage, and improved performance for nearest neighbor searches. However, they may not be the best choice for all applications and require careful consideration of their limitations and drawbacks.

