// Python module for sending push notifications to multiple devices using different protocols (e.g., APNs, FCM)
import requests
from concurrent.futures import ThreadPoolExecutor

def sendPushNotification(device_type, device_id, message):
    # Send a push notification to the device using the appropriate protocol
    if device_type == "ios":
        response = requests.post("https://api.push.apple.com/3/device/" + device_id, data=message)
    elif device_type == "android":
        response = requests.post("https://fcm.googleapis.com/v1/projects/my-project/messages:send", json={"to": device_id, "data": message})
    else:
        # Unknown device type
        return False

    if response.status_code == 200:
        # Push notification sent successfully
        return True
    else:
        # Error sending push notification
        print("Error sending push notification:", response.text)
        return False

def sendPushNotifications(devices, messages):
    # Create a thread pool for concurrently sending push notifications
    with ThreadPoolExecutor() as executor:
        # Submit each push notification to the thread pool
        futures = [executor.submit(sendPushNotification, device_type, device_id, message) for device_type, device_id, message in zip(devices, messages)]

    return [future.result() for future in futures]
