        url = img["src"]
        if not os.path.exists(directory + "/" + url.split("/")[-1]):
            try:
                # Download and process the image, saving it to disk with a unique name
                image_data = downloadImage(url)
                processed_image = processImage(image_data)
                file = open(directory + "/" + url.split("/")[-1], "wb")
                file.write(processed_image)
            except Exception as e:
                # Error handling for downloading/processing images
