// Python script to modify a Kickstart configuration file by replacing placeholders with actual values provided through a dictionary
import re
import subprocess

def replacePlaceholders(file_path, placeholder_dict):
    # Replace placeholders in the Kickstart configuration file with actual values
    with open(file_path, "r") as file:
        content = file.read()

    for placeholder, value in placeholder_dict.items():
        pattern = re.compile("\{" + placeholder + "\}")
        content = pattern.sub(value, content)

    # Write the modified content to a new file
    with open("output.txt", "w") as file:
        file.write(content)
