// Define the maximum length for the input directory path
#define MAX_INPUT_PATH_LENGTH 1000

// Define the maximum number of packets to be processed per second
#define MAX_PACKETS_PER_SECOND 1000000

// Define the cache size for previously read file contents
#define CACHE_SIZE 1000000

// Define the time interval for periodically checking and updating the cache with new, pre-computed file contents from a batch processing job
#define UPDATE_CACHE_INTERVAL 3600

// Define the number of threads in the non-blocking thread pool for reading and concatenating files
#define NBTP_THREADS 4

// Define the maximum length for a file name
