#define MAX_RETRIES 5

// Define the time interval for retrying API calls, memory allocations, and database communication
#define RETRY_INTERVAL 10

// Define the maximum length for a message to be logged
#define MAX_LOG_MESSAGE_LENGTH 4096

// Define the log file name and path
#define LOG_FILE_NAME "packet_generator.log"
#define LOG_FILE_PATH "/var/log/"

// Define the configuration file name and path
#define CONFIG_FILE_NAME "packet_generator_config.txt"
#define CONFIG_FILE_PATH "/etc/"

// Define the encryption algorithm to use for securly appending passwords to the configuration
#define ENCRYPTION_ALGORITHM EVP_aes_256_cbc()

// Define the hashing algorithms to use for generating hashes of files
#define HASHING_ALGORITHMS SHA256(), MD5()

// Define the database connection parameters
