```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <semaphore.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>
#include <limits.h>
#include <assert.h>

#define SEMAPHORE_NAME "my_semaphore"
#define INITIAL_VALUE 1
#define TIMEOUT 5 // seconds

// Macro to check if a value is within the range of an integer
#define VALUE_IN_RANGE(value) ((value) >= INT_MIN && (value) <= INT_MAX)

// Structure to store semaphore state and stats
typedef struct {
    sem_t *sem; // Semaphore handle
    int value; // Current value of the semaphore
    long acquire_count; // Number of times the semaphore was acquired
    long release_count; // Number of times the semaphore was released
    long timeouts; // Number of times a timeout occurred when acquiring the semaphore
} semaphore_t;

// Function to create and initialize a named semaphore with an initial value
semaphore_t *create_semaphore(const char *name, int init_value) {
    if (!VALUE_IN_RANGE(init_value)) {
        fprintf(stderr, "Invalid initial value for semaphore\n");
        return NULL;
    }

    // Create a new semaphore object with the specified name and initial value
    semaphore_t *sem = (semaphore_t *)malloc(sizeof(semaphore_t));
    if (!sem) {
        fprintf(stderr, "Failed to allocate memory for semaphore\n");
        return NULL;
    }

    // Open a file descriptor for the semaphore using its name
    int fd = shm_open(name, O_CREAT | O_EXCL | O_RDWR, 0644);
    if (fd == -1) {
        fprintf(stderr, "Failed to create named semaphore: %s\n", strerror(errno));
        free(sem);
        return NULL;
    }

    // Set the initial value of the semaphore using ftruncate()
    if (ftruncate(fd, sizeof(int)) == -1) {
        fprintf(stderr, "Failed to set initial value for named semaphore: %s\n", strerror(errno));
        close(fd);
        free(sem);
        return NULL;
    }

    // Map the file descriptor to a memory region using mmap()
    void *addr = mmap(NULL, sizeof(int), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (addr == MAP_FAILED) {
        fprintf(stderr, "Failed to map named semaphore: %s\n", strerror(errno));
        close(fd);
        free(sem);
        return NULL;
    }

    // Initialize the semaphore handle and value
    sem->sem = (sem_t *)addr;
    sem->value = init_value;
    sem->acquire_count = 0;
    sem->release_count = 0;
    sem->timeouts = 0;

    // Close the file descriptor and return the semaphore handle
    close(fd);
    return sem;
}

// Function to delete a named semaphore and release its resources
void delete_semaphore(semaphore_t *sem) {
    if (!sem) {
        fprintf(stderr, "Invalid semaphore handle\n");
        return;
    }

    // Unmap the memory region associated with the semaphore handle using munmap()
    if (munmap((void *)sem->sem, sizeof(int)) == -1) {
        fprintf(stderr, "Failed to unmap named semaphore: %s\n", strerror(errno));
    }

    // Close the file descriptor associated with the semaphore using close()
    if (close(shm_open(sem->sem->name, O_RDWR, 0)) == -1) {
        fprintf(stderr, "Failed to close named semaphore: %s\n", strerror(errno));
    }

    // Free the memory allocated for the semaphore handle
    free(sem);
}

// Function to acquire a named semaphore and block until it becomes available or a timeout occurs
void *acquire_semaphore(semaphore_t *sem, long timeout) {
    if (!sem) {
        fprintf(stderr, "Invalid semaphore handle\n");
        return NULL;
    }

    // Check if the specified timeout is within the range of an integer
    if (!VALUE_IN_RANGE(timeout)) {
        fprintf(stderr, "Invalid timeout value for semaphore acquire\n");
        return NULL;
    }

    // Lock the semaphore to prevent concurrent modifications while acquiring it
    pthread_mutex_lock(&sem->sem->mutex);

    // Check if the semaphore has already been acquired and increment the acquisition count
    if (sem->value > 0) {
        sem->acquire_count++;
        sem->value--;
    } else if (timeout > 0) {
        // Block until the semaphore becomes available or a timeout occurs
        struct timespec ts = { .tv_sec = timeout, .tv_nsec = 0 };
        if (sem_timedwait(sem->sem, &ts) == -1) {
            pthread_mutex_unlock(&sem->sem->mutex);
            fprintf(stderr, "Failed to acquire named semaphore: %s\n", strerror(errno));
            return NULL;
        } else if (ts.tv_sec > 0 || ts.tv_nsec > 0) {
            // Increment the timeout count if the wait timed out
            sem->timeouts++;
        }
    } else {
        pthread_mutex_unlock(&sem->sem->mutex);
        fprintf(stderr, "Failed to acquire named semaphore: %s\n", strerror(errno));
        return NULL;
    }

    // Return the semaphore handle and unlock it
    pthread_mutex_unlock(&sem->sem->mutex);
    return (void *)sem;
}

// Function to release a named semaphore
void release_semaphore(semaphore_t *sem) {
    if (!sem) {
        fprintf(stderr, "Invalid semaphore handle\n");
        return;
    }

    // Lock the semaphore to prevent concurrent modifications while releasing it
    pthread_mutex_lock(&sem->sem->mutex);

    // Increment the release count and check if the semaphore has been acquired
    sem->release_count++;
    if (sem->value < 0) {
        // If the semaphore is not acquired, set its value to 1
        sem->value = 1;
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&sem->sem->mutex);
}

// Function to print the statistics of a named semaphore
void stats_semaphore(semaphore_t *sem) {
    if (!sem) {
        fprintf(stderr, "Invalid semaphore handle\n");
        return;
    }

    // Print the acquisition and release counts as well as the timeout count
    printf("Semaphore statistics:\nAcquired: %ld\nReleased: %ld\nTimeouts: %ld\n", sem->acquire_count, sem->release_count, sem->timeouts);
}

// Main function to demonstrate the usage of named semaphores
int main() {
    // Create a new named semaphore with an initial value of 1
    semaphore_t *sem = create_semaphore(1);

    // Acquire the semaphore and block until it becomes available or a timeout occurs
    void *result = acquire_semaphore(sem, 5);
    if (result == NULL) {
        fprintf(stderr, "Failed to acquire named semaphore\n");
        return 1;
    }

    // Release the semaphore and print its statistics
    release_semaphore(sem);
    stats_semaphore(sem);

    // Delete the named semaphore and free its resources
    delete_semaphore(sem);

    return 0;
}
