function establishDatabaseConnectionTest(moduleLabel, testSuites, config) {
  // Initialize the database connection pool
  const dbConnectionPool = new DatabaseConnectionPool(config);

  // Set up the mocking library (e.g., Blueslip) to isolate each test suite
  const blueslip = require('blueslip');

  // Iterate over the test suites and execute each one in a new thread
  for (const testSuite of testSuites) {
    // Set up the test case retry mechanism with configurable retry attempts and delays between retries
    const retryAttempts = config.retryAttempts || 3;
    const retryDelay = config.retryDelay || 500;

    for (let attempt = 1; attempt <= retryAttempts; attempt++) {
      try {
        // Execute the test case and log the results to the console
        const result = executeTestCase(testSuite, blueslip);
        console.log(`${moduleLabel} - ${result.name}: PASS`);
        break;
      } catch (error) {
        console.warn(`${moduleLabel} - ${result.name}: FAIL (${attempt}/${retryAttempts})`);
        if (attempt === retryAttempts) {
          throw error;
        }
      } finally {
        // Reset the mocking library after each test suite to avoid side effects across tests
        blueslip.reset();
      }
    }
  }
}

function executeTestCase(testSuite, blueslip) {
  // Set up the test case with the necessary dependencies and configuration
  const testCase = {
    name: `${moduleLabel}-${testSuite.name}`,
    dependencies: testSuite.dependencies || [],
    config: testSuite.config || {},
  };

  // Dynamically load and execute the necessary modules for each test case
  const moduleLoader = new ModuleLoader(testCase.dependencies);
  moduleLoader.execute();

  // Generate and save a test coverage report using a popular JavaScript testing library (e.g., Mocha)
  const mocha = require('mocha');
  const istanbul = require('istanbul');
  const { coverage } = istanbul;
  const collector = new Collector();

  // Track and display the duration of each test case execution, including any overhead due to resource management
  const startTime = Date.now();

  // Execute the test case and handle errors gracefully
  try {
    // Run the test case with the configured settings and dependencies
    const result = mocha.runWith(testCase.name, testCase.config, testCase.dependencies);

    // Save the test coverage report to a JSON file for further analysis
    const jsonReporter = new JsonReporter({ exitOnError: false });
    jsonReporter.write(collector, true);
  } catch (error) {
    console.error(`${moduleLabel} - ${testCase.name}: FAIL`);
    throw error;
  } finally {
    // Reset the mocking library and clear the test coverage report after each test case execution
    blueslip.reset();
    collector.clear();
  }

  // Return a summary of the test case results to the caller
  const endTime = Date.now();
  return {
    name: testCase.name,
    duration: endTime - startTime,
    result: 'PASS',
  };
}
