    def __init__(self, directory):
        self.directory = directory

    def create_directories(self, field_names):
        for field_name in field_names:
            try:
                os.makedirs(os.path.join(self.directory, field_name))
                logging.info(f'Created directory {field_name}')
            except FileExistsError as e:
                logging.warning(f'Directory {field_name} already exists')

    def periodic_cleanup(self):
        pass

    def refresh_directories(self, field_names):
        for field_name in field_names:
            try:
                if os.path.exists(os.path.join(self.directory, field_name)):
                    # Send a refresh status message to the parent window
                    logging.info(f'Refreshing directory {field_name}')
                else:
                    self.create_directories([field_name])
            except FileExistsError as e:
                logging.warning(f'Directory {field_name} already exists')

    def get_directory_info(self, field_names):
        for field_name in field_names:
            try:
                if os.path.exists(os.path.join(self.directory, field_name)):
                    # Send a refresh status message to the parent window
                    logging.info(f'Getting directory info {field_name}')
                else:
                    self.create_directories([field_name])
            except FileExistsError as e:
                logging.warning(f'Directory {field_name} already exists')

