```php
<?php

// Load required libraries and dependencies
require_once 'vendor/autoload.php';
use Symfony\Component\HttpFoundation\Request;
use Symfony\Component\HttpFoundation\Response;
use Doctrine\ORM\EntityManagerInterface;
use App\Entity\User;
use App\Repository\UserRepository;
use Psr\Log\LoggerInterface;

class DynamicImageCrawler {
    private $em;
    private $repository;
    private $logger;

    public function __construct(EntityManagerInterface $em, UserRepository $repository, LoggerInterface $logger) {
        $this->em = $em;
        $this->repository = $repository;
        $this->logger = $logger;
    }

    // Handle create user account request
    public function handleCreateUserRequest(Request $request) {
        try {
            $data = json_decode($request->getContent(), true);

            // Validate input data
            if (!isset($data['email']) || !filter_var($data['email'], FILTER_VALIDATE_EMAIL)) {
                throw new \Exception("Invalid email address");
            }

            if (!isset($data['password']) || strlen($data['password']) < 8) {
                throw new \Exception("Password must be at least 8 characters long");
            }

            // Create user account
            $user = new User();
            $user->setEmail($data['email']);
            $user->setPassword($this->hashPassword($data['password']));

            // Save user account to database
            $this->em->persist($user);
            $this->em->flush();

            return new Response(json_encode([
                'status' => 'success',
                'message' => 'User account created successfully',
                'data' => [
                    'id' => $user->getId(),
                    'name' => $user->getName(),
                    'email' => $user->getEmail()
                ]
            ]));
        } catch (\Exception $e) {
            return new Response(json_encode([
                'status' => 'error',
                'message' => "Failed to create user account due to {$e->getMessage()}",
                'data' => null
            ]));
        }
    }

    // Handle update user account request
    public function handleUpdateUserRequest(Request $request) {
        try {
            $data = json_decode($request->getContent(), true);

            // Validate input data
            if (!isset($data['id']) || !is_numeric($data['id'])) {
                throw new \Exception("Invalid user ID");
            }

            if (isset($data['email']) && filter_var($data['email'], FILTER_VALIDATE_EMAIL)) {
                $user = $this->repository->find($data['id']);

                if ($user) {
                    $user->setEmail($data['email']);
                    $this->em->flush();
                } else {
                    throw new \Exception("User with ID {$data['id']} not found");
                }
            }

            if (isset($data['password']) && strlen($data['password']) >= 8) {
                $user = $this->repository->find($data['id']);

                if ($user) {
                    $user->setPassword($this->hashPassword($data['password']));
                    $this->em->flush();
                } else {
                    throw new \Exception("User with ID {$data['id']} not found");
                }
            }

            return new Response(json_encode([
                'status' => 'success',
                'message' => 'User account updated successfully',
                'data' => [
                    'id' => $user->getId(),
                    'name' => $user->getName(),
                    'email' => $user->getEmail()
                ]
            ]));
        } catch (\Exception $e) {
            return new Response(json_encode([
                'status' => 'error',
                'message' => "Failed to update user account due to {$e->getMessage()}",
                'data' => null
            ]));
        }
    }

    // Handle delete user account request
    public function handleDeleteUserRequest(Request $request) {
        try {
            $data = json_decode($request->getContent(), true);

            // Validate input data
            if (!isset($data['id']) || !is_numeric($data['id'])) {
                throw new \Exception("Invalid user ID");
            }

            $user = $this->repository->find($data['id']);

            if ($user) {
                $this->em->remove($user);
                $this->em->flush();
            } else {
                throw new \Exception("User with ID {$data['id']} not found");
            }

            return new Response(json_encode([
                'status' => 'success',
                'message' => "User account with ID {$data['id']} deleted successfully",
                'data' => null
            ]));
        } catch (\Exception $e) {
            return new Response(json_encode([
                'status' => 'error',
                'message' => "Failed to delete user account due to {$e->getMessage()}",
                'data' => null
            ]));
        }
    }

    // Hash password using BCrypt
    private function hashPassword($password) {
        $hash = password_hash($password, PASSWORD_BCRYPT, ['cost' => 12]);

        return $hash;
    }
}
