```rust
use std::{fs, io};
use http::{RequestBuilder, Url};
use reqwest::Client;
use serde_json::Value;
use log::{error, info};

struct HttpClient {
    client: Client,
    config: Value,
}

impl HttpClient {
    fn new(config_file: &str) -> Self {
        let config = load_config(config_file);
        Self {
            client: reqwest::Client::builder().build()?,
            config: config,
        }
    }

    fn request(&self, url: &Url) -> io::Result<RequestBuilder> {
        let mut builder = self.client.request(url);
        if !self.config["disable_certificate_validation"].as_bool().unwrap() {
            builder = builder.danger_accept_invalid_certs();
        }
        for (header, value) in &self.config["headers"] {
            builder = builder.header(header, value);
        }
        if self.config["redirects"].as_bool().unwrap() {
            builder = builder.follow_redirects();
        }
        Ok(builder)
    }

    fn send(&self, request: &RequestBuilder) -> io::Result<Response> {
        let response = self.client.execute(request)?;
        if !response.status().is_success() {
            error!("Received error from server: {}", response);
        }
        Ok(response)
    }
}

fn load_config(config_file: &str) -> Value {
    let config = fs::read_to_string(config_file)?;
    serde_json::from_str(&config).unwrap()
}
