<?php

function dynamicClinicScheduler($operation, $clinic_id, $status, $location, $capacity) {
    // Connect to the MySQL database and check for existing clinic records
    $db = mysqli_connect("localhost", "username", "password", "database");
    if (!$db) {
        trigger_error("Failed to connect to MySQL: " . mysqli_connect_error());
    }

    // Perform the requested operation based on the given parameters
    switch ($operation) {
        case "create":
            // Check if the clinic ID is already in use
            $query = "SELECT id FROM clinics WHERE id = '$clinic_id'";
            $result = mysqli_query($db, $query);
            if (mysqli_num_rows($result) > 0) {
                return array("error" => "Clinic ID already in use");
            }

            // Insert the new clinic record into the database
            $query = "INSERT INTO clinics (id, status, location, capacity) VALUES ('$clinic_id', '$status', '$location', '$capacity')";
