using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;

namespace CsvFileProcessor
{
    public class CsvFileProcessor
    {
        private readonly string _filePath;
        private readonly int _bufferSize;
        private readonly object _lockObject = new object();
        private Dictionary<string, List<T>> _cache = new Dictionary<string, List<T>>();

        public CsvFileProcessor(string filePath, int bufferSize = 1024)
        {
            _filePath = filePath;
            _bufferSize = bufferSize;
        }

        // GetColumnData method implementation
        public List<T> GetColumnData<T>(string columnName) where T : struct
        {
            lock (_lockObject)
            {
                if (!_cache.ContainsKey(columnName))
                {
                    try
                    {
                        using var reader = new StreamReader(_filePath);
                        string line;
                        while ((line = reader.ReadLine()) != null)
                        {
                            string[] values = line.Split(',');
                            if (values.Length == 0) continue;
                            List<T> columnData = new List<T>();
                            for (int i = 0; i < values.Length; i++)
                            {
                                if (!string.IsNullOrWhiteSpace(values[i]))
                                {
                                    T value;
                                    if (typeof(T) == typeof(int))
                                    {
                                        value = Convert.ToInt32(values[i]);
                                    }
                                    else if (typeof(T) == typeof(double))
                                    {
                                        value = Convert.ToDouble(values[i]);
                                    }
                                    else
                                    {
                                        value = values[i];
                                    }
                                    columnData.Add(value);
                                }
                            }
                            _cache.Add(columnName, columnData);
                        }
                    }
                    catch (Exception ex)
                    {
                        throw new ColumnNotFoundException($"Column '{columnName}' not found in file.");
                    }
                }
                return _cache[columnName];
            }
        }

        // GetRowData method implementation
        public Dictionary<string, T> GetRowData(int rowIndex) where T : struct
        {
            lock (_lockObject)
            {
                if (rowIndex < 0 || rowIndex >= _cache.Count) return null;
                Dictionary<string, T> rowData = new Dictionary<string, T>();
                foreach (var column in _cache.Keys)
                {
                    rowData[column] = _cache[column][rowIndex];
                }
                return rowData;
            }
        }

        // ExportToCsv method implementation
        public void ExportToCsv(string outputFilePath, Dictionary<string, List<T>> data)
        {
            using var writer = new StreamWriter(outputFilePath);
            foreach (var column in data.Keys)
            {
                writer.Write($"{column},");
            }
            writer.WriteLine();
            foreach (var row in data.Values)
            {
                foreach (var value in row)
                {
                    if (value is int || value is double)
                    {
                        writer.Write($"{value},");
                    }
                    else
                    {
                        writer.Write($"\"{value}\",");
                    }
                }
                writer.WriteLine();
            }
        }
    }
}
