import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

import org.apache.http.HttpResponse;
import org.apache.http.client.methods.HttpPut;
import org.apache.http.entity.ByteArrayEntity;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;

public class CloudStorageClient {
    private static final int MAX_CONCURRENT_REQUESTS = 100;
    private static final int REQUEST_RETRY_COUNT = 3;
    private static final long RATE_LIMIT_INTERVAL = 5000L; // 5 seconds

    private CloseableHttpClient httpClient;
    private ExecutorService executorService;

    public CloudStorageClient() {
        this.httpClient = HttpClients.createDefault();
        this.executorService = Executors.newFixedThreadPool(MAX_CONCURRENT_REQUESTS);
    }

    public void close() throws Exception {
        httpClient.close();
        executorService.shutdownNow();
    }

    private HttpResponse executeRequest(HttpPut request) {
        try {
            return httpClient.execute(request);
        } catch (Exception e) {
            if (e instanceof InterruptedException || e instanceof IOException) {
                throw new RuntimeException("Error executing HTTP request", e);
            } else {
                return null; // retry policy will handle this case
            }
        }
    }

    private void retryRequest(HttpPut request, int retriesLeft) {
        try {
            executeRequest(request);
        } catch (Exception e) {
            if (retriesLeft > 0) {
                // retry policy will handle this case
            } else {
                throw new RuntimeException("Error executing HTTP request", e);
            }
        }
    }

    public void putObject(String bucketName, String objectKey, byte[] data) throws Exception {
        HttpPut request = new HttpPut("https://s3.amazonaws.com/" + bucketName + "/" + objectKey);
        request.setEntity(new ByteArrayEntity(data));
        int retriesLeft = REQUEST_RETRY_COUNT;
        while (retriesLeft > 0) {
            HttpResponse response = executeRequest(request);
            if (response == null || response.getStatusLine().getStatusCode() != 200) {
                retryRequest(request, retriesLeft - 1);
            } else {
                break;
            }
        }
    }

    public byte[] getObject(String bucketName, String objectKey) throws Exception {
        HttpGet request = new HttpGet("https://s3.amazonaws.com/" + bucketName + "/" + objectKey);
        int retriesLeft = REQUEST_RETRY_COUNT;
        while (retriesLeft > 0) {
            HttpResponse response = executeRequest(request);
            if (response == null || response.getStatusLine().getStatusCode() != 200) {
                retryRequest(request, retriesLeft - 1);
            } else {
                return EntityUtils.toByteArray(response.getEntity());
            }
        }
    }

    public void deleteObject(String bucketName, String objectKey) throws Exception {
        HttpDelete request = new HttpDelete("https://s3.amazonaws.com/" + bucketName + "/" + objectKey);
        int retriesLeft = REQUEST_RETRY_COUNT;
        while (retriesLeft > 0) {
            HttpResponse response = executeRequest(request);
            if (response == null || response.getStatusLine().getStatusCode() != 204) {
                retryRequest(request, retriesLeft - 1);
            } else {
                break;
            }
        }
    }
}
