#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

// Semaphore types
enum sem_type {
    SEM_TYPE_COUNTING,
    SEM_TYPE_BINARY,
};

// Semaphore structure
struct semaphore {
    int id; // Unique identifier for the semaphore
    enum sem_type type; // Type of semaphore (counting or binary)
    union {
        struct {
            int value; // Current value of the counting semaphore
            pthread_mutex_t mutex; // Mutex for protecting access to the semaphore
            pthread_cond_t cond; // Condition variable for waiting threads
        } counting;
        struct {
            char binary[1]; // Binary semaphore (always set to 0 or 1)
            pthread_mutex_t mutex; // Mutex for protecting access to the semaphore
            pthread_cond_t cond; // Condition variable for waiting threads
        } binary;
    };
};

// Semaphore table (for storing and retrieving semaphores)
struct semaphore *semaphores = NULL;
size_t num_semaphores = 0;

// Mutex for protecting access to the semaphore table
pthread_mutex_t semaphore_table_lock = PTHREAD_MUTEX_INITIALIZER;

// Condition variable for waiting threads
pthread_cond_t semaphore_table_cv = PTHREAD_COND_INITIALIZER;

// Function to create a new semaphore with the given type and initial value
int create_semaphore(enum sem_type type, int init_value) {
    // Lock the semaphore table mutex
    pthread_mutex_lock(&semaphore_table_lock);

    // Allocate a new semaphore structure and initialize its fields
    struct semaphore *new_sem = malloc(sizeof(struct semaphore));
    new_sem->id = num_semaphores++;
    new_sem->type = type;
    if (type == SEM_TYPE_COUNTING) {
        new_sem->counting.value = init_value;
        pthread_mutex_init(&new_sem->counting.mutex, NULL);
        pthread_cond_init(&new_sem->counting.cond, NULL);
    } else if (type == SEM_TYPE_BINARY) {
        new_sem->binary.value = init_value;
        pthread_mutex_init(&new_sem->binary.mutex, NULL);
        pthread_cond_init(&new_sem->binary.cond, NULL);
    }

    // Add the new semaphore to the table and signal any waiting threads
    if (num_semaphores > 0) {
        semaphores = realloc(semaphores, num_semaphores * sizeof(struct semaphore));
    } else {
        semaphores = malloc(sizeof(struct semaphore));
    }
    semaphores[new_sem->id] = new_sem;
    pthread_cond_signal(&semaphore_table_cv);

    // Unlock the mutex and return success
    pthread_mutex_unlock(&semaphore_table_lock);
    return 0;
}

// Function to delete a semaphore with the given ID
int delete_semaphore(int id) {
    // Lock the semaphore table mutex
    pthread_mutex_lock(&semaphore_table_lock);

    // Check if the semaphore exists in the table
    struct semaphore *sem = semaphores[id];
    if (sem == NULL) {
        return -1;
    }

    // Free the semaphore structure and remove it from the table
    free(sem);
    semaphores[id] = NULL;

    // Signal any waiting threads and unlock the mutex
    pthread_cond_signal(&semaphore_table_cv);
    pthread_mutex_unlock(&semaphore_table_lock);
    return 0;
}

// Function to acquire a semaphore with the given ID and timeout in milliseconds
int acquire_semaphore(int id, int timeout) {
    // Lock the semaphore table mutex
    pthread_mutex_lock(&semaphore_table_lock);

    // Check if the semaphore exists in the table
    struct semaphore *sem = semaphores[id];
    if (sem == NULL) {
        return -1;
    }

    // If the semaphore is binary, simply wait on the condition variable
    if (sem->type == SEM_TYPE_BINARY) {
        pthread_mutex_lock(&sem->binary.mutex);
        while (sem->binary.value == 0) {
            pthread_cond_wait(&sem->binary.cond, &sem->binary.mutex);
        }
        sem->binary.value = 0;
        pthread_mutex_unlock(&sem->binary.mutex);
    } else if (sem->type == SEM_TYPE_COUNTING) {
        // If the semaphore is counting, we need to acquire a mutex and decrement its value
        pthread_mutex_lock(&sem->counting.mutex);
        while (sem->counting.value <= 0) {
            pthread_cond_wait(&sem->counting.cond, &sem->counting.mutex);
        }
        sem->counting.value--;
        // If a timeout was specified, we need to wait on the condition variable until it is signaled or the timeout expires
        if (timeout > 0) {
            struct timespec ts = get_timespec(timeout);
            int result = pthread_cond_timedwait(&sem->counting.cond, &sem->counting.mutex, &ts);
            // If the timeout expired or an error occurred, release the mutex and return -1
            if (result == ETIMEDOUT || result < 0) {
                pthread_mutex_unlock(&sem->counting.mutex);
                return -1;
            }
        }
    }

    // Unlock the mutex and return success
    pthread_mutex_unlock(&semaphore_table_lock);
    return 0;
}

// Function to release a semaphore with the given ID
int release_semaphore(int id) {
    // Lock the semaphore table mutex
    pthread_mutex_lock(&semaphore_table_lock);

    // Check if the semaphore exists in the table
    struct semaphore *sem = semaphores[id];
    if (sem == NULL) {
        return -1;
    }

    // If the semaphore is binary, simply signal its condition variable
    if (sem->type == SEM_TYPE_BINARY) {
        pthread_mutex_lock(&sem->binary.mutex);
        sem->binary.value = 1;
        pthread_cond_signal(&sem->binary.cond);
        pthread_mutex_unlock(&sem->binary.mutex);
    } else if (sem->type == SEM_TYPE_COUNTING) {
        // If the semaphore is counting, we need to acquire a mutex and increment its value
        pthread_mutex_lock(&sem->counting.mutex);
        sem->counting.value++;
        pthread_cond_signal(&sem->counting.cond);
        pthread_mutex_unlock(&sem->counting.mutex);
    }

    // Unlock the mutex and return success
    pthread_mutex_unlock(&semaphore_table_lock);
    return 0;
}

// Function to get a timespec structure for the given timeout in milliseconds
struct timespec get_timespec(int timeout) {
    struct timespec ts = {};
    clock_gettime(CLOCK_MONOTONIC, &ts);
    int sec = (timeout - 1) / 1000;
    int nsec = (timeout - 1) % 1000 * 1000000;
    ts.tv_sec += sec;
    ts.tv_nsec += nsec;
    return ts;
}
```

This code creates a hash table to store the semaphores and uses mutexes and condition variables to implement the semaphore operations. The `create_semaphore` function creates a new semaphore with the given initial value, the `delete_semaphore` function deletes a semaphore with the given ID, the `acquire_semaphore` function acquires a semaphore with the given ID and timeout in milliseconds, and the `release_semaphore` function releases a semaphore with the given ID. The `get_timespec` function converts a timeout in milliseconds to a timespec structure for use with condition variables.

