import time
from datetime import datetime
from typing import List, Dict
from collections import deque

class RealTimeDataAggregator:
    def __init__(self, devices: List[str], aggregation_window: int = 60, max_buffer_size: int = 10000):
        self.devices = devices
        self.aggregation_window = aggregation_window
        self.max_buffer_size = max_buffer_size
        self.data_buffers = {}
        for device in self.devices:
            self.data_buffers[device] = deque(maxlen=self.max_buffer_size)

    def _process_data(self, data: Dict[str, float], timestamp: datetime):
        for device, value in data.items():
            if device not in self.data_buffers:
                continue
            self.data_buffers[device].append((value, timestamp))

    def _aggregate_data(self):
        aggregated_data = {}
        for device, buffer in self.data_buffers.items():
            if not buffer:
                continue
            values = [x[0] for x in buffer]
            mean = sum(values) / len(values)
            stddev = sum((x - mean)**2 for x in values)**0.5
            aggregated_data[device] = {
                "mean": mean,
                "stddev": stddev,
                "timestamp": timestamp
            }
        return aggregated_data

    def _filter_data(self, data: Dict[str, float], threshold: float):
        filtered_data = {}
        for device, value in data.items():
            if value < threshold:
                continue
            filtered_data[device] = value
        return filtered_data

    def _send_to_cloud(self, data: Dict[str, float], timestamp: datetime):
        # Send the data to the cloud storage service using TLS encryption
        pass

    def _send_to_visualization(self, data: Dict[str, float], timestamp: datetime):
        # Send the data to the visualization dashboard
        pass

    def run(self):
        while True:
            try:
                start = time.time()
                for device in self.devices:
                    try:
                        data, timestamp = ssl.recv(device)
                        if not data:
                            continue
                        data = json.loads(data)
                        self._process_data(data, timestamp)
                        aggregated_data = self._aggregate_data()
                        filtered_data = self._filter_data(aggregated_data, threshold=0.5)
                        self._send_to_cloud(filtered_data, timestamp)
                        self._send_to_visualization(filtered_data, timestamp)
                    except ssl.SSLError:
                        continue
                end = time.time()
                sleep_time = max(0, self.aggregation_window - (end - start))
                time.sleep(sleep_time)
            except Exception as e:
                print("Error in RealTimeDataAggregator")
                print(e)
