    char* result = NULL;
    int length = strlen(input_str);
    int word_count = 0;
    int total_word_length = 0;
    int adjusted_size_limit = size_limit;

    // Fetch the list of words to be trimmed from the beginning and end of the input string
    char** words = fetchWords(input_str);
    if (!words) {
        printf("Error: Failed to fetch word list\n");
        return NULL;
    }

    // Trim the specified words from the beginning and end of the input string
    for (int i = 0; i < length && word_count < adjusted_size_limit; i++) {
        if (!strncmp(input_str + i, words[word_count], strlen(words[word_count]))) {
            // Skip over the trimmed word and update the length accordingly
            i += strlen(words[word_count]);
            total_word_length += strlen(words[word_count]);
            word_count++;
        } else {
            break;
        }
    }

    // Capitalize the first letter of each word in the resulting string
    char* output_str = malloc((length - total_word_length) * sizeof(char));
    if (!output_str) {
        printf("Error: Failed to allocate memory for output string\n");
        return NULL;
    }
    int output_index = 0;
    for (int i = 0; i < length && output_index < adjusted_size_limit - word_count; i++) {
        if (!strncmp(input_str + i, words[word_count], strlen(words[word_count]))) {
            // Skip over the trimmed word and update the length accordingly
            i += strlen(words[word_count]);
            total_word_length += strlen(words[word_count]);
            word_count++;
        } else if (isalpha(input_str[i])) {
            output_str[output_index++] = toupper(input_str[i]);
        } else {
            output_str[output_index++] = input_str[i];
        }
    }
    result = output_str;

    // Free memory allocated for the word list and return the trimmed and capitalized string
    freeWords(words);
    return result;
}
