// Async array reduce function
const asyncArrayReduce = (arr, initialValue, callback) => {
  // Initialize variables
  let accumulatedValue = initialValue;
  let completedOperations = 0;
  const totalOperations = arr.length;
  let errorOccurred = false;

  // Handle errors within the callback function
  try {
    for (let i = 0; i < arr.length && !errorOccurred; i++) {
      accumulatedValue = await callback(accumulatedValue, arr[i], i, arr);
      completedOperations++;
    }
  } catch (err) {
    errorOccurred = true;
    console.log(`Error occurred while reducing array: ${err}`);
  }

  // Report the progress of the reduction process
  console.log(`Completed ${completedOperations} operations out of ${totalOperations}`);

  // Return the final reduced value or an error if one occurs
  return errorOccurred ? err : accumulatedValue;
};
