use std::fs::File;
use std::io::Read;
use std::path::Path;
use std::time::Instant;

fn get_compilation_summary(directory_path: &str) -> Result<String, String> {
    // Initialize variables
    let mut files = Vec::new();
    let mut total_time = 0.0;
    let mut peak_memory = 0;
    let start_time = Instant::now();

    // Get a list of Rust files in the directory
    if let Ok(dir) = std::fs::read_dir(directory_path) {
        for file in dir.flatten() {
            let path = Path::new(&file.path());
            if let Some(ext) = path.extension().and_then(|os| os.to_str()) {
                if ext == "rs" {
                    files.push(path);
                }
            }
        }
    } else {
        return Err("Failed to read directory".to_string());
    }

    // Compile all Rust files in the directory
    for file in &files {
        let mut file = File::open(&file.to_str().unwrap())?;
        let mut contents = String::new();
        if let Ok(size) = file.read_to_string(&mut contents) {
            if size > 0 {
                // Compile the Rust file
                let compile_start_time = Instant::now();
                let _output = std::process::Command::new("rustc")
                    .arg(file.path())
                    .spawn()?
                    .wait_with_output()?;
                total_time += compile_start_time.elapsed().as_secs_f64();
                peak_memory = std::cmp::max(peak_memory, get_resident_set_size());
            }
        } else {
            return Err("Failed to read file contents".to_string());
        }
    }

    // Log the compilation progress and any warnings or errors encountered
    let end_time = Instant::now();
    println!("Compilation summary:");
    println!("  Total time taken: {:.2} seconds", total_time);
    println!("  Peak memory usage: {} bytes", peak_memory);
    println!("  Completed compilation of {} files in {:.2} seconds", files.len(), end_time.duration_since(start_time).as_secs_f64());

    // Return the summary as a string
    Ok(format!("Compilation summary:\nTotal time taken: {:.2} seconds\nPeak memory usage: {} bytes\nCompleted compilation of {} files in {:.2} seconds", total_time, peak_memory, files.len(), end_time.duration_since(start_time).as_secs_f64()))
}
