import os
import logging
import time
from concurrent.futures import ThreadPoolExecutor

logging.basicConfig(filename="logfile.txt", level=logging.INFO)

class LogProcessor:
    def __init__(self, log_file):
        self.log_file = log_file
        self.executor = ThreadPoolExecutor(max_workers=5)

    def process_chunk(self, chunk):
        # Process a chunk of the log file in parallel
        with open(self.log_file, 'r') as f:
            for line in f:
                # Calculate average response time for requests from each unique IP address
                if 'IP' in line:
                    ip = line.split(' ')[1]
                    start_time = float(line.split(' ')[2])
                    end_time = float(line.split(' ')[3])
                    response_time = end_time - start_time
                    logging.info(f"IP {ip}: Average response time: {response_time} ms")
                # Aggregate data safely to avoid race conditions and ensure data integrity
                else:
                    logging.info(line)

    def process_log(self):
        # Process the entire log file in parallel using a ThreadPoolExecutor
        with open(self.log_file, 'r') as f:
            chunks = []
            for line in f:
                if len(chunks) == 0 or chunks[-1] != '\n':
                    chunks.append(line)
                else:
                    chunks.pop()
                    self.executor.submit(self.process_chunk, ''.join(chunks))
                    chunks = []
            if len(chunks) > 0:
                self.executor.submit(self.process_chunk, ''.join(chunks))

if __name__ == "__main__":
    log_file = "10GB_logfile.txt"
    processor = LogProcessor(log_file)
    start_time = time.time()
    processor.process_log()
    end_time = time.time()
    logging.info("Processing time: {} seconds".format(end_time - start_time))
