CryptographicFunction = namedtuple('CryptographicFunction', ['name', 'function'])

class CryptoHash:
    def __init__(self, filename):
        self.filename = filename
        self.functions = []
        self.params = []

    def read_hashes(self):
        with open(self.filename, 'r') as f:
            hashes = json.load(f)
            for hash in hashes:
                self.functions.append(CryptographicFunction(name=hash['Name'], function=hash['Function']))
                if 'Params' in hash:
                    self.params.extend([Param(**param) for param in hash['Params']])

    def verify_function(self, name):
        for function in self.functions:
            if function.name == name:
                return True
        return False

    def get_function(self, name):
        for function in self.functions:
            if function.name == name:
                return function
        raise Exception(f"Cryptographic function {name} does not exist")

    def get_params(self, name):
        for param in self.params:
            if param.function == name:
                yield param
