<?php

class UserDAO {
    private $db;

    public function __construct($db) {
        $this->db = $db;
    }

    public function updateUserPassword($username, $new_password) {
        // Validate new password
        if (strlen($new_password) < 8 || !preg_match('/[A-Z]/', $new_password) || !preg_match('/[a-z]/', $new_password) || !preg_match('/\d/', $new_password) || !preg_match('/[^A-Za-z\d]/', $new_password)) {
            throw new Exception("Invalid password");
        }

        // Check if username is contained in the password
        if (strpos($new_password, $username) !== false) {
            throw new Exception("Username cannot be part of the password");
        }

        // Update password
        $sql = "UPDATE users SET password = ? WHERE username = ?";
        $stmt = $this->db->prepare($sql);
        $stmt->bindValue(1, $new_password, PDO::PARAM_STR);
        $stmt->bindValue(2, $username, PDO::PARAM_STR);
        $stmt->execute();
    }
}

class RecommendationEngine {
    private $db;

    public function __construct($db) {
        $this->db = $db;
    }

    public function updateUserPreferences($username, $new_preferences) {
        // Validate new preferences
        if (!is_array($new_preferences)) {
            throw new Exception("Invalid preferences");
        }

        // Check if username is contained in the preferences
        if (strpos($new_preferences, $username) !== false) {
            throw new Exception("Username cannot be part of the preferences");
        }

        // Update preferences
        $sql = "UPDATE users SET preferences = ? WHERE username = ?";
        $stmt = $this->db->prepare($sql);
        $stmt->bindValue(1, json_encode($new_preferences), PDO::PARAM_STR);
        $stmt->bindValue(2, $username, PDO::PARAM_STR);
        $stmt->execute();
    }
}

class UserService {
    private $dao;
    private $engine;

    public function __construct($dao, $engine) {
        $this->dao = $dao;
        $this->engine = $engine;
    }

    public function updateUserPassword($username, $new_password) {
        // Validate new password
        if (strlen($new_password) < 8 || !preg_match('/[A-Z]/', $new_password) || !preg_match('/[a-z]/', $new_password) || !preg_match('/\d/', $new_password) || !preg_match('/[^A-Za-z\d]/', $new_password)) {
            throw new Exception("Invalid password");
        }

        // Check if username is contained in the password
        if (strpos($new_password, $username) !== false) {
            throw new Exception("Username cannot be part of the password");
        }

        // Update password
        try {
            $this->dao->updateUserPassword($username, $new_password);
        } catch (Exception $e) {
            // Log error and return
            $this->logError("Error updating user password: " . $e->getMessage());
            return;
        }
    }

    public function updateUserPreferences($username, $new_preferences) {
        // Validate new preferences
        if (!is_array($new_preferences)) {
            throw new Exception("Invalid preferences");
        }

        // Check if username is contained in the preferences
        if (strpos($new_preferences, $username) !== false) {
            throw new Exception("Username cannot be part of the preferences");
        }

        // Update preferences
        try {
            $this->engine->updateUserPreferences($username, $new_preferences);
        } catch (Exception $e) {
            // Log error and return
            $this->logError("Error updating user preferences: " . $e->getMessage());
            return;
        }
    }

    public function logError($message) {
        // Log error to audit log table
        $sql = "INSERT INTO audit_log (message, timestamp, ip_address, user_agent) VALUES (?, ?, ?, ?)";
        $stmt = $this->db->prepare($sql);
        $stmt->bindValue(1, $message, PDO::PARAM_STR);
        $stmt->bindValue(2, time(), PDO::PARAM_INT);
        $stmt->bindValue(3, $_SERVER['REMOTE_ADDR'], PDO::PARAM_STR);
        $stmt->bindValue(4, $_SERVER['HTTP_USER_AGENT'], PDO::PARAM_STR);
        $stmt->execute();
    }
}
