// Octree node structure
struct OctreeNode {
    int level;
    int dataIndex; // Index of the first point in this node's data array
    int numPoints; // Number of points stored in this node's data array
    std::shared_ptr<OctreeNode> children[8]; // Pointers to child nodes
};

// Octree management class
class Octree {
public:
    Octree(int featureSize, int numInitialLeafNodes, int maxDataCapacity) :
        _featureSize(featureSize), _numInitialLeafNodes(numInitialLeafNodes),
        _maxDataCapacity(maxDataCapacity) { }

    void buildAndManageOctree(std::vector<float>& points) {
        // Initialize root node with initial leaf nodes
        std::shared_ptr<OctreeNode> root = constructInitialLeafNodes(points);

        // Insert remaining points into the octree
        insertPointsIntoTree(root, points, 0);

        // Prune unused child nodes from the tree
        pruneTree(root);
    }

private:
    int _featureSize;
    int _numInitialLeafNodes;
    int _maxDataCapacity;

    std::shared_ptr<OctreeNode> constructInitialLeafNodes(std::vector<float>& points) {
        // Create root node with initial leaf nodes
        std::shared_ptr<OctreeNode> root = std::make_shared<OctreeNode>();
        root->level = 0;
        root->dataIndex = 0;
        root->numPoints = _numInitialLeafNodes;
        for (int i = 0; i < _numInitialLeafNodes; ++i) {
            root->children[i] = std::make_shared<OctreeNode>();
            root->children[i]->level = 1;
            root->children[i]->dataIndex = i * _featureSize;
            root->children[i]->numPoints = _maxDataCapacity / _numInitialLeafNodes;
        }

        return root;
    }

    void insertPointsIntoTree(std::shared_ptr<OctreeNode> node, std::vector<float>& points, int level) {
        // If the node is a leaf node, add the points to its data array
        if (level == 0) {
            for (int i = 0; i < node->numPoints; ++i) {
                node->data.push_back(points[node->dataIndex + i]);
            }
            return;
        }

        // If the node is not a leaf node, insert points into its child nodes recursively
        for (int i = 0; i < _numInitialLeafNodes; ++i) {
            int childLevel = level - 1;
            std::shared_ptr<OctreeNode> child = node->children[i];
            int childDataIndex = child->dataIndex;
            int childNumPoints = child->numPoints;

            for (int j = 0; j < childNumPoints; ++j) {
                child->data.push_back(points[childDataIndex + j]);
            }
        }
    }

    void pruneTree(std::shared_ptr<OctreeNode> node) {
        // If the node has no children, return
        if (node->children[0] == nullptr) {
            return;
        }

        // If the node has child nodes, remove unused child nodes and recurse
        for (int i = 0; i < _numInitialLeafNodes; ++i) {
            std::shared_ptr<OctreeNode> child = node->children[i];
            if (child != nullptr && child->data.size() == 0) {
                node->children[i] = nullptr;
            } else {
                pruneTree(child);
            }
        }
    }
};

int main() {
    // Initialize octree with feature size, number of initial leaf nodes, and maximum data capacity
    int featureSize = 3;
    int numInitialLeafNodes = 10;
    int maxDataCapacity = 5000;
    Octree octree(featureSize, numInitialLeafNodes, maxDataCapacity);

    // Load point cloud data from file
    std::vector<float> points;
    loadPointsFromFile("points.ply", points);

    // Build and manage octree for spatial partitioning
    octree.buildAndManageOctree(points);

    return 0;
}
