use std::path::Path;
use std::fs::File;
use std::io::Write;
use std::process::Command;

fn create_config_dir(repo: &str, dir: &str) -> Result<(), String> {
    let repo_url = format!("{}/{}", repo, dir);
    if !Path::new(&repo_url).exists() {
        Command::new("git")
            .arg("init")
            .arg(repo_url)
            .output()?;
    }
    let mut file = File::create(format!("{}/{}", repo, dir))?;
    file.write_all(b"# Configuration directory for application settings\n")?;
    Ok(())
}
