// Octree class in C++
class Octree {
  private:
    struct Node {
      int objectCount;
      vector<Node*> children;
      vector<Object*> objects;
    };

    Node* root;
    int capacity;
    bool isThreadSafe;

  public:
    Octree(int capacity, bool isThreadSafe) {
      this->capacity = capacity;
      this->isThreadSafe = isThreadSafe;
    }

    void insert(Object* object) {
      if (objectCount >= capacity) {
        splitNode();
      }
      addObject(object);
    }

    void remove(Object* object) {
      for (int i = 0; i < root->objects.size(); i++) {
        if (root->objects[i] == object) {
          root->objects.erase(root->objects.begin() + i);
          return;
        }
      }
    }

    void splitNode() {
      Node* newNode = new Node();
      for (int i = 0; i < root->objects.size(); i++) {
        Object* object = root->objects[i];
        int index = getIndex(object);
        if (index != -1) {
          addObject(root, object, newNode, index);
        } else {
          removeObject(root, object);
          addObject(newNode, object);
        }
      }
      delete root;
      root = newNode;
    }

    void addObject(Object* object) {
      if (isThreadSafe) {
        std::lock_guard<std::mutex> lock(mutex);
        addObject(root, object);
      } else {
        addObject(root, object);
      }
    }

    void removeObject(Object* object) {
      if (isThreadSafe) {
        std::lock_guard<std::mutex> lock(mutex);
        removeObject(root, object);
      } else {
        removeObject(root, object);
      }
    }

    void addObject(Node* node, Object* object, Node* newNode = nullptr, int index = -1) {
      if (newNode != nullptr) {
        newNode->objects.push_back(object);
        return;
      }
      if (node->children.size() == 0) {
        node->objects.push_back(object);
        node->objectCount++;
        return;
      }
      int i = getIndex(object, index + 1);
      addObject(node->children[i], object, newNode, index + 1);
    }

    void removeObject(Node* node, Object* object) {
      if (node->objects.size() == 0) {
        return;
      }
      int i = getIndex(object);
      if (i != -1) {
        node->objects.erase(node->objects.begin() + i);
        node->objectCount--;
        return;
      }
      for (int i = 0; i < node->children.size(); i++) {
        removeObject(node->children[i], object);
      }
    }

    int getIndex(Object* object, int index = -1) {
      if (index != -1) {
        return index;
      }
      for (int i = 0; i < root->objects.size(); i++) {
        Object* obj = root->objects[i];
        if (obj == object) {
          return i;
        }
      }
      return -1;
    }
};

