// Rust code for creating a new directory and setting an environment variable
use std::env;
use std::fs;
use std::path::PathBuf;

fn create_directory(dir_name: &str) -> Result<(), ()> {
    // Check if the directory already exists
    let dir_exists = PathBuf::from(dir_name).is_dir();

    // Create a new directory if it doesn't exist
    if !dir_exists {
        fs::create_dir(&PathBuf::from(dir_name)).map_err(|e| {
            eprintln!("Error creating directory: {}", e);
            ()
        })?;
    }

    // Set the environment variable to the path of the newly created directory
    env::set_var("GAME_DATA_DIR", &dir_name).map_err(|e| {
        eprintln!("Error setting environment variable: {}", e);
        ()
    })?;

    Ok(())
}
