#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <assert.h>

#include "cryptolib.h"

struct cryptolib_context {
    struct list_head supported_algorithms;
    struct list_head supported_hashes;
};

struct cryptolib_algorithm {
    char *name;
    cryptolib_primitive_add primitive_add;
    cryptolib_primitive_remove primitive_remove;
    struct list_head list;
};

struct cryptolib_hash {
    char *name;
    cryptolib_hash_add hash_add;
    cryptolib_hash_remove hash_remove;
    struct list_head list;
};

struct cryptolib_context *cryptolib_init(const char *config_file) {
    struct cryptolib_context *ctx = malloc(sizeof(struct cryptolib_context));
    if (!ctx) {
        return NULL;
    }
    ctx->supported_algorithms = list_create();
    ctx->supported_hashes = list_create();

    // Load configuration from file
    FILE *config = fopen(config_file, "r");
    if (!config) {
        free(ctx);
        return NULL;
    }

    char line[256];
    while (fgets(line, sizeof(line), config)) {
        // Skip comments and empty lines
        if (line[0] == '#' || strlen(line) == 0) {
            continue;
        }

        // Parse the line and add supported algorithms/hashes to the list
        char *name = strtok(line, " ");
        char *primitive = strtok(NULL, " ");
        if (strcmp(primitive, "add") == 0) {
            struct cryptolib_algorithm *alg = malloc(sizeof(struct cryptolib_algorithm));
            alg->name = name;
            alg->primitive_add = get_primitive_add(name);
            alg->primitive_remove = get_primitive_remove(name);
            list_add(&ctx->supported_algorithms, &alg->list);
        } else if (strcmp(primitive, "remove") == 0) {
            struct cryptolib_algorithm *alg = malloc(sizeof(struct cryptolib_algorithm));
            alg->name = name;
            alg->primitive_add = get_primitive_add(name);
            alg->primitive_remove = get_primitive_remove(name);
            list_add(&ctx->supported_algorithms, &alg->list);
        } else if (strcmp(primitive, "hash") == 0) {
            struct cryptolib_hash *hash = malloc(sizeof(struct cryptolib_hash));
            hash->name = name;
            hash->hash_add = get_hash_add(name);
            hash->hash_remove = get_hash_remove(name);
            list_add(&ctx->supported_hashes, &hash->list);
        }
    }

    fclose(config);

    return ctx;
}

void cryptolib_deinit(struct cryptolib_context *ctx) {
    // Free all the supported algorithms and hashes
    struct list_head *alg, *tmp;
    list_for_each_safe(alg, tmp, &ctx->supported_algorithms) {
        free(list_entry(alg, struct cryptolib_algorithm, list));
    }

    list_free(&ctx->supported_algorithms);

    // Free all the supported hashes
    struct list_head *hash, *tmp;
    list_for_each_safe(hash, tmp, &ctx->supported_hashes) {
        free(list_entry(hash, struct cryptolib_hash, list));
    }

    list_free(&ctx->supported_hashes);
}

int cryptolib_add(struct cryptolib_context *ctx, const char *name) {
    // Check if the algorithm or hash is already supported
    struct cryptolib_algorithm *alg;
    alg = list_find(&ctx->supported_algorithms, name);
    if (alg) {
        return -1;
    }

    // Load the configuration file for the new algorithm/hash
    FILE *config = fopen(name, "r");
    if (!config) {
        return -2;
    }

    char line[256];
    while (fgets(line, sizeof(line), config)) {
        // Skip comments and empty lines
        if (line[0] == '#' || strlen(line) == 0) {
            continue;
        }

        // Parse the line and add supported algorithms/hashes to the list
        char *primitive = strtok(line, " ");
        if (strcmp(primitive, "add") == 0) {
            alg = malloc(sizeof(struct cryptolib_algorithm));
            alg->name = name;
            alg->primitive_add = get_primitive_add(name);
            alg->primitive_remove = get_primitive_remove(name);
            list_add(&ctx->supported_algorithms, &alg->list);
        } else if (strcmp(primitive, "remove") == 0) {
            alg = malloc(sizeof(struct cryptolib_algorithm));
            alg->name = name;
            alg->primitive_add = get_primitive_add(name);
            alg->primitive_remove = get_primitive_remove(name);
            list_add(&ctx->supported_algorithms, &alg->list);
        } else if (strcmp(primitive, "hash") == 0) {
            struct cryptolib_hash *hash = malloc(sizeof(struct cryptolib_hash));
            hash->name = name;
            hash->hash_add = get_hash_add(name);
            hash->hash_remove = get_hash_remove(name);
            list_add(&ctx->supported_hashes, &hash->list);
        }
    }

    fclose(config);

    return 0;
}

int cryptolib_remove(struct cryptolib_context *ctx, const char *name) {
    // Check if the algorithm or hash is already supported
    struct cryptolib_algorithm *alg;
    alg = list_find(&ctx->supported_algorithms, name);
    if (!alg) {
        return -1;
    }

    // Remove the algorithm/hash from the list
    list_remove(&ctx->supported_algorithms, &alg->list);

    free(alg);

    return 0;
}

int cryptolib_run(struct cryptolib_context *ctx, const char *name, ...) {
    // Check if the algorithm or hash is supported
    struct cryptolib_algorithm *alg;
    alg = list_find(&ctx->supported_algorithms, name);
    if (!alg) {
        return -1;
    }

    // Call the primitive add function for the algorithm
    if (alg->primitive_add) {
        va_list args;
        va_start(args, name);
        alg->primitive_add(ctx, name, &args);
        va_end(args);
    }

    // Call the primitive remove function for the algorithm
    if (alg->primitive_remove) {
        va_list args;
        va_start(args, name);
        alg->primitive_remove(ctx, name, &args);
        va_end(args);
    }

    return 0;
}

int cryptolib_hash(struct cryptolib_context *ctx, const char *name, ...) {
    // Check if the hash is supported
    struct cryptolib_hash *hash;
    hash = list_find(&ctx->supported_hashes, name);
    if (!hash) {
        return -1;
    }

    // Call the hash add function
    va_list args;
    va_start(args, name);
    hash->hash_add(ctx, name, &args);
    va_end(args);

    return 0;
}

void *get_primitive_add(const char *name) {
    // Check if the algorithm or hash is supported
    struct cryptolib_algorithm *alg;
    alg = list_find(&ctx->supported_algorithms, name);
    if (!alg) {
        return NULL;
    }

    // Return the primitive add function for the algorithm
    return alg->primitive_add;
}

void *get_primitive_remove(const char *name) {
    // Check if the algorithm or hash is supported
    struct cryptolib_algorithm *alg;
    alg = list_find(&ctx->supported_algorithms, name);
    if (!alg) {
        return NULL;
    }

    // Return the primitive remove function for the algorithm
    return alg->primitive_remove;
}

void *get_hash_add(const char *name) {
    // Check if the hash is supported
    struct cryptolib_hash *hash;
    hash = list_find(&ctx->supported_hashes, name);
    if (!hash) {
        return NULL;
    }

    // Return the hash add function for the hash
    return hash->hash_add;
}

void *get_hash_remove(const char *name) {
    // Check if the hash is supported
    struct cryptolib_hash *hash;
    hash = list_find(&ctx->supported_hashes, name);
    if (!hash) {
        return NULL;
    }

    // Return the hash remove function for the hash
    return hash->hash_remove;
}

