package com.example.websocket;

import org.springframework.stereotype.Component;
import org.springframework.web.socket.config.annotation.EnableWebSocket;
import org.springframework.web.socket.config.annotation.WebSocketConfigurer;
import org.springframework.web.socket.config.annotation.WebSocketHandlerRegistry;

@Component
@EnableWebSocket
public class WebSocketConfig implements WebSocketConfigurer {
    @Override
    public void registerWebSocketHandlers(WebSocketHandlerRegistry registry) {
        registry.addHandler(new WebSocketHandler(), "/websocket");
    }
}

class WebSocketHandler extends TextWebSocketHandler {
    private final Semaphore semaphore = new Semaphore(50); // limit the number of concurrent operations

    @Override
    public void handleTextMessage(WebSocketSession session, String message) throws Exception {
        if (!semaphore.tryAcquire()) { // wait for a permit to become available
            return;
        }

        try {
            // process the message
            System.out.println("Received message: " + message);

            // handle the message and update the shared database state
            session.getBasicRemote().sendText(message);
        } catch (Exception e) {
            // handle any exceptions gracefully
            System.out.println("Error handling message: " + e.getMessage());
        } finally {
            semaphore.release(); // release the permit
        }
    }
}
