package com.example.xml;

import javax.xml.namespace.QName;
import javax.xml.xpath.*;

public class AsyncXmlReduce {
    private static final String NAMESPACE = "http://www.w3.org/2001/XMLSchema-instance";
    private static final QName XPATH_EXPR = new QName("", "//data");

    public void reduce(String xml, Consumer<String> callback) {
        try {
            XPathFactory xpathFactory = XPathFactory.newInstance();
            XPath xpath = xpathFactory.newXPath();

            // parse the XML document and extract data using XPath expressions
            Object result = xpath.evaluate(XPATH_EXPR, new InputSource(xml), XPathConstants.STRING);

            if (result != null) {
                String data = (String) result;
                callback.accept(data); // invoke the callback with the extracted data
            } else {
                System.out.println("No data found");
            }
        } catch (XPathExpressionException e) {
            System.out.println("Error evaluating XPath expression: " + e.getMessage());
        }
    }
}
