package com.example.api;

import javax.xml.ws.BindingProvider;
import javax.xml.ws.soap.SOAPBinding;

public class ApiClient {
    private final String endpointUrl;
    private final String authToken;

    public ApiClient(String endpointUrl, String authToken) {
        this.endpointUrl = endpointUrl;
        this.authToken = authToken;
    }

    public <T> T callApi(Class<T> responseType) {
        try {
            // create a SOAP binding and set the authentication token
            BindingProvider binding = (BindingProvider) Service.create(new URL(endpointUrl), responseType);
            binding.getRequestContext().put("Authorization", "Bearer " + authToken);

            // make the API call and handle the response
            T response = binding.invoke(responseType);
            System.out.println("API call successful, received response: " + response);

            return response;
        } catch (Exception e) {
            System.out.println("Error calling API: " + e.getMessage());
            throw new RuntimeException(e);
        }
    }
}
