<?php
// Load dependencies
use Slim\App;
use Slim\Http\Request;
use Slim\Http\Response;

// Define routes
$app = new App();

$app->post('/users', function (Request $request, Response $response) {
    // Get request body parameters
    $name = $request->getParsedBody()['name'];
    $email = $request->getParsedBody()['email'];
    $password = $request->getParsedBody()['password'];
    $role = $request->getParsedBody()['role'];

    // Validate input
    if (empty($name) || empty($email) || empty($password)) {
        return $response->withJson(['status' => 'error', 'message' => 'Invalid request body'], 400);
    }

    // Check if email is unique
    $isUnique = checkEmailUnique($email);
    if (!$isUnique) {
        return $response->withJson(['status' => 'error', 'message' => 'Email already exists'], 409);
    }

    // Hash password
    $hashedPassword = hashPassword($password);

    // Insert user into database
    $query = "INSERT INTO users (name, email, password, role) VALUES (:name, :email, :password, :role)";
    $stmt = $this->db->prepare($query);
    $stmt->bindParam(':name', $name, PDO::PARAM_STR);
    $stmt->bindParam(':email', $email, PDO::PARAM_STR);
    $stmt->bindParam(':password', $hashedPassword, PDO::PARAM_STR);
    $stmt->bindParam(':role', $role, PDO::PARAM_INT);
    $stmt->execute();

    // Return success response
    return $response->withJson(['status' => 'success', 'message' => 'User created successfully'], 201);
});

$app->get('/users/{id}', function (Request $request, Response $response) {
    // Get user ID from route params
    $id = $request->getAttribute('id');

    // Validate input
    if (empty($id)) {
        return $response->withJson(['status' => 'error', 'message' => 'Invalid request parameter'], 400);
    }

    // Check if user exists
    $user = getUserById($id);
    if (!$user) {
        return $response->withJson(['status' => 'error', 'message' => 'User not found'], 404);
    }

    // Return user data
    return $response->withJson(['status' => 'success', 'data' => $user], 200);
});

$app->put('/users/{id}', function (Request $request, Response $response) {
    // Get user ID from route params
    $id = $request->getAttribute('id');

    // Validate input
    if (empty($id)) {
        return $response->withJson(['status' => 'error', 'message' => 'Invalid request parameter'], 400);
    }

    // Check if user exists
    $user = getUserById($id);
    if (!$user) {
        return $response->withJson(['status' => 'error', 'message' => 'User not found'], 404);
    }

    // Get request body parameters
    $name = $request->getParsedBody()['name'];
    $email = $request->getParsedBody()['email'];
    $password = $request->getParsedBody()['password'];
    $role = $request->getParsedBody()['role'];

    // Validate input
    if (empty($name) || empty($email) || empty($password)) {
        return $response->withJson(['status' => 'error', 'message' => 'Invalid request body'], 400);
    }

    // Hash password
    $hashedPassword = hashPassword($password);

    // Update user in database
    $query = "UPDATE users SET name=:name, email=:email, password=:password, role=:role WHERE id=:id";
    $stmt = $this->db->prepare($query);
    $stmt->bindParam(':name', $name, PDO::PARAM_STR);
    $stmt->bindParam(':email', $email, PDO::PARAM_STR);
    $stmt->bindParam(':password', $hashedPassword, PDO::PARAM_STR);
    $stmt->bindParam(':role', $role, PDO::PARAM_INT);
    $stmt->execute();

    // Return success response
    return $response->withJson(['status' => 'success', 'message' => 'User updated successfully'], 200);
});

$app->delete('/users/{id}', function (Request $request, Response $response) {
    // Get user ID from route params
    $id = $request->getAttribute('id');

    // Validate input
    if (empty($id)) {
        return $response->withJson(['status' => 'error', 'message' => 'Invalid request parameter'], 400);
    }

    // Check if user exists
    $user = getUserById($id);
    if (!$user) {
        return $response->withJson(['status' => 'error', 'message' => 'User not found'], 404);
    }

    // Delete user from database
