    $stmt = $this->db->prepare($query);
    $stmt->bindParam(':id', $id, PDO::PARAM_INT);
    $stmt->execute();

    // Return success response
    return $response->withJson(['status' => 'success', 'message' => 'User deleted successfully'], 200);
});
