import org.json.JSONException;

public class DataPipeline {
    private static final ObjectMapper mapper = new ObjectMapper();
    private static final Map<String, JsonNode> cache = new HashMap<>();

    public static void main(String[] args) throws JSONException {
        // Parse the incoming JSON document
        String json = "{\"name\":\"John\",\"age\":30,\"address\":{\"city\":\"New York\",\"state\":\"NY\"}}";
        JsonNode root = mapper.readTree(json);

        // Extract the nested data structure using Jackson
        ObjectNode address = (ObjectNode) root.get("address");
        String city = address.get("city").asText();
        String state = address.get("state").asText();

        // Cache the parsed result for future reuse
        cache.put(root.toString(), root);

        // Log the performance and error information
        System.out.println("Parsing time: " + (System.currentTimeMillis() - start) + "ms");
        if (error != null) {
            System.out.println("Error: " + error);
        } else {
            System.out.println("City: " + city);
            System.out.println("State: " + state);
        }
    }
}
