    // initialize the variables for the image cache and word list metadata
    image_cache_t *image_cache = NULL;
    word_list_metadata_t *word_list_metadata = NULL;

    // fetch the word list from the external data source
    if (fetch_word_list(token, language, &word_list_metadata, 1) != 0) {
