    // initialize the variables for the trimmed and capitalized string
    trimmed_string_t *trimmed_string = malloc(sizeof(trimmed_string_t));
    trimmed_string->string = input_string;
    trimmed_string->length = strlen(input_string);

    // loop through the word list and trim the specified words from the beginning and end of the string
    for (int i = 0; i < word_list_metadata.length; i++) {
        char *word = word_list_metadata[i].word;
        int length = word_list_metadata[i].length;

        if (trimmed_string->length <= length) {
            break;
        }

        // trim the specified words from the beginning and end of the string
        char *new_string = malloc(sizeof(char) * (trimmed_string->length - length));
        strcpy(new_string, trimmed_string->string + length);
        free(trimmed_string->string);
        trimmed_string->string = new_string;
        trimmed_string->length -= length;
    }

    // loop through the word list and capitalize the first letter of each remaining word
    for (int i = 0; i < word_list_metadata.length; i++) {
        char *word = word_list_metadata[i].word;
        int length = word_list_metadata[i].length;

        // capitalize the first letter of each remaining word
