        strcpy(new_string, trimmed_string->string);
        new_string[0] = toupper(new_string[0]);
        free(trimmed_string->string);
        trimmed_string->string = new_string;
        trimmed_string->length++;
    }

    // return the trimmed and capitalized string
    return trimmed_string;
