    if (image_metadata == NULL) {
        return -4;
    }

    // add the image to the cache
    int ret = image_cache_add(image_metadata, data, data_len);
    if (ret != 0) {
        free(image_metadata);
        return ret;
    }

    // return success
    return 0;
}

