    // check if the token and language are valid
    if (token == NULL || strlen(token) <= 0 || language == NULL || strlen(language) <= 0) {
        return -1;
    }

    // allocate memory for the word list metadata
    word_list_metadata_t *word_list_metadata = malloc(sizeof(word_list_metadata_t));

    // check if the word list metadata is valid
    if (word_list_metadata == NULL) {
        return -2;
    }

