    if (list == NULL) {
        perror("createWordList");
        exit(EXIT_FAILURE);
    }
    list->numWords = 0;
    return list;
}

// Function to add a word to the word list
void addWordToWordList(WordList* list, const char* word) {
    if (list->numWords == MAX_WORDS) {
        printf("Error: too many words in list\n");
        return;
    }
    list->words[list->numWords++] = strdup(word);
}

// Function to remove a word from the word list
void removeWordFromWordList(WordList* list, const char* word) {
    for (int i = 0; i < list->numWords; i++) {
        if (strcmp(list->words[i], word) == 0) {
            free(list->words[i]);
            for (int j = i; j < list->numWords - 1; j++) {
                list->words[j] = list->words[j + 1];
            }
            list->numWords--;
            break;
        }
    }
}

