char* dynamicTrimAndCapitalize(const char* inputString, const WordList* wordList) {
    // Allocate memory for the trimmed and capitalized string
    char* outputString = malloc(sizeof(char) * (strlen(inputString) + 1));
    if (outputString == NULL) {
        perror("dynamicTrimAndCapitalize");
        exit(EXIT_FAILURE);
    }

    // Initialize variables for the trimmed and capitalized string length
    int outputLen = 0;

    // Iterate through each word in the input string
    const char* currentWord = strtok(inputString, " ");
    while (currentWord != NULL) {
        // If the word is in the word list, remove it from the beginning and end of the string
        if (wordList->numWords > 0 && strcmp(currentWord, wordList->words[0]) == 0) {
            removeWordFromWordList(wordList, currentWord);
            currentWord = strtok(NULL, " ");
        } else if (wordList->numWords > 0 && strcmp(currentWord, wordList->words[wordList->numWords - 1]) == 0) {
            removeWordFromWordList(wordList, currentWord);
            currentWord = NULL;
        }

        // If the word is not in the word list, append it to the trimmed string
        if (currentWord != NULL) {
            strcpy(outputString + outputLen, currentWord);
            outputLen += strlen(currentWord);
        }

        // Append a space character to the end of the trimmed string
        strcpy(outputString + outputLen++, " ");

        // Get the next word in the input string
        currentWord = strtok(NULL, " ");
    }

    // Remove any trailing whitespace characters from the trimmed string
    while (isspace(*(outputString + outputLen - 1))) {
        *(outputString + --outputLen) = '\0';
    }

    // Capitalize the first letter of each word in the trimmed string
    for (int i = 0; i < outputLen; i++) {
        if (*(outputString + i) == ' ') {
            *(outputString + i + 1) = toupper(*(outputString + i + 1));
        } else {
            *(outputString + i) = toupper(*(outputString + i));
        }
    }

    return outputString;
}
