async function asyncArrayReduce(array, initialValue, customAccumulator, config) {
  const { maxParallelOperations, throttlingInterval, cachePolicy, authToken, progressCallback } = config;

  // Initialize variables for the reduced value and the number of completed operations
  let reducedValue = initialValue;
  let numCompletedOperations = 0;

  // Create a semaphore to control the concurrency level
  const semaphore = new Semaphore(maxParallelOperations);

  // Iterate through each element in the array
  for (let i = 0; i < array.length; i++) {
    // Acquire a permit from the semaphore to perform an operation
    await semaphore.acquire();

    try {
      // Perform the custom accumulator function on each element in the array
      reducedValue = await customAccumulator(reducedValue, array[i]);
    } catch (error) {
      // Handle any errors during the reduction process
      console.log(`Error: ${error}`);
    } finally {
      // Release the permit from the semaphore after the operation is complete
      semaphore.release();
    }

    // Increment the number of completed operations
    numCompletedOperations++;

    // Report the progress of the reduction process to the callback function
    if (progressCallback) {
      progressCallback(numCompletedOperations, reducedValue);
    }
  }

  return reducedValue;
}
