import org.apache.commons.lang3.tuple.ImmutablePair;
import org.apache.commons.lang3.tuple.Pair;

public static void validate(String apiUrl, JSONObject jsonData) {
    Pair<Integer, String> result = Retry.retry(() -> {
        try {
            RESTAPIValidator.validate(apiUrl, jsonData);
            return ImmutablePair.of(200, "OK");
        } catch (IOException e) {
            // log error and handle accordingly
            System.out.println("Failed to validate JSON data: " + e.getMessage());
            return ImmutablePair.of(503, "Service Unavailable");
        }
    }, 3); // retry up to 3 times

    if (result.getLeft() != 200) {
        // handle failed request
        System.out.println("Failed to validate JSON data: " + result.getRight());
    }
}
