function handleClinicOperations($operation, $clinicId, $data) {
    // Check rate limit for this IP address
    if (!checkRateLimit()) {
        return "Error: Rate limit exceeded";
    }

    switch ($operation) {
        case 'create':
            // Validate clinic name and location details
            $clinicName = trim($data['name']);
            if (strlen($clinicName) > 50 || in_array($clinicName, getProhibitedTerms())) {
                return "Error: Invalid clinic name";
            }

            // Check medical supply chain management system for availability of supplies
            $supplyCheck = checkSupplyAvailability();
            if (!$supplyCheck) {
                return "Error: Supply chain management system unavailable";
            }

            // Create clinic record in database
            $clinicId = createClinic($clinicName, $data['location'], $data['capacity']);

            // Notify weather API for closure risks and update patient scheduling system
            notifyWeatherAPI();
            updatePatientSchedulingSystem();

            return "Success: Clinic created";
        case 'update':
            // Validate clinic status and other metadata
            $clinicStatus = trim($data['status']);
            if (!in_array($clinicStatus, array('open', 'closed', 'emergency'))) {
                return "Error: Invalid clinic status";
            }

            // Check medical supply chain management system for adjusting supply levels
            $supplyAdjustment = checkSupplyLevels();
            if (!$supplyAdjustment) {
                return "Error: Supply chain management system unavailable";
            }

            // Update clinic record in database and notify relevant parties
            updateClinicStatus($clinicId, $clinicStatus);

            // Notify weather API for closure risks and update patient scheduling system
            notifyWeatherAPI();
            updatePatientSchedulingSystem();

            return "Success: Clinic status updated";
        case 'delete':
            // Check if clinic is in use before deleting it
            $inUse = checkClinicInUse($clinicId);
            if ($inUse) {
                return "Error: Clinic in use";
            }

            // Notify patients with upcoming appointments and suggest nearby alternatives
            notifyPatients();

            // Retry mechanism for failed database transactions or external API calls
            $retries = 0;
            while ($retries < 5) {
                try {
                    deleteClinic($clinicId);
                    break;
                } catch (Exception $e) {
                    logError($e->getMessage());
                    sleep(pow(2, $retries)); // exponential backoff
                    $retries++;
                }
            }

            if ($retries == 5) {
                return "Error: Failed to delete clinic";
            }

            // Notify medical supply chain management system for supply adjustments
            notifySupplyChainManagementSystem();

            return "Success: Clinic deleted";
        default:
            return "Error: Invalid operation";
    }
}
