    public static async Task<T> DeserializeAsync<T>(string filePath, int maxFileSize = DEFAULT_MAX_FILE_SIZE, string checksumAlgorithm = DEFAULT_CHECKSUM_ALGORITHM) where T : class
    {
        try
        {
            // Check if the file exists and is within the maximum size limit
            if (!File.Exists(filePath))
                throw new FileNotFoundException("The specified file does not exist.", filePath);
            if (new System.IO.FileInfo(filePath).Length > maxFileSize)
                throw new IOException($"The file is too large ({new System.IO.FileInfo(filePath).Length} bytes, maximum allowed is {maxFileSize} bytes).");

            // Load the file and calculate its checksum
            var fileStream = File.OpenRead(filePath);
            using (var sha256Hash = SHA256.Create())
            {
                var hashBytes = await sha256Hash.ComputeHashAsync(fileStream).ConfigureAwait(false);
                fileStream.Position = 0;

                // Validate the checksum against the expected value
                if (!ValidateChecksum(hashBytes, checksumAlgorithm))
                    throw new Exception("The checksum of the file does not match the expected value.");
            }

            // Deserialize the data from the file
            var xmlSerializer = new XmlSerializer(typeof(T));
            using (var reader = new StreamReader(filePath, Encoding.UTF8))
            {
                return (T)xmlSerializer.Deserialize(reader);
            }
        }
        catch (Exception ex)
        {
            throw new Exception("Failed to deserialize the data from the file.", ex);
        }
    }

    private static bool ValidateChecksum(byte[] hashBytes, string checksumAlgorithm)
    {
