    if (threads == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for threads\n");
        close_file(fd);
        return -1;
    }

    // Loop over the input file and process each line in parallel using a dynamic number of threads
    off_t offset = 0;
    while (offset != -1) {
        thread_info_t *thread_info = (thread_info_t *) malloc(sizeof(thread_info_t));
        if (thread_info == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for thread information\n");
            free(threads);
            close_file(fd);
            return -1;
        }
        thread_info->file_descriptor = fd;
        thread_info->offset = offset;

        // Create a new thread for processing the line
        pthread_create(&threads[num_threads], NULL, process_line, (void *) thread_info);
        num_threads++;

        // Check if all lines have been processed or if we need to continue with the next one
        offset = lseek(fd, 0, SEEK_CUR);
    }

    // Wait for all threads to complete before generating the report
    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Generate the report based on the processed lines
    generate_report();

    // Close the input file and free memory
    close_file(fd);
    free(threads);

    return 0;
}

