class SemaphoreManager:
    def __init__(self, config_file):
        self.config = None
        self.semaphores = {}
        self.executor = None
        self.load_balancer = None
        self.log = logging.getLogger(__name__)
        self.read_config(config_file)
        self.setup_logging()
        self.create_semaphores()

    def read_config(self, config_file):
        with open(config_file) as f:
            self.config = json.load(f)

    def setup_logging(self):
        logging.basicConfig(level=logging.INFO)

    def create_semaphores(self):
        for semaphore in self.config["semaphores"]:
            name = semaphore["name"]
            initial_value = semaphore["initialValue"]
            maximum_value = semaphore["maximumValue"]
            priority = semaphore["priority"]
            self.semaphores[name] = Semaphore(name, initial_value, maximum_value, priority)

    def create_semaphore(self, name):
        if name in self.semaphores:
            return
        else:
            semaphore = Semaphore(name, 0, 1, 0)
            self.semaphores[name] = semaphore

    def delete_semaphore(self, name):
        if name in self.semaphores:
            del self.semaphores[name]

    def increment_semaphore(self, name, amount=1):
        if name in self.semaphores:
            self.semaphores[name].value += amount

    def decrement_semaphore(self, name, amount=1):
        if name in self.semaphores:
            self.semaphores[name].value -= amount

    def wait_for_semaphore(self, name, timeout=None):
        semaphore = self.semaphores[name]
        if semaphore.value > 0:
            semaphore.value -= 1
            return True
        else:
            if not timeout or time.time() - start_time < timeout:
                return False
            raise TimeoutError("Semaphore '{}' has been locked for too long".format(name))

    def acquire_semaphore(self, name):
        semaphore = self.semaphores[name]
        if semaphore.value > 0:
            semaphore.value -= 1
            return True
        else:
            raise ValueError("Semaphore '{}' is not available".format(name))

    def release_semaphore(self, name):
        semaphore = self.semaphores[name]
        if semaphore.value < 1:
            raise ValueError("Semaphore '{}' has already been released".format(name))
        else:
            semaphore.value += 1

    def get_semaphore_count(self, name):
        return self.semaphores[name].value

    def set_semaphore_priority(self, name, priority):
        self.semaphores[name].priority = priority

    def get_semaphore_priority(self, name):
        return self.semaphores[name].priority

class Semaphore:
    def __init__(self, name, initial_value, maximum_value, priority=0):
        self.name = name
        self.value = initial_value
        self.maximum_value = maximum_value
        self.priority = priority

    def acquire(self, timeout=None):
        if self.value > 0:
            self.value -= 1
            return True
        else:
            if not timeout or time.time() - start_time < timeout:
                return False
            raise TimeoutError("Semaphore '{}' has been locked for too long".format(self.name))

    def release(self):
        if self.value < 1:
            raise ValueError("Semaphore '{}' has already been released".format(self.name))
        else:
            self.value += 1

    def get_semaphore_count(self):
        return self.value

    def set_semaphore_priority(self, priority):
        self.priority = priority

    def get_semaphore_priority(self):
        return self.priority

