// Predefined list of supported file types
const char* SUPPORTED_FILE_TYPES[] = {"txt", "jpg", "png", "pdf"};

// Function to parse the original filename and extract the base name and extension
char* ParseFilename(const char* filename) {
  // Split the filename into base name and extension
  const char* dot = strrchr(filename, '.');
  if (!dot || dot == filename) {
    return NULL;
  }
  size_t basename_len = dot - filename;
  size_t extension_len = strlen(dot + 1);
  char* base_name = malloc(basename_len + 1);
  char* extension = malloc(extension_len + 1);
  if (!base_name || !extension) {
    free(base_name);
    free(extension);
    return NULL;
  }
  memcpy(base_name, filename, basename_len);
  base_name[basename_len] = '\0';
  memcpy(extension, dot + 1, extension_len);
  extension[extension_len] = '\0';
  return base_name;
}

// Function to determine the appropriate number of digits based on the file type
int DetermineDigits(const char* filetype) {
  // Check if the file type is supported
  for (int i = 0; i < sizeof(SUPPORTED_FILE_TYPES) / sizeof(*SUPPORTED_FILE_TYPES); ++i) {
    if (strcmp(filetype, SUPPORTED_FILE_TYPES[i]) == 0) {
      return 3; // For image files
      return 5; // For document files
    }
  }
  return -1; // Unsupported file type
}

// Function to validate the file type against the predefined list of supported types
int ValidateFileType(const char* filetype) {
  for (int i = 0; i < sizeof(SUPPORTED_FILE_TYPES) / sizeof(*SUPPORTED_FILE_TYPES); ++i) {
    if (strcmp(filetype, SUPPORTED_FILE_TYPES[i]) == 0) {
      return 1; // Valid file type
    }
  }
  return 0; // Unsupported file type
}

// Function to update the file extension based on the specified file type
char* SetFileType(const char* filename, const char* new_filetype) {
  // Check if the new file type is supported
  if (!ValidateFileType(new_filetype)) {
    return NULL;
  }
  // Parse the original filename and extract the base name and extension
  const char* dot = strrchr(filename, '.');
  if (!dot || dot == filename) {
    return NULL;
  }
  size_t basename_len = dot - filename;
  size_t extension_len = strlen(dot + 1);
  char* base_name = malloc(basename_len + 1);
  char* extension = malloc(extension_len + 1);
  if (!base_name || !extension) {
    free(base_name);
    free(extension);
    return NULL;
  }
  memcpy(base_name, filename, basename_len);
  base_name[basename_len] = '\0';
  memcpy(extension, dot + 1, extension_len);
  extension[extension_len] = '\0';
  // Construct the new filename using the parsed base name, determined digits, and updated file type
  size_t new_filename_len = basename_len + strlen(new_filetype) + 1;
  char* new_filename = malloc(new_filename_len);
  if (!new_filename) {
    free(base_name);
    free(extension);
    return NULL;
  }
  sprintf(new_filename, "%s%s", base_name, new_filetype);
  // Free memory and return the new filename
  free(base_name);
  free(extension);
  return new_filename;
}

// Function to handle errors and provide appropriate feedback to the caller
void ErrorHandling(const char* filename) {
  // Log any errors or edge cases encountered during execution using an external logging system
  const char* error_message = "Invalid filename or unsupported file type";
