  base_name[basename_len] = '\0';
  memcpy(extension, dot + 1, extension_len);
  extension[extension_len] = '\0';
  // Check if there is a file type specified and validate it
  const char* new_filetype = NULL;
  if (argc == 3) {
    new_filetype = argv[2];
    if (!ValidateFileType(new_filetype)) {
      ErrorHandling(filename);
      return 4;
    }
  } else {
    new_filetype = SetFileType(filename, dot + 1);
    if (!new_filetype) {
      free(base_name);
      free(extension);
      return 5;
    }
  }
  // Create the new filename based on the specified command-line arguments
