class FileStorageManager {
    private $files;
    private $users;
    private $permissions;
    private $activityLog;

    public function __construct(array $files, array $users, array $permissions) {
        $this->files = $files;
        $this->users = $users;
        $this->permissions = $permissions;
        $this->activityLog = [];
    }

    public function uploadFile($filePath, $destinationPath) {
        // Validate file type and size before uploading
        if (!$this->validateFileType($filePath)) {
            throw new \InvalidArgumentException('File type is not supported');
        }

        // Implement multipart uploads for large files to prevent memory exhaustion
        $fileSize = filesize($filePath);
        if ($fileSize > 10 * 1024 * 1024) {
            $this->multipartUpload($filePath, $destinationPath);
        } else {
            // Simple upload for small files
            move_uploaded_file($filePath, $destinationPath);
        }
    }

    public function downloadFile($fileId) {
        // Ensure that the file is accessible only to authenticated users
        if (!$this->isAuthenticated()) {
            throw new \RuntimeException('User not authenticated');
        }

        // Implement file chunking for large downloads to improve performance and reduce server load
        $fileSize = filesize($destinationPath);
        if ($fileSize > 10 * 1024 * 1024) {
            $this->chunkedDownload($fileId);
        } else {
            // Simple download for small files
            readfile($destinationPath);
        }
    }

    public function validateFileType($fileType) {
        $supportedFileTypes = ['jpg', 'png', 'pdf', 'docx'];
        return in_array($fileType, $supportedFileTypes);
    }

    public function sanitizeFileName($fileName) {
        // Use a whitelist approach to validate filenames and remove any disallowed characters
        $sanitizedFilename = preg_replace('/[^A-Za-z0-9_\-\.]/', '', $fileName);
        return $sanitizedFilename;
    }

    public function listUserFiles($userId) {
        // Optimize the query to avoid performance bottlenecks when dealing with large numbers of files
        $files = $this->files[$userId];
        return array_map(function ($file) {
            return [
                'id' => $file['id'],
                'name' => $file['name'],
                'size' => $file['size'],
                'uploadDate' => $file['uploadDate']
            ];
        }, $files);
    }

    public function deleteFile($fileId) {
        // Ensure that the deletion process is atomic and idempotent
        if ($this->isDeleted($fileId)) {
            return;
        }
        unset($this->files[$fileId]);
        $this->permissions[$fileId] = [];
    }

    public function generateDownloadLink($fileId) {
        // Use token-based authentication to ensure that only authorized users can access the file
        if (!$this->isAuthenticated()) {
            throw new \RuntimeException('User not authenticated');
        }

        // Expire the link after a configurable time to enhance security
        $link = $this->generateToken($fileId);
        return [
            'link' => $link,
            'expiresAt' => date('Y-m-d H:i:s', strtotime('+1 hour'))
        ];
    }

    public function manageFilePermissions($fileId, $permissions) {
        // Implement role-based access control (RBAC) to allow different users with different roles to have varying levels of access to the files
        if (!$this->isAuthenticated()) {
            throw new \RuntimeException('User not authenticated');
        }

        // Ensure that permissions are updated atomically and consistently
        $this->permissions[$fileId] = $permissions;
    }

    public function logUploadAndDownloadActivity($userId, $fileId, $activityType) {
        // Log each upload and download activity for audit purposes
        if (!$this->isAuthenticated()) {
            throw new \RuntimeException('User not authenticated');
        }

        // Ensure that logs do not contain sensitive information such as file content or user credentials
        $logEntry = [
            'user_id' => $userId,
            'file_id' => $fileId,
            'activity_type' => $activityType,
            'timestamp' => date('Y-m-d H:i:s')
        ];
        array_push($this->activityLog, $logEntry);
    }

    private function isAuthenticated() {
        // Implement authentication logic here
        return true;
    }

    private function isDeleted($fileId) {
        // Check if the file has been deleted
        return !isset($this->files[$fileId]);
    }

    private function generateToken($fileId) {
        // Generate a unique token for the download link
        $token = hash('sha256', $fileId . microtime());
        return $token;
    }
}
