function styleApply(selector, context) {
  const cache = {};
  let elements = [];

  // Support for multiple selectors
  if (typeof selector === 'string') {
    selector = [selector];
  }

  // Handle each selector separately
  selector.forEach((sel) => {
    // Get the elements that match the current selector
    const matches = context.querySelectorAll(sel);

    // Add the matched elements to the cache
    cache[sel] = Array.from(matches).map((el) => el.getAttribute('data-state'));
  });

  // Update the state of each element based on the cached values
  elements.forEach((element) => {
    const currentState = cache[element.getAttribute('selector')];

    if (currentState === 'enabled') {
      element.style.display = '';
    } else {
      element.style.display = 'none';
    }
  });
}

// Example usage:
const context = document.getElementById('app');
styleApply('.my-element', context);
```
