using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Security.Cryptography;
using System.IO;

namespace SecureDataProcessor
{
    public class CSPManager
    {
        // Dictionary to store the CSP configurations
        private static readonly Dictionary<string, CspConfiguration> _cspConfigurations = new Dictionary<string, CspConfiguration>();

        // List of available CSPs
        private static readonly List<ICsp> _availableCsps = new List<ICsp>();

        // Constructor to initialize the CSPManager
        public CSPManager()
        {
            // Initialize the CSP configurations
            _cspConfigurations.Add("CspA", new CspConfiguration() { Name = "CspA", Protocol = "http", Host = "localhost", Port = 8080 });
            _cspConfigurations.Add("CspB", new CspConfiguration() { Name = "CspB", Protocol = "https", Host = "example.com", Port = 443 });

            // Initialize the available CSPs
            _availableCsps.Add(new HttpCsp());
            _availableCsps.Add(new HttpsCsp());
        }

        // Method to get a CSP instance by name
        public static ICsp GetCspInstance(string cspName)
        {
            if (!_cspConfigurations.ContainsKey(cspName))
            {
                throw new Exception($"Invalid CSP name: '{cspName}'");
            }

            var configuration = _cspConfigurations[cspName];
            return _availableCsps.FirstOrDefault(x => x.Protocol == configuration.Protocol && x.Host == configuration.Host && x.Port == configuration.Port);
        }
    }

    public class CspConfiguration
    {
        // Name of the CSP
        public string Name { get; set; }

        // Protocol used by the CSP (e.g., http, https)
        public string Protocol { get; set; }

        // Hostname of the CSP
        public string Host { get; set; }

        // Port number of the CSP
        public int Port { get; set; }
    }

    public interface ICsp
    {
        // Method to fetch a key from the CSP
        Task<string> FetchKeyAsync(string keyId);

        // Method to fetch an IV from the CSP
        Task<string> FetchIVAsync(string ivId);

        // Property to get the protocol used by the CSP (e.g., http, https)
        string Protocol { get; }

        // Property to get the hostname of the CSP
        string Host { get; }

        // Property to get the port number of the CSP
        int Port { get; }
    }

    public class HttpCsp : ICsp
    {
        // Implementation of the FetchKeyAsync method for HTTP CSPs
        public async Task<string> FetchKeyAsync(string keyId)
        {
            var httpClient = new HttpClient();
            var response = await httpClient.GetAsync($"{this.Protocol}://{this.Host}:{this.Port}/key/{keyId}");
            return await response.Content.ReadAsStringAsync();
        }

        // Implementation of the FetchIVAsync method for HTTP CSPs
        public async Task<string> FetchIVAsync(string ivId)
        {
            var httpClient = new HttpClient();
            var response = await httpClient.GetAsync($"{this.Protocol}://{this.Host}:{this.Port}/iv/{ivId}");
            return await response.Content.ReadAsStringAsync();
        }

        // Property to get the protocol used by the CSP (e.g., http, https)
        public string Protocol { get; set; }

        // Property to get the hostname of the CSP
        public string Host { get; set; }

        // Property to get the port number of the CSP
        public int Port { get; set; }
    }

    public class HttpsCsp : HttpCsp
    {
        // Implementation of the FetchKeyAsync method for HTTPS CSPs
        public async Task<string> FetchKeyAsync(string keyId)
        {
            var httpClient = new HttpClient();
            var response = await httpClient.GetAsync($"{this.Protocol}://{this.Host}:{this.Port}/key/{keyId}");
            return await response.Content.ReadAsStringAsync();
        }

        // Implementation of the FetchIVAsync method for HTTPS CSPs
        public async Task<string> FetchIVAsync(string ivId)
        {
            var httpClient = new HttpClient();
            var response = await httpClient.GetAsync($"{this.Protocol}://{this.Host}:{this.Port}/iv/{ivId}");
            return await response.Content.ReadAsStringAsync();
        }
    }

    public class SecureDataProcessor
    {
        // Dictionary to store the encryption keys and IVs
        private readonly Dictionary<string, string> _keys = new Dictionary<string, string>();
        private readonly Dictionary<string, string> _ivs = new Dictionary<string, string>();

        // Constructor to initialize the encryption keys and IVs
        public SecureDataProcessor()
        {
            _keys.Add("KeyA", "0123456789abcdef");
            _keys.Add("KeyB", "fedcba9876543210");
            _ivs.Add("IVA", "abcdefghijklmnop");
            _ivs.Add("IVB", "qrstuvwxyzABC");
        }

        // Method to encrypt data using AES-GCM
        public string Encrypt(string plaintext)
        {
            var key = _keys["KeyA"];
            var iv = _ivs["IVA"];
            var aesGcm = new AesGcm(key);
            return aesGcm.Encrypt(plaintext, iv);
        }

        // Method to decrypt data using AES-GCM
        public string Decrypt(string ciphertext)
        {
            var key = _keys["KeyA"];
            var iv = _ivs["IVA"];
            var aesGcm = new AesGcm(key);
            return aesGcm.Decrypt(ciphertext, iv);
        }
    }
}
```
