        public IActionResult Encrypt([FromBody]string plaintext)
        {
            if (string.IsNullOrEmpty(plaintext))
            {
                return BadRequest();
            }

            var ciphertext = _secureDataProcessor.Encrypt(plaintext);

            return Ok(ciphertext);
        }

        [HttpPost("decrypt")]
        public IActionResult Decrypt([FromBody]string ciphertext)
        {
            if (string.IsNullOrEmpty(ciphertext))
            {
                return BadRequest();
            }

            var plaintext = _secureDataProcessor.Decrypt(ciphertext);

            return Ok(plaintext);
        }
    }
}
