typedef struct {
    char* client_id;
    char* client_secret;
} OAuth2Credentials;

typedef struct {
    int age;
    int num_transactions;
    double weighted_sum_threshold;
} TransactionProcessingCriteria;

typedef struct {
    int transaction_id;
    char* transaction_data;
} TransactionRequest;

typedef struct {
    int total_filtered_transactions;
    double total_weighted_sum;
    double average_transaction_value;
} TransactionMetrics;

typedef struct {
    int transaction_id;
    char* certificate_data;
} CertificateRequest;

typedef struct {
    char* pem_file;
    size_t file_size;
} CombinedCertificates;

typedef struct {
    TransactionProcessingCriteria criteria;
    OAuth2Credentials credentials;
    Configuration configuration;
} ProcessingContext;

typedef struct {
    int transaction_id;
    char* transaction_data;
    double weighted_sum;
} ProcessedTransaction;

typedef struct {
    ProcessedTransactionResult result;
    CombinedCertificates certificates;
} ProcessingResult;

void handleSecureTransactionProcessing(ProcessingContext* context) {
    // Authenticate the user using OAuth 2.0 client credentials and store the access token in thread-local storage for session management.
    // Implement retry logic with exponential backoff up to 5 attempts, handling potential network failures gracefully.
    char* access_token = authenticateUser(context->credentials.client_id, context->credentials.client_secret);
    pthread_setspecific((pthread_key_t)0, access_token);

    // Asynchronously fetch and process transactions from a distributed database, incorporating efficient pagination and rate limiting to manage high traffic scenarios.
    // Implement performance optimization and resource management to ensure scalability and minimize latency.
    TransactionRequest* transaction_requests = fetchTransactions(context->configuration);
    ProcessedTransaction* processed_transactions = processTransactions(transaction_requests, context->criteria);

    // Design and implement a data structure to manage and aggregate transaction metrics efficiently, balancing between memory usage and computational speed.
    TransactionMetrics metrics = calculateMetrics(processed_transactions);

    // Handle concurrent access to shared resources and ensure thread safety to prevent data corruption during high-concurrency transactions.
    pthread_mutex_lock(&metrics_lock);
    updateMetrics(metrics, processed_transactions);
    pthread_mutex_unlock(&metrics_lock);

    // Securely combine the private keys and certificates from the filtered transactions into a single PEM file, validating each certificate's validity and compatibility before inclusion.
    CombinedCertificates combined_certificates = combineCertificates(processed_transactions);

    // Prevent certificate collision and manage the file size effectively to avoid excessive memory usage and ensure optimal storage utilization.
    pthread_mutex_lock(&pem_file_lock);
    updatePemFile(combined_certificates.pem_file, combined_certificates.file_size);
    pthread_mutex_unlock(&pem_file_lock);

    // Encode the combined PEM file in base64 and return the maximum weighted sum along with the corresponding transaction ID in a ProcessedTransactionResult structure.
    // Implement robust error handling, logging failed operations, and providing detailed error messages to aid debugging and maintenance.
    ProcessingResult result = {
        .result = {
            .transaction_id = processed_transactions[0].transaction_id,
            .weighted_sum = metrics.total_weighted_sum,
        },
        .certificates = combined_certificates,
    };
    return result;
}
