            // Check if the config directory exists and create it if not
            var configDirPath = Environment.GetFolderPath(ConfigDirectoryName);
            if (!Directory.Exists(configDirPath))
            {
                Directory.CreateDirectory(configDirPath);
            }

            // Set the environment variable to the path of the config directory
            SetEnvironmentVariable("CONFIG_DIR", configDirPath);

            // Load the XML configuration file
            var configFile = Path.Combine(ConfigDirectoryName, ConfigFilePath);
            if (!File.Exists(configFile))
            {
                Console.WriteLine($"Missing config file: {configFile}");
                return;
            }

            using (var reader = XmlReader.Create(configFile))
            {
                while (reader.Read())
                {
                    if (reader.IsStartElement())
                    {
                        switch (reader.Name)
                        {
                            case "tile-size":
                                // Set the size of tiles based on the value in the config file
                                var tileSize = reader.ReadString();
                                Console.WriteLine($"Setting tile size to: {tileSize}");
                                break;
                            case "game-world-dimensions":
                                // Set the dimensions of the game world based on the value in the config file
                                var worldWidth = reader.ReadString();
                                var worldHeight = reader.ReadString();
                                Console.WriteLine($"Setting game world dimensions to: {worldWidth}x{worldHeight}");
                                break;
                            case "camera-speed":
                                // Set the speed of the camera based on the value in the config file
                                var cameraSpeed = reader.ReadString();
                                Console.WriteLine($"Setting camera speed to: {cameraSpeed}");
                                break;
                        }
                    }
                }
            }
        }
    }
}
