```rust
use std::env;
use std::fs;
use std::path::PathBuf;

fn set_environment_variable(name: &str, value: &str) {
    if let Some(old_value) = env::var_os(name) {
        // If the environment variable is already set, use the existing value
        return old_value.into_string().unwrap();
    } else {
        // Otherwise, create a new directory and set the environment variable to its path
        let dir_path = env::temp_dir().join(name);
        fs::create_dir(&dir_path).unwrap();
        return dir_path.into_os_string().into_string().unwrap();
    }
}

fn main() {
    // Create a new directory and set the environment variable to its path
    let config_dir = set_environment_variable("CONFIG_DIR", "config_dir");

    // Load the XML configuration file
    let config_file = PathBuf::from(format!("{}/{}", &config_dir, "config.xml"));
    if !config_file.exists() {
        println!("Missing config file: {}", &config_file);
        return;
    }

    // Parse the XML configuration file and set the appropriate variables
    let mut parser = xml::reader::Parser::new();
    let root = parser.parse(config_file)?;
    for child in root.children() {
        match child.name() {
            "tile-size" => {
                // Set the size of tiles based on the value in the config file
                let tile_size = child.text().unwrap();
                println!("Setting tile size to: {}", &tile_size);
            }
            "game-world-dimensions" => {
                // Set the dimensions of the game world based on the value in the config file
                let world_width = child.attributes.get("width").unwrap();
                let world_height = child.attributes.get("height").unwrap();
                println!("Setting game world dimensions to: {}x{}", &world_width, &world_height);
            }
            "camera-speed" => {
                // Set the speed of the camera based on the value in the config file
                let camera_speed = child.text().unwrap();
                println!("Setting camera speed to: {}", &camera_speed);
            }
        }
    }
}
