class SecureWebFileManager {
  private $saltRoundCount = 12;
  private $hashedPassword;
  private $cachedStrings = [];

  public function generateSecureRandomString($length) {
    if (isset($this->cachedStrings[$length])) {
      return $this->cachedStrings[$length];
    }

    $characters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+-={}[]:";\'<>?,./';
    $randomString = '';

    for ($i = 0; $i < $length; $i++) {
      $randomString .= $characters[rand(0, strlen($characters) - 1)];
    }

    $this->cachedStrings[$length] = $randomString;

    return $randomString;
  }

  public function hashPassword($password) {
    if (strlen($password) < 8) {
      throw new \Exception('The password must be at least 8 characters long.');
    }

    $this->hashedPassword = password_hash($password, PASSWORD_BCRYPT, ['cost' => $this->saltRoundCount]);
  }

  public function checkPassword($password) {
    if (strlen($password) < 8) {
      return false;
    }

    return password_verify($password, $this->hashedPassword);
  }

  public function validateCharacterSet($characterSet) {
    $valid = true;

    if (!preg_match('/[A-Z]/', $characterSet)) {
      $valid = false;
    }

    if (!preg_match('/[a-z]/', $characterSet)) {
      $valid = false;
    }

    if (!preg_match('/\d/', $characterSet)) {
      $valid = false;
    }

    if (!preg_match('/[^A-Za-z0-9]/', $characterSet)) {
      $valid = false;
    }

    if (!$valid) {
      return 'The character set must contain at least one uppercase letter, one lowercase letter, one digit, and one special character.';
    }
  }

  public function setSaltRoundCount($rounds) {
    if ($rounds < 12 || $rounds > 31) {
      throw new \Exception('The salt round count must be between 12 and 31.');
    }

    $this->saltRoundCount = $rounds;
  }

  public function resetPassword() {
    $this->cachedStrings = [];
    $this->hashedPassword = password_hash(generateSecureRandomString(8), PASSWORD_BCRYPT, ['cost' => $this->saltRoundCount]);
  }

  public function logPasswordAttempts($ipAddress, $result) {
    // Implement database or file-based logging system to store logs securely and efficiently.
  }

  public function sanitizeInput($input) {
    return htmlspecialchars(trim($input));
  }

  public function validateFileExtension($file, $allowedExtensions) {
    $ext = pathinfo($file, PATHINFO_EXTENSION);
    if (!in_array($ext, $allowedExtensions)) {
      return 'The file extension is not allowed.';
    }
  }

  public function resizeImage($file, $maxWidth, $maxHeight) {
    $image = new \Imagick();
    $image->readImage($file);
    $image->thumbnailImage($maxWidth, $maxHeight, true);
    return $image;
  }
}
