use std::env;
use std::fs;
use std::path::PathBuf;
use std::time::SystemTime;
use log::{error, warn};

fn create_directory(name: &str) -> Result<(), Box<dyn Error>> {
    let mut dir = PathBuf::from(env!("OUT_DIR"));
    dir.push(name);
    fs::create_dir(&dir)?;
    env::set_var("DIRECTORY", dir.to_str().unwrap());
    Ok(())
}

fn cleanup_directories() {
    let mut directories = Vec::new();
    for entry in WalkDir::new(".").into_iter() {
        let entry = entry?;
        if !entry.file_type().is_dir() || entry.path().to_str().unwrap() == "DIRECTORY" {
            continue;
        }
        directories.push(entry.path());
    }
    for directory in &directories {
        let age = SystemTime::now().duration_since(directory.metadata()?.modified()?)?;
        if age > Duration::from_secs(5 * 60) {
            fs::remove_dir(&directory)?;
        }
    }
}

fn create_nested_directory(name: &str, structure: &[&str]) -> Result<(), Box<dyn Error>> {
    let mut dir = PathBuf::from(env!("OUT_DIR"));
    for part in structure {
        dir.push(part);
        fs::create_dir(&dir)?;
    }
    env::set_var("DIRECTORY", dir.to_str().unwrap());
    Ok(())
}

fn log_operation(operation: &str, directory: &Path) {
    let mut buffer = String::new();
    let datetime = Local::now().format("%Y-%m-%d %H:%M:%S");
    write!(buffer, "{} {}", datetime, operation)?;
    log::info!("{}", buffer);
}

fn get_metadata(name: &str) -> Result<(), Box<dyn Error>> {
    let mut dir = PathBuf::from(env!("OUT_DIR"));
    dir.push(name);
    if !dir.exists() {
        return Err("Directory does not exist".into());
    }
    let metadata = dir.metadata()?;
    Ok(())
}

fn set_environment_variable(name: &str, value: &str) -> Result<(), Box<dyn Error>> {
    env::set_var("DIRECTORY", value);
    log::info!("{}", name.to_string());
    Ok(())
}
```
