{
    private int minValue;
    private int maxValue;
    private int seed = 0;

    public RandomValueGenerator(int minValue, int maxValue)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public float GenerateRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public int GenerateRandomInteger()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public Vector3 GenerateRandomVector3()
    {
        float x = UnityEngine.Random.Range(minValue, maxValue);
        float y = UnityEngine.Random.Range(minValue, maxValue);
        float z = UnityEngine.Random.Range(minValue, maxValue);
        return new Vector3(x, y, z);
    }

    public Quaternion GenerateRandomQuaternion()
    {
        float angle = UnityEngine.Random.Range(minValue, maxValue);
        float axisX = UnityEngine.Random.Range(minValue, maxValue);
        float axisY = UnityEngine.Random.Range(minValue, maxValue);
        float axisZ = UnityEngine.Random.Range(minValue, maxValue);
        return new Quaternion(axisX, axisY, axisZ, angle);
    }

    public override string ToString()
    {
        return $"Random Value Generator: ({minValue}, {maxValue})";
    }
}
