#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/err.h>

/*
 * Initializes an AES-256-CBC cipher with a given password, using the OpenSSL library.
 * Supports variable IV and key lengths based on user input, and incorporates salting to enhance security.
 * Derives the encryption key from the password using PBKDF2 with a specified number of iterations.
 * Additionally, provides a mechanism to securely store and retrieve the salt used during key derivation.
 * Returns a pointer to the cipher context.
 */
EVP_CIPHER_CTX* initAESCipher(const char* password, const char* iv, int ivLen, int keyLen, int numIterations) {
    // Validate inputs
    if (password == NULL || iv == NULL || ivLen <= 0 || keyLen <= 0 || numIterations <= 0) {
        return NULL;
    }

    // Generate a random salt for key derivation
    unsigned char salt[64];
    RAND_bytes(salt, sizeof(salt));

    // Derive the encryption key from the password using PBKDF2
    EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), salt, (unsigned char*)password, strlen(password), numIterations, NULL, 0);

    // Create a cipher context for AES-256-CBC
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        return NULL;
    }

    // Set the encryption key and IV length
    int setKeyLen = EVP_CIPHER_CTX_set_key_length(ctx, keyLen);
    int setIVLen = EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_INIT_IV_LEN, ivLen, NULL);
    if (setKeyLen <= 0 || setIVLen <= 0) {
        return NULL;
    }

    // Set the encryption key and IV
    unsigned char* key = malloc(keyLen);
    memcpy(key, EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), salt, (unsigned char*)password, strlen(password), numIterations, NULL, 0), keyLen);
    int setKey = EVP_CIPHER_CTX_set_key(ctx, key, keyLen);
    unsigned char* iv = malloc(ivLen);
    memcpy(iv, iv, ivLen);
    int setIV = EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_INIT_IV, ivLen, NULL);
    if (setKey <= 0 || setIV <= 0) {
        return NULL;
    }

    // Cleanup function to safely disable and free resources associated with the cipher context when it is no longer needed
    EVP_CIPHER_CTX_free(ctx);

    return ctx;
}

/*
 * Cleans up a cipher context by disabling and freeing any resources associated with it.
 */
void cleanupAESCipher(EVP_CIPHER_CTX* ctx) {
    // Disable the cipher context
    EVP_CIPHER_CTX_cleanup(ctx);

    // Free any allocated memory
    free(ctx);
}

