    private readonly RedisConnection _redisConnection;

    public CachingRestApiClient(string apiUrl, RedisConnection redisConnection) {
        _apiUrl = apiUrl;
        _redisConnection = redisConnection;
    }

    public async Task<string> SendRequestAsync(byte[] data) {
        // Check if the data is already cached
        string cacheKey = GetCacheKey(data);
        byte[] cachedData = await _redisConnection.GetAsync(cacheKey);

        if (cachedData != null) {
            // Return the cached data
            return Encoding.UTF8.GetString(cachedData);
        } else {
            // Serialize the data into a JSON string
            string json = JsonConvert.SerializeObject(data, Formatting.None);

            try {
                // Send the request to the external REST API
                HttpResponseMessage response = await _httpClient.PostAsync(_apiUrl, new StringContent(json));

                if (response.IsSuccessStatusCode) {
                    // Store the response in cache
                    string responseString = await response.Content.ReadAsStringAsync();
                    cachedData = Encoding.UTF8.GetBytes(responseString);
                    await _redisConnection.SetAsync(cacheKey, cachedData);
                } else {
                    // Handle failure to send request or receive response
                    throw new Exception("Failed to send request to external API.");
                }
            } catch (Exception ex) {
                // Handle exceptions related to sending request or receiving response
                Console.WriteLine(ex.Message);
            } finally {
                _httpClient.Dispose();
            }
        }

        return cachedData;
    }

