#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <algorithm>
#include <cmath>

using namespace std;

// Attack profile struct
struct AttackProfile {
    int cost; // energy cost for attacking
    string specialEffects; // special effects of the attack (e.g., fire, ice)
    vector<int> targetPrioritizationRules; // prioritize targets based on certain criteria (e.g., distance, health)
    int cooldownPeriod; // time in seconds before the next attack can be used
};

// Character struct
struct Character {
    int energy; // current energy level of the character
    int health; // current health of the character
    vector<int> targetPrioritizationRules; // prioritize targets based on certain criteria (e.g., distance, health)
    unordered_map<string, AttackProfile> attackProfiles; // map of attack profiles
};

// Function to dynamically select the most optimal attack strategy for a character
AttackProfile dynamicAttackSelection(Character character, vector<int> enemyUnits) {
    // Sort enemies by distance from character
    sort(enemyUnits.begin(), enemyUnits.end(), [](const int& lhs, const int& rhs) {
        return (lhs < rhs);
    });

    // Initialize attack profile with highest cooldown period and lowest cost
    AttackProfile currentAttack;
    for (auto& attack : character.attackProfiles) {
        if (attack.second.cooldownPeriod > currentAttack.cooldownPeriod ||
            (attack.second.cooldownPeriod == currentAttack.cooldownPeriod && attack.second.cost < currentAttack.cost)) {
            currentAttack = attack.second;
        }
    }

    // Check for available energy and distance to enemies
    int availableEnergy = character.energy - currentAttack.cost;
    if (availableEnergy < 0) {
        return AttackProfile();
    }

    // Loop through enemy units and check for optimal attack
    for (int i = 0; i < enemyUnits.size(); ++i) {
        int distanceToEnemy = abs(enemyUnits[i] - character.position);
        if (distanceToEnemy > currentAttack.targetPrioritizationRules[1]) {
            continue;
        }

        // Check for available energy and distance to enemies
        int availableEnergy = character.energy - currentAttack.cost;
        if (availableEnergy < 0) {
            return AttackProfile();
        }

        // Update attack profile with optimal target
        if (currentAttack.targetPrioritizationRules[2] == "distance") {
            currentAttack.target = enemyUnits[i];
        } else if (currentAttack.targetPrioritizationRules[2] == "health") {
            currentAttack.target = find(enemyUnits.begin(), enemyUnits.end(), [](int x) { return x; });
        }

        // Update attack profile with optimal cooldown period and energy cost
        currentAttack.cooldownPeriod = character.attackProfiles[currentAttack.name].cooldownPeriod;
        currentAttack.cost = character.attackProfiles[currentAttack.name].cost;
    }

    return currentAttack;
}

int main() {
    // Initialize character and enemy units
    Character character = Character();
    vector<int> enemyUnits = {5, 10, 15};

    // Select optimal attack strategy based on character's state, available resources, and proximity to enemies
    AttackProfile attackProfile = dynamicAttackSelection(character, enemyUnits);

    // Print attack profile information
    cout << "Selected attack: " << attackProfile.name << endl;
    cout << "Energy cost: " << attackProfile.cost << endl;
    cout << "Cooldown period: " << attackProfile.cooldownPeriod << endl;
    cout << "Target: " << attackProfile.target << endl;
}
```
This code uses a character struct to store information about the character's energy, health, and attack profiles. It also includes a vector of enemy units for the proximity calculation. The `dynamicAttackSelection` function takes in a character object and an array of enemy units as input, sorts the enemies by distance from the character, and then checks for available energy and distance to the enemies. If there is sufficient energy and distance to the enemies, it updates the attack profile with the optimal target and cooldown period. Finally, it returns the updated attack profile object. The `main` function initializes a character object and an array of enemy units, calls the `dynamicAttackSelection` function, and prints the selected attack profile information.

