class CloudStorageManager {
    private $allowedExtensions = [];
    private $compressLimit = 5 * 1024 * 1024; // 5MB
    private $imageResizeMaxWidth = 800;
    private $imageResizeMaxHeight = 600;

    public function __construct() {
        $this->allowedExtensions = array("jpg", "jpeg", "png", "gif");
    }

    /**
     * Validate the file extension against a dynamically configurable list of allowed file types.
     * Ensure the method can handle updates to the allowed file types via an API call without downtime.
     */
    public function validateFileExtension($file, $allowedExtensions) {
        if (!isset($allowedExtensions)) {
            $allowedExtensions = $this->allowedExtensions;
        }
        return in_array(pathinfo($file, PATHINFO_EXTENSION), $allowedExtensions);
    }

    /**
     * Resize images to fit within specified dimensions while maintaining aspect ratio.
     * Optimize this method for performance when dealing with high-resolution images, considering parallel processing and caching strategies to handle multiple concurrent requests efficiently.
     */
    public function resizeImage($file, $maxWidth, $maxHeight) {
        // Check if the file is an image
        if (getimagesize($file)) {
            // Get the original dimensions of the image
            list($width, $height) = getimagesize($file);
            // Calculate the scale factor
            $scaleFactor = max(min($maxWidth / $width, $maxHeight / $height), 1);
            // Resize the image
            $newWidth = round($width * $scaleFactor);
            $newHeight = round($height * $scaleFactor);
            Image::make($file)->resize($newWidth, $newHeight)->save();
        }
    }

    /**
     * Upload files to cloud storage after validating their size, type, and preventing overwriting of existing files.
     * Implement a retry mechanism for failed uploads and manage concurrent upload requests using distributed locks to ensure data integrity.
     */
    public function uploadFile($file, $destinationPath) {
        // Validate the file
        if (!$this->validateFileExtension($file)) {
            throw new InvalidArgumentException("Invalid file extension");
        }
        // Check if the file already exists at the destination path
        if (Storage::exists($destinationPath)) {
            throw new RuntimeException("File already exists at destination path");
        }
        // Upload the file
        Storage::put($destinationPath, $file);
    }

    /**
     * Download files from cloud storage with proper content type and attachment name set in the HTTP response.
     * Validate the file's existence and MIME type before downloading, and optimize for efficient streaming of large files.
     */
    public function downloadFile($filePath, $mimeType, $attachmentName) {
        // Check if the file exists
        if (!Storage::exists($filePath)) {
            throw new RuntimeException("File not found");
        }
        // Get the MIME type of the file
        $mimeType = Storage::getMimetype($filePath);
        // Stream the file to the user
        Storage::download($filePath, $attachmentName, $mimeType);
    }

    /**
     * Ensure atomicity in file deletion to prevent partial deletions.
     * Gracefully handle errors such as file not found, permission issues, and network failures.
     */
    public function deleteFile($filePath) {
        // Check if the file exists
        if (!Storage::exists($filePath)) {
            throw new RuntimeException("File not found");
        }
        // Delete the file
        Storage::delete($filePath);
    }

    /**
     * Securely move files between different cloud storage locations, handling large file transfers efficiently.
     * Use background jobs and asynchronous processing to minimize impact on user experience.
     */
    public function moveFile($sourcePath, $destinationPath) {
        // Check if the source file exists
        if (!Storage::exists($sourcePath)) {
            throw new RuntimeException("Source file not found");
        }
        // Check if the destination path is a valid directory
        if (!is_dir($destinationPath)) {
            throw new InvalidArgumentException("Destination path must be a valid directory");
        }
        // Move the file to the destination location
        Storage::move($sourcePath, $destinationPath);
    }

    /**
     * Perform atomic file renaming operations to avoid data corruption.
     * Ensure the method can handle existing files at the new path by appending version numbers or timestamps.
     */
    public function renameFile($oldFilePath, $newFilePath) {
        // Check if the old file exists
        if (!Storage::exists($oldFilePath)) {
            throw new RuntimeException("Old file not found");
        }
        // Check if the new file already exists
        if (Storage::exists($newFilePath)) {
            // Append a version number to the new file name
            $version = 1;
            while (true) {
                $newFileName = $newFilePath . "-" . $version;
                if (!Storage::exists($newFileName)) {
                    break;
                }
                $version++;
            }
            // Rename the file
            Storage::rename($oldFilePath, $newFileName);
        } else {
            // Rename the file
            Storage::rename($oldFilePath, $newFilePath);
        }
    }

    /**
     * Combine file validation, optional image resizing, and secure cloud upload into a single method.
     * Integrate automatic file compression for large files to optimize storage space, and consider rate limiting to prevent abuse.
     */
    public function secureFileUpload($file) {
        // Validate the file
        if (!$this->validateFileExtension($file)) {
            throw new InvalidArgumentException("Invalid file extension");
        }
        // Check if the file is too large to compress
        $maxSize = 10 * 1024 * 1024; // 10 MB
        if ($file->getClientSize() > $maxSize) {
            throw new RuntimeException("File too large");
        }
        // Resize the image, if necessary
        $this->resizeImage($file);
        // Upload the file to cloud storage
        $this->uploadFile($file);
    }
