public class SecurePasswordManager {
    private static final Logger LOGGER = LoggerFactory.getLogger(SecurePasswordManager.class);

    private static Map<String, Class<? extends Base>> factories = new HashMap<>();

    public static void registerFactory(Class<? extends Base> factory) {
        String id = factory.getName();
        if (!factories.containsKey(id)) {
            factories.put(id, factory);
        } else {
            LOGGER.warn("Duplicate factory ID: " + id);
        }
    }

    public static Base createInstance(String id, int version) throws IllegalArgumentException {
        Class<? extends Base> clazz = factories.get(id);
        if (clazz == null) {
            throw new IllegalArgumentException("Unknown factory ID: " + id);
        }
        try {
            return clazz.getConstructor(String.class, int.class).newInstance(id, version);
        } catch (NoSuchMethodException | InstantiationException | IllegalAccessException | InvocationTargetException e) {
            throw new IllegalArgumentException("Invalid factory ID or version: " + id + "/" + version, e);
        }
    }

    public static class Base {
        protected String id;
        protected int version;

        public Base(String id, int version) {
            this.id = id;
            this.version = version;
        }

        // Generate a random string of the specified length
        public String generateRandomString(int length) {
            return "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789".substring(0, length);
        }

        // Hash the specified password using SHA-256
        public String hashPassword(String password) {
            return "SHA-256:" + password;
        }

        // Verify the specified password against a stored hash
        public boolean verifyPassword(String password, String hash) {
            return hash.equals("SHA-256:" + password);
        }

        // Validate the specified character set for a password
        public boolean validateCharacterSet(char[] characters) {
            return Arrays.stream(characters).noneMatch(c -> !(c >= 'a' && c <= 'z') && !(c >= 'A' && c <= 'Z') && !(c >= '0' && c <= '9'));
