import os
import hashlib
import json
from datetime import datetime

from flask import Flask, request, jsonify
from flask_jwt import JWTManager
from sqlalchemy import create_engine, Column, Integer, String, DateTime
from sqlalchemy.orm import scoped_session, sessionmaker

# Environment variables for database connection and API endpoints
DB_USERNAME = os.getenv("DB_USERNAME")
DB_PASSWORD = os.getenv("DB_PASSWORD")
DB_HOST = os.getenv("DB_HOST")
DB_PORT = int(os.getenv("DB_PORT"))
API_BASE_URL = os.getenv("API_BASE_URL")
JWT_SECRET = os.getenv("JWT_SECRET")

# Create database connection and sessionmaker
engine = create_engine(f"postgresql://{DB_USERNAME}:{DB_PASSWORD}@{DB_HOST}:{DB_PORT}/resource_api")
Session = sessionmaker(bind=engine)
session = Session()

# Set up Flask app with JWTManager for token-based authentication and authorization
app = Flask(__name__)
jwt = JWTManager(app)

# Define database models for resources and file hashes
class Resource(Base):
    __tablename__ = "resources"

    id = Column(Integer, primary_key=True)
    name = Column(String)
    description = Column(String)
    version = Column(Integer)
    created_at = Column(DateTime, default=datetime.utcnow)

class FileHash(Base):
    __tablename__ = "file_hashes"

    id = Column(Integer, primary_key=True)
    file_path = Column(String)
    hash_value = Column(String)
    created_at = Column(DateTime, default=datetime.utcnow)

# Define Flask endpoints for resource management and file hash calculation
@app.route("/resources", methods=["PUT"])
@jwt.requires_auth
def update_resource():
    # Get request data and validate it
    resource_data = request.get_json()
    if not resource_data:
        return jsonify({"error": "Invalid request data"}), 400

    # Update existing resource in the database
    try:
        resource = session.query(Resource).filter_by(id=resource_data["id"]).one()
        resource.name = resource_data["name"]
        resource.description = resource_data["description"]
        resource.version += 1
        session.commit()
    except Exception:
        return jsonify({"error": "Invalid resource ID"}), 400

    # Return updated resource object
    return jsonify(resource.to_dict())

@app.route("/resources", methods=["POST"])
@jwt.requires_auth
def create_resource():
    # Get request data and validate it
    resource_data = request.get_json()
    if not resource_data:
        return jsonify({"error": "Invalid request data"}), 400

    # Create new resource in the database
    try:
        resource = Resource(name=resource_data["name"], description=resource_data["description"])
        session.add(resource)
        session.commit()
    except Exception:
        return jsonify({"error": "Failed to create resource"}), 400

    # Return created resource object
    return jsonify(resource.to_dict())

@app.route("/file-hash", methods=["POST"])
@jwt.requires_auth
def calculate_file_hash():
    # Get request data and validate it
    file_data = request.get_json()
    if not file_data:
        return jsonify({"error": "Invalid request data"}), 400

    # Calculate MD5 hash of the file in chunks for large files
    try:
        with open(file_data["path"], "rb") as f:
            md5 = hashlib.md5()
            while True:
                chunk = f.read(4096)
                if not chunk:
                    break
                md5.update(chunk)
        return jsonify({"hash_value": md5.hexdigest()})
    except Exception:
        return jsonify({"error": "Failed to calculate hash"}), 400

# Define Flask error handlers for various scenarios
@app.errorhandler(401)
def unauthorized(e):
    return jsonify({"error": "Unauthorized"}), 401

@app.errorhandler(403)
def forbidden(e):
    return jsonify({"error": "Forbidden"}), 403

@app.errorhandler(404)
def not_found(e):
    return jsonify({"error": "Not found"}), 404

@app.errorhandler(500)
def server_error(e):
    return jsonify({"error": "Server error"}), 500
