Here's an example implementation of the `loadResourceBundle` function in C:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

typedef struct {
    char* key;
    union {
        int i;
        float f;
        char* s;
    } value;
} resource_item_t;

typedef struct {
    int count;
    resource_item_t** items;
} resource_bundle_t;

int loadResourceBundle(const char* path) {
    // Open the file and read its contents into memory
    FILE* file = fopen(path, "r");
    if (file == NULL) {
        printf("Error: failed to open file %s\n", path);
        return -1;
    }

    char* buffer = malloc(sizeof(char) * 256);
    assert(buffer != NULL);

    size_t bytes_read = fread(buffer, sizeof(char), 256, file);
    if (bytes_read == 0) {
        printf("Error: failed to read from file %s\n", path);
        return -1;
    }

    // Parse the contents of the file and build a resource bundle
    int count = 0;
    resource_item_t* items[count];
    char* token = strtok(buffer, "\n");
    while (token != NULL) {
        char* key = token;
        char* value = strchr(key, '=');
        if (value == NULL) {
            printf("Error: failed to parse line %s\n", token);
            return -1;
        }

        *value++ = '\0';
        resource_item_t item = { key, 0 };

        // Check the type of the value and convert it accordingly
        if (strcmp(value, "integer") == 0) {
            item.value.i = atoi(value);
        } else if (strcmp(value, "float") == 0) {
            item.value.f = atof(value);
        } else if (strcmp(value, "string") == 0) {
            char* tmp = strdup(value + 1);
            assert(tmp != NULL);
            item.value.s = tmp;
        } else {
            printf("Error: unknown value type %s\n", value);
            return -1;
        }

        items[count++] = malloc(sizeof(resource_item_t));
        assert(items[count - 1] != NULL);
        *items[count - 1] = item;

        token = strtok(NULL, "\n");
    }

    // Close the file and return the resource bundle
    fclose(file);
    resource_bundle_t* bundle = malloc(sizeof(resource_bundle_t));
    assert(bundle != NULL);
    bundle->count = count;
    bundle->items = items;
    return bundle;
}
```
This function takes a file path as input and loads the contents of the file into memory. It then parses each line in the file, tokenizing on newline characters (`\n`), and extracts the key-value pairs from each line. The function checks the type of the value for each pair and converts it to the appropriate type using `atoi`, `atof`, or `strdup`.

The function then builds an array of `resource_item_t` structures, where each structure represents a single key-value pair. The function allocates memory for the array and its items using dynamic memory allocation. If any error occurs during memory allocation or file I/O, the function returns -1 and prints an error message to standard output.

Finally, the function closes the input file and returns a pointer to the loaded resource bundle. The returned pointer is of type `resource_bundle_t`, which is a custom data structure that contains an array of `resource_item_t` structures and the number of items in the array. This data structure can be used to access the loaded resources, such as retrieving values by key or iterating over all key-value pairs.

