use std::env;
use std::fs;
use std::path::PathBuf;

fn create_config_dir_and_set_env_var(name: &str) -> Result<(), String> {
    // Check if the environment variable is already set
    let env_var = env::var(name);
    if env_var.is_ok() {
        return Ok(());
    }

    // Create a new directory with the given name
    let mut config_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    config_dir.push(name);
    fs::create_dir(&config_dir).map_err(|e| e.to_string())?;

    // Set the environment variable to the path of the new directory
    env::set_var(name, &config_dir.as_os_str().to_string_lossy());
    Ok(())
}
