function extractBookNames(text) {
  const oldTestament = ["Genesis", "Exodus", "Leviticus", "Numbers", "Deuteronomy"];
  const newTestament = ["Matthew", "Mark", "Luke", "John"];
  const validBooks = [...oldTestament, ...newTestament];

  // Ignore punctuation and special characters in the text
  text = text.replace(/[^\w\s]/g, "");

  // Remove case sensitivity from book names
  text = text.toLowerCase();

  const bookNames = {};

  // Loop through each valid book name in the list
  for (const book of validBooks) {
    // Search for matches using a regular expression
    const regex = new RegExp(`\\b${book}\\b`, "g");
    let match;
    while ((match = regex.exec(text)) !== null) {
      // Increment the number of times each book is found in the text
      if (!bookNames[book]) {
        bookNames[book] = 0;
      }
      bookNames[book]++;
    }
  }

  return bookNames;
}
```
