class ResourceUpdateHandler:
    def __init__(self):
        self.resources = {}
        self.executor = ThreadPoolExecutor(max_workers=5)

    def update_resource(self, resource_id, request_body):
        try:
            # Parse the request body and validate the data
            data = json.loads(request_body)
            if not self.validate_data(data):
                raise ValueError("Invalid data")

            # Update the resource in memory
            self.resources[resource_id] = data

            # Calculate the MD5 hash of the file and return it
            file_path = os.path.join(os.getcwd(), "files", resource_id)
            hash_object = hashlib.md5()
            with open(file_path, "rb") as f:
                for chunk in iter(lambda: f.read(4096), b""):
                    hash_object.update(chunk)
            return {"hash": hash_object.hexdigest()}

        except Exception as e:
            # Log the error and return a meaningful response
            print(f"Error updating resource {resource_id}: {e}")
            return {"error": "An unexpected error occurred"}

    def validate_data(self, data):
        # Implement validation logic here
        pass

class FileHashCalculator:
    def __init__(self):
        self.hash_object = hashlib.md5()

    def calculate_hash(self, file_path):
        try:
            with open(file_path, "rb") as f:
                for chunk in iter(lambda: f.read(4096), b""):
                    self.hash_object.update(chunk)
            return self.hash_object.hexdigest()

        except Exception as e:
            # Log the error and return a meaningful response
            print(f"Error calculating hash for {file_path}: {e}")
            return None
