#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
#include <pthread.h>

#define MAX_LINE_LENGTH 1024
#define MIN_NUM_FIELDS 3
#define DEFAULT_ENCODING "UTF-8"

// Struct to store processed line data
typedef struct {
    int num_fields;
    char **fields;
} line_data_t;

// Function to parse a line and extract the numeric fields
line_data_t *parse_line(char *line) {
    // Allocate memory for the fields array
    line_data_t *data = malloc(sizeof(line_data_t));
    if (!data) {
        perror("Failed to allocate memory for line data");
        return NULL;
    }

    // Count the number of numeric fields in the line
    int num_fields = 0;
    char *token = strtok(line, " ");
    while (token != NULL) {
        if (isdigit(token[0]) || token[0] == '-') {
            num_fields++;
        }
        token = strtok(NULL, " ");
    }

    // If there are fewer than three numeric fields, skip the line
    if (num_fields < MIN_NUM_FIELDS) {
        free(data);
        return NULL;
    }

    // Allocate memory for the fields array and store the tokens
    data->fields = malloc(sizeof(char *) * num_fields);
    if (!data->fields) {
        perror("Failed to allocate memory for field pointers");
        free(data);
        return NULL;
    }

    token = strtok(line, " ");
    int i = 0;
    while (token != NULL) {
        if (isdigit(token[0]) || token[0] == '-') {
            data->fields[i++] = token;
        }
        token = strtok(NULL, " ");
    }

    // Store the number of numeric fields in the line
    data->num_fields = num_fields;

    return data;
}

// Function to calculate the sum and average of the last three fields on a line
void calculate_averages(line_data_t *data) {
    double sum = 0.0;
    for (int i = data->num_fields - MIN_NUM_FIELDS; i < data->num_fields; i++) {
        sum += atof(data->fields[i]);
    }
    double average = sum / MIN_NUM_FIELDS;
    printf("%.2f\n", average);
}

// Function to process a line and calculate the averages
void process_line(char *line) {
    // Parse the line and extract the numeric fields
    line_data_t *data = parse_line(line);
    if (data == NULL) {
        return;
    }

    // Calculate the sum and average of the last three fields
    calculate_averages(data);

    // Free the memory allocated for the line data
    free(data->fields);
    free(data);
}

// Function to process a range of lines in a file
void process_file(FILE *file, int start, int end) {
    // Check if the requested range is valid
    if (start < 0 || end > MAX_LINE_LENGTH || start > end) {
        fprintf(stderr, "Invalid line range\n");
        return;
    }

    // Read the file and process each line in the range
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    for (int i = start; i <= end && (read = getline(&line, &len, file)) != -1; i++) {
        process_line(line);
    }

    // Free the memory allocated for the line buffer
    free(line);
}

// Function to read a file and print its processed contents
void read_file(char *filename) {
    // Open the file and check if it exists
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open file");
        return;
    }

    // Get the number of lines in the file
    int num_lines = 0;
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        num_lines++;
    }
    rewind(file);

    // Read the file and process each line in a separate thread
    pthread_t *threads = malloc(sizeof(pthread_t) * num_lines);
    for (int i = 0; i < num_lines; i++) {
        if (pthread_create(&threads[i], NULL, process_line, line)) {
            perror("Failed to create thread");
            free(threads);
            return;
        }
    }

    // Wait for all threads to complete and check for errors
    void *status;
    for (int i = 0; i < num_lines; i++) {
        if (pthread_join(threads[i], &status)) {
            perror("Failed to join thread");
        } else if (status) {
            fprintf(stderr, "Error in thread %d\n", i);
        }
    }

    // Free the memory allocated for the threads and close the file
    free(threads);
    fclose(file);
}
```
This code uses a struct to store the processed line data and a separate function to parse each line. The `process_line` function is called in a separate thread, which helps improve performance by allowing multiple lines to be processed simultaneously. The `read_file` function reads the file and calls `process_line` on each line, while also checking for errors.

This code uses the `pthread_create` function to create a new thread, and the `pthread_join` function to wait for the thread to complete. It also uses the `malloc` and `free` functions to allocate and free memory for the threads.

This code does not handle errors in the file reading process or in the line processing function. It is up to the user to ensure that the input file exists and is a valid text file, and that the requested line range is valid.

