  if (!file) {
    printf("Error opening %s: %s\n", uri, strerror(errno));
    exit(EXIT_FAILURE);
  }

  // Read remote module implementation into memory
  fseek(file, 0, SEEK_END);
  long size = ftell(file);
  rewind(file);
  void* data = malloc(size);
  if (!data) {
    printf("Error allocating %ld bytes: %s\n", size, strerror(errno));
    exit(EXIT_FAILURE);
  }
  fread(data, size, 1, file);
  fclose(file);

  // Save remote module implementation to disk
  FILE* handle = fopen(module, "wb");
  if (!handle) {
    printf("Error saving %s: %s\n", module, strerror(errno));
    exit(EXIT_FAILURE);
  }
  fwrite(data, size, 1, handle);
  free(data);
}

