package com.example.database;

import java.sql.*;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.TimeUnit;
import java.util.logging.Logger;

public class DatabaseConnectionManager {
    private static final Logger LOGGER = Logger.getLogger(DatabaseConnectionManager.class.getName());

    // Initialize the connection pool with the specified initial size and maximum size
    private ArrayBlockingQueue<Connection> connectionPool;
    private int maxSize;

    public DatabaseConnectionManager(int initialSize, int maxSize, String connectionString) {
        this.connectionPool = new ArrayBlockingQueue<>(initialSize);
        this.maxSize = maxSize;
        initializePool(initialSize, maxSize, connectionString);
    }

    // Initialize the connection pool with the specified initial size and maximum size
    private void initializePool(int initialSize, int maxSize, String connectionString) {
        try {
            if (initialSize < 0 || maxSize < 0) {
                throw new IllegalArgumentException("Invalid input parameters for initialSize or maxSize");
            }
            for (int i = 0; i < initialSize; i++) {
                Connection conn = DriverManager.getConnection(connectionString);
                connectionPool.add(conn);
            }
        } catch (SQLException | IllegalArgumentException e) {
            LOGGER.severe("Error initializing connection pool: " + e.getMessage());
        }
    }

    // Returns a database connection from the pool, waiting until one becomes available if necessary
    public Connection getConnection() {
        try {
            return connectionPool.take();
        } catch (InterruptedException e) {
            LOGGER.severe("Error taking connection from pool: " + e.getMessage());
        }
        return null;
    }

    // Releases the given database connection back to the pool for reuse
    public void releaseConnection(Connection conn) {
        try {
            if (conn != null && !conn.isClosed()) {
                conn.close();
                LOGGER.info("Released connection " + conn.toString());
            }
        } catch (SQLException e) {
            LOGGER.severe("Error releasing connection: " + e.getMessage());
        } finally {
            connectionPool.add(conn);
        }
    }

    // Tests the given database connection to ensure it is still valid and functional
    public boolean testConnection(Connection conn) {
        try {
            if (conn != null && !conn.isClosed()) {
                Statement stmt = conn.createStatement();
                stmt.executeQuery("SELECT 1");
                return true;
            }
        } catch (SQLException e) {
            LOGGER.warning("Error testing connection: " + e.getMessage());
        }
        return false;
    }

    // Resets the connection pool by closing all active and idle connections and reinitializing the pool with the initial size and maximum size
    public void resetPool() {
        try {
            Connection conn = connectionPool.take();
            while (!conn.isClosed()) {
                conn.close();
                LOGGER.info("Closed connection " + conn.toString());
                conn = connectionPool.take();
            }
            initializePool(connectionPool.size(), maxSize, connectionString);
        } catch (InterruptedException | SQLException e) {
            LOGGER.severe("Error resetting connection pool: " + e.getMessage());
        } finally {
            connectionPool = new ArrayBlockingQueue<>(connectionPool.size());
        }
    }

    // Sets the maximum time (in milliseconds) a connection can remain idle in the pool before being closed
    public void setMaxIdleTime(long maxIdleTime) {
        if (maxIdleTime <= 0) {
            LOGGER.warning("Invalid input for maxIdleTime: " + maxIdleTime);
            return;
        }
        this.maxIdleTime = maxIdleTime;
    }

    // Enables or disables the testing of borrowed connections
    public void setTestOnBorrow(boolean testOnBorrow) {
        this.testOnBorrow = testOnBorrow;
    }

    // Logs the usage of database connections from the pool, including actions performed and the associated database name
    public void logConnectionUsage(String ipAddress, String action, String databaseName) {
        LOGGER.info("Connection used: " + ipAddress + ", " + action + ", " + databaseName);
    }

    // Provides a method to monitor the current status of the connection pool, including the number of active, idle, and total connections
    public void monitorPoolStatus() {
        int activeConnections = 0;
        int idleConnections = 0;
        for (Connection conn : connectionPool) {
            if (!conn.isClosed()) {
                activeConnections++;
            } else {
                idleConnections++;
            }
        }
        LOGGER.info("Active connections: " + activeConnections);
        LOGGER.info("Idle connections: " + idleConnections);
        LOGGER.info("Total connections: " + connectionPool.size());
    }

    // Sanitizes SQL queries to prevent SQL injection attacks, ensuring that only safe and valid queries are executed
    public String sanitizeSQLQuery(String query) {
        return query;
    }
}
