class BaseClass:
    def __init__(self):
        self._registry = {}

    def register_factory(self, name, factory):
        if name in self._registry:
            raise ValueError("A factory with the same name already exists")
        self._registry[name] = factory

    def discover_subclasses(self, directory):
        for file in os.listdir(directory):
            path = os.path.join(directory, file)
            if not os.path.isfile(path):
                continue
            name, ext = os.path.splitext(file)
            if ext == ".py":
                module = importlib.import_module("." + name, package=self.__class__.__name__)
                for attr in dir(module):
                    obj = getattr(module, attr)
                    if isinstance(obj, type) and issubclass(obj, BaseClass):
                        self.register_factory(name, obj)

    def from_json(self, json_string):
        # Validate the input JSON string against a schema
        # to ensure it contains all necessary fields and follows the correct format
        try:
            data = json.loads(json_string)
        except ValueError as e:
            raise ValueError("Invalid JSON string") from e

        if "factory" not in data or "args" not in data:
            raise ValueError("JSON string does not contain necessary fields")

        factory = self.get_factory(data["factory"])
        if factory is None:
