    if (err != 0) {
        return NULL;
    }

    // Perform encryption or decryption based on the command line option
    if (strcmp(commandLineOption, "encrypt") == 0) {
        char *ciphertext = AES_ecb_encrypt(plaintext, key);
        return ciphertext;
    } else if (strcmp(commandLineOption, "decrypt") == 0) {
        char *plaintext = AES_ecb_decrypt(plaintext, key);
        return plaintext;
    }

    // Return NULL if the command line option is not valid
    return NULL;
}
```
