#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/err.h>

// Function to initialize AES-256-CBC cipher with given password using OpenSSL library
EVP_CIPHER_CTX* init_aes_cbc(const char* password) {
    // Allocate memory for cipher context
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        fprintf(stderr, "Error: Insufficient memory to initialize AES-256-CBC cipher\n");
        return NULL;
    }

    // Set key length and IV length
    int key_len = 32;
    int iv_len = 16;

    // Generate random IV for each initialization
    unsigned char* iv = (unsigned char*) malloc(iv_len * sizeof(unsigned char));
    if (iv == NULL) {
        fprintf(stderr, "Error: Insufficient memory to generate random IV\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    RAND_bytes(iv, iv_len);

    // Derive key using PBKDF2 with a configurable iteration count
    unsigned char* derived_key = (unsigned char*) malloc(key_len * sizeof(unsigned char));
    if (derived_key == NULL) {
        fprintf(stderr, "Error: Insufficient memory to derive key using PBKDF2\n");
        free(iv);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    int derived_key_len = 0;
    if (!PKCS5_PBKDF2_HMAC_SHA1((const unsigned char*) password, strlen(password), (const unsigned char*) "salt", strlen("salt"), iter_count, key_len, derived_key)) {
        fprintf(stderr, "Error: Failed to derive key using PBKDF2\n");
        free(iv);
        free(derived_key);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Initialize cipher with derived key and random IV
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, derived_key, iv)) {
        fprintf(stderr, "Error: Failed to initialize AES-256-CBC cipher\n");
        free(iv);
        free(derived_key);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Set key length and IV length
    EVP_CIPHER_CTX_set_key_length(ctx, key_len);
    EVP_CIPHER_CTX_set_iv_length(ctx, iv_len);

    // Free memory for derived key and random IV
    free(derived_key);
    free(iv);

    return ctx;
}

// Function to clean up and disable cipher when it is no longer needed
void cleanup_aes_cbc(EVP_CIPHER_CTX* ctx) {
    // Free memory for cipher context
    EVP_CIPHER_CTX_free(ctx);
}
