public class OptimizeImageUploadAndResize {
    private static final int DEFAULT_COMPRESSION_QUALITY = 90;
    private static final int MIN_IMAGE_SIZE_MB = 1;
    private static final int MAX_IMAGE_SIZE_MB = 50;
    private static final int CONCURRENCY_LEVEL = 4;
    private static final String ACCESS_KEY_ID = "accessKeyId";
    private static final String SECRET_ACCESS_KEY = "secretAccessKey";
    private static final String BUCKET_NAME = "bucketName";
    private static final String CONFIGURATION_FILE = "configuration.txt";

    public static void main(String[] args) {
        AmazonS3 s3Client = new AmazonS3Client(new BasicAWSCredentials(ACCESS_KEY_ID, SECRET_ACCESS_KEY));
        S3Object object = new S3Object();
        object.setBucketName(BUCKET_NAME);
        object.setKey("image-key");
        try {
            byte[] imageData = getImageData();
            if (imageData == null) {
                System.out.println("Invalid input");
                return;
            }
            // Upload the image to S3
            s3Client.putObject(object, new ByteArrayInputStream(imageData), "image/jpeg");
            // Get the resized image URL from S3
            String resizedImageUrl = getResizedImageURL(s3Client, object);
            System.out.println("Resized image URL: " + resizedImageUrl);
        } catch (IOException | AmazonServiceException e) {
            System.out.println("Error uploading or getting the resized image");
            e.printStackTrace();
        }
    }

    private static byte[] getImageData() throws IOException {
        // Read the image data from a file
        File file = new File("/path/to/image.jpg");
        return Files.readAllBytes(file.toPath());
    }

    private static String getResizedImageURL(AmazonS3 s3Client, S3Object object) throws IOException {
        // Get the original image metadata
        ObjectMetadata metadata = s3Client.getObjectMetadata(object);
        long originalFileSize = metadata.getContentLength();
        int originalWidth = (int) metadata.get("x-image-width");
        int originalHeight = (int) metadata.get("x-image-height");

        // Load the configuration file
        Properties properties = new Properties();
        FileInputStream configFileStream = new FileInputStream(CONFIGURATION_FILE);
        properties.load(configFileStream);
        int targetWidth = Integer.parseInt(properties.getProperty("target-width"));
        int targetHeight = Integer.parseInt(properties.getProperty("target-height"));
        int compressionQuality = Integer.parseInt(properties.getProperty("compression-quality"));
        configFileStream.close();

        // Determine the target dimensions based on the aspect ratio of the original image and the configuration file settings
        int targetAspectRatio = (int) Math.round((double) targetWidth / targetHeight);
        int resizedWidth;
        int resizedHeight;
        if (targetAspectRatio > originalAspectRatio) {
            resizedWidth = targetWidth;
            resizedHeight = (int) Math.round((double) originalHeight * targetWidth / originalWidth);
        } else {
            resizedWidth = (int) Math.round((double) originalWidth * targetHeight / originalHeight);
            resizedHeight = targetHeight;
        }

        // Resize the image and compress it to the specified quality level
        BufferedImage bufferedImage = ImageIO.read(new ByteArrayInputStream(imageData));
        bufferedImage = resizeImage(bufferedImage, resizedWidth, resizedHeight);
        bufferedImage = compressImage(bufferedImage, compressionQuality);

        // Upload the resized image to S3 and get the URL
        object.setKey("resized-image-key");
        s3Client.putObject(object, new ByteArrayInputStream(getBufferedImageAsByteArray(bufferedImage)), "image/jpeg");
        String resizedImageUrl = s3Client.generatePresignedUrl(BUCKET_NAME, object.getKey()).toString();

        return resizedImageUrl;
    }

    private static BufferedImage resizeImage(BufferedImage bufferedImage, int width, int height) {
        // Get the original image dimensions
        int originalWidth = bufferedImage.getWidth();
        int originalHeight = bufferedImage.getHeight();

        // Calculate the scale factor
        double scaleX = (double) width / originalWidth;
        double scaleY = (double) height / originalHeight;

        // Create a new image with the target dimensions
        BufferedImage resizedImage = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);

        // Draw the original image on the new image with the scale factor
        Graphics2D graphics = resizedImage.createGraphics();
        graphics.drawImage(bufferedImage, 0, 0, width, height, null);
        graphics.dispose();

        return resizedImage;
    }

    private static BufferedImage compressImage(BufferedImage bufferedImage, int compressionQuality) {
        // Get the original image dimensions
        int originalWidth = bufferedImage.getWidth();
        int originalHeight = bufferedImage.getHeight();

        // Calculate the target file size based on the compression quality level
        long targetFileSize = (long) Math.ceil((double) originalWidth * originalHeight / compressionQuality);

        // Compress the image using the JPEG format and the specified compression quality level
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        ImageIO.write(bufferedImage, "jpg", outputStream);
        byte[] compressedData = outputStream.toByteArray();

        // Check if the file size is within the expected range
        long actualFileSize = compressedData.length;
        if (actualFileSize > targetFileSize) {
            System.out.println("Warning: Compression increased the file size");
        } else if (actualFileSize < targetFileSize) {
            // TODO: Add a mechanism to reduce the file size further using lossless compression techniques
        }

        return bufferedImage;
    }

    private static byte[] getBufferedImageAsByteArray(BufferedImage bufferedImage) {
        // Convert the BufferedImage to a byte array in JPEG format
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        ImageIO.write(bufferedImage, "jpg", outputStream);
        return outputStream.toByteArray();
    }
}
