import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import org.apache.http.client.methods.HttpGet;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;

public class JSONParser {
    private static final ObjectMapper MAPPER = new ObjectMapper();
    private static final CloseableHttpClient CLIENT = HttpClients.createDefault();
    private static final Map<String, JsonNode> CACHE = new ConcurrentHashMap<>();

    public static JsonNode parseJSON(String json) throws Exception {
        // Parse the JSON string using Jackson library
        return MAPPER.readTree(json);
    }

    public static void cacheResult(String key, JsonNode value) {
        // Store the parsed result in a concurrent hash map
        CACHE.putIfAbsent(key, value);
    }

    public static JsonNode getCachedResult(String key) {
        // Retrieve the cached result for the given key
        return CACHE.get(key);
    }

    public static void clearCache() {
        // Clear all entries from the cache
        CACHE.clear();
    }

    public static JsonNode extractValue(String json, String path) throws Exception {
        // Extract a specific value from the JSON document using the provided path
        return MAPPER.readTree(json).at(path);
    }

    public static boolean validateJSON(String json) throws Exception {
        // Validate the JSON string against a predefined schema
        try {
            JsonNode node = MAPPER.readTree(json);
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    public static String getAPIResponse(String url) throws Exception {
        // Send an HTTP GET request to the provided URL and retrieve the response
        HttpGet httpget = new HttpGet(url);
        try (CloseableHttpClient client = CLIENT) {
            return client.execute(httpget).getEntity().toString();
        } catch (Exception e) {
            throw new Exception("Error sending HTTP GET request to URL", e);
        }
    }
}
