```cpp
#include <iostream>
#include <memory>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

// Octree node structure
struct OctreeNode {
    std::vector<std::unique_ptr<OctreeNode>> children;
    std::vector<std::pair<int, int>> points; // (x, y) coordinates of points in this node's bounding box
};

// Spatial partitioning system using an octree
class Octree {
public:
    void insertPoint(int x, int y);
    bool checkCollision(int x1, int y1, int x2, int y2) const;
private:
    std::mutex mutex_;
    std::condition_variable cv_;
    std::unique_ptr<OctreeNode> root_;
};

// Implementation of the Octree class
void Octree::insertPoint(int x, int y) {
    std::lock_guard<std::mutex> lock(mutex_);
    // Check if a node with the given coordinates already exists
    if (!root_) {
        root_ = std::make_unique<OctreeNode>();
    }
    OctreeNode* current = root_.get();
    while (true) {
        // Find the child node that contains the point
        int index = 0;
        for (int i = 1; i < 8; ++i) {
            if (x >= current->children[i]->boundingBox.minX && x <= current->children[i]->boundingBox.maxX &&
                    y >= current->children[i]->boundingBox.minY && y <= current->children[i]->boundingBox.maxY) {
                index = i;
            }
        }
        if (index == 0) {
            break; // The point is outside the bounding box of all child nodes
        }
        current = current->children[index].get();
    }
    current->points.push_back(std::make_pair(x, y));
}

bool Octree::checkCollision(int x1, int y1, int x2, int y2) const {
    std::lock_guard<std::mutex> lock(mutex_);
    // Find the node that contains the point
    const OctreeNode* current = root_.get();
    while (true) {
        if (!current) {
            return false; // The point is outside the bounding box of all nodes
        }
        int index = 0;
        for (int i = 1; i < 8; ++i) {
            if (x1 >= current->children[i]->boundingBox.minX && x1 <= current->children[i]->boundingBox.maxX &&
                    y1 >= current->children[i]->boundingBox.minY && y1 <= current->children[i]->boundingBox.maxY) {
                index = i;
            }
        }
        if (index == 0) {
            break; // The point is outside the bounding box of all child nodes
        }
        current = current->children[index].get();
    }
    // Check for collision with all points in the node
    for (const auto& point : current->points) {
        if (point.first == x2 && point.second == y2) {
            return true;
        }
    }
    return false;
}
