function generateAccessToken($userId) {
    // Generate a unique access token for the user
    $token = bin2hex(openssl_random_pseudo_bytes(32));
    $stmt = $db->prepare('INSERT INTO access_tokens (user_id, token) VALUES (?, ?)');
    $stmt->bind_param('is', $userId, $token);
    $stmt->execute();
    return $token;
}

function uploadFile($file) {
    // Upload the file to the server and return the filename
    $filename = $file['name'];
    move_uploaded_file($file['tmp_name'], 'uploads/' . $filename);
    return $filename;
}

function getFilename($id) {
    // Get the filename associated with a file ID
    $stmt = $db->prepare('SELECT name FROM files WHERE id=?');
    $stmt->bind_param('i', $id);
    $stmt->execute();
    $result = $stmt->get_result();
    return $result->fetch_assoc()['name'];
}

