C++ Spatial Partitioning System Using an Octree for Efficient Collision Detection:
```c++
#include <iostream>
#include <vector>
#include <unordered_map>
#include <thread>

// Define a struct to represent a node in the octree
struct Node {
    int x, y, z; // Coordinates of the node
    std::vector<Node*> children; // Child nodes
};

// Define a class to manage the spatial partitioning
class Octree {
public:
    Octree(int size) : size_(size) {}

    void insert(int x, int y, int z, const Node& node) {
        // Insert the node into the octree at the given coordinates
        nodes_[x][y][z] = node;
    }

    std::vector<Node*> query(int x, int y, int z, int size) {
        // Query the nodes in the octree within a certain radius centered around the given coordinates
        std::vector<Node*> result;
        for (auto& node : nodes_[x - size / 2][y - size / 2][z - size / 2]) {
            if (node->x <= x + size / 2 && node->y <= y + size / 2 && node->z <= z + size / 2) {
                result.push_back(node);
            }
        }
        return result;
    }

private:
    int size_; // Size of the octree in each dimension
    std::unordered_map<int, std::unordered_map<int, std::vector<Node*>>> nodes_; // Map of nodes by x, y, and z coordinates
};
