public class WeatherDataAggregator {
    private static final Map<String, String> apiTokens = new HashMap<>();
    private static final Map<String, WeatherDataProvider> weatherProviders = new HashMap<>();

    public static void init() {
        apiTokens.put("openweathermap", "YOUR_OPENWEATHERMAP_API_TOKEN");
        apiTokens.put("weatherapi", "YOUR_WEATHERAPI_API_TOKEN");

        weatherProviders.put("openweathermap", new OpenWeatherMapProvider());
        weatherProviders.put("weatherapi", new WeatherApiProvider());
    }

    public static CompletableFuture<WeatherData> getWeatherData(String location) {
        CompletableFuture<WeatherData> future = new CompletableFuture<>();

        try {
            String apiToken = apiTokens.get(location);
            WeatherDataProvider provider = weatherProviders.get(location);

            if (provider == null) {
                future.completeExceptionally(new Exception("Invalid location"));
            } else {
                provider.getWeatherData(apiToken, location).thenAccept(future::complete).exceptionally(ex -> {
                    ex.printStackTrace();
                    return null;
                });
            }
        } catch (Exception e) {
            future.completeExceptionally(e);
        }

        return future;
    }
}

