public static IDataReader ParameterizeAndExecuteCommand(List<object> values, SqlConnection connection, string commandText)
{
    // Create a parameterized SQL command
    var command = new SqlCommand(commandText, connection);

    // Add parameters for each value in the list
    foreach (var value in values)
    {
        command.Parameters.AddWithValue($"@value_{values.IndexOf(value)}", value);
    }

    // Execute the SQL command and return an IDataReader for the result set
    return command.ExecuteReader();
}
