#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// Function to dynamically trim and capitalize a string
char* dynamicTrimAndCapitalize(const char* input, const char* wordsToTrim, int sizeLimit)
{
    // Dynamic memory allocation for the resulting string
    char* result = malloc(sizeLimit);

    if (result == NULL)
    {
        printf("Error: Memory allocation failed. Exiting.\n");
        return NULL;
    }

    int index = 0;
    bool wordStarted = false;
    bool wordFinished = false;

    // Iterate through the input string
    for (int i = 0; i < strlen(input); i++)
    {
        char c = input[i];

        if (wordStarted)
        {
            result[index] = c;
            index++;
        }

        if (c == ' ' || c == '\n')
        {
            wordFinished = true;
            continue;
        }

        if (!wordStarted)
        {
            if (strchr(wordsToTrim, c) != NULL)
            {
                continue;
            }
            else
            {
                result[index] = toupper(c);
                index++;
                wordStarted = true;
            }
        }
    }

    // Adjust the size limit based on the length of the fetched word list
    int adjustedSizeLimit = index + (strlen(wordsToTrim) - strlen(wordsToTrim));

    if (adjustedSizeLimit > sizeLimit)
    {
        printf("Error: The resulting string exceeds the limit. Exiting.\n");
        free(result);
        return NULL;
    }

    // Capitalize the first letter of each word in the resulting string
    for (int i = 0; i < index; i++)
    {
        if (i == 0 || result[i - 1] == ' ')
        {
            result[i] = toupper(result[i]);
        }
    }

    // Return the resulting string or NULL if it exceeds the adjusted size limit
    return result;
}
