```
use std::collections::HashMap;
use std::io::{BufReader, BufWriter};
use std::net::TcpStream;
use std::path::PathBuf;
use std::sync::Arc;
use std::thread;
use std::time::Duration;

use rust_crypto::digest::Digest;
use rust_crypto::hash::Hasher;
use rust_crypto::symmetric_cipher::Cipher;

struct ConfigManager {
    url: String,
    branch: String,
    params: HashMap<String, String>,
}

impl ConfigManager {
    fn new(url: &str, branch: &str) -> Self {
        ConfigManager {
            url: url.to_string(),
            branch: branch.to_string(),
            params: HashMap::new(),
        }
    }

    fn set_param(&mut self, key: &str, value: &str) {
        self.params.insert(key.to_string(), value.to_string());
    }

    fn get_param(&self, key: &str) -> Option<String> {
        self.params.get(key).cloned()
    }

    fn fetch_config(&mut self) -> Result<Vec<u8>, String> {
        let mut stream = TcpStream::connect(&self.url)?;
        let mut reader = BufReader::new(&stream);
        let mut buffer = vec![];
        reader.read_to_end(&mut buffer).map_err(|e| e.to_string())?;
        Ok(buffer)
    }

    fn decrypt_config(&self, config: &[u8]) -> Result<Vec<u8>, String> {
        let mut cipher = Cipher::new();
        cipher.set_key(&self.get_param("key").unwrap());
        cipher.decrypt(config)
    }

    fn validate_config(&self, config: &[u8]) -> Result<(), String> {
        let mut hasher = Hasher::new();
        for block in self.split_blocks(config) {
            hasher.update(block);
        }
        if !hasher.finalize().equals(&self.get_param("hash").unwrap()) {
            Err("Invalid configuration".to_string())
        } else {
            Ok(())
        }
    }

    fn split_blocks(&self, config: &[u8]) -> Vec<&[u8]> {
        let mut blocks = vec![];
        for (i, block) in config.iter().enumerate() {
            if i % self.get_param("block_size").unwrap().parse::<usize>().unwrap() == 0 {
                blocks.push(block);
            }
        }
        blocks
    }

    fn save_config(&self, config: &[u8]) -> Result<(), String> {
        let mut file = BufWriter::new(PathBuf::from("config.txt"));
        file.write_all(config).map_err(|e| e.to_string())?;
        Ok(())
    }
}

fn main() -> Result<(), String> {
    let mut manager = ConfigManager::new("https://example.com", "main");
    manager.set_param("key", "my-secret-key");
    manager.set_param("hash", "1234567890abcdef");
    manager.set_param("block_size", "1024");

    let config = manager.fetch_config()?;
    let decrypted_config = manager.decrypt_config(&config)?;
    manager.validate_config(&decrypted_config)?;

    for block in manager.split_blocks(&decrypted_config) {
        println!("{:?}", block);
    }

    manager.save_config(&decrypted_config)?;
    Ok(())
}
```
This code uses the `rust_crypto` library to handle cryptographic operations, such as decrypting and validating the configuration files. It also uses the `std::sync::Arc` type to create a shared reference to the configuration manager, which is necessary for managing concurrent access to the configuration data.

The `fetch_config` function downloads the configuration file from the remote repository using an HTTP GET request, and returns the raw bytes of the file as a vector of unsigned 8-bit integers. The `decrypt_config` function uses the `Cipher` type from the `rust_crypto` library to decrypt the downloaded configuration file, and returns the decrypted data as a vector of unsigned 8-bit integers.

The `validate_config` function uses the `Hasher` type from the `rust_crypto` library to compute the hash of the decrypted configuration file, and compares it with the expected value stored in the configuration manager. If the two values are not equal, an error is returned.

The `split_blocks` function splits the decrypted configuration file into blocks of size 1024 bytes (as specified by the "block_size" parameter), and returns a vector of references to these blocks.

Finally, the `save_config` function saves the decrypted and validated configuration data to a local file named "config.txt".

Note that this is just an example code, and you will need to modify it to suit your specific use case. For example, you may want to add error handling for network errors or authentication failures, or implement more advanced features such as config file merging or conflict resolution. Additionally, you should ensure that the configuration data is properly encrypted and authenticated to prevent unauthorized access or tampering.

