using System.Xml.XPath;

namespace XMLDocumentLoader
{
    public class DocumentLoader
    {
        private const string XPATH_SELECTOR = "/*/*";
        private const int CACHE_EXPIRATION_SECONDS = 3600; // 1 hour

        private Dictionary<string, CacheEntry> cache = new Dictionary<string, CacheEntry>();

        public async Task<XDocument> LoadDocumentAsync(string uri)
        {
            var cacheKey = GenerateCacheKey(uri);

            if (cache.ContainsKey(cacheKey))
            {
                return cache[cacheKey].Document;
            }

            XDocument document;

            try
            {
                document = await LoadDocumentFromSourceAsync(uri);
            }
            catch (Exception ex)
            {
                // Log error and return null
                Console.WriteLine($"Error loading document from {uri}: {ex.Message}");
                return null;
            }

            cache[cacheKey] = new CacheEntry(document, CACHE_EXPIRATION_SECONDS);

            return document;
        }

        public async Task<XDocument> LoadSchemaAsync(string uri)
        {
            var schemaUri = GetSchemaUri(uri);

            if (schemaUri == null)
            {
                return null;
            }

            var cacheKey = GenerateCacheKey(schemaUri);

            if (cache.ContainsKey(cacheKey))
            {
                return cache[cacheKey].Document;
            }

            XDocument schema;

            try
            {
                schema = await LoadSchemaFromSourceAsync(schemaUri);
            }
            catch (Exception ex)
            {
                // Log error and return null
                Console.WriteLine($"Error loading schema from {schemaUri}: {ex.Message}");
                return null;
            }

            cache[cacheKey] = new CacheEntry(schema, CACHE_EXPIRATION_SECONDS);

            return schema;
        }

        public async Task<bool> ValidateDocumentAsync(XDocument document)
        {
            var schema = await LoadSchemaAsync(document.BaseUri);

            if (schema == null)
            {
                Console.WriteLine($"No schema found for {document.BaseUri}");
                return false;
            }

            try
            {
                document.Validate(schema, (sender, args) =>
                {
                    var message = $"Schema validation error: {args.Message}";
                    Console.WriteLine(message);
                });

                return true;
            }
            catch (Exception ex)
            {
                // Log error and return null
                Console.WriteLine($"Error validating document against schema: {ex.Message}");
                return false;
            }
        }

