from concurrent.futures import ThreadPoolExecutor, as_completed
from queue import Queue
from threading import Semaphore

class SensorDataProcessor:
    def __init__(self):
        self.sensor_data = {}
        self.sensor_queue = Queue()
        self.thread_pool = ThreadPoolExecutor(max_workers=10)
        self.semaphore = Semaphore(5)

    def process_sensor_data(self, sensor_id, data):
        with self.semaphore:
            self.sensor_data[sensor_id] = json.loads(data)
            self.sensor_queue.put((sensor_id, data))

    def process_event_detection(self):
        while True:
            sensor_id, data = self.sensor_queue.get()
            if self.check_data_validity(data):
                self.process_aggregation(sensor_id, data)
            else:
                self.process_cleaning(sensor_id, data)
                self.process_aggregation(sensor_id, data)

    def process_aggregation(self, sensor_id, data):
        with self.semaphore:
            aggregated_data = self.aggregate_data(data)
            self.save_aggregated_data(sensor_id, aggregated_data)

    def check_data_validity(self, data):
