import org.springframework.context.annotation.Bean;
import org.springframework.stereotype.Component;
import org.springframework.web.reactive.HandlerMapping;
import org.springframework.web.server.adapter.WebHttpHandlerBuilder;

@SpringBootApplication
public class WebSocketApplication {

    public static void main(String[] args) {
        SpringApplication.run(WebSocketApplication.class, args);
    }

    @Bean
    public HandlerMapping websocketMapping() {
        return new WebHttpHandlerBuilder().webHandler(new WebSocketHandler()).build();
    }

    @Component
    public static class WebSocketHandler extends TextWebSocketHandler {

        private final WebSocketService service;

        public WebSocketHandler(WebSocketService service) {
            this.service = service;
        }

        @Override
        public Mono<Void> handleTextMessage(WebSocketSession session, TextMessage message) {
            // Handle the incoming text message from the client
            String data = message.getPayload();
            System.out.println("Received message: " + data);
            return service.handleMessage(session, data).then();
        }
    }

}
