        this->feature_size = feature_size;
        this->initial_leaf_nodes = initial_leaf_nodes;
        this->maximum_data_capacity = maximum_data_capacity;
    }

    ~SpatialCache() {
        // Clean up the spatial cache
        for (auto& node : nodes) {
            delete[] node.points;
        }
    }

    void addPoint(float* point) {
        // Add a new point to the spatial cache
        mutex_.lock();
        bool is_new_node = true;
        for (auto& node : nodes) {
            if (node.depth == 0 && node.center[0] == point[0] && node.center[1] == point[1] && node.center[2] == point[2]) {
                is_new_node = false;
                break;
            }
        }
        if (is_new_node) {
            // Create a new octree node for the new point
            OctreeNode* node = new OctreeNode();
            node->depth = 0;
            node->center[0] = point[0];
            node->center[1] = point[1];
            node->center[2] = point[2];
            nodes.push_back(node);
        }
        // Add the new point to the appropriate octree node
        for (auto& node : nodes) {
            if (node.depth == 0 && node.center[0] == point[0] && node.center[1] == point[1] && node.center[2] == point[2]) {
                node->points.push_back(point);
                break;
            }
        }
        mutex_.unlock();
    }

    void removePoint(float* point) {
        // Remove a point from the spatial cache
        mutex_.lock();
        for (auto& node : nodes) {
            if (node.depth == 0 && node.center[0] == point[0] && node.center[1] == point[1] && node.center[2] == point[2]) {
                // Remove the point from the octree node
                for (auto it = node->points.begin(); it != node->points.end(); ++it) {
                    if (*it == point) {
                        node->points.erase(it);
                        break;
                    }
                }
            }
        }
        mutex_.unlock();
    }

    vector<float*> getPoints(float* query_point, int depth) {
        // Get the points within a certain distance from a query point
        vector<float*> result;
        mutex_.lock();
        for (auto& node : nodes) {
            if (node.depth == depth && distance(query_point, node.center) < feature_size) {
                // Add the points from the octree node to the result
                for (auto* point : node->points) {
                    result.push_back(point);
                }
            }
        }
        mutex_.unlock();
        return result;
    }

private:
    int feature_size;
    int initial_leaf_nodes;
    int maximum_data_capacity;
    vector<OctreeNode*> nodes;
    mutex mutex_;
};

class SpatialQueryingAPI {
public:
    SpatialQueryingAPI(string api_key, string api_secret) {
        // Initialize the spatial querying API with the given authentication credentials
        this->api_key = api_key;
        this->api_secret = api_secret;
    }

    vector<float*> getPoints(float* query_point, int depth) {
        // Query the spatial cache for points within a certain distance from a query point
        vector<float*> result;
        mutex_.lock();
        for (auto& node : nodes) {
            if (node.depth == depth && distance(query_point, node.center) < feature_size) {
                // Add the points from the octree node to the result
                for (auto* point : node->points) {
                    result.push_back(point);
                }
            }
        }
        mutex_.unlock();
        return result;
    }

private:
    string api_key;
    string api_secret;
    SpatialCache* cache;
};

class StateManagementService {
public:
    StateManagementService(int maximum_size) {
        // Initialize the state management service with a maximum size for the cache
        this->maximum_size = maximum_size;
        this->sync();
    }

    void addState(string state) {
        // Add a new state to the cache
        mutex_.lock();
        if (states.size() >= maximum_size) {
            // Remove the oldest state from the cache if necessary
            states.pop_front();
        }
        states.push_back(state);
        mutex_.unlock();
    }

    void removeState(string state) {
        // Remove a state from the cache
        mutex_.lock();
        for (auto it = states.begin(); it != states.end(); ++it) {
            if (*it == state) {
                states.erase(it);
                break;
            }
        }
        mutex_.unlock();
    }

    string getState() {
        // Get the current state from the cache
        return states.back();
    }

private:
    int maximum_size;
    deque<string> states;
};
